pub fn run(
    allocator: std.mem.Allocator,
    cmd: lib.Command,
    args: []const []const u8,
) !void {
    if (!lib.commandAvailable(cmd)) return error.InvalidCommand;
    if (lib.HctpProductAvailable) {
        if (cmd == .hctp_source) return hctp_source.run(allocator, args);
        if (cmd == .hylo_extract) return hylo_extract.run(allocator, args);
    }
    var opts = try parseOptionsForCommand(cmd, args);
    if (cmd == .decision_capsule and !opts.format_set) opts.format = .json;
    if (opts.help) {
        try printCommandHelp(cmd);
        return;
    }
    if (opts.format_set) try validateFormatForCommand(cmd, opts);
    try validateCommandOptions(cmd, opts);

    const sessions_root = try resolveSessionsRoot(allocator, opts.root);
    defer allocator.free(sessions_root);

    switch (cmd) {
        .skills_rank => try cmdSkillsRank(allocator, sessions_root, opts),
        .skill_success_rank => try cmdSkillSuccessRank(allocator, sessions_root, opts),
        .skill_trend => try cmdSkillTrend(allocator, sessions_root, opts),
        .skill_report => try cmdSkillReport(allocator, sessions_root, opts),
        .skill_audit => try QueryLiftCommands.cmdSkillAudit(allocator, sessions_root, opts),
        .skill_evidence => try QueryLiftCommands.cmdSkillEvidence(allocator, sessions_root, opts),
        .skill_decision_audit => try cmdSkillDecisionAudit(allocator, sessions_root, opts),
        .skill_contract => try cmdSkillContract(allocator, opts),
        .skill_decision_receipt => try cmdSkillDecisionReceipt(allocator, opts),
        .decision_capsule => try cmdDecisionCapsule(allocator, sessions_root, opts),
        .hctp_source => unreachable,
        .hylo_extract => unreachable,
        .skill_blocks => try cmdSkillBlocks(allocator, sessions_root, opts),
        .artifact_search => try cmdArtifactSearch(allocator, sessions_root, opts),
        .tool_audit => try QueryLiftCommands.cmdToolAudit(allocator, sessions_root, opts),
        .memory_inventory => try QueryLiftCommands.cmdMemoryInventory(allocator, sessions_root, opts),
        .message_search => try QueryLiftCommands.cmdMessageSearch(allocator, sessions_root, opts),
        .message_audit => try QueryLiftCommands.cmdMessageAudit(allocator, sessions_root, opts),
        .skill_cohort => try QueryLiftCommands.cmdSkillCohort(allocator, sessions_root, opts),
        .tool_search => try QueryLiftCommands.cmdToolSearch(allocator, sessions_root, opts),
        .memory_extension_audit => try QueryLiftCommands.cmdMemoryExtensionAudit(allocator, sessions_root, opts),
        .token_window => try QueryLiftCommands.cmdTokenWindow(allocator, sessions_root, opts),
        .workdir_report => try QueryLiftCommands.cmdWorkdirReport(allocator, sessions_root, opts),
        .role_breakdown => try cmdRoleBreakdown(allocator, sessions_root, opts),
        .occurrence_export => try cmdOccurrenceExport(allocator, sessions_root, opts),
        .orchestration_concurrency => try cmdOrchestrationConcurrency(allocator, sessions_root, opts),
        .find_session => try cmdFindSession(allocator, sessions_root, opts),
        .plan_search => try cmdPlanSearch(allocator, sessions_root, opts),
        .reply_latency => try cmdReplyLatency(allocator, sessions_root, opts),
        .session_prompts => try cmdSessionPrompts(allocator, sessions_root, opts),
        .report_bundle => try cmdReportBundle(allocator, sessions_root, opts),
        .section_audit => try cmdSectionAudit(allocator, sessions_root, opts),
        .token_usage => try cmdTokenUsage(allocator, sessions_root, opts),
        .token_cost => try cmdTokenCost(allocator, sessions_root, opts),
        .routing_gap => try cmdRoutingGap(allocator, sessions_root, opts),
        .datasets => try cmdDatasets(allocator, opts),
        .dataset_schema => try cmdDatasetSchema(allocator, opts),
        .query => try cmdQuery(allocator, sessions_root, opts),
        .adjudication_audit => try cmdAdjudicationAudit(allocator, sessions_root, opts),
        .resolve_churn_audit => try cmdResolveChurnAudit(allocator, sessions_root, opts),
        .review_compiler_audit => try cmdReviewCompilerAudit(allocator, sessions_root, opts),
        .cas_review_audit => try cmdCasReviewAudit(allocator, sessions_root, opts),
        .goal_audit => try QueryLiftCommands.cmdGoalAudit(allocator, sessions_root, opts),
        .workflow_audit => try cmdWorkflowAudit(allocator, sessions_root, opts),
        .workflow_overlap => try cmdWorkflowOverlap(allocator, sessions_root, opts),
        .session_tooling => try cmdSessionTooling(allocator, sessions_root, opts),
        .query_diagnose => try cmdQueryDiagnose(allocator, sessions_root, opts),
        .actuation_audit => try cmdActuationAudit(allocator, sessions_root, opts),
        .execution_policy_audit => try cmdExecutionPolicyAudit(allocator, sessions_root, opts),
        .policy_calibration => try cmdPolicyCalibration(allocator, sessions_root, opts),
        .capabilities => try cmdCapabilities(allocator, opts),
        .memory_provenance => try cmdMemoryProvenance(allocator, opts),
        .memory_map => try cmdMemoryMap(allocator, opts),
        .memory_history => try cmdMemoryHistory(allocator, opts),
        .opencode_prompts => try cmdOpencodePrompts(allocator, sessions_root, opts),
        .opencode_events => try cmdOpencodeEvents(allocator, sessions_root, opts),
        .sessions => try cmdTraceSessions(allocator, sessions_root, opts),
        .turns => try cmdTraceTurns(allocator, sessions_root, opts),
        .session_detail => try cmdTraceSessionDetail(allocator, sessions_root, opts),
        .tool_lifecycle => try cmdTraceToolLifecycle(allocator, sessions_root, opts),
        .session_graph => try cmdTraceSessionGraph(allocator, sessions_root, opts),
        .tail => try cmdTraceTail(allocator, sessions_root, opts),
        .index => try cmdIndex(allocator, sessions_root, opts),
        .unknown => return error.InvalidCommand,
    }
}

fn printCommandHelp(cmd: lib.Command) !void {
    var stdout_writer = std.Io.File.stdout().writer(std.Io.Threaded.global_single_threaded.io(), &.{});
    const stdout = &stdout_writer.interface;

    const common =
        \\shared options:
        \\  --format <table|json|csv|jsonl>
        \\  --root <path> (session datasets)
        \\  --output <path>
        \\  --limit|--max|--top <N>
    ;

    const body = switch (cmd) {
        .hctp_source => if (lib.HctpProductAvailable) hctp_source.usage() else unreachable,
        .hylo_extract => if (lib.HctpProductAvailable) hylo_extract.usage() else unreachable,
        .skills_rank =>
        \\usage: seq skills-rank [--since <iso>] [--until <iso>] [--format table|json|csv] [--max N]
        ,
        .skill_success_rank =>
        \\usage: seq skill-success-rank [--skill <name>] [--mode summary|sessions] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--limit N] [--format table|json|csv|jsonl]
        ,
        .skill_trend =>
        \\usage: seq skill-trend --skill <name> [--bucket day|week|month] [--since <iso>] [--until <iso>] [--format table|json|csv] [--max N]
        ,
        .skill_report =>
        \\usage: seq skill-report --skill <name> [--since <iso>] [--until <iso>]
        ,
        .skill_audit =>
        \\usage: seq skill-audit [--skill <name>] [--mode summary|mentions|trend|activation] [--roles <csv>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--limit N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --mode activation         Counts explicit $skill calls, assistant $skill calls, injected blocks, bare references, and SKILL.md tool reads
        ,
        .skill_evidence =>
        \\usage: seq skill-evidence --skill <name> (--session-id <id>|--path <jsonl>) [--since-cursor <cursor-json-or-token>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--include-raw] [--format json]
        \\extra options:
        \\  --since-cursor <cursor>    Return only evidence after the prior cursor emitted by this command
        \\  --include-raw              Include raw evidence snippets; default output is sanitized summaries only
        ,
        .skill_decision_audit =>
        \\usage: seq skill-decision-audit --skill <name> (--session-id <id>|--path <jsonl>|--repo <path>|--workdir <path>|--last <duration>|--since <iso>|--until <iso>) [--mode summary|episodes|misses|clauses|outcomes|tune-packet|delta] [--causality explicit|strong|associated|any] [--include-workers] [--include-excerpts] [--format table|json|jsonl|csv|markdown]
        \\extra options:
        \\  --contract <path>           Use an explicit SKDC-v1 contract file
        \\  --contract-authority <kind> explicit (default) | inferred
        \\  --skill-root <path>         Discover skill decision contracts under this root
        \\  --since-cursor <cursor>     Return a one-session SDD-v1 delta after a prior cursor
        ,
        .skill_contract =>
        \\usage: seq skill-contract validate --file <decision-contract.yaml> [--format json]
        \\       seq skill-contract show --skill <name> --skill-root <path> [--format json]
        \\       seq skill-contract scaffold --skill <name> --kind decision --output <file>
        ,
        .skill_decision_receipt =>
        \\usage: seq skill-decision-receipt validate --file <receipt.json> [--format json]
        ,
        .skill_blocks =>
        \\usage: seq skill-blocks --skill <name> [--mode blocks|body|term-counts|term-summary] [--term-group <name=csv>] [--examples N] [--history <distinct|all|latest>] [--session-id <id>|--path <jsonl>|--current] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--limit N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --mode body               Emit the single selected block_text directly; use --history latest or narrower filters if multiple blocks match
        ,
        .artifact_search =>
        \\usage: seq artifact-search [--contains <text>|--contains-any <csv>|--regex <expr>] [--kind <auto|session|memory|orchestration|tooling|prompt>] [--surface <auto|messages|tool_calls|memory_blocks>] [--roles <csv>] [--tool <name>] [--workdir <path>] [--session-id <id>|--path <jsonl>] [--since <iso>] [--until <iso>] [--follow <none|auto>] [--strip-skill-blocks] [--no-dedupe-exact] [--stats] [--limit N] [--format table|json|csv|jsonl]
        ,
        .tool_audit =>
        \\usage: seq tool-audit [--mode summary|rows|args|unresolved] [--group-by executable|tool|session|workdir|command] [--tool <name>] [--executable <name>] [--workdir <path>] [--contains <text>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--limit N] [--format table|json|csv|jsonl]
        ,
        .memory_inventory =>
        \\usage: seq memory-inventory [--mode categories|files|blocks|stage1|extensions] [--memory-root <path>] [--extensions-root <path>] [--state-db-path <path>] [--contains <text>|--regex <expr>] [--limit N] [--format table|json|csv|jsonl]
        ,
        .message_search =>
        \\usage: seq message-search [--contains <text>|--regex <expr>|--contains-any <csv>|--contains-all <csv>] [--roles <csv>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--limit N] [--format table|json|csv|jsonl]
        ,
        .message_audit =>
        \\usage: seq message-audit [--mode summary|rows|sessions] [--contains <text>|--regex <expr>|--contains-any <csv>|--contains-all <csv>] [--roles <csv>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--show-query] [--limit N] [--format table|json|csv|jsonl]
        ,
        .skill_cohort =>
        \\usage: seq skill-cohort [--skill <name>] [--mode summary|cohort|mentions] [--roles <csv>] [--contains <text>|--regex <expr>|--contains-any <csv>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--show-query] [--limit N] [--format table|json|csv|jsonl]
        ,
        .tool_search =>
        \\usage: seq tool-search [--mode rows|summary|args] [--group-by executable|tool|session|workdir|command] [--tool <name>] [--executable <name>] [--workdir <path>] [--path <jsonl>|--session-id <id>] [--contains <text>|--contains-any <csv>|--regex <expr>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--show-query] [--limit N] [--format table|json|csv|jsonl]
        ,
        .memory_extension_audit =>
        \\usage: seq memory-extension-audit [--mode summary|rows] [--extensions-root <path>] [--contains <text>|--regex <expr>] [--show-query] [--limit N] [--format table|json|csv|jsonl]
        ,
        .token_window =>
        \\usage: seq token-window [--mode summary|rows] [--window-hours N] [--since <iso>] [--until <iso>] [--path <jsonl>] [--exclude-current] [--show-query] [--format table|json|csv|jsonl]
        ,
        .workdir_report =>
        \\usage: seq workdir-report [--workdir <path>] [--mode summary|sessions] [--contains <text>] [--contains-any <csv>] [--since <iso>] [--until <iso>] [--limit N] [--format table|json|csv|jsonl]
        ,
        .role_breakdown =>
        \\usage: seq role-breakdown [--since <iso>] [--until <iso>] [--format table|json|csv] [--max N]
        ,
        .occurrence_export =>
        \\usage: seq occurrence-export [--skill <name>] [--since <iso>] [--until <iso>] [--format jsonl|json|csv] [--max N]
        ,
        .orchestration_concurrency =>
        \\usage: seq orchestration-concurrency [--session-id <id>|--path <jsonl>] [--format table|json|csv|jsonl] [--floor-threshold N] [--fail-on-floor] [--fail-on-mesh-truth]
        ,
        .find_session =>
        \\usage: seq find-session (--prompt <text>|--session-id <id>) [--since <iso>] [--until <iso>] [--limit N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --session-id <id>         Resolve one session summary by id; when combined with --prompt, search only that session
        ,
        .plan_search =>
        \\usage: seq plan-search [--repo <path>] [--session-id <id>|--path <jsonl>] [--since <iso>] [--until <iso>] [--contains <text>|--regex <expr>] [--sort timestamp|-timestamp] [--include-body] [--stats] [--limit N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --repo <path>             Match session_meta cwd against this repo root or one of its descendants
        \\  --path <path>             Inspect exactly one rollout/session JSONL file
        \\  --session-id <id>         Resolve exactly one session file by session id substring
        \\  --contains <text>         Filter title+plan body by case-insensitive substring
        \\  --regex <expr>            Filter title+plan body by the artifact-search regex subset
        \\  --sort timestamp|-timestamp
        \\                           Order oldest-first or newest-first (default: -timestamp)
        \\  --include-body            Include the exact <proposed_plan> block in output rows
        \\  --stats                   Emit scan counters and filter-usage flags
        ,
        .reply_latency =>
        \\usage: seq reply-latency [--session-id <id>|--path <jsonl>|--current] [--mode single-message|contiguous] [--since <iso>] [--until <iso>] [--limit N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --path <path>              Inspect exactly one rollout/session JSONL file
        \\  --session-id <id>          Resolve exactly one session file by session id substring
        \\  --current                  Resolve current session via CODEX_THREAD_ID
        \\  --mode <name>              single-message (default) | contiguous
        ,
        .session_prompts =>
        \\usage: seq session-prompts [--session-id <id>|--path <jsonl>|--current] [--roles <csv>] [--since <iso>] [--until <iso>] [--strip-skill-blocks] [--no-dedupe-exact] [--limit N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --path <path>              Inspect exactly one rollout/session JSONL file
        \\  --session-id <id>          Resolve exactly one session file by session id substring
        \\  --current                  Resolve current session via CODEX_THREAD_ID
        \\  --roles <csv>              user | assistant | user,assistant
        \\  --strip-skill-blocks       Remove <skill>...</skill> envelopes before output
        \\  --no-dedupe-exact          Keep duplicated role+text rows
        ,
        .report_bundle =>
        \\usage: seq report-bundle [--since <iso>] [--until <iso>] [--top N]
        ,
        .section_audit =>
        \\usage: seq section-audit --sections <csv> [--since <iso>] [--until <iso>]
        ,
        .token_usage =>
        \\usage: seq token-usage [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--path <jsonl>|--session-id <id>] [--group-by day|path] [--tz utc|local|+HH:MM|-HH:MM] [--summary] [--audit] [--top N] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --last <duration>          Rolling window ending at --until or now; examples: 90m, 24h, 7d
        \\  --path <path>              Restrict the report to one rollout/session JSONL file
        \\  --session-id <id>          Restrict the report to one session file by session id substring
        \\  --group-by <name>          day (default) | path
        \\  --tz <name>                utc (default) | local | +HH:MM | -HH:MM
        \\  --summary                  Emit one summary row with totals and averages
        \\  --audit                    Emit self-auditing token accounting proof fields
        ,
        .token_cost =>
        \\usage: seq token-cost [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--path <jsonl>|--session-id <id>] [--group-by day|path|model|fast_mode] [--tz utc|local|+HH:MM|-HH:MM] [--summary] [--audit] [--pricing codex|api] [--model <name>] [--pricing-file <json>] [--refresh-pricing] [--offline] [--usd-per-credit <amount>] [--force-fast|--force-standard] [--format table|json|csv|jsonl]
        \\extra options:
        \\  --last <duration>           Rolling window ending at --until or now; examples: 90m, 24h, 7d
        \\  --pricing <kind>            codex (default credit pricing) | api (exact OpenAI API USD pricing)
        \\  --model <name>              Override trace model when pricing API rates
        \\  --pricing-file <json>       Load rates from an explicit JSON pricing file
        \\  --refresh-pricing           Refresh current OpenAI Codex pricing into the user cache
        \\  --offline                   Do not use network refresh; require explicit/bundled pricing
        \\  --usd-per-credit <amount>   Convert estimated credits to USD using this user-supplied rate
        \\  --force-fast                Price all supported rows with fast-mode multipliers and mark source override
        \\  --force-standard            Price all rows at standard rate and mark source override
        ,
        .routing_gap =>
        \\usage: seq routing-gap --cue-spec <json|@path> [--discovery-skills <csv>] [--format table|json|csv|jsonl]
        ,
        .datasets =>
        \\usage: seq datasets
        ,
        .dataset_schema =>
        \\usage: seq dataset-schema --dataset <name>
        ,
        .query =>
        \\usage: seq query --spec <json|@path>
        ,
        .decision_capsule =>
        \\usage: seq decision-capsule (--session-id <id>|--path <rollout.jsonl>) [--thread-id <id>] [--decision-id <id>|--turn-id <id>|--turn-index <n>|--contains <text>|--regex <pattern>|--skill <name>] [--mode capsule|candidates|anchors|validate] [--format table|json|jsonl|csv|markdown]
        ,
        .adjudication_audit =>
        \\usage: seq adjudication-audit [--mode summary|rows|report] [--skill <name>] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--include-root-equivalent <csv>] [--bundle-dir <path>] [--limit N] [--format table|markdown|json|csv|jsonl]
        \\extra options:
        \\  --skill <name>                 Skill to audit (default: review-adjudication)
        \\  --include-root-equivalent <csv> Include root-equivalent workflow names such as resolve,fixed-point-driver
        \\  --bundle-dir <path>            Write reproducible evidence rows beside the main report
        ,
        .resolve_churn_audit =>
        \\usage: seq resolve-churn-audit --since <iso> --until <iso> --repo <path> [--exclude-current] [--format markdown|json]
        \\extra options:
        \\  --repo <path>             Match session cwd/tool cwd against this repo root or descendants
        \\  --exclude-current         Exclude the current CODEX_THREAD_ID session
        \\  raw $resolve mentions are denominator candidates only; true sessions require assistant workflow or tool evidence
        ,
        .review_compiler_audit =>
        \\usage: seq review-compiler-audit [--protocol auto|legacy-cleanroom|c3|c3-mrpc|mbk|mbk-v1-legacy-open-horizon|intent-closed-cegis-v1|mixed|none] [--mode summary|runs|batches|counterexamples|potential|closure|report|evidence] [--emit-count-evidence] --since <iso> --until <iso> --repo <path> [--artifact-root <path>] [--strict] [--exclude-current] [--format table|json|jsonl|markdown]
        \\extra options:
        \\  --protocol <name>         auto (default) | legacy-cleanroom | c3 | c3-mrpc | mbk | mbk-v1-legacy-open-horizon | intent-closed-cegis-v1 | mixed | none
        \\  --mode <name>             summary (default) | runs | batches | counterexamples | potential | closure | report | evidence
        \\  --emit-count-evidence     Emit per-count evidence rows; equivalent to --mode evidence
        \\  --artifact-root <path>    Include controller artifact root in corpus/report metadata
        \\  --strict                  Exit 2 for hard current intent-closed/C3 closure failures
        \\  --repo <path>             Match session cwd/tool cwd against this repo root or descendants
        \\  --exclude-current         Exclude the current CODEX_THREAD_ID session
        \\  path mentions are candidates only; true C3 governance requires controller evidence or explicit workflow declaration
        ,
        .cas_review_audit =>
        \\usage: seq cas-review-audit [--path <rollout.jsonl>|--receipt-path <json>|--repo <path>] [--base-sha <sha>] [--head-sha <sha>] [--target-fingerprint <fp>] [--mode summary|rows|report] [--format table|json|csv|jsonl|markdown]
        \\extra options:
        \\  --receipt-path <path>       Include a persisted review-session receipt
        \\  --receipt-glob <glob>       Include persisted review-session receipts matching a simple * glob
        \\  --mode <name>               summary (default) | rows | report
        \\  --format markdown           Only valid with --mode report
        ,
        .actuation_audit =>
        \\usage: seq actuation-audit --root <path> [--session-id <id>|--path <rollout.jsonl>|(--repo <path>|--workdir <path>) (--since <iso>|--until <iso>|--last <duration>)] [--include-workers] [--mode summary|runs|slices|proof|compactions|decisions|hylo|report] [--strict] [--include-excerpts] [--format table|json|jsonl|csv|markdown]
        \\extra options:
        \\  --exclude-current          Exclude the current CODEX_THREAD_ID session from corpus selectors
        \\  --strict                   Exit 2 when a true run has a defined actuation control failure
        \\  --include-excerpts         Include bounded sanitized excerpts; full prompts and private reasoning stay excluded
        ,
        .execution_policy_audit =>
        \\usage: seq execution-policy-audit --root <path> [--session-id <id>|--path <rollout.jsonl>|--repo <path>|--since <iso>|--until <iso>|--last <duration>] [--exclude-current] [--include-workers] [--policy-root <path>] [--mode summary|runs|policies|transitions|calibration|regret|proof|report] [--strict] [--format table|json|jsonl|csv|markdown]
        \\extra options:
        \\  --policy-root <path>        Include policy artifact root in corpus metadata
        \\  --strict                   Exit 2 for hard current-protocol execution policy failures
        \\  --format markdown          Only valid with --mode report
        ,
        .policy_calibration =>
        \\usage: seq policy-calibration --root <path> [--session-id <id>|--path <rollout.jsonl>|--repo <path>|--since <iso>|--until <iso>|--last <duration>] [--exclude-current] [--include-workers] [--policy-root <path>] [--format table|json|jsonl|csv]
        \\extra options:
        \\  Emits the execution policy calibration projection; equivalent to execution-policy-audit --mode calibration
        \\  --policy-root <path>        Include policy artifact root in corpus metadata
        ,
        .goal_audit =>
        \\usage: seq goal-audit [--mode summary|rows] [--workflow review|resolve|review,resolve] [--duration-gte <seconds|minutes|hours>] [--status <name>] [--contains <text>] [--since <iso>] [--until <iso>] [--path <jsonl>|--session-id <id>] [--exclude-current] [--show-query] [--limit N] [--format table|json|csv|jsonl]
        ,
        .workflow_audit =>
        \\usage: seq workflow-audit --workflow <name> [--mode summary|signals|outcomes|sessions|report|term-summary|cohort-report|provenance] [--term-group <name=csv>] [--examples N] [--unique-by snippet|path-snippet] [--last <Nm|Nh|Nd>|--since <iso>] [--until <iso>] [--exclude-current] [--workdir <path>] [--limit N] [--format table|json|csv|jsonl|markdown]
        ,
        .workflow_overlap =>
        \\usage: seq workflow-overlap --workflow <a,b> [--mode summary|sessions] [--since <iso>] [--until <iso>] [--workdir <path>] [--limit N] [--format table|json|csv|jsonl]
        ,
        .session_tooling =>
        \\usage: seq session-tooling [--session-id <id>|--path <jsonl>] [--since <iso>] [--until <iso>] [--group-by executable|command|tool] [--summary] [--limit N] [--format table|json|csv|jsonl]
        ,
        .query_diagnose =>
        \\usage: seq query-diagnose [--session-id <id>|--path <jsonl>] [--since <iso>] [--until <iso>] [--threshold-ms N] [--strict-hang] [--fail-on-hang] [--next-actions] [--summary] [--format table|json|csv|jsonl]
        ,
        .capabilities =>
        \\usage: seq capabilities [--format table|json|csv|jsonl]
        ,
        .memory_provenance =>
        \\usage: seq memory-provenance (--thread-id <id> | --rollout-summary-file <path>) [--state-db-path <path>] [--memory-root <path>] [--extensions-root <path>] [--trace none|auto|always] [--format table|json|csv|jsonl]
        ,
        .memory_map =>
        \\usage: seq memory-map (--thread-id <id> | --contains <text> | --regex <expr>) [--memory-root <path>] [--extensions-root <path>] [--since <iso>] [--until <iso>] [--trace none|auto|always] [--limit N] [--format table|json|csv|jsonl]
        ,
        .memory_history =>
        \\usage: seq memory-history (--thread-id <id> | --contains <text> | --regex <expr>) [--state-db-path <path>] [--memory-root <path>] [--extensions-root <path>] [--since <iso>] [--until <iso>] [--trace none|auto|always] [--limit N] [--format table|json|csv|jsonl]
        ,
        .opencode_prompts =>
        \\usage: seq opencode-prompts [--spec <json|@path>] [--contains <text>] [--regex <expr>] [--session <id|slug>] [--since <epoch-ms|iso>] [--until <epoch-ms|iso>] [--latest] [--mode <name>] [--part-type <name>] [--group-by <csv>] [--metric <csv>] [--select <csv>] [--sort <csv>] [--source auto|db|jsonl] [--opencode-db-path <path>] [--opencode-path <path>] [--include-raw] [--limit N] [--format table|json|csv|jsonl]
        ,
        .opencode_events =>
        \\usage: seq opencode-events [--spec <json|@path>] [--contains <text>] [--regex <expr>] [--session <id|slug>] [--since <epoch-ms|iso>] [--until <epoch-ms|iso>] [--latest] [--role <name>] [--mode <name>] [--part-type <name>] [--tool <name>] [--status <name>] [--group-by <csv>] [--metric <csv>] [--select <csv>] [--sort <csv>] [--source auto|db|jsonl] [--opencode-db-path <path>] [--opencode-path <path>] [--include-raw] [--limit N] [--format table|json|csv|jsonl]
        ,
        .sessions =>
        \\usage: seq sessions [--root <path>] [--since <iso>] [--until <iso>] [--repo <path>] [--contains <text>] [--ongoing|--completed] [--worker-kind all|none|inline|external] [--limit N] [--format table|json|jsonl]
        ,
        .turns =>
        \\usage: seq turns [--path <jsonl>|--session-id <id>|--root <path>] [--since <iso>] [--until <iso>] [--status complete|aborted|ongoing|error] [--contains <text>] [--include-tools] [--limit N] [--format table|json|jsonl]
        ,
        .session_detail =>
        \\usage: seq session-detail (--path <jsonl>|--session-id <id>) [--include-tools] [--format json|markdown]
        ,
        .tool_lifecycle =>
        \\usage: seq tool-lifecycle (--path <jsonl>|--session-id <id>) [--include-raw] [--format table|json|jsonl]
        ,
        .session_graph =>
        \\usage: seq session-graph --session-id <id> [--root <path>] [--include-tools] [--format table|json|dot]
        ,
        .tail =>
        \\usage: seq tail (--current|--path <jsonl>|--session-id <id>) [--events raw,turns,tools,tokens,status] [--poll-ms N] [--debounce-ms N] [--once] [--format table|jsonl]
        ,
        .index =>
        \\usage: seq index build|status|refresh|vacuum [--root <path>] [--format table|json|csv|jsonl]
        ,
        .unknown =>
        \\usage: seq <command> --help
        ,
    };

    try stdout.writeAll(body);
    try stdout.writeByte('\n');
    try stdout.writeAll(common);
    try stdout.writeByte('\n');
}

fn printCliError(comptime fmt: []const u8, args: anytype) void {
    var stderr_writer = std.Io.File.stderr().writer(std.Io.Threaded.global_single_threaded.io(), &.{});
    const stderr = &stderr_writer.interface;
    stderr.print(fmt, args) catch {};
}

fn unsupportedOption(option: []const u8, cmd: lib.Command) !void {
    printCliError("error: option {s} is not supported for {s}\n", .{ option, @tagName(cmd) });
    return error.UnsupportedOption;
}

fn ensureOptionAllowed(flag_set: bool, allowed: bool, option: []const u8, cmd: lib.Command) !void {
    if (flag_set and !allowed) {
        try unsupportedOption(option, cmd);
    }
}

fn commandSupportsSummary(cmd: lib.Command) bool {
    const name = @tagName(cmd);
    return std.mem.eql(u8, name, "session_tooling") or
        std.mem.eql(u8, name, "query_diagnose") or
        std.mem.eql(u8, name, "token_usage") or
        std.mem.eql(u8, name, "token_cost") or
        std.mem.eql(u8, name, "goal_audit");
}

fn commandSupportsExcludeCurrent(cmd: lib.Command) bool {
    const name = @tagName(cmd);
    return std.mem.eql(u8, name, "message_audit") or
        std.mem.eql(u8, name, "actuation_audit") or
        std.mem.eql(u8, name, "execution_policy_audit") or
        std.mem.eql(u8, name, "policy_calibration") or
        std.mem.eql(u8, name, "skill_audit") or
        std.mem.eql(u8, name, "skill_cohort") or
        std.mem.eql(u8, name, "skill_success_rank") or
        std.mem.eql(u8, name, "message_search") or
        std.mem.eql(u8, name, "tool_search") or
        std.mem.eql(u8, name, "token_window") or
        std.mem.eql(u8, name, "resolve_churn_audit") or
        std.mem.eql(u8, name, "review_compiler_audit") or
        std.mem.eql(u8, name, "cas_review_audit") or
        std.mem.eql(u8, name, "workflow_audit") or
        std.mem.eql(u8, name, "goal_audit") or
        std.mem.eql(u8, name, "skill_decision_audit");
}

fn validateFormatForCommand(cmd: lib.Command, opts: Options) !void {
    const fmt = opts.format;
    switch (cmd) {
        .hctp_source, .hylo_extract => {},
        .skills_rank, .skill_trend, .skill_report, .role_breakdown, .report_bundle, .section_audit, .datasets, .dataset_schema => {
            if (fmt == .jsonl or fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
        },
        .skill_blocks => {
            if (opts.mode == null or std.mem.eql(u8, opts.mode.?, "blocks")) {
                if (fmt != .json and fmt != .jsonl) return error.InvalidFormatForCommand;
            } else if (std.mem.eql(u8, opts.mode.?, "body")) {
                return error.InvalidFormatForCommand;
            } else if (std.mem.eql(u8, opts.mode.?, "term-counts") or std.mem.eql(u8, opts.mode.?, "term-summary")) {
                if (fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
            } else {
                return error.InvalidModeArg;
            }
        },
        .skill_evidence => {
            if (fmt != .json) return error.InvalidFormatForCommand;
        },
        .skill_decision_audit => {
            if (fmt == .dot) return error.InvalidFormatForCommand;
            if (fmt == .markdown) {
                const mode = opts.mode orelse "summary";
                if (!std.mem.eql(u8, mode, "summary")) return error.InvalidFormatForCommand;
            }
        },
        .decision_capsule => {
            if (fmt == .dot) return error.InvalidFormatForCommand;
            const mode = decision_capsule.Mode.parse(opts.mode) catch return error.InvalidModeArg;
            if (fmt == .markdown and mode != .capsule) return error.InvalidFormatForCommand;
        },
        .actuation_audit => {
            if (fmt == .dot) return error.InvalidFormatForCommand;
            const mode = opts.mode orelse "summary";
            if (!isValidActuationAuditMode(mode)) return error.InvalidModeArg;
            if (fmt == .markdown and !std.mem.eql(u8, mode, "report")) return error.InvalidFormatForCommand;
        },
        .cas_review_audit => {
            if (fmt == .dot) return error.InvalidFormatForCommand;
            const mode = opts.mode orelse "summary";
            if (!isValidCasReviewAuditMode(mode)) return error.InvalidModeArg;
            if (fmt == .markdown and !std.mem.eql(u8, mode, "report")) return error.InvalidFormatForCommand;
        },
        .execution_policy_audit => {
            if (fmt == .dot) return error.InvalidFormatForCommand;
            const mode = opts.mode orelse "summary";
            if (!isValidExecutionPolicyAuditMode(mode)) return error.InvalidModeArg;
            if (fmt == .markdown and !std.mem.eql(u8, mode, "report")) return error.InvalidFormatForCommand;
        },
        .policy_calibration => {
            if (fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
        },
        .skill_contract, .skill_decision_receipt, .capabilities => {
            if (fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
        },
        .occurrence_export => {
            if (fmt == .table or fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
        },
        .session_detail => {
            if (fmt != .json and fmt != .markdown) return error.InvalidFormatForCommand;
        },
        .session_graph => {
            if (fmt == .csv or fmt == .markdown) return error.InvalidFormatForCommand;
        },
        .workflow_audit => {
            if (opts.mode) |mode| {
                if (std.mem.eql(u8, mode, "cohort-report") and fmt != .markdown and fmt != .json) return error.InvalidFormatForCommand;
            }
            if (fmt == .dot) return error.InvalidFormatForCommand;
        },
        .adjudication_audit => {
            if (fmt == .dot) return error.InvalidFormatForCommand;
        },
        .resolve_churn_audit => {
            if (fmt != .markdown and fmt != .json) return error.InvalidFormatForCommand;
        },
        .review_compiler_audit => {
            if (fmt != .markdown and fmt != .json and fmt != .table and fmt != .jsonl) return error.InvalidFormatForCommand;
        },
        .sessions, .turns, .tool_lifecycle, .tail => {
            if (fmt == .csv or fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
        },
        .query => {},
        .artifact_search, .tool_audit, .memory_inventory, .message_search, .message_audit, .skill_cohort, .tool_search, .memory_extension_audit, .token_window, .workdir_report, .orchestration_concurrency, .find_session, .plan_search, .reply_latency, .session_prompts, .token_usage, .token_cost, .routing_gap, .session_tooling, .query_diagnose, .memory_provenance, .memory_map, .memory_history, .opencode_prompts, .opencode_events, .skill_audit, .skill_success_rank, .goal_audit, .workflow_overlap, .index => {
            if (fmt == .markdown or fmt == .dot) return error.InvalidFormatForCommand;
        },
        .unknown => return error.InvalidCommand,
    }
}

fn validateCommandOptions(cmd: lib.Command, opts: Options) !void {
    const supports_current = cmd == .session_prompts or cmd == .reply_latency or cmd == .skill_blocks or cmd == .tail;
    const supports_roles_csv = cmd == .session_prompts or cmd == .artifact_search or cmd == .skill_audit or cmd == .message_search or cmd == .message_audit or cmd == .skill_cohort;
    const supports_strip_skill_blocks = cmd == .session_prompts or cmd == .artifact_search;
    const supports_no_dedupe_exact = cmd == .session_prompts or cmd == .artifact_search;
    const supports_audit = cmd == .token_usage or cmd == .token_cost;
    const supports_next_actions = cmd == .query_diagnose;
    const supports_latest = switch (cmd) {
        .opencode_prompts, .opencode_events => true,
        else => false,
    };
    const supports_floor_threshold = cmd == .orchestration_concurrency;
    const supports_fail_on_floor = cmd == .orchestration_concurrency;
    const supports_fail_on_mesh_truth = cmd == .orchestration_concurrency;
    const supports_fail_on_hang = cmd == .query_diagnose;
    const supports_threshold_ms = cmd == .query_diagnose;
    const supports_strict_hang = cmd == .query_diagnose;
    const supports_skill = switch (cmd) {
