            if (opts.path == null and opts.file_text == null) return error.MissingArgValue;
        } else if (source_count != 1) {
            printCliError("error: decision-capsule requires exactly one source selector: --session-id or --path\n", .{});
            return error.MissingArgValue;
        }
    }
    if (cmd == .skill_contract) {
        try validateSkillContractArgs(opts);
    }
    if (cmd == .skill_decision_receipt) {
        try validateSkillDecisionReceiptArgs(opts);
    }
    if (cmd == .message_audit) {
        if (opts.mode) |text| {
            if (!isValidMessageAuditMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .skill_cohort) {
        if (opts.mode) |text| {
            if (!isValidSkillCohortMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .tool_audit) {
        if (opts.mode) |text| {
            if (!isValidToolAuditMode(text)) return error.InvalidModeArg;
        }
        if (opts.group_by_text) |text| {
            if (!isValidToolAuditGroupBy(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .tool_search) {
        if (opts.mode) |text| {
            if (!isValidToolSearchMode(text)) return error.InvalidModeArg;
        }
        if (opts.group_by_text) |text| {
            if (!isValidToolAuditGroupBy(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .memory_inventory) {
        if (opts.mode) |text| {
            if (!isValidMemoryInventoryMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .memory_extension_audit) {
        if (opts.mode) |text| {
            if (!isValidMemoryExtensionAuditMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .token_window) {
        if (opts.mode) |text| {
            if (!isValidTokenWindowMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .workdir_report) {
        if (opts.mode) |text| {
            if (!isValidWorkdirReportMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .workflow_audit) {
        if (opts.mode) |text| {
            if (!isValidWorkflowAuditMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .workflow_overlap) {
        if (opts.mode) |text| {
            if (!isValidWorkflowOverlapMode(text)) return error.InvalidModeArg;
        }
        if (opts.workflow) |text| {
            if (!isValidWorkflowOverlapCsv(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .adjudication_audit) {
        if (opts.mode) |text| {
            if (!isValidAdjudicationAuditMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .resolve_churn_audit) {
        if (opts.since == null or opts.until == null or opts.repo_text == null) {
            printCliError("error: resolve-churn-audit requires --since, --until, and --repo\n", .{});
            return error.MissingArgValue;
        }
    }
    if (cmd == .review_compiler_audit) {
        if (opts.since == null or opts.until == null or opts.repo_text == null) {
            printCliError("error: review-compiler-audit requires --since, --until, and --repo\n", .{});
            return error.MissingArgValue;
        }
        if (opts.protocol_text) |text| {
            _ = try parseReviewCompilerProtocol(text);
        }
        if (opts.mode) |text| {
            if (!isValidReviewCompilerAuditMode(text)) return error.InvalidModeArg;
        }
    }
    if (cmd == .actuation_audit) {
        if (opts.mode) |text| {
            if (!isValidActuationAuditMode(text)) return error.InvalidModeArg;
        }
        if (!hasActuationAuditScope(opts)) {
            printCliError("error: actuation-audit requires --session-id, --path, or (--repo/--workdir with --since/--until/--last)\n", .{});
            return error.MissingArgValue;
        }
    }
    if (cmd == .cas_review_audit) {
        if (opts.mode) |text| {
            if (!isValidCasReviewAuditMode(text)) return error.InvalidModeArg;
        }
        if (!hasCasReviewAuditScope(opts)) {
            printCliError("error: cas-review-audit requires --session-id, --path, --receipt-path, --receipt-glob, --repo, --workdir, --since, --until, or --last\n", .{});
            return error.MissingArgValue;
        }
    }
    if (cmd == .execution_policy_audit) {
        if (opts.mode) |text| {
            if (!isValidExecutionPolicyAuditMode(text)) return error.InvalidModeArg;
        }
        if (!hasExecutionPolicyAuditScope(opts)) {
            printCliError("error: execution-policy-audit requires --session-id, --path, --repo, --since, --until, or --last\n", .{});
            return error.MissingArgValue;
        }
    }
    if (cmd == .policy_calibration) {
        if (!hasExecutionPolicyAuditScope(opts)) {
            printCliError("error: policy-calibration requires --session-id, --path, --repo, --since, --until, or --last\n", .{});
            return error.MissingArgValue;
        }
    }
    if (opts.unique_by_text) |text| {
        if (!std.mem.eql(u8, text, "snippet") and !std.mem.eql(u8, text, "path-snippet")) return error.InvalidModeArg;
    }
    if (opts.examples > 10) return error.InvalidLimit;
    if (cmd == .goal_audit) {
        if (opts.mode) |text| {
            if (!isValidGoalAuditMode(text)) return error.InvalidModeArg;
        }
        if (opts.workflow) |text| {
            if (!isValidGoalAuditWorkflowCsv(text)) return error.InvalidModeArg;
        }
    }
    if (opts.events_text) |text| _ = try parseTailEventMask(text);
}

