    return switch (cmd) {
        .artifact_search,
        .orchestration_concurrency,
        .plan_search,
        .reply_latency,
        .session_prompts,
        .session_tooling,
        .query_diagnose,
        .skill_evidence,
        .skill_decision_audit,
        .actuation_audit,
        .cas_review_audit,
        .execution_policy_audit,
        .policy_calibration,
        .decision_capsule,
        .skill_blocks,
        .token_usage,
        .token_cost,
        .token_window,
        .goal_audit,
        .tool_search,
        .turns,
        .session_detail,
