    try row.putOwnedKey("unexpected", .{ .int = ledger.learning.calibration_summary.unexpected_facts });
    try row.putOwnedKey("proof", .{ .string = ledger.governance.potential_summary.potential_findings_json });
    try row.putOwnedKey("surprise", .{ .int = ledger.learning.calibration_summary.unexpected_facts });
    try row.putOwnedKey("potential", .{ .string = ledger.governance.potential_summary.potential_gate });
    try row.putOwnedKey("state_after", .null);
    try row.putOwnedKey("unknowns", .{ .string = ledger.learning.unknowns_summary.unknowns_json });
    try row.putOwnedKey("critical_unknowns", .{ .int = ledger.learning.unknowns_summary.critical_unknowns });
    try row.putOwnedKey("resolved_unknowns", .{ .int = ledger.learning.unknowns_summary.resolved_unknowns });
    try row.putOwnedKey("premature_mutations", .{ .int = ledger.learning.unknowns_summary.premature_mutations });
    try row.putOwnedKey("regret_candidates", .{ .string = ledger.learning.regret_summary.regret_candidates_json });
    try row.putOwnedKey("class", .{ .string = ledger.learning.regret_summary.regret_candidates_json });
    try row.putOwnedKey("selected_action", .null);
    try row.putOwnedKey("candidate_action", .null);
    try row.putOwnedKey("causal_claim_allowed", .{ .bool = false });
    try row.putOwnedKey("stable_decision_ids", .{ .string = ledger.learning.decisions_summary.decision_ids_json });
    try row.putOwnedKey("state_id", .null);
    try row.putOwnedKey("selected_route", .null);
    try row.putOwnedKey("repeated_state_action", .{ .string = ledger.learning.repeated_state_action_json });
    try row.putOwnedKey("proof_required", .{ .int = ledger.governance.potential_summary.proof_required });
    try row.putOwnedKey("proof_passed", .{ .int = ledger.governance.potential_summary.proof_passed });
    try row.putOwnedKey("proof_stale", .{ .int = ledger.governance.potential_summary.proof_stale });
    try row.putOwnedKey("proof_missing", .{ .int = ledger.governance.potential_summary.proof_missing });
    try row.putOwnedKey("required", .{ .int = ledger.governance.potential_summary.proof_required });
    try row.putOwnedKey("passed", .{ .int = ledger.governance.potential_summary.proof_passed });
    try row.putOwnedKey("stale", .{ .int = ledger.governance.potential_summary.proof_stale });
    try row.putOwnedKey("missing", .{ .int = ledger.governance.potential_summary.proof_missing });
    try row.putOwnedKey("final_proof", .{ .string = ledger.governance.potential_summary.potential_findings_json });
    try row.putOwnedKey("outcome_levels", .{ .string = ledger.governance.lineage_summary.outcome_levels_json });
    try row.putOwnedKey("strict_findings", .{ .string = ledger.governance.strict_findings_json });
    try row.putOwnedKey("evidence_ref_count", .{ .int = @intCast(ledger.classification.evidence_refs.len) });
    try row.putOwnedKey("evidence_refs", .{ .string = ledger.classification.evidence_ref_json });
    const contamination = try execution_policy_audit.render.stringArrayJson(allocator, ledger.classification.contamination_flags);
    defer allocator.free(contamination);
    try row.putOwnedKey("contamination_flags", .{ .string = contamination });
    const limitations = try execution_policy_audit.render.stringArrayJson(allocator, ledger.classification.limitations);
    defer allocator.free(limitations);
    try row.putOwnedKey("limitations", .{ .string = limitations });
    try row.putOwnedKey("diagnostic_query_json", .{ .string = ledger.diagnostic_query_json });
    try rows.append(allocator, row);
}

fn hasStrictExecutionPolicyFailure(rows: []const query.Row) bool {
    for (rows) |row| {
        const findings = scalarString(row.valueOrNull("strict_findings")) orelse continue;
        if (!std.mem.eql(u8, findings, "[]")) return true;
    }
    return false;
}

fn executionPolicyTracePassesScope(session: canonical_trace.SessionRecord, opts: Options, current_thread_id: ?[]const u8) bool {
    if (current_thread_id) |id| {
        if (session.session_id) |session_id| {
            if (std.mem.eql(u8, session_id, id)) return false;
        }
    }
    const ts = session.start_time orelse session.end_time;
    if ((opts.since != null or opts.until != null or opts.last_text != null) and !timestampSatisfiesBounds(ts, opts)) return false;
    if (opts.repo_text) |repo| {
        const cwd = session.cwd orelse return false;
        const repo_root = normalizeRepoMatchPath(std.heap.page_allocator, repo) catch return false;
        defer std.heap.page_allocator.free(repo_root);
        const matches = pathMatchesRepoScope(std.heap.page_allocator, repo_root, cwd) catch return false;
        if (!matches) return false;
    }
    return true;
}

fn cmdActuationAuditReport(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    var params = std.ArrayList(spec.ParamSpec).empty;
    defer params.deinit(allocator);
    try appendActuationScopeParams(allocator, &params, opts);
    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    try collectActuationDatasetRows(allocator, "actuation_runs", sessions_root, params.items, &rows);
    if (opts.actuation_strict and hasStrictActuationFailure(rows.items)) std.process.exit(2);

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    try writer.writeAll("# Actuation Audit\n\n");
    try writer.print("- included_runs: {d}\n", .{rows.items.len});
    var violations: usize = 0;
    for (rows.items) |row| {
        const verdict = scalarString(row.valueOrNull("verdict")) orelse "unknown";
        if (std.mem.eql(u8, verdict, "projection_inversion") or std.mem.eql(u8, verdict, "graph_bypass")) violations += 1;
    }
    try writer.print("- control_failures: {d}\n\n", .{violations});
    try writeRefactorKernelReportSection(writer, summarizeRefactorKernelRows(rows.items));
    try writer.writeAll("| session_id | verdict | compile_failures | mutations_without_gcr |\n");
    try writer.writeAll("| --- | --- | ---: | ---: |\n");
    for (rows.items) |row| {
        try writer.print("| {s} | {s} | {d} | {d} |\n", .{
            scalarString(row.valueOrNull("session_id")) orelse "",
            scalarString(row.valueOrNull("verdict")) orelse "",
            scalarIntOrZero(row.valueOrNull("graph.compile_failures")),
            scalarIntOrZero(row.valueOrNull("graph.mutations_without_gcr")),
        });
    }
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, opts.out_path);
}

fn actuationDatasetForMode(mode: []const u8) []const u8 {
    if (std.mem.eql(u8, mode, "runs") or std.mem.eql(u8, mode, "summary") or std.mem.eql(u8, mode, "report")) return "actuation_runs";
    if (std.mem.eql(u8, mode, "slices")) return "actuation_slices";
    if (std.mem.eql(u8, mode, "decisions")) return "actuation_decisions";
    if (std.mem.eql(u8, mode, "proof")) return "actuation_proofs";
    if (std.mem.eql(u8, mode, "compactions")) return "actuation_compactions";
    if (std.mem.eql(u8, mode, "hylo")) return "actuation_hylo_runs";
    return "actuation_runs";
}

fn actuationColumnsForMode(mode: []const u8) []const []const u8 {
    if (std.mem.eql(u8, mode, "summary")) return &.{ "session_id", "true_actuating", "verdict", "graph.compile_attempts", "graph.compile_failures", "graph.mutations_without_gcr", "projection.update_plan_calls", "surface.churn.apply_patch_calls", "rk_class", "rk_conf", "rk_patch", "rk_no_gcr" };
    if (std.mem.eql(u8, mode, "runs")) return &.{ "run_id", "session_id", "path", "repo", "branch", "true_actuating", "verdict", "graph.compile_attempts", "graph.compile_failures", "graph.mutations_without_gcr", "projection.update_plan_calls", "surface.churn.apply_patch_calls", "rk_class", "rk_conf", "rk_patch", "rk_no_gcr", "worker_inclusion", "diagnostic_query_json" };
    if (std.mem.eql(u8, mode, "slices")) return findDatasetMeta("actuation_slices").?.fields;
    if (std.mem.eql(u8, mode, "decisions")) return findDatasetMeta("actuation_decisions").?.fields;
    if (std.mem.eql(u8, mode, "proof")) return findDatasetMeta("actuation_proofs").?.fields;
    if (std.mem.eql(u8, mode, "compactions")) return findDatasetMeta("actuation_compactions").?.fields;
    if (std.mem.eql(u8, mode, "hylo")) return findDatasetMeta("actuation_hylo_runs").?.fields;
    return findDatasetMeta("actuation_runs").?.fields;
}

const refactor_kernel_class_names = [_][]const u8{
    "governed_refactor_kernel",
    "governed_refactor_kernel_with_control_violation",
    "refactor_kernel_decision_missing_outcome",
    "potential_hidden_refactor_kernel_explicit",
    "potential_hidden_refactor_kernel_inferred",
    "large_graph_bypass_unclassified",
    "ordinary_graph_bypass",
};

const RefactorKernelClassTotals = struct {
    sessions: i64 = 0,
    patch_calls: i64 = 0,
    mutations_without_graph_control: i64 = 0,
};

const RefactorKernelSummary = struct {
    classes: [refactor_kernel_class_names.len]RefactorKernelClassTotals = .{RefactorKernelClassTotals{}} ** refactor_kernel_class_names.len,
    potential_hidden_patch_calls: i64 = 0,
    potential_hidden_mutations_without_graph_control: i64 = 0,
    formal_decision_present: i64 = 0,
    outcome_present: i64 = 0,
};

fn renderActuationRunsJson(allocator: std.mem.Allocator, rows: []const query.Row, jsonl: bool) ![]u8 {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    if (jsonl) {
        for (rows) |row| {
            try writeActuationRunJsonObject(writer, row);
            try writer.writeByte('\n');
        }
    } else {
        try writer.writeAll("[\n");
        for (rows, 0..) |row, idx| {
            if (idx > 0) try writer.writeAll(",\n");
            try writer.writeAll("  ");
            try writeActuationRunJsonObject(writer, row);
        }
        if (rows.len > 0) try writer.writeByte('\n');
        try writer.writeAll("]\n");
    }
    return writer_alloc.toOwnedSlice();
}

fn writeActuationRunJsonObject(writer: anytype, row: query.Row) !void {
    var first = true;
    try writer.writeByte('{');
    try writeNamedScalar(writer, "run_id", row.valueOrNull("run_id"), &first);
    try writeNamedScalar(writer, "session_id", row.valueOrNull("session_id"), &first);
    try writeNamedScalar(writer, "path", row.valueOrNull("path"), &first);
    try writeNamedScalar(writer, "repo", row.valueOrNull("repo"), &first);
    try writeNamedScalar(writer, "branch", row.valueOrNull("branch"), &first);
    try writeNamedScalar(writer, "true_actuating", row.valueOrNull("true_actuating"), &first);
    try writeNamedScalar(writer, "verdict", row.valueOrNull("verdict"), &first);
    try writeNamedScalar(writer, "graph.compile_attempts", row.valueOrNull("graph.compile_attempts"), &first);
    try writeNamedScalar(writer, "graph.compile_failures", row.valueOrNull("graph.compile_failures"), &first);
    try writeNamedScalar(writer, "graph.mutations_without_gcr", row.valueOrNull("graph.mutations_without_gcr"), &first);
    try writeNamedScalar(writer, "projection.update_plan_calls", row.valueOrNull("projection.update_plan_calls"), &first);
    try writeNamedScalar(writer, "surface.churn.apply_patch_calls", row.valueOrNull("surface.churn.apply_patch_calls"), &first);
    try writeNamedObjectPrefix(writer, "refactor_kernel", &first);
    try writeRefactorKernelRowJson(writer, row);
    try writeNamedScalar(writer, "worker_inclusion", row.valueOrNull("worker_inclusion"), &first);
    try writeNamedScalar(writer, "diagnostic_query_json", row.valueOrNull("diagnostic_query_json"), &first);
    try writer.writeByte('}');
}

fn writeRefactorKernelRowJson(writer: anytype, row: query.Row) !void {
    var first = true;
    try writer.writeByte('{');
    try writeNamedScalar(writer, "classification", row.valueOrNull("refactor_kernel.classification"), &first);
    try writeNamedScalar(writer, "confidence", row.valueOrNull("refactor_kernel.confidence"), &first);
    try writeNamedScalar(writer, "formal_decision_present", row.valueOrNull("refactor_kernel.formal_decision_present"), &first);
    try writeNamedScalar(writer, "outcome_present", row.valueOrNull("refactor_kernel.outcome_present"), &first);
    try writeNamedScalar(writer, "explicit_phrase_present", row.valueOrNull("refactor_kernel.explicit_phrase_present"), &first);
    try writeNamedScalar(writer, "selected_route_present", row.valueOrNull("refactor_kernel.selected_route_present"), &first);
    try writeNamedScalar(writer, "next_resolution_mode_present", row.valueOrNull("refactor_kernel.next_resolution_mode_present"), &first);
    try writeNamedScalar(writer, "potential_hidden_kernel", row.valueOrNull("refactor_kernel.potential_hidden_kernel"), &first);
    try writeNamedScalar(writer, "graph_bypass", row.valueOrNull("refactor_kernel.graph_bypass"), &first);
    try writeNamedScalar(writer, "patch_calls", row.valueOrNull("refactor_kernel.patch_calls"), &first);
    try writeNamedScalar(writer, "update_plan_calls", row.valueOrNull("refactor_kernel.update_plan_calls"), &first);
    try writeNamedScalar(writer, "mutations_without_graph_control", row.valueOrNull("refactor_kernel.mutations_without_graph_control"), &first);
    try writeNamedScalar(writer, "accepted_liability_markers", row.valueOrNull("refactor_kernel.accepted_liability_markers"), &first);
    try writeNamedScalar(writer, "owner_boundary_markers", row.valueOrNull("refactor_kernel.owner_boundary_markers"), &first);
    try writeNamedScalar(writer, "review_fold_markers", row.valueOrNull("refactor_kernel.review_fold_markers"), &first);
    try writeNamedScalar(writer, "cas_bottleneck_markers", row.valueOrNull("refactor_kernel.cas_bottleneck_markers"), &first);
    try writeNamedScalar(writer, "rko_graph_bypass_yes", row.valueOrNull("refactor_kernel.rko_graph_bypass_yes"), &first);
    try writeNamedScalar(writer, "rko_mutations_without_control_nonzero", row.valueOrNull("refactor_kernel.rko_mutations_without_control_nonzero"), &first);
    try writer.writeAll(",\"reasons\":");
    try writer.writeAll(scalarString(row.valueOrNull("refactor_kernel.reasons")) orelse "[]");
    try writer.writeByte('}');
}

fn writeNamedScalar(writer: anytype, name: []const u8, value: spec.Scalar, first: *bool) !void {
    if (!first.*) try writer.writeByte(',');
    first.* = false;
    try output.writeJsonString(writer, name);
    try writer.writeByte(':');
    try output.writeScalarJson(writer, value);
}

fn writeNamedObjectPrefix(writer: anytype, name: []const u8, first: *bool) !void {
    if (!first.*) try writer.writeByte(',');
    first.* = false;
    try output.writeJsonString(writer, name);
    try writer.writeByte(':');
}

fn renderStringArrayJson(allocator: std.mem.Allocator, values: []const []u8) ![]u8 {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    try actuation_audit.render.writeStringArray(&writer_alloc.writer, values);
    return writer_alloc.toOwnedSlice();
}

fn renderActuationSummaryJson(allocator: std.mem.Allocator, rows: []const query.Row) ![]u8 {
    const summary = summarizeRefactorKernelRows(rows);
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    try writer.writeAll("{\n  \"included_runs\": ");
    try writer.print("{d}", .{rows.len});
    try writer.writeAll(",\n  \"refactor_kernel\": {");
    try writeRefactorKernelSummaryFields(writer, summary, "    ", true);
    try writer.writeAll("\n  }\n}\n");
    return writer_alloc.toOwnedSlice();
}

fn writeRefactorKernelSummaryFields(writer: anytype, summary: RefactorKernelSummary, indent: []const u8, pretty: bool) !void {
    for (refactor_kernel_class_names, 0..) |name, idx| {
        if (idx > 0) try writer.writeByte(',');
        if (pretty) {
            try writer.writeByte('\n');
            try writer.writeAll(indent);
        }
        try output.writeJsonString(writer, name);
        try writer.writeAll(if (pretty) ": " else ":");
        try writer.print("{d}", .{summary.classes[idx].sessions});
    }
    try writeSummaryIntField(writer, "potential_hidden_patch_calls", summary.potential_hidden_patch_calls, indent, pretty);
    try writeSummaryIntField(writer, "potential_hidden_mutations_without_graph_control", summary.potential_hidden_mutations_without_graph_control, indent, pretty);
    try writeSummaryIntField(writer, "formal_decision_present", summary.formal_decision_present, indent, pretty);
    try writeSummaryIntField(writer, "outcome_present", summary.outcome_present, indent, pretty);
}

fn writeSummaryIntField(writer: anytype, name: []const u8, value: i64, indent: []const u8, pretty: bool) !void {
    try writer.writeByte(',');
    if (pretty) {
        try writer.writeByte('\n');
        try writer.writeAll(indent);
    }
    try output.writeJsonString(writer, name);
    try writer.writeAll(if (pretty) ": " else ":");
    try writer.print("{d}", .{value});
}

fn summarizeRefactorKernelRows(rows: []const query.Row) RefactorKernelSummary {
    var summary = RefactorKernelSummary{};
    for (rows) |row| {
        const class = scalarString(row.valueOrNull("refactor_kernel.classification")) orelse "none";
        const patch_calls = scalarIntOrZero(row.valueOrNull("refactor_kernel.patch_calls"));
        const mutations_without_graph_control = scalarIntOrZero(row.valueOrNull("refactor_kernel.mutations_without_graph_control"));
        if (refactorKernelClassIndex(class)) |idx| {
            summary.classes[idx].sessions += 1;
            summary.classes[idx].patch_calls += patch_calls;
            summary.classes[idx].mutations_without_graph_control += mutations_without_graph_control;
        }
        if (std.mem.eql(u8, class, "potential_hidden_refactor_kernel_explicit") or std.mem.eql(u8, class, "potential_hidden_refactor_kernel_inferred")) {
            summary.potential_hidden_patch_calls += patch_calls;
            summary.potential_hidden_mutations_without_graph_control += mutations_without_graph_control;
        }
        if (scalarBool(row.valueOrNull("refactor_kernel.formal_decision_present"))) summary.formal_decision_present += 1;
        if (scalarBool(row.valueOrNull("refactor_kernel.outcome_present"))) summary.outcome_present += 1;
    }
    return summary;
}

fn refactorKernelClassIndex(class: []const u8) ?usize {
    for (refactor_kernel_class_names, 0..) |name, idx| {
        if (std.mem.eql(u8, class, name)) return idx;
    }
    return null;
}

fn writeRefactorKernelReportSection(writer: anytype, summary: RefactorKernelSummary) !void {
    try writer.writeAll("## Refactor-Kernel Signal Classification\n\n");
    try writer.writeAll("| Class | Sessions | Patch calls | Mutations without graph/control |\n");
    try writer.writeAll("|---|---:|---:|---:|\n");
    for (refactor_kernel_class_names, 0..) |name, idx| {
        const totals = summary.classes[idx];
        try writer.print("| {s} | {d} | {d} | {d} |\n", .{ name, totals.sessions, totals.patch_calls, totals.mutations_without_graph_control });
    }
    try writer.writeAll("\n");
    try writer.writeAll("Potential hidden refactor-kernel is observational evidence, not causal proof.\n");
    try writer.writeAll("Formal AER/RKO evidence proves route legibility, not successful closure.\n");
    try writer.writeAll("Graph-bypass inside governed refactor-kernel remains a governance failure.\n\n");
}

fn renderActuationHyloSummaryJson(allocator: std.mem.Allocator, rows: []const query.Row) ![]u8 {
    var true_runs: i64 = 0;
    var hylo_required: i64 = 0;
    var alsr_present: i64 = 0;
    var hyl_present: i64 = 0;
    var hsr_step_count: i64 = 0;
    var mutations: i64 = 0;
    var mutations_with_unfold: i64 = 0;
    var actions_without_fold: i64 = 0;
    var continues_without_next_state: i64 = 0;
    var terminal_folds: i64 = 0;
    var atcg_after_terminal_fold: i64 = 0;
    var graph_bypass: i64 = 0;
    var quality_counts: [actuation_hylo.quality_state_count]usize = .{0} ** actuation_hylo.quality_state_count;
    var failure_counts: [actuation_hylo.failure_class_count]usize = .{0} ** actuation_hylo.failure_class_count;

    for (rows) |row| {
        if (scalarBool(row.valueOrNull("true_run"))) true_runs += 1;
        if (!scalarBool(row.valueOrNull("hylo_required"))) continue;
        hylo_required += 1;
        if (scalarBool(row.valueOrNull("alsr_present"))) alsr_present += 1;
        if (scalarBool(row.valueOrNull("hyl_present"))) hyl_present += 1;
        hsr_step_count += scalarIntOrZero(row.valueOrNull("hsr_step_count"));
        mutations += scalarIntOrZero(row.valueOrNull("mutations"));
        mutations_with_unfold += scalarIntOrZero(row.valueOrNull("mutations_with_unfold"));
        actions_without_fold += scalarIntOrZero(row.valueOrNull("actions_without_fold"));
        continues_without_next_state += scalarIntOrZero(row.valueOrNull("continues_without_next_state"));
        terminal_folds += scalarIntOrZero(row.valueOrNull("terminal_folds"));
        atcg_after_terminal_fold += scalarIntOrZero(row.valueOrNull("atcg_after_terminal_fold"));
        if (scalarBool(row.valueOrNull("graph_bypass"))) graph_bypass += 1;

        const quality = scalarString(row.valueOrNull("quality_state")) orelse "absent";
        for (actuation_hylo.quality_state_names, 0..) |name, idx| {
            if (std.mem.eql(u8, quality, name)) {
                quality_counts[idx] += 1;
                break;
            }
        }
        const failures = scalarString(row.valueOrNull("failure_classes")) orelse "";
        for (actuation_hylo.failure_class_names, 0..) |name, idx| {
            if (std.mem.indexOf(u8, failures, name) != null) failure_counts[idx] += 1;
        }
    }

    const failures_json = try actuation_hylo.failureClassesJson(allocator, failure_counts);
    defer allocator.free(failures_json);

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    try writer.writeAll("{\n");
    try writer.print("  \"true_runs\": {d},\n", .{true_runs});
    try writer.print("  \"hylo_required\": {d},\n", .{hylo_required});
    try writer.print("  \"alsr_present\": {d},\n", .{alsr_present});
    try writer.print("  \"hyl_present\": {d},\n", .{hyl_present});
    try writer.print("  \"hsr_step_count\": {d},\n", .{hsr_step_count});
    try writer.print("  \"mutations\": {d},\n", .{mutations});
    try writer.print("  \"mutations_with_unfold\": {d},\n", .{mutations_with_unfold});
    try writer.print("  \"actions_without_fold\": {d},\n", .{actions_without_fold});
    try writer.print("  \"continues_without_next_state\": {d},\n", .{continues_without_next_state});
    try writer.print("  \"terminal_folds\": {d},\n", .{terminal_folds});
    try writer.print("  \"atcg_after_terminal_fold\": {d},\n", .{atcg_after_terminal_fold});
    try writer.print("  \"graph_bypass\": {d},\n", .{graph_bypass});
    try writer.writeAll("  \"quality_states\": {");
    for (actuation_hylo.quality_state_names, 0..) |name, idx| {
        if (idx > 0) try writer.writeAll(", ");
        try output.writeJsonString(writer, name);
        try writer.print(": {d}", .{quality_counts[idx]});
    }
    try writer.writeAll("},\n");
    try writer.writeAll("  \"failure_classes\": ");
    try writer.writeAll(failures_json);
    try writer.writeAll("\n}\n");
    return writer_alloc.toOwnedSlice();
}

fn hasStrictActuationFailure(rows: []const query.Row) bool {
    for (rows) |row| {
        const verdict = scalarString(row.valueOrNull("verdict")) orelse continue;
        if (std.mem.eql(u8, verdict, "projection_inversion") or std.mem.eql(u8, verdict, "graph_bypass")) return true;
    }
    return false;
}

fn hasStrictActuationFailureForParams(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    params: []const spec.ParamSpec,
    dataset_name: []const u8,
    rows: []const query.Row,
) !bool {
    if (std.mem.eql(u8, dataset_name, "actuation_runs")) return hasStrictActuationFailure(rows);
    var run_rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &run_rows);
    try collectActuationDatasetRows(allocator, "actuation_runs", sessions_root, params, &run_rows);
    return hasStrictActuationFailure(run_rows.items);
}

fn appendActuationScopeParams(allocator: std.mem.Allocator, params: *std.ArrayList(spec.ParamSpec), opts: Options) !void {
    if (opts.path) |path| try params.append(allocator, .{ .key = "path", .value = .{ .string = path } });
    if (opts.session_id) |session_id| try params.append(allocator, .{ .key = "session_id", .value = .{ .string = session_id } });
    if (opts.repo_text) |repo| try params.append(allocator, .{ .key = "repo", .value = .{ .string = repo } });
    if (opts.workdir_text) |workdir| try params.append(allocator, .{ .key = "workdir", .value = .{ .string = workdir } });
    if (opts.since) |since| try params.append(allocator, .{ .key = "since", .value = .{ .string = since } });
    if (opts.until) |until| try params.append(allocator, .{ .key = "until", .value = .{ .string = until } });
    if (opts.last_text) |last| try params.append(allocator, .{ .key = "last", .value = .{ .string = last } });
    if (opts.exclude_current) try params.append(allocator, .{ .key = "exclude_current", .value = .{ .bool = true } });
    if (opts.include_workers) try params.append(allocator, .{ .key = "include_workers", .value = .{ .bool = true } });
}

fn cmdDecisionCapsule(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const mode = try decision_capsule.Mode.parse(opts.mode);
    if (mode == .validate) {
        const path = opts.file_text orelse opts.path orelse return error.MissingArgValue;
        const text = try std.Io.Dir.cwd().readFileAlloc(defaultIo(), path, allocator, .limited(8 * 1024 * 1024));
        defer allocator.free(text);
        var report = try dcp_schema.validateText(allocator, text);
        defer report.deinit(allocator);
        try writeDcpValidationReport(allocator, report, opts);
        if (!report.valid) return error.InvalidPacket;
        return;
    }

    var paths = try resolveTraceTargetPaths(allocator, sessions_root, opts, true);
    defer freePathList(allocator, &paths);
    var trace = try canonical_trace.parseSessionTrace(allocator, paths.items[0], traceParseOptions(opts));
    defer trace.deinit(allocator);

    const filters = historical_decisions.Filters{
        .decision_id = opts.decision_id,
        .turn_id = opts.turn_id,
        .turn_index = opts.turn_index,
        .skill = opts.skill,
        .contains = opts.contains,
        .regex = opts.regex,
    };

    if (mode == .candidates) {
        const candidates = try decision_capsule.compileCandidates(allocator, trace, filters);
        defer decision_capsule.deinitCandidates(allocator, candidates);
        try writeDecisionCandidateRows(allocator, candidates, opts);
        return;
    }

    var capsule = try decision_capsule.buildCapsuleJson(allocator, trace, paths.items[0], .{
        .filters = filters,
        .outcome_policy = try decision_capsule.OutcomePolicy.parse(opts.outcome_policy_text),
        .strict = opts.strict,
        .include_excerpts = opts.include_excerpts,
        .excerpt_chars = opts.excerpt_chars,
        .source_thread_id = opts.thread_id,
    });
    defer capsule.deinit(allocator);

    if (mode == .anchors) {
        try writeDecisionAnchorRows(allocator, capsule, opts);
        return;
    }

    switch (opts.format) {
        .json => try writeTextOutput(capsule.json, opts.out_path),
        .jsonl => {
            var rendered = std.Io.Writer.Allocating.init(allocator);
            defer rendered.deinit();
            const compact = try dcp_schema.canonicalJsonText(allocator, capsule.json);
            defer allocator.free(compact);
            try rendered.writer.writeAll(compact);
            try rendered.writer.writeByte('\n');
            const text = try rendered.toOwnedSlice();
            defer allocator.free(text);
            try writeTextOutput(text, opts.out_path);
        },
        .markdown => {
            const text = try renderDecisionCapsuleMarkdown(allocator, capsule);
            defer allocator.free(text);
            try writeTextOutput(text, opts.out_path);
        },
        .table, .csv => try writeDecisionCapsuleSummaryRow(allocator, capsule, opts),
        .dot => return error.InvalidFormatForCommand,
    }
}

fn writeDcpValidationReport(allocator: std.mem.Allocator, report: dcp_schema.ValidationReport, opts: Options) !void {
    var row = query.Row.init(allocator);
    defer row.deinit();
    const errors = try joinStringListSep(allocator, report.errors, ",");
    defer allocator.free(errors);
    const warnings = try joinStringListSep(allocator, report.warnings, ",");
    defer allocator.free(warnings);
    const anchors = try joinStringListSep(allocator, report.anchors_available, ",");
    defer allocator.free(anchors);
    try row.putOwnedKey("verdict", .{ .string = if (report.valid) "pass" else "fail" });
    try putOptionalString(&row, "packet_id", report.packet_id);
    try row.putOwnedKey("anchors_available", .{ .string = anchors });
    try row.putOwnedKey("errors", .{ .string = errors });
    try row.putOwnedKey("warnings", .{ .string = warnings });
    var rows = [_]query.Row{row};
    const cols = [_][]const u8{ "verdict", "packet_id", "anchors_available", "errors", "warnings" };
    try output.writeOutput(allocator, opts.format, rows[0..], cols[0..], opts.out_path);
}

fn writeDecisionCandidateRows(allocator: std.mem.Allocator, candidates: []historical_decisions.Candidate, opts: Options) !void {
    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    for (candidates) |candidate| {
        const rejected = try joinStringListSep(allocator, candidate.rejected_routes, ",");
        defer allocator.free(rejected);
        const rationale = try joinStringListSep(allocator, candidate.explicit_rationale, " | ");
        defer allocator.free(rationale);
        const assumptions = try joinStringListSep(allocator, candidate.explicit_assumptions, " | ");
        defer allocator.free(assumptions);
        const evidence = try joinStringListSep(allocator, candidate.evidence_refs, ",");
        defer allocator.free(evidence);
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        try row.putOwnedKey("decision_id", .{ .string = candidate.decision_id });
        try row.putOwnedKey("session_id", .{ .string = candidate.session_id });
        try row.putOwnedKey("turn_index", .{ .int = candidate.turn_index });
        try row.putOwnedKey("turn_id", .{ .string = candidate.turn_id });
        try row.putOwnedKey("question", .{ .string = candidate.question });
        try row.putOwnedKey("selected_route", .{ .string = candidate.selected_route });
        try row.putOwnedKey("rejected_routes", .{ .string = rejected });
        try row.putOwnedKey("explicit_rationale", .{ .string = rationale });
        try row.putOwnedKey("explicit_assumptions", .{ .string = assumptions });
        try row.putOwnedKey("evidence_refs", .{ .string = evidence });
        try row.putOwnedKey("source_kind", .{ .string = candidate.source_kind });
        try row.putOwnedKey("confidence", .{ .float = candidate.confidence.score() });
        try row.putOwnedKey("contamination_flags", .{ .string = candidate.contamination_flags });
        try rows.append(allocator, row);
    }
    const cols = [_][]const u8{ "decision_id", "session_id", "turn_index", "turn_id", "question", "selected_route", "source_kind", "confidence", "contamination_flags" };
    try output.writeOutput(allocator, opts.format, rows.items, cols[0..], opts.out_path);
}

fn writeDecisionAnchorRows(allocator: std.mem.Allocator, capsule: decision_capsule.CapsuleResult, opts: Options) !void {
    var row = query.Row.init(allocator);
    defer row.deinit();
    const selected_anchors = try selectedAnchorNames(allocator, capsule.anchors_available, opts.anchor_text);
    defer freeStringSlice(allocator, selected_anchors);
    const anchors = try joinStringListSep(allocator, selected_anchors, ",");
    defer allocator.free(anchors);
    const warnings = try joinStringListSep(allocator, capsule.warning_codes, ",");
    defer allocator.free(warnings);
    try row.putOwnedKey("packet_id", .{ .string = capsule.packet_id });
    try row.putOwnedKey("decision_id", .{ .string = capsule.decision_id });
    try row.putOwnedKey("anchors_available", .{ .string = anchors });
    try row.putOwnedKey("warning_codes", .{ .string = warnings });
    var rows = [_]query.Row{row};
    const cols = [_][]const u8{ "packet_id", "decision_id", "anchors_available", "warning_codes" };
    try output.writeOutput(allocator, opts.format, rows[0..], cols[0..], opts.out_path);
}

fn selectedAnchorNames(allocator: std.mem.Allocator, available: []const []u8, anchor_text: ?[]const u8) ![]const []u8 {
    const wanted = anchor_text orelse "all";
    if (std.mem.eql(u8, wanted, "all")) return cloneConstStringList(allocator, available);
    const canonical = if (std.mem.eql(u8, wanted, "pre"))
        "pre_decision"
    else if (std.mem.eql(u8, wanted, "post"))
        "post_decision_pre_outcome"
    else if (std.mem.eql(u8, wanted, "outcome"))
        "outcome_aware"
    else
        return error.InvalidModeArg;
    for (available) |name| {
        if (!std.mem.eql(u8, name, canonical)) continue;
        return singletonStringList(allocator, canonical);
    }
    return allocator.alloc([]u8, 0);
}

fn writeDecisionCapsuleSummaryRow(allocator: std.mem.Allocator, capsule: decision_capsule.CapsuleResult, opts: Options) !void {
    var row = query.Row.init(allocator);
    defer row.deinit();
    const anchors = try joinStringListSep(allocator, capsule.anchors_available, ",");
    defer allocator.free(anchors);
    const warnings = try joinStringListSep(allocator, capsule.warning_codes, ",");
    defer allocator.free(warnings);
    try row.putOwnedKey("packet_id", .{ .string = capsule.packet_id });
    try row.putOwnedKey("decision_id", .{ .string = capsule.decision_id });
    try row.putOwnedKey("anchors_available", .{ .string = anchors });
    try row.putOwnedKey("warning_codes", .{ .string = warnings });
    var rows = [_]query.Row{row};
    const cols = [_][]const u8{ "packet_id", "decision_id", "anchors_available", "warning_codes" };
    try output.writeOutput(allocator, opts.format, rows[0..], cols[0..], opts.out_path);
}

fn renderDecisionCapsuleMarkdown(allocator: std.mem.Allocator, capsule: decision_capsule.CapsuleResult) ![]u8 {
    const anchors = try joinStringListSep(allocator, capsule.anchors_available, ", ");
    defer allocator.free(anchors);
    const warnings = try joinStringListSep(allocator, capsule.warning_codes, ", ");
    defer allocator.free(warnings);

    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, capsule.json, .{});
    defer parsed.deinit();
    const packet = switch (parsed.value) {
        .object => |obj| stdJsonObjectField(obj, "decision_context_packet") orelse return error.InvalidPacket,
        else => return error.InvalidPacket,
    };
    const source = stdJsonObjectField(packet, "source");
    const turns = stdJsonObjectField(packet, "turns");
    const episode = stdJsonObjectField(packet, "episode");
    const artifact_state = stdJsonObjectField(packet, "artifact_state");
    const contamination = stdJsonObjectField(packet, "contamination");
    const anchors_obj = stdJsonObjectField(packet, "anchors");

    var rendered = std.Io.Writer.Allocating.init(allocator);
    errdefer rendered.deinit();
    const writer = &rendered.writer;

    try writer.writeAll("# Decision Capsule\n\n");
    try writer.print("- packet_id: `{s}`\n", .{capsule.packet_id});
    try writer.print("- decision_id: `{s}`\n", .{capsule.decision_id});
    try writer.print("- anchors_available: {s}\n", .{if (anchors.len == 0) "none" else anchors});
    try writer.print("- warning_codes: {s}\n", .{if (warnings.len == 0) "none" else warnings});

    try writer.writeAll("\n## Source\n\n");
    if (source) |obj| {
        try writer.print("- session_id: `{s}`\n", .{jsonStringFieldOr(obj, "session_id", "unknown")});
        try writer.print("- root_session_id: `{s}`\n", .{jsonStringFieldOr(obj, "root_session_id", "unknown")});
        try writer.print("- rollout_path: `{s}`\n", .{jsonStringFieldOr(obj, "rollout_path", "unknown")});
        try writer.print("- model: `{s}`\n", .{jsonStringFieldOr(obj, "source_model", "unknown")});
        try writer.print("- codex_version: `{s}`\n", .{jsonStringFieldOr(obj, "source_codex_version", "unknown")});
    } else {
        try writer.writeAll("- unavailable\n");
    }

    try writer.writeAll("\n## Decision\n\n");
    if (turns) |obj| {
        try writer.print("- decision_turn_index: {d}\n", .{jsonIntFieldOr(obj, "decision_turn_index", 0)});
        try writer.print("- decision_turn_id: `{s}`\n", .{jsonStringFieldOr(obj, "decision_turn_id", "unknown")});
        try writer.print("- first_outcome_turn_index: {d}\n", .{jsonIntFieldOr(obj, "first_outcome_turn_index", 0)});
        try writer.print("- source_turn_digest: `{s}`\n", .{jsonStringFieldOr(obj, "source_turn_digest", "unknown")});
    }
    if (episode) |obj| {
        try writer.print("- question: {s}\n", .{jsonStringFieldOr(obj, "question", "unknown")});
        try writer.print("- selected_route: {s}\n", .{jsonStringFieldOr(obj, "selected_route", "unknown")});
    }

    try writer.writeAll("\n## Explicit Evidence\n\n");
    if (episode) |obj| {
        try writeMarkdownStringArray(writer, obj, "explicit_rationale", "explicit_rationale");
        try writeMarkdownStringArray(writer, obj, "explicit_assumptions", "explicit_assumptions");
        try writeMarkdownStringArray(writer, obj, "rejected_routes", "rejected_routes");
        try writeMarkdownStringArray(writer, obj, "evidence_refs", "evidence_refs");
        try writeMarkdownStringArray(writer, obj, "outcome_refs", "outcome_refs");
        try writeMarkdownStringArray(writer, obj, "skills_and_instructions", "skills_and_instructions");
        try writeMarkdownStringArray(writer, obj, "tools_and_artifacts", "tools_and_artifacts");
    } else {
        try writer.writeAll("- unavailable\n");
    }

    try writer.writeAll("\n## Anchors\n\n");
    if (anchors_obj) |obj| {
        try writeMarkdownAnchor(writer, obj, "pre_decision");
        try writeMarkdownAnchor(writer, obj, "post_decision_pre_outcome");
        try writeMarkdownAnchor(writer, obj, "outcome_aware");
    } else {
        try writer.writeAll("- unavailable\n");
    }

    try writer.writeAll("\n## Artifact State\n\n");
    if (artifact_state) |obj| {
        try writer.print("- reconstructability: `{s}`\n", .{jsonStringFieldOr(obj, "reconstructability", "unknown")});
        try writer.print("- cwd: `{s}`\n", .{jsonStringFieldOr(obj, "cwd", "unknown")});
        try writer.print("- repository_root: `{s}`\n", .{jsonStringFieldOr(obj, "repository_root", "unknown")});
        try writer.print("- branch: `{s}`\n", .{jsonStringFieldOr(obj, "branch", "unknown")});
        try writer.print("- head: `{s}`\n", .{jsonStringFieldOr(obj, "head", "unknown")});
    } else {
        try writer.writeAll("- unavailable\n");
    }

    try writer.writeAll("\n## Contamination\n\n");
    if (contamination) |obj| {
        try writer.print("- injected_skill_blocks: {}\n", .{jsonBoolFieldOr(obj, "injected_skill_blocks", false)});
        try writer.print("- developer_system_instructions: {}\n", .{jsonBoolFieldOr(obj, "developer_system_instructions", false)});
        try writer.print("- generated_reports: {}\n", .{jsonBoolFieldOr(obj, "generated_reports", false)});
        try writer.print("- current_audit_prompt: {}\n", .{jsonBoolFieldOr(obj, "current_audit_prompt", false)});
        try writer.print("- quoted_material: {}\n", .{jsonBoolFieldOr(obj, "quoted_material", false)});
    } else {
        try writer.writeAll("- unavailable\n");
    }

    try writer.writeAll("\n## Limitations\n\n");
    try writeMarkdownStringArray(writer, packet, "limitations", "limitations");

    try writer.writeAll("\n## Reproduction\n\n");
    try writer.writeAll("Run `seq decision-capsule --mode validate --file <capsule.json> --format json`.\n");

    return rendered.toOwnedSlice();
}

fn jsonStringFieldOr(obj: std.json.ObjectMap, key: []const u8, fallback: []const u8) []const u8 {
    return stdJsonStringField(obj, key) orelse fallback;
}

fn jsonIntFieldOr(obj: std.json.ObjectMap, key: []const u8, fallback: i64) i64 {
    return stdJsonIntField(obj, key) orelse fallback;
}

fn jsonBoolFieldOr(obj: std.json.ObjectMap, key: []const u8, fallback: bool) bool {
    const value = obj.get(key) orelse return fallback;
    return switch (value) {
        .bool => |flag| flag,
        else => fallback,
    };
}

fn writeMarkdownStringArray(writer: anytype, obj: std.json.ObjectMap, key: []const u8, label: []const u8) !void {
    try writer.print("- {s}:", .{label});
    const value = obj.get(key) orelse {
        try writer.writeAll(" none\n");
        return;
    };
    const items = switch (value) {
        .array => |array| array.items,
        else => {
            try writer.writeAll(" none\n");
            return;
        },
    };
    if (items.len == 0) {
        try writer.writeAll(" none\n");
        return;
    }
    try writer.writeByte('\n');
    for (items) |item| {
        switch (item) {
            .string => |text| try writer.print("  - {s}\n", .{text}),
            else => {},
        }
    }
}

fn writeMarkdownAnchor(writer: anytype, anchors_obj: std.json.ObjectMap, key: []const u8) !void {
    const anchor = stdJsonObjectField(anchors_obj, key) orelse {
        try writer.print("- {s}: unavailable\n", .{key});
        return;
    };
    try writer.print("- {s}: available={}, keep_through_turn_index={d}, drop_last_n_turns={d}, digest=`{s}`\n", .{
        key,
        jsonBoolFieldOr(anchor, "available", false),
        jsonIntFieldOr(anchor, "keep_through_turn_index", 0),
        jsonIntFieldOr(anchor, "drop_last_n_turns", 0),
        jsonStringFieldOr(anchor, "anchor_digest", "unknown"),
    });
}

fn cmdSkillDecisionAudit(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const mode = opts.mode orelse "summary";
    const causality = opts.causality_text orelse "strong";
    if (opts.include_excerpts) {
        printCliError("warning: --include-excerpts may emit bounded transcript excerpts; default output avoids raw transcript text\n", .{});
    }
    if (std.mem.eql(u8, mode, "delta") and opts.session_id == null and opts.path == null) {
        printCliError("error: skill-decision-audit --mode delta requires --session-id or --path\n", .{});
        return error.MissingArgValue;
    }

    var audit = try compileSkillDecisionAudit(allocator, sessions_root, opts);
    defer audit.deinit(allocator);

    if (std.mem.eql(u8, mode, "episodes")) {
        try output.writeOutput(allocator, opts.format, audit.episodes.items, skill_decision_episode_columns[0..], opts.out_path);
        return;
    }
    if (std.mem.eql(u8, mode, "outcomes")) {
        try output.writeOutput(allocator, opts.format, audit.outcomes.items, skill_decision_outcome_columns[0..], opts.out_path);
        return;
    }
    if (std.mem.eql(u8, mode, "clauses")) {
        try output.writeOutput(allocator, opts.format, audit.clauses.items, skill_decision_clause_columns[0..], opts.out_path);
        return;
    }
    if (std.mem.eql(u8, mode, "misses")) {
        try output.writeOutput(allocator, opts.format, audit.misses.items, skill_decision_miss_columns[0..], opts.out_path);
        return;
    }
    if (std.mem.eql(u8, mode, "delta")) {
        try writeSkillDecisionDeltaJson(allocator, opts, audit);
        return;
    }
    if (std.mem.eql(u8, mode, "tune-packet")) {
        try writeSkillDecisionTunePacketJson(allocator, opts, audit, mode, causality);
        return;
    }
    if (opts.format == .markdown) {
        try writeSkillDecisionMarkdown(allocator, opts, audit, mode, causality);
        return;
    }

    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    try rows.append(allocator, try buildSkillDecisionSummaryRow(allocator, opts, audit, mode, causality));
    const cols = [_][]const u8{ "target_skill", "mode", "causality", "candidate_sessions", "activation_sessions", "decision_episodes", "explicit_effect_episodes", "associated_outcome_episodes", "contract_authority", "contract_fingerprint", "matched_cohort_v1" };
    try output.writeOutput(allocator, opts.format, rows.items, cols[0..], opts.out_path);
}

const skill_decision_episode_columns = [_][]const u8{ "decision_id", "episode_id", "session_id", "root_session_id", "worker_session_id", "skill", "skill_version", "contract_fingerprint", "receipt_contract_fingerprint", "contract_binding_status", "contract_authority", "start_timestamp", "end_timestamp", "trigger_observed", "activation_class", "question_preview", "alternatives", "selected_route", "rejected_routes", "clause_refs", "decision_effect", "evidence_strength", "outcome_class", "later_reopened", "later_reversed", "artifact_state", "evidence_refs", "counterevidence_refs", "contamination_flags" };
const skill_decision_outcome_columns = [_][]const u8{ "episode_id", "timestamp", "outcome_kind", "outcome_value", "proof_ref", "artifact_state", "association_method", "distance_turns", "distance_seconds", "causal_claim_allowed" };
const skill_decision_clause_columns = [_][]const u8{ "skill", "contract_fingerprint", "skill_kind", "trigger_id", "clause_id", "expected_routes", "prohibited_routes", "required_artifacts", "success_signals", "failure_signals", "source_path", "contract_authority", "compliance" };
const skill_decision_miss_columns = [_][]const u8{ "decision_id", "session_id", "skill", "trigger_id", "cue_evidence", "window", "confidence", "reason", "receipt_contract_fingerprint", "contract_fingerprint" };

const LoadedSkillDecisionContract = struct {
    parsed: ?skill_contract.ParsedContract = null,
    fingerprint: ?[]u8 = null,
    source_path: ?[]u8 = null,
    authority: []const u8 = "absent",

    fn deinit(self: *LoadedSkillDecisionContract, allocator: std.mem.Allocator) void {
        if (self.parsed) |*parsed| parsed.deinit();
        if (self.fingerprint) |value| allocator.free(value);
        if (self.source_path) |value| allocator.free(value);
    }

    fn contract(self: LoadedSkillDecisionContract) ?skill_contract.Contract {
        return if (self.parsed) |parsed| parsed.contract else null;
    }
};

const SkillDecisionAudit = struct {
    target_skill: []const u8,
    contract: LoadedSkillDecisionContract,
    episodes: std.ArrayList(query.Row) = .empty,
    outcomes: std.ArrayList(query.Row) = .empty,
    clauses: std.ArrayList(query.Row) = .empty,
    misses: std.ArrayList(query.Row) = .empty,
    rows_scanned: i64 = 0,
    sessions_scanned: i64 = 0,
    candidate_sessions: i64 = 0,
    activation_sessions: i64 = 0,

    fn deinit(self: *SkillDecisionAudit, allocator: std.mem.Allocator) void {
        self.contract.deinit(allocator);
        deinitQueryRows(allocator, &self.episodes);
        deinitQueryRows(allocator, &self.outcomes);
        deinitQueryRows(allocator, &self.clauses);
        deinitQueryRows(allocator, &self.misses);
    }
};

fn compileSkillDecisionAudit(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    opts: Options,
) !SkillDecisionAudit {
    var audit = SkillDecisionAudit{
        .target_skill = opts.skill.?,
        .contract = try loadSkillDecisionContract(allocator, opts),
    };
    errdefer audit.deinit(allocator);

    try appendContractClauseRows(allocator, &audit);

    const day_filter = deriveSessionDayPathFilterFromOptions(opts);
    var paths = try resolveOrchestrationInputPaths(allocator, sessions_root, opts, day_filter);
    defer freePathList(allocator, &paths);
    const exclude_path = if (opts.exclude_current) try resolveCurrentSessionPathForExclusionLocal(allocator, sessions_root) else null;
    defer if (exclude_path) |path| allocator.free(path);
    const repo_scope = if (opts.repo_text) |repo| try toAbsolutePath(allocator, repo) else null;
    defer if (repo_scope) |repo| allocator.free(repo);
    const workdir_scope = if (opts.workdir_text) |workdir| try toAbsolutePath(allocator, workdir) else null;
    defer if (workdir_scope) |workdir| allocator.free(workdir);

    var activation_sessions = std.StringHashMap(void).init(allocator);
    defer activation_sessions.deinit();

    for (paths.items) |path| {
        if (exclude_path) |excluded| if (std.mem.eql(u8, path, excluded)) continue;
        const content = try readFileAllocOrSkip(allocator, path);
        if (content == null) continue;
        defer allocator.free(content.?);
        if (!try sessionContentMatchesSkillDecisionScope(allocator, path, repo_scope, workdir_scope)) continue;
        audit.candidate_sessions += 1;
        audit.sessions_scanned += 1;
        audit.rows_scanned += countNonEmptyLines(content.?);

        const session_id = inferSessionIdFromPath(path);
        if (try sessionHasSkillActivation(allocator, path, content.?, audit.target_skill, opts)) {
            try activation_sessions.put(session_id, {});
        }
        try collectReceiptEpisodesForSession(allocator, &audit, path, content.?, opts);
        try collectExplicitRouteEpisodesForSession(allocator, &audit, path, content.?, opts);
    }
    audit.activation_sessions = @intCast(activation_sessions.count());
    try finalizeContractClauseCompliance(&audit);
    return audit;
}

fn sessionContentMatchesSkillDecisionScope(
    allocator: std.mem.Allocator,
    path: []const u8,
    repo_scope: ?[]const u8,
    workdir_scope: ?[]const u8,
) !bool {
    if (repo_scope == null and workdir_scope == null) return true;
    var parsed = canonical_trace.parseSessionSummaryTrace(allocator, path, .{}) catch return false;
    defer parsed.deinit(allocator);
    if (workdir_scope) |scope| {
        if (sessionTraceMatchesWorkdirScope(allocator, parsed, scope)) return true;
    }
    if (repo_scope) |scope| {
        if (try resolveTraceMatchesRepo(allocator, scope, parsed)) return true;
    }
    return false;
}

fn sessionTraceMatchesWorkdirScope(
    allocator: std.mem.Allocator,
    parsed: canonical_trace.CanonicalSessionTrace,
    workdir_scope: []const u8,
) bool {
    if (parsed.session.cwd) |cwd| {
        const normalized = normalizeRepoMatchPath(allocator, cwd) catch return false;
        defer allocator.free(normalized);
        if (std.mem.eql(u8, normalized, workdir_scope)) return true;
    }
    for (parsed.tools.items) |tool| {
        if (tool.cwd) |cwd| {
            const normalized = normalizeRepoMatchPath(allocator, cwd) catch continue;
            defer allocator.free(normalized);
            if (std.mem.eql(u8, normalized, workdir_scope)) return true;
        }
    }
    return false;
}

fn loadSkillDecisionContract(allocator: std.mem.Allocator, opts: Options) !LoadedSkillDecisionContract {
    if (opts.contract_text) |path| {
        return loadSkillDecisionContractPath(allocator, path, opts.contract_authority_text orelse "explicit");
    }
    if (opts.skill_root_text) |root| {
        const root_abs = try toAbsolutePath(allocator, root);
        defer allocator.free(root_abs);
        const yaml_path = try std.fs.path.join(allocator, &.{ root_abs, opts.skill.?, "references", "decision-contract.yaml" });
        defer allocator.free(yaml_path);
        if (fileExists(yaml_path)) return loadSkillDecisionContractPath(allocator, yaml_path, "explicit");
        const json_path = try std.fs.path.join(allocator, &.{ root_abs, opts.skill.?, "references", "decision-contract.json" });
        defer allocator.free(json_path);
        if (fileExists(json_path)) return loadSkillDecisionContractPath(allocator, json_path, "explicit");
    }
    return .{};
}

fn loadSkillDecisionContractPath(allocator: std.mem.Allocator, path: []const u8, authority: []const u8) !LoadedSkillDecisionContract {
    const absolute = try toAbsolutePath(allocator, path);
    errdefer allocator.free(absolute);
    const content = try std.Io.Dir.cwd().readFileAlloc(defaultIo(), absolute, allocator, .limited(4 * 1024 * 1024));
    defer allocator.free(content);
    var parsed = try skill_contract.parseText(allocator, content);
    errdefer parsed.deinit();
    const report = try skill_contract.validateParsed(allocator, parsed.contract);
    defer report.deinit(allocator);
    if (!report.valid) return error.InvalidSpec;
    return .{
        .parsed = parsed,
        .fingerprint = if (report.fingerprint) |fp| try allocator.dupe(u8, fp) else null,
        .source_path = absolute,
        .authority = authority,
    };
}

fn fileExists(path: []const u8) bool {
    const file = std.Io.Dir.openFileAbsolute(defaultIo(), path, .{}) catch return false;
    file.close(defaultIo());
    return true;
}

fn resolveCurrentSessionPathForExclusionLocal(allocator: std.mem.Allocator, sessions_root: []const u8) ![]u8 {
    const current_id = try currentSessionIdFromEnv(allocator);
    defer allocator.free(current_id);
    var paths = try collectJsonlPaths(allocator, sessions_root, null);
    defer freePathList(allocator, &paths);
    for (paths.items) |path| {
        if (std.mem.containsAtLeast(u8, path, 1, current_id)) return allocator.dupe(u8, path);
    }
    return allocator.dupe(u8, "");
}

fn countNonEmptyLines(text: []const u8) i64 {
    var count: i64 = 0;
    var it = std.mem.splitScalar(u8, text, '\n');
    while (it.next()) |line| {
        if (std.mem.trim(u8, line, " \t\r\n").len > 0) count += 1;
    }
    return count;
}

fn sessionHasSkillActivation(
    allocator: std.mem.Allocator,
    path: []const u8,
    content: []const u8,
    skill: []const u8,
    opts: Options,
) !bool {
    const mentions = try datasets.skill_mentions.parseJsonl(allocator, path, content, .{});
    defer datasets.skill_mentions.freeRows(allocator, mentions);
    for (mentions) |row| {
        if (!timestampSatisfiesBounds(row.timestamp, opts)) continue;
        if (!eqlIgnoreCaseAscii(row.skill, skill)) continue;
        const kind = skill_decision_signals.classifySkillMention(row.role, row.types);
        if (kind == .explicit_user_activation or kind == .assistant_declared_activation) return true;
    }
    return false;
}

fn collectReceiptEpisodesForSession(
    allocator: std.mem.Allocator,
    audit: *SkillDecisionAudit,
    path: []const u8,
    content: []const u8,
    opts: Options,
) !void {
    const messages = try datasets.messages.parseJsonl(allocator, path, content, .{
        .strip_skill_blocks = true,
        .dedupe_by_role_and_text = true,
    });
    defer datasets.messages.freeRows(allocator, messages);
    for (messages) |row| {
        if (!timestampSatisfiesBounds(row.timestamp, opts)) continue;
        if (std.mem.indexOf(u8, row.text, "skill_decision_receipt") == null) continue;
        var parsed = skill_decision_receipt.parseText(allocator, row.text) catch continue;
        defer parsed.deinit();
        if (!eqlIgnoreCaseAscii(parsed.receipt.skill, audit.target_skill)) continue;
        const validation = try skill_decision_receipt.validateParsed(allocator, parsed.receipt, audit.target_skill, audit.contract.contract());
        defer validation.deinit(allocator);
        if (!validation.valid) {
            if (hasReceiptContractBindingFailure(validation.codes)) {
                try appendSkillDecisionReceiptBindingMiss(allocator, &audit.misses, audit, path, row.timestamp, parsed.receipt, validation.codes);
            }
            continue;
        }

        const decision_id = if (parsed.receipt.decision_id.len > 0) parsed.receipt.decision_id else "unknown";
        const episode_id = try std.fmt.allocPrint(allocator, "{s}:receipt:{s}", .{ inferSessionIdFromPath(path), decision_id });
        defer allocator.free(episode_id);
        const outcome = firstOutcomeAfter(messages, row.timestamp);
        const alternatives = try joinStringListSep(allocator, parsed.receipt.alternatives_considered, ",");
        defer allocator.free(alternatives);
        const rejected_routes = try joinStringListSep(allocator, parsed.receipt.rejected_routes, ",");
        defer allocator.free(rejected_routes);
        const clause_refs = try joinStringListSep(allocator, parsed.receipt.clause_refs, ",");
        defer allocator.free(clause_refs);
        try appendSkillDecisionEpisodeRow(allocator, &audit.episodes, audit, .{
            .decision_id = decision_id,
            .episode_id = episode_id,
            .path = path,
            .session_id = inferSessionIdFromPath(path),
            .start_timestamp = row.timestamp,
            .end_timestamp = row.timestamp,
            .skill_version = parsed.receipt.skill_version,
            .receipt_contract_fingerprint = parsed.receipt.skill_contract_fingerprint,
            .contract_binding_status = if (audit.contract.contract() != null) "matched" else "unbound",
            .question_preview = parsed.receipt.question,
            .alternatives = alternatives,
            .selected_route = parsed.receipt.selected_route,
            .rejected_routes = rejected_routes,
            .clause_refs = clause_refs,
            .decision_effect = if (parsed.receipt.rejected_routes.len > 0) "explicit_route_change" else "unknown",
            .evidence_strength = "explicit",
            .outcome_class = outcome.kind,
            .artifact_state = if (parsed.receipt.artifact_state_present) "present" else "unknown",
            .evidence_refs = "sdr",
            .contamination_flags = skill_decision_signals.contaminationFlags(row.text),
        });
        if (outcome.kind.len > 0 and !std.mem.eql(u8, outcome.kind, "unknown")) {
            try appendSkillDecisionOutcomeRow(allocator, &audit.outcomes, episode_id, outcome, "same_session_after_episode", "not_proven");
        }
    }
}

fn hasReceiptContractBindingFailure(codes: []const []const u8) bool {
    return skill_decision_receipt.containsCode(codes, "missing_skill_contract_fingerprint") or
        skill_decision_receipt.containsCode(codes, "skill_contract_fingerprint_mismatch");
}

fn appendSkillDecisionReceiptBindingMiss(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(query.Row),
    audit: *SkillDecisionAudit,
    path: []const u8,
    timestamp: ?[]const u8,
    receipt: skill_decision_receipt.Receipt,
    codes: []const []const u8,
) !void {
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    try row.putOwnedKey("decision_id", .{ .string = receipt.decision_id });
    try row.putOwnedKey("session_id", .{ .string = inferSessionIdFromPath(path) });
    try row.putOwnedKey("skill", .{ .string = audit.target_skill });
    try row.putOwnedKey("trigger_id", .{ .string = if (receipt.trigger_refs.len > 0) receipt.trigger_refs[0] else "" });
    try row.putOwnedKey("cue_evidence", .{ .string = "structured_sdr" });
    try putOptionalString(&row, "window", timestamp);
    try row.putOwnedKey("confidence", .{ .string = "explicit" });
    try row.putOwnedKey("reason", .{ .string = if (skill_decision_receipt.containsCode(codes, "skill_contract_fingerprint_mismatch")) "skill_contract_fingerprint_mismatch" else "missing_skill_contract_fingerprint" });
    try row.putOwnedKey("receipt_contract_fingerprint", if (receipt.skill_contract_fingerprint.len > 0) .{ .string = receipt.skill_contract_fingerprint } else .null);
    try row.putOwnedKey("contract_fingerprint", if (audit.contract.fingerprint) |fp| .{ .string = fp } else .null);
    try out.append(allocator, row);
}

fn collectExplicitRouteEpisodesForSession(
    allocator: std.mem.Allocator,
    audit: *SkillDecisionAudit,
    path: []const u8,
    content: []const u8,
    opts: Options,
) !void {
    const messages = try datasets.messages.parseJsonl(allocator, path, content, .{
        .strip_skill_blocks = true,
        .dedupe_by_role_and_text = true,
    });
    defer datasets.messages.freeRows(allocator, messages);
    for (messages, 0..) |row, idx| {
        if (!timestampSatisfiesBounds(row.timestamp, opts)) continue;
        if (!std.mem.eql(u8, row.role, "assistant")) continue;
        if (std.mem.indexOf(u8, row.text, "skill_decision_receipt") != null) continue;
        if (!containsDollarSkillLocal(row.text, audit.target_skill) and !containsBareSkillReferenceLocal(row.text, audit.target_skill)) continue;
        const selected = extractStructuredRouteValue(row.text, "selected_route") orelse uniqueContractRouteMatch(audit.contract.contract(), row.text) orelse continue;
        const rejected = extractStructuredRouteValue(row.text, "rejected_route") orelse "";
        const decision_id = try std.fmt.allocPrint(allocator, "explicit-{d}", .{idx + 1});
        defer allocator.free(decision_id);
        const episode_id = try std.fmt.allocPrint(allocator, "{s}:explicit:{d}", .{ inferSessionIdFromPath(path), idx + 1 });
        defer allocator.free(episode_id);
        const outcome = firstOutcomeAfter(messages, row.timestamp);
        const clause_refs = try inferredClauseRefsForRoute(allocator, audit.contract.contract(), selected);
        defer allocator.free(clause_refs);
        try appendSkillDecisionEpisodeRow(allocator, &audit.episodes, audit, .{
            .decision_id = decision_id,
            .episode_id = episode_id,
            .path = path,
            .session_id = inferSessionIdFromPath(path),
            .start_timestamp = row.timestamp,
            .end_timestamp = row.timestamp,
            .activation_class = "assistant_declared_activation",
            .question_preview = "unknown",
            .selected_route = selected,
            .rejected_routes = rejected,
            .clause_refs = clause_refs,
            .decision_effect = if (rejected.len > 0) "explicit_route_change" else "unknown",
            .evidence_strength = "explicit",
            .outcome_class = outcome.kind,
            .artifact_state = "unknown",
            .evidence_refs = "assistant_route_attribution",
            .contamination_flags = skill_decision_signals.contaminationFlags(row.text),
        });
        if (outcome.kind.len > 0 and !std.mem.eql(u8, outcome.kind, "unknown")) {
            try appendSkillDecisionOutcomeRow(allocator, &audit.outcomes, episode_id, outcome, "same_session_after_episode", "not_proven");
        }
    }
}

