    try row.putOwnedKey("receipt_contract_fingerprint", if (input.receipt_contract_fingerprint.len > 0) .{ .string = input.receipt_contract_fingerprint } else .null);
    try row.putOwnedKey("contract_binding_status", .{ .string = input.contract_binding_status });
    try row.putOwnedKey("contract_authority", .{ .string = audit.contract.authority });
    try putOptionalString(&row, "start_timestamp", input.start_timestamp);
    try putOptionalString(&row, "end_timestamp", input.end_timestamp);
    try row.putOwnedKey("trigger_observed", .{ .bool = false });
    try row.putOwnedKey("activation_class", .{ .string = input.activation_class });
    try row.putOwnedKey("question_preview", .{ .string = if (input.question_preview.len > 0) input.question_preview else "unknown" });
    try row.putOwnedKey("alternatives", .{ .string = input.alternatives });
    try row.putOwnedKey("selected_route", .{ .string = input.selected_route });
    try row.putOwnedKey("rejected_routes", .{ .string = input.rejected_routes });
    try row.putOwnedKey("clause_refs", .{ .string = input.clause_refs });
    try row.putOwnedKey("decision_effect", .{ .string = input.decision_effect });
    try row.putOwnedKey("evidence_strength", .{ .string = input.evidence_strength });
    try row.putOwnedKey("outcome_class", .{ .string = input.outcome_class });
    try row.putOwnedKey("later_reopened", .{ .bool = std.mem.eql(u8, input.outcome_class, "review_reopen") });
    try row.putOwnedKey("later_reversed", .{ .bool = std.mem.eql(u8, input.outcome_class, "reversal") });
    try row.putOwnedKey("artifact_state", .{ .string = input.artifact_state });
    try row.putOwnedKey("evidence_refs", .{ .string = input.evidence_refs });
    try row.putOwnedKey("counterevidence_refs", .{ .string = input.counterevidence_refs });
    try row.putOwnedKey("contamination_flags", .{ .string = input.contamination_flags });
    try out.append(allocator, row);
}

const OutcomeSignal = struct {
    kind: []const u8 = "unknown",
    timestamp: ?[]const u8 = null,
    value: []const u8 = "",
};

fn firstOutcomeAfter(messages: []const datasets.messages.MessageRow, timestamp: ?[]const u8) OutcomeSignal {
    const start = timestamp orelse "";
    for (messages) |row| {
        const ts = row.timestamp orelse "";
        if (start.len > 0 and std.mem.order(u8, ts, start) != .gt) continue;
        if (containsIgnoreCaseAscii(row.text, "review reopen")) return .{ .kind = "review_reopen", .timestamp = row.timestamp, .value = "review_reopen" };
        if (containsIgnoreCaseAscii(row.text, "reversal")) return .{ .kind = "reversal", .timestamp = row.timestamp, .value = "reversal" };
        if (containsIgnoreCaseAscii(row.text, "proof pass") or containsIgnoreCaseAscii(row.text, "validation pass")) return .{ .kind = "proof_pass", .timestamp = row.timestamp, .value = "pass" };
        if (containsIgnoreCaseAscii(row.text, "proof fail") or containsIgnoreCaseAscii(row.text, "validation fail")) return .{ .kind = "proof_fail", .timestamp = row.timestamp, .value = "fail" };
        if (containsIgnoreCaseAscii(row.text, "commit")) return .{ .kind = "commit", .timestamp = row.timestamp, .value = "commit" };
        if (containsIgnoreCaseAscii(row.text, "push")) return .{ .kind = "push", .timestamp = row.timestamp, .value = "push" };
        if (containsIgnoreCaseAscii(row.text, "pull request") or containsIgnoreCaseAscii(row.text, "PR #")) return .{ .kind = "pr", .timestamp = row.timestamp, .value = "pr" };
        if (containsIgnoreCaseAscii(row.text, "closure")) return .{ .kind = "closure", .timestamp = row.timestamp, .value = "closure" };
    }
    return .{};
}

fn appendSkillDecisionOutcomeRow(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(query.Row),
    episode_id: []const u8,
    outcome: OutcomeSignal,
    association_method: []const u8,
    causal_claim: []const u8,
) !void {
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    try row.putOwnedKey("episode_id", .{ .string = episode_id });
    try putOptionalString(&row, "timestamp", outcome.timestamp);
    try row.putOwnedKey("outcome_kind", .{ .string = outcome.kind });
    try row.putOwnedKey("outcome_value", .{ .string = outcome.value });
    try row.putOwnedKey("proof_ref", .null);
    try row.putOwnedKey("artifact_state", .{ .string = "unknown" });
    try row.putOwnedKey("association_method", .{ .string = association_method });
    try row.putOwnedKey("distance_turns", .null);
    try row.putOwnedKey("distance_seconds", .null);
    try row.putOwnedKey("causal_claim_allowed", .{ .bool = std.mem.eql(u8, causal_claim, "allowed") });
    try out.append(allocator, row);
}

fn appendContractClauseRows(allocator: std.mem.Allocator, audit: *SkillDecisionAudit) !void {
    const contract = audit.contract.contract() orelse return;
    for (contract.clauses) |clause| {
        const trigger_refs = try joinStringListSep(allocator, clause.trigger_refs, ",");
        defer allocator.free(trigger_refs);
        const expected = try joinStringListSep(allocator, clause.expected_routes, ",");
        defer allocator.free(expected);
        const prohibited = try joinStringListSep(allocator, clause.prohibited_routes, ",");
        defer allocator.free(prohibited);
        const required = try joinStringListSep(allocator, clause.required_artifacts, ",");
        defer allocator.free(required);
        const success = try joinStringListSep(allocator, clause.success_signals, ",");
        defer allocator.free(success);
        const failure = try joinStringListSep(allocator, clause.failure_signals, ",");
        defer allocator.free(failure);
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        try row.putOwnedKey("skill", .{ .string = audit.target_skill });
        try row.putOwnedKey("contract_fingerprint", if (audit.contract.fingerprint) |fp| .{ .string = fp } else .null);
        try row.putOwnedKey("skill_kind", .{ .string = contract.skill_kind });
        try row.putOwnedKey("trigger_id", .{ .string = trigger_refs });
        try row.putOwnedKey("clause_id", .{ .string = clause.clause_id });
        try row.putOwnedKey("expected_routes", .{ .string = expected });
        try row.putOwnedKey("prohibited_routes", .{ .string = prohibited });
        try row.putOwnedKey("required_artifacts", .{ .string = required });
        try row.putOwnedKey("success_signals", .{ .string = success });
        try row.putOwnedKey("failure_signals", .{ .string = failure });
        try row.putOwnedKey("source_path", if (audit.contract.source_path) |path| .{ .string = path } else .null);
        try row.putOwnedKey("contract_authority", .{ .string = audit.contract.authority });
        try row.putOwnedKey("compliance", .{ .string = "never_exercised" });
        try audit.clauses.append(allocator, row);
    }
}

fn finalizeContractClauseCompliance(audit: *SkillDecisionAudit) !void {
    for (audit.clauses.items) |*clause_row| {
        const clause_id = scalarString(clause_row.valueOrNull("clause_id")) orelse continue;
        var status: []const u8 = "never_exercised";
        for (audit.episodes.items) |episode| {
            const refs = scalarString(episode.valueOrNull("clause_refs")) orelse "";
            if (refs.len == 0 or !commaSeparatedListContainsToken(refs, clause_id)) continue;
            const effect = scalarString(episode.valueOrNull("decision_effect")) orelse "";
            status = if (std.mem.eql(u8, effect, "contrary_to_contract")) "violated" else "followed";
            break;
        }
        try clause_row.putOwnedKey("compliance", .{ .string = status });
    }
}

fn commaSeparatedListContainsToken(list: []const u8, needle: []const u8) bool {
    var it = std.mem.splitScalar(u8, list, ',');
    while (it.next()) |raw| {
        const token = std.mem.trim(u8, raw, " \t\r\n");
        if (std.mem.eql(u8, token, needle)) return true;
    }
    return false;
}

fn buildSkillDecisionSummaryRow(
    allocator: std.mem.Allocator,
    opts: Options,
    audit: SkillDecisionAudit,
    mode: []const u8,
    causality: []const u8,
) !query.Row {
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    try row.putOwnedKey("target_skill", .{ .string = opts.skill.? });
    try row.putOwnedKey("mode", .{ .string = mode });
    try row.putOwnedKey("causality", .{ .string = causality });
    try row.putOwnedKey("candidate_sessions", .{ .int = audit.candidate_sessions });
    try row.putOwnedKey("activation_sessions", .{ .int = audit.activation_sessions });
    try row.putOwnedKey("decision_episodes", .{ .int = @intCast(audit.episodes.items.len) });
    try row.putOwnedKey("explicit_effect_episodes", .{ .int = countExplicitEffectEpisodes(audit.episodes.items) });
    try row.putOwnedKey("associated_outcome_episodes", .{ .int = @intCast(audit.outcomes.items.len) });
    try row.putOwnedKey("contract_authority", .{ .string = audit.contract.authority });
    try row.putOwnedKey("contract_fingerprint", if (audit.contract.fingerprint) |fp| .{ .string = fp } else .null);
    try row.putOwnedKey("matched_cohort_v1", .{ .bool = false });
    return row;
}

fn countExplicitEffectEpisodes(rows: []const query.Row) i64 {
    var count: i64 = 0;
    for (rows) |row| {
        const strength = scalarString(row.valueOrNull("evidence_strength")) orelse "";
        const effect = scalarString(row.valueOrNull("decision_effect")) orelse "";
        if (std.mem.eql(u8, strength, "explicit") and !std.mem.eql(u8, effect, "unknown") and !std.mem.eql(u8, effect, "no_visible_delta")) count += 1;
    }
    return count;
}

fn countEpisodesWithEffect(rows: []const query.Row, effect: []const u8) i64 {
    var count: i64 = 0;
    for (rows) |row| {
        if (scalarStringEq(row.valueOrNull("decision_effect"), effect)) count += 1;
    }
    return count;
}

fn countOutcomes(rows: []const query.Row, kind: []const u8) i64 {
    var count: i64 = 0;
    for (rows) |row| {
        if (scalarStringEq(row.valueOrNull("outcome_kind"), kind)) count += 1;
    }
    return count;
}

fn writeSkillDecisionTunePacketJson(
    allocator: std.mem.Allocator,
    opts: Options,
    audit: SkillDecisionAudit,
    mode: []const u8,
    causality: []const u8,
) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    const cursor_json = try skillDecisionCursorJsonAlloc(allocator, opts, audit);
    defer allocator.free(cursor_json);
    try writer.writeAll("{\n  \"skill_tuning_evidence\": {\n    \"packet_version\": \"STE-v1\",\n    \"target_skill\": ");
    try output.writeJsonString(writer, opts.skill.?);
    try writer.writeAll(",\n    \"target_kind\": ");
    try output.writeJsonString(writer, if (audit.contract.contract()) |contract| contract.skill_kind else "unknown");
    try writer.writeAll(",\n    \"skill_versions_observed\": [],\n    \"contract\": {\n      \"authority\": ");
    try output.writeJsonString(writer, audit.contract.authority);
    try writer.writeAll(",\n      \"fingerprint\": ");
    if (audit.contract.fingerprint) |fp| try output.writeJsonString(writer, fp) else try writer.writeAll("null");
    try writer.writeAll(",\n      \"clause_ids\": [");
    for (audit.clauses.items, 0..) |row, idx| {
        if (idx > 0) try writer.writeAll(", ");
        try output.writeJsonString(writer, scalarString(row.valueOrNull("clause_id")) orelse "");
    }
    try writer.writeAll(
        \\]
        \\    },
        \\    "window": {
        \\      "since":
    );
    try writeOptionalJsonString(writer, opts.since);
    try writer.writeAll(",\n      \"until\": ");
    try writeOptionalJsonString(writer, opts.until);
    try writer.writeAll(",\n      \"repo\": ");
    try writeOptionalJsonString(writer, opts.repo_text);
    try writer.writeAll(",\n      \"workdir\": ");
    try writeOptionalJsonString(writer, opts.workdir_text);
    try writer.print(
        \\,
        \\      "current_session_excluded": {}
        \\    }},
        \\    "denominator": {{
        \\      "candidate_sessions": {d},
        \\      "activation_sessions": {d},
        \\      "decision_episodes": {d},
        \\      "explicit_effect_episodes": {d},
        \\      "associated_outcome_episodes": {d},
        \\      "matched_control_episodes": 0
        \\    }},
        \\    "trigger_quality": {{
        \\      "trigger_present": 0,
        \\      "correctly_activated": 0,
        \\      "missed": 0,
        \\      "false_activations": 0,
        \\      "ambiguous": 0
        \\    }},
        \\    "decision_influence": {{
        \\      "explicit_route_changes": {d},
        \\      "prevented_actions": {d},
        \\      "scope_narrowings": {d},
        \\      "proof_changes": {d},
        \\      "escalations_or_blocks": {d},
        \\      "reinforced_existing": {d},
        \\      "no_visible_delta": {d},
        \\      "contrary_to_contract": {d},
        \\      "unknown": {d}
        \\    }},
        \\    "contract_compliance": {{
        \\      "followed": {{}},
        \\      "violated": {{}},
        \\      "ambiguous": {{}},
        \\      "never_exercised": [
    , .{
        opts.exclude_current,
        audit.candidate_sessions,
        audit.activation_sessions,
        audit.episodes.items.len,
        countExplicitEffectEpisodes(audit.episodes.items),
        audit.outcomes.items.len,
        countEpisodesWithEffect(audit.episodes.items, "explicit_route_change"),
        countEpisodesWithEffect(audit.episodes.items, "prevented_action"),
        countEpisodesWithEffect(audit.episodes.items, "narrowed_scope"),
        countEpisodesWithEffect(audit.episodes.items, "added_or_changed_proof"),
        countEpisodesWithEffect(audit.episodes.items, "escalated_or_blocked"),
        countEpisodesWithEffect(audit.episodes.items, "reinforced_existing_choice"),
        countEpisodesWithEffect(audit.episodes.items, "no_visible_delta"),
        countEpisodesWithEffect(audit.episodes.items, "contrary_to_contract"),
        countEpisodesWithEffect(audit.episodes.items, "unknown"),
    });
    var first_never = true;
    for (audit.clauses.items) |row| {
        if (!scalarStringEq(row.valueOrNull("compliance"), "never_exercised")) continue;
        if (!first_never) try writer.writeAll(", ");
        first_never = false;
        try output.writeJsonString(writer, scalarString(row.valueOrNull("clause_id")) orelse "");
    }
    try writer.print(
        \\]
        \\    }},
        \\    "outcomes": {{
        \\      "first_pass_success": 0,
        \\      "proof_pass": {d},
        \\      "proof_fail": {d},
        \\      "review_clean": 0,
        \\      "review_reopens": {d},
        \\      "reversals": {d},
        \\      "blocked_correctly": 0,
        \\      "unknown": 0
        \\    }},
        \\    "workarounds": [],
        \\    "recurrent_gap_signatures": [],
        \\    "exemplars": {{
        \\      "positive": [],
        \\      "negative": []
        \\    }},
        \\    "evidence_limitations": [
        \\      "Outcome association is temporal/artifact-adjacent evidence only; outcome causality is not proven.",
        \\      "Natural-language episodes are limited to explicit skill plus route markers."
        \\    ],
        \\    "cursor_end": {s}
        \\  }},
        \\  "seq_receipt": {{
        \\    "receipt_version": "SEQ-R1",
        \\    "command": "skill-decision-audit",
        \\    "outcome": "success",
        \\    "exit_code": 0,
        \\    "rows_scanned": {d},
        \\    "sessions_scanned": {d},
        \\    "episodes_emitted": {d},
        \\    "contract_fingerprint":
    , .{
        countOutcomes(audit.outcomes.items, "proof_pass"),
        countOutcomes(audit.outcomes.items, "proof_fail"),
        countOutcomes(audit.outcomes.items, "review_reopen"),
        countOutcomes(audit.outcomes.items, "reversal"),
        cursor_json,
        audit.rows_scanned,
        audit.sessions_scanned,
        audit.episodes.items.len,
    });
    if (audit.contract.fingerprint) |fp| try output.writeJsonString(writer, fp) else try writer.writeAll("null");
    try writer.writeAll(",\n    \"cursor_end\": ");
    try writer.writeAll(cursor_json);
    try writer.writeAll(",\n    \"warning_codes\": []\n  },\n  \"metadata\": {\n    \"mode\": ");
    try output.writeJsonString(writer, mode);
    try writer.writeAll(",\n    \"causality\": ");
    try output.writeJsonString(writer, causality);
    try writer.writeAll("\n  }\n}\n");
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, opts.out_path);
}

fn writeSkillDecisionDeltaJson(allocator: std.mem.Allocator, opts: Options, audit: SkillDecisionAudit) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    const cursor_json = try skillDecisionCursorJsonAlloc(allocator, opts, audit);
    defer allocator.free(cursor_json);
    const cursor_status = skillDecisionCursorStatus(opts, audit);
    const counts = try skillDecisionDeltaCounts(allocator, opts, audit, cursor_status);
    try writer.writeAll("{\n  \"skill_decision_delta\": {\n    \"delta_version\": \"SDD-v1\",\n    \"target_skill\": ");
    try output.writeJsonString(writer, opts.skill.?);
    try writer.writeAll(",\n    \"session\": ");
    const session_ref: ?[]const u8 = if (opts.session_id) |id| id else opts.path;
    try writeOptionalJsonString(writer, session_ref);
    try writer.writeAll(",\n    \"cursor_start\": ");
    try writeOptionalJsonString(writer, opts.since_cursor_text);
    try writer.writeAll(",\n    \"cursor_status\": ");
    try output.writeJsonString(writer, cursor_status);
    try writer.print(
        \\,
        \\    "cursor_end": {s},
        \\    "state": "scanned",
        \\    "new_signals": {d},
        \\    "new_episodes": {d},
        \\    "new_clause_events": {d},
        \\    "new_outcomes": {d},
        \\    "decision_relevant": {},
        \\    "reason": "{s}"
        \\  }}
        \\}}
        \\
    , .{ cursor_json, counts.new_signals, counts.new_episodes, counts.new_clause_events, counts.new_outcomes, counts.decision_relevant, counts.reason });
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, opts.out_path);
}

const SkillDecisionDeltaCounts = struct {
    new_signals: i64,
    new_episodes: i64,
    new_clause_events: i64,
    new_outcomes: i64,
    decision_relevant: bool,
    reason: []const u8,
};

fn skillDecisionDeltaCounts(
    allocator: std.mem.Allocator,
    opts: Options,
    audit: SkillDecisionAudit,
    cursor_status: []const u8,
) !SkillDecisionDeltaCounts {
    if (opts.since_cursor_text == null or !std.mem.eql(u8, cursor_status, "valid")) {
        const reason: []const u8 = if (opts.since_cursor_text == null) "initial bounded scan" else "cursor invalidated full bounded rescan";
        return .{
            .new_signals = audit.rows_scanned,
            .new_episodes = @intCast(audit.episodes.items.len),
            .new_clause_events = @intCast(audit.clauses.items.len),
            .new_outcomes = @intCast(audit.outcomes.items.len),
            .decision_relevant = audit.episodes.items.len > 0 or audit.outcomes.items.len > 0,
            .reason = reason,
        };
    }

    const cursor_text = opts.since_cursor_text.?;
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, cursor_text, .{}) catch {
        return .{
            .new_signals = audit.rows_scanned,
            .new_episodes = @intCast(audit.episodes.items.len),
            .new_clause_events = @intCast(audit.clauses.items.len),
            .new_outcomes = @intCast(audit.outcomes.items.len),
            .decision_relevant = audit.episodes.items.len > 0 or audit.outcomes.items.len > 0,
            .reason = "unparseable cursor full bounded rescan",
        };
    };
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |obj| obj,
        else => return .{
            .new_signals = audit.rows_scanned,
            .new_episodes = @intCast(audit.episodes.items.len),
            .new_clause_events = @intCast(audit.clauses.items.len),
            .new_outcomes = @intCast(audit.outcomes.items.len),
            .decision_relevant = audit.episodes.items.len > 0 or audit.outcomes.items.len > 0,
            .reason = "unparseable cursor full bounded rescan",
        },
    };
    const last_offset = stdJsonIntField(root, "last_event_offset") orelse 0;
    const last_timestamp = stdJsonStringField(root, "last_timestamp");
    const new_signals = @max(audit.rows_scanned - last_offset, 0);
    if (new_signals == 0) {
        return .{
            .new_signals = 0,
            .new_episodes = 0,
            .new_clause_events = 0,
            .new_outcomes = 0,
            .decision_relevant = false,
            .reason = "cursor-filtered bounded rescan",
        };
    }
    const new_episodes = countRowsAfterTimestamp(audit.episodes.items, "start_timestamp", last_timestamp);
    const new_outcomes = countRowsAfterTimestamp(audit.outcomes.items, "timestamp", last_timestamp);
    return .{
        .new_signals = new_signals,
        .new_episodes = new_episodes,
        .new_clause_events = new_episodes,
        .new_outcomes = new_outcomes,
        .decision_relevant = new_episodes > 0 or new_outcomes > 0,
        .reason = "cursor-filtered bounded rescan",
    };
}

fn countRowsAfterTimestamp(rows: []const query.Row, field: []const u8, since: ?[]const u8) i64 {
    const timestamp = since orelse return @intCast(rows.len);
    var count: i64 = 0;
    for (rows) |row| {
        const value = scalarString(row.valueOrNull(field)) orelse continue;
        if (std.mem.order(u8, value, timestamp) == .gt) count += 1;
    }
    return count;
}

fn skillDecisionCursorStatus(opts: Options, audit: SkillDecisionAudit) []const u8 {
    const cursor = opts.since_cursor_text orelse return "initial";
    if (audit.contract.fingerprint) |fp| {
        if (std.mem.indexOf(u8, cursor, fp) == null) return "invalidated";
    }
    return "valid";
}

fn skillDecisionCursorJsonAlloc(allocator: std.mem.Allocator, opts: Options, audit: SkillDecisionAudit) ![]u8 {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    const file_size = if (opts.path) |path| skillDecisionCursorFileSize(path) else null;
    try writer.writeAll("{\"cursor_version\":\"SDD-C1\",\"session_path\":");
    try writeOptionalJsonString(writer, opts.path);
    try writer.writeAll(",\"session_id\":");
    try writeOptionalJsonString(writer, opts.session_id);
    try writer.writeAll(",\"file_size\":");
    if (file_size) |size| try writer.print("{d}", .{size}) else try writer.writeAll("null");
    try writer.writeAll(",\"file_identity\":");
    if (opts.path) |path| {
        if (file_size) |size| {
            const identity = try std.fmt.allocPrint(allocator, "{s}:{d}", .{ path, size });
            defer allocator.free(identity);
            try output.writeJsonString(writer, identity);
        } else {
            try output.writeJsonString(writer, path);
        }
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"last_timestamp\":");
    try writeOptionalJsonString(writer, lastSkillDecisionEpisodeTimestamp(audit.episodes.items));
    try writer.print(",\"last_event_offset\":{d},\"rows_scanned\":{d},\"sessions_scanned\":{d},\"episodes_emitted\":{d},\"contract_fingerprint\":", .{
        audit.rows_scanned,
        audit.rows_scanned,
        audit.sessions_scanned,
        audit.episodes.items.len,
    });
    if (audit.contract.fingerprint) |fp| try output.writeJsonString(writer, fp) else try writer.writeAll("null");
    try writer.writeAll(",\"seq_version\":");
    try output.writeJsonString(writer, app_meta.version);
    try writer.writeAll("}");
    return writer_alloc.toOwnedSlice();
}

fn skillDecisionCursorFileSize(path: []const u8) ?i64 {
    var file = std.Io.Dir.cwd().openFile(defaultIo(), path, .{}) catch return null;
    defer file.close(defaultIo());
    const stat = file.stat(defaultIo()) catch return null;
    return @intCast(stat.size);
}

fn lastSkillDecisionEpisodeTimestamp(rows: []const query.Row) ?[]const u8 {
    var latest: ?[]const u8 = null;
    for (rows) |row| {
        const ts = scalarString(row.valueOrNull("end_timestamp")) orelse continue;
        if (latest == null or std.mem.order(u8, ts, latest.?) == .gt) latest = ts;
    }
    return latest;
}

fn writeSkillDecisionMarkdown(
    allocator: std.mem.Allocator,
    opts: Options,
    audit: SkillDecisionAudit,
    mode: []const u8,
    causality: []const u8,
) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    try writer.print(
        \\# skill-decision-audit
        \\
        \\## Scope and denominator
        \\target_skill: {s}
        \\mode: {s}
        \\causality: {s}
        \\candidate_sessions: {d}
        \\activation_sessions: {d}
        \\decision_episodes: {d}
        \\
        \\## Contract authority/version
        \\authority: {s}
        \\
        \\## Decision influence
        \\explicit_route_changes: {d}
        \\unknown: {d}
        \\
        \\## Outcomes
        \\associated_outcome_episodes: {d}
        \\
        \\## Limitations
        \\Outcome causality is not proven. Natural-language attribution is limited to explicit skill plus route markers.
        \\
    , .{
        opts.skill.?,
        mode,
        causality,
        audit.candidate_sessions,
        audit.activation_sessions,
        audit.episodes.items.len,
        audit.contract.authority,
        countEpisodesWithEffect(audit.episodes.items, "explicit_route_change"),
        countEpisodesWithEffect(audit.episodes.items, "unknown"),
        audit.outcomes.items.len,
    });
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, opts.out_path);
}

fn joinStringListSep(allocator: std.mem.Allocator, items: []const []const u8, sep: []const u8) ![]u8 {
    if (items.len == 0) return allocator.dupe(u8, "");
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    for (items, 0..) |item, idx| {
        if (idx > 0) try out.appendSlice(allocator, sep);
        try out.appendSlice(allocator, item);
    }
    return out.toOwnedSlice(allocator);
}

fn singletonStringList(allocator: std.mem.Allocator, value: []const u8) ![]const []u8 {
    const out = try allocator.alloc([]u8, 1);
    out[0] = try allocator.dupe(u8, value);
    return out;
}

fn cloneConstStringList(allocator: std.mem.Allocator, items: []const []const u8) ![]const []u8 {
    var out: std.ArrayList([]u8) = .empty;
    errdefer freeStringListLocal(allocator, &out);
    for (items) |item| try out.append(allocator, try allocator.dupe(u8, item));
    return out.toOwnedSlice(allocator);
}

fn freeStringSlice(allocator: std.mem.Allocator, items: []const []u8) void {
    for (items) |item| allocator.free(item);
    allocator.free(items);
}

fn freeStringListLocal(allocator: std.mem.Allocator, list: *std.ArrayList([]u8)) void {
    for (list.items) |item| allocator.free(item);
    list.deinit(allocator);
}

fn containsBareSkillReferenceLocal(text: []const u8, skill: []const u8) bool {
    if (skill.len == 0 or skill.len > text.len) return false;
    var pos: usize = 0;
    while (pos + skill.len <= text.len) : (pos += 1) {
        const end = pos + skill.len;
        if (!eqlIgnoreCaseAscii(text[pos..end], skill)) continue;
        if (pos > 0 and (std.ascii.isAlphanumeric(text[pos - 1]) or text[pos - 1] == '-' or text[pos - 1] == '_')) continue;
        if (end < text.len and (std.ascii.isAlphanumeric(text[end]) or text[end] == '-' or text[end] == '_')) continue;
        return true;
    }
    return false;
}

fn containsDollarSkillLocal(text: []const u8, skill: []const u8) bool {
    var cursor: usize = 0;
    while (skill_decision_signals.nextDollarSkill(text, cursor)) |match| {
        cursor = match.end;
        if (eqlIgnoreCaseAscii(match.skill, skill)) return true;
    }
    return false;
}

fn extractStructuredRouteValue(text: []const u8, key: []const u8) ?[]const u8 {
    const idx = std.mem.indexOf(u8, text, key) orelse return null;
    var pos = idx + key.len;
    while (pos < text.len and (text[pos] == ' ' or text[pos] == ':' or text[pos] == '=' or text[pos] == '"' or text[pos] == '\'')) : (pos += 1) {}
    const start = pos;
    while (pos < text.len and (std.ascii.isAlphanumeric(text[pos]) or text[pos] == '-' or text[pos] == '_' or text[pos] == '.')) : (pos += 1) {}
    if (pos == start) return null;
    return text[start..pos];
}

fn uniqueContractRouteMatch(contract_opt: ?skill_contract.Contract, text: []const u8) ?[]const u8 {
    const contract = contract_opt orelse return null;
    var found: ?[]const u8 = null;
    for (contract.routes) |route| {
        var matched = containsBareSkillReferenceLocal(text, route.route_id);
        for (route.aliases) |alias| {
            if (!matched and containsIgnoreCaseAscii(text, alias)) matched = true;
        }
        if (!matched) continue;
        if (found != null and !std.mem.eql(u8, found.?, route.route_id)) return null;
        found = route.route_id;
    }
    return found;
}

fn inferredClauseRefsForRoute(allocator: std.mem.Allocator, contract_opt: ?skill_contract.Contract, route_id: []const u8) ![]u8 {
    const contract = contract_opt orelse return allocator.dupe(u8, "");
    var out: std.ArrayList([]const u8) = .empty;
    defer out.deinit(allocator);
    for (contract.clauses) |clause| {
        for (clause.expected_routes) |expected| {
            if (std.mem.eql(u8, expected, route_id)) {
                try out.append(allocator, clause.clause_id);
                break;
            }
        }
    }
    return joinStringListSep(allocator, out.items, ",");
}

fn cmdSkillContract(allocator: std.mem.Allocator, opts: Options) !void {
    const action = opts.command_action.?;
    if (std.mem.eql(u8, action, "scaffold")) {
        const scaffold = try std.fmt.allocPrint(allocator,
            \\skill_decision_contract:
            \\  contract_version: SKDC-v1
            \\
            \\  skill:
            \\    name: {s}
            \\    kind: decision
            \\    source_fingerprint:
            \\
            \\  triggers: []
            \\  routes: []
            \\  clauses: []
            \\
            \\  instrumentation:
            \\    decision_receipt: optional
            \\    rationale: Fill in stable decision instrumentation expectations.
            \\
        , .{opts.skill.?});
        defer allocator.free(scaffold);
        try writeTextOutput(scaffold, opts.out_path);
        return;
    }

    if (std.mem.eql(u8, action, "validate")) {
        const content = try std.Io.Dir.cwd().readFileAlloc(defaultIo(), opts.file_text.?, allocator, .limited(4 * 1024 * 1024));
        defer allocator.free(content);
        var parsed_contract = try skill_contract.parseText(allocator, content);
        defer parsed_contract.deinit();
        const report = try skill_contract.validateParsed(allocator, parsed_contract.contract);
        defer report.deinit(allocator);
        try writeSkillValidationReport(
            allocator,
            opts,
            "skill_contract",
            action,
            report.valid,
            report.codes,
            report.fingerprint,
            parsed_contract.contract,
        );
        if (!report.valid) return error.InvalidSpec;
        return;
    }
    if (std.mem.eql(u8, action, "show")) {
        var loaded = try loadSkillDecisionContract(allocator, opts);
        defer loaded.deinit(allocator);
        try writeSkillContractShow(allocator, opts, loaded);
        return;
    }
    try writeSkillCompanionStatus(allocator, opts, "skill_contract", action, "semantic_validation_pending");
}

fn writeSkillContractShow(
    allocator: std.mem.Allocator,
    opts: Options,
    loaded: LoadedSkillDecisionContract,
) !void {
    const contract = loaded.contract() orelse {
        try writeSkillCompanionStatus(allocator, opts, "skill_contract", "show", "contract_absent");
        return;
    };
    if (opts.format == .json) {
        var writer_alloc = std.Io.Writer.Allocating.init(allocator);
        defer writer_alloc.deinit();
        const writer = &writer_alloc.writer;
        try writer.writeAll("{\n  \"skill_contract\": {\n    \"action\": \"show\",\n    \"authority\": ");
        try output.writeJsonString(writer, loaded.authority);
        try writer.writeAll(",\n    \"fingerprint\": ");
        if (loaded.fingerprint) |fp| try output.writeJsonString(writer, fp) else try writer.writeAll("null");
        try writer.writeAll(",\n    \"source_path\": ");
        if (loaded.source_path) |path| try output.writeJsonString(writer, path) else try writer.writeAll("null");
        try writer.writeAll(",\n    \"contract_version\": ");
        try output.writeJsonString(writer, contract.contract_version);
        try writer.writeAll(",\n    \"skill\": ");
        try output.writeJsonString(writer, contract.skill_name);
        try writer.writeAll(",\n    \"skill_kind\": ");
        try output.writeJsonString(writer, contract.skill_kind);
        try writer.writeAll(",\n    \"clause_ids\": [");
        for (contract.clauses, 0..) |clause, idx| {
            if (idx > 0) try writer.writeAll(", ");
            try output.writeJsonString(writer, clause.clause_id);
        }
        try writer.writeAll("]\n  }\n}\n");
        const rendered = try writer_alloc.toOwnedSlice();
        defer allocator.free(rendered);
        try writeTextOutput(rendered, opts.out_path);
        return;
    }

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    try writer.print(
        \\skill_contract:
        \\  action: show
        \\  authority: {s}
        \\  fingerprint: {s}
        \\  source_path: {s}
        \\  contract_version: {s}
        \\  skill: {s}
        \\  skill_kind: {s}
        \\  clause_ids:
        \\
    , .{
        loaded.authority,
        loaded.fingerprint orelse "",
        loaded.source_path orelse "",
        contract.contract_version,
        contract.skill_name,
        contract.skill_kind,
    });
    for (contract.clauses) |clause| {
        try writer.print("    - {s}\n", .{clause.clause_id});
    }
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, opts.out_path);
}

fn cmdSkillDecisionReceipt(allocator: std.mem.Allocator, opts: Options) !void {
    const content = try std.Io.Dir.cwd().readFileAlloc(defaultIo(), opts.file_text.?, allocator, .limited(4 * 1024 * 1024));
    defer allocator.free(content);
    const report = try skill_decision_receipt.validateText(allocator, content, null, null);
    defer report.deinit(allocator);
    try writeSkillValidationReport(
        allocator,
        opts,
        "skill_decision_receipt",
        opts.command_action.?,
        report.valid,
        report.codes,
        report.canonical_hash,
        null,
    );
    if (!report.valid) return error.InvalidSpec;
}

fn writeSkillValidationReport(
    allocator: std.mem.Allocator,
    opts: Options,
    key: []const u8,
    action: []const u8,
    valid: bool,
    codes: []const []const u8,
    fingerprint_or_hash: ?[]const u8,
    contract: ?skill_contract.Contract,
) !void {
    if (opts.format == .json) {
        var writer_alloc = std.Io.Writer.Allocating.init(allocator);
        defer writer_alloc.deinit();
        const writer = &writer_alloc.writer;
        try writer.writeAll("{\n  ");
        try output.writeJsonString(writer, key);
        try writer.writeAll(": {\n    \"action\": ");
        try output.writeJsonString(writer, action);
        try writer.writeAll(",\n    \"valid\": ");
        try writer.writeAll(if (valid) "true" else "false");
        try writer.writeAll(",\n    \"fingerprint\": ");
        if (fingerprint_or_hash) |fp| try output.writeJsonString(writer, fp) else try writer.writeAll("null");
        try writer.writeAll(",\n    \"validation_codes\": [");
        for (codes, 0..) |code, idx| {
            if (idx > 0) try writer.writeAll(", ");
            try output.writeJsonString(writer, code);
        }
        try writer.writeAll("]");
        if (contract) |value| try writeContractReceiptBindingProjection(writer, value);
        try writer.writeAll("\n  }\n}\n");
        const rendered = try writer_alloc.toOwnedSlice();
        defer allocator.free(rendered);
        try writeTextOutput(rendered, opts.out_path);
        return;
    }

    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    if (codes.len == 0) {
        var row = query.Row.init(allocator);
        try row.putOwnedKey("surface", .{ .string = key });
        try row.putOwnedKey("action", .{ .string = action });
        try row.putOwnedKey("valid", .{ .bool = valid });
        try row.putOwnedKey("fingerprint", if (fingerprint_or_hash) |fp| .{ .string = fp } else .null);
        try row.putOwnedKey("validation_code", .{ .string = "ok" });
        try rows.append(allocator, row);
    } else {
        for (codes) |code| {
            var row = query.Row.init(allocator);
            try row.putOwnedKey("surface", .{ .string = key });
            try row.putOwnedKey("action", .{ .string = action });
            try row.putOwnedKey("valid", .{ .bool = valid });
            try row.putOwnedKey("fingerprint", if (fingerprint_or_hash) |fp| .{ .string = fp } else .null);
            try row.putOwnedKey("validation_code", .{ .string = code });
            try rows.append(allocator, row);
        }
    }
    const cols = [_][]const u8{ "surface", "action", "valid", "fingerprint", "validation_code" };
    try output.writeOutput(allocator, opts.format, rows.items, cols[0..], opts.out_path);
}

fn writeContractReceiptBindingProjection(
    writer: *std.Io.Writer,
    contract: skill_contract.Contract,
) !void {
    try writer.writeAll(",\n    \"skill\": ");
    try output.writeJsonString(writer, contract.skill_name);
    try writer.writeAll(",\n    \"skill_kind\": ");
    try output.writeJsonString(writer, contract.skill_kind);
    try writer.writeAll(",\n    \"trigger_ids\": [");
    for (contract.triggers, 0..) |trigger, index| {
        if (index > 0) try writer.writeAll(", ");
        try output.writeJsonString(writer, trigger.trigger_id);
    }
    try writer.writeAll("],\n    \"route_ids\": [");
    for (contract.routes, 0..) |route, index| {
        if (index > 0) try writer.writeAll(", ");
        try output.writeJsonString(writer, route.route_id);
    }
    try writer.writeAll("],\n    \"clause_ids\": [");
    for (contract.clauses, 0..) |clause, index| {
        if (index > 0) try writer.writeAll(", ");
        try output.writeJsonString(writer, clause.clause_id);
    }
    try writer.writeAll("],\n    \"clause_routes\": [");
    for (contract.clauses, 0..) |clause, index| {
        if (index > 0) try writer.writeAll(", ");
        try writer.writeAll("{\"clause_id\": ");
        try output.writeJsonString(writer, clause.clause_id);
        try writer.writeAll(", \"expected_routes\": ");
        try writeProjectionStringArray(writer, clause.expected_routes);
        try writer.writeAll(", \"prohibited_routes\": ");
        try writeProjectionStringArray(writer, clause.prohibited_routes);
        try writer.writeByte('}');
    }
    try writer.writeByte(']');
}

fn writeProjectionStringArray(
    writer: *std.Io.Writer,
    values: []const []const u8,
) !void {
    try writer.writeByte('[');
    for (values, 0..) |value, index| {
        if (index > 0) try writer.writeAll(", ");
        try output.writeJsonString(writer, value);
    }
    try writer.writeByte(']');
}

fn writeSkillCompanionStatus(
    allocator: std.mem.Allocator,
    opts: Options,
    key: []const u8,
    action: []const u8,
    code: []const u8,
) !void {
    if (opts.format == .json) {
        var writer_alloc = std.Io.Writer.Allocating.init(allocator);
        defer writer_alloc.deinit();
        const writer = &writer_alloc.writer;
        try writer.writeAll("{\n  ");
        try output.writeJsonString(writer, key);
        try writer.writeAll(": {\n    \"action\": ");
        try output.writeJsonString(writer, action);
        try writer.writeAll(",\n    \"valid\": true,\n    \"validation_codes\": [");
        try output.writeJsonString(writer, code);
        try writer.writeAll("]\n  }\n}\n");
        const rendered = try writer_alloc.toOwnedSlice();
        defer allocator.free(rendered);
        try writeTextOutput(rendered, opts.out_path);
        return;
    }

    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    var row = query.Row.init(allocator);
    try row.putOwnedKey("surface", .{ .string = key });
    try row.putOwnedKey("action", .{ .string = action });
    try row.putOwnedKey("valid", .{ .bool = true });
    try row.putOwnedKey("validation_code", .{ .string = code });
    try rows.append(allocator, row);
    const cols = [_][]const u8{ "surface", "action", "valid", "validation_code" };
    try output.writeOutput(allocator, opts.format, rows.items, cols[0..], opts.out_path);
}

fn writeOptionalJsonString(writer: anytype, value: ?[]const u8) !void {
    if (value) |text| {
        try output.writeJsonString(writer, text);
    } else {
        try writer.writeAll("null");
    }
}

fn cmdQuery(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const raw_spec = opts.spec_text orelse return error.MissingSpecArg;
    const spec_text = try loadSpecText(allocator, raw_spec);
    defer allocator.free(spec_text);

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();

    var parsed = try std.json.parseFromSlice(std.json.Value, arena.allocator(), spec_text, .{});
    defer parsed.deinit();

    const query_spec = try spec.parseQuerySpecValue(arena.allocator(), parsed.value);
    const dataset_name = blk: {
        const root_obj = switch (parsed.value) {
            .object => |obj| obj,
            else => return error.InvalidSpec,
        };
        if (root_obj.get("dataset")) |value| switch (value) {
            .string => |text| break :blk text,
            else => return error.InvalidSpec,
        };
        break :blk opts.dataset orelse "messages";
    };

    const fmt = blk: {
        const root_obj = switch (parsed.value) {
            .object => |obj| obj,
            else => return error.InvalidSpec,
        };
        if (root_obj.get("format")) |value| switch (value) {
            .string => |text| break :blk try output.Format.parse(text),
            else => return error.InvalidSpec,
        };
        if (opts.format_set) break :blk opts.format;
        break :blk if (query_spec.group_by.len > 0) output.Format.table else output.Format.jsonl;
    };
    if (std.mem.eql(u8, opts.index_mode, "required") and !(try seqIndexExists(allocator, sessions_root))) {
        return error.IndexUnavailable;
    }

    const wants_stats = opts.stats or query_spec.stats or query_spec.explain;
    var stats = stats_mod.SeqStats{};
    const stats_start_ms = if (wants_stats) stats_mod.SeqStats.startTimer() else 0;
    if (opts.path != null or opts.session_id != null or opts.current) stats.used_session_selector = true;

    var rows = try collectDatasetRowsForSpecTracked(allocator, dataset_name, sessions_root, query_spec, if (wants_stats) &stats else null);
    defer deinitQueryRows(allocator, &rows);
    if (wants_stats) stats.rows_materialized = @intCast(rows.items.len);

    var result = try query.executeWithStats(allocator, rows.items, query_spec, if (wants_stats) &stats else null);
    defer result.deinit(allocator);
    if (wants_stats) {
        stats.rows_emitted = @intCast(result.rows.items.len);
        stats.finish(stats_start_ms);
    }

    const cols_opt: ?[]const []const u8 = if (query_spec.select.len > 0) query_spec.select else null;
    if (fmt == .dot and std.mem.eql(u8, dataset_name, "session_graph_edges")) {
        try writeTraceGraphDotRows(allocator, result.rows.items, opts.out_path);
        return;
    }
    if (fmt == .dot or fmt == .markdown) return error.InvalidFormatForCommand;
    if (query_spec.explain) {
        try writeQueryExplainJson(allocator, dataset_name, query_spec, stats, result.rows.items, cols_opt, opts.out_path);
        return;
    }
    const stats_cols = if (wants_stats) try columnsWithStats(allocator, cols_opt) else null;
    defer if (stats_cols) |cols| allocator.free(cols);
    if (wants_stats) try attachSeqStatsToRows(result.rows.items, stats);
    try output.writeOutput(allocator, fmt, result.rows.items, stats_cols orelse cols_opt, opts.out_path);
}

fn seqIndexPath(allocator: std.mem.Allocator, sessions_root: []const u8) ![]u8 {
    return std.fs.path.join(allocator, &.{ sessions_root, ".seq-index.jsonl" });
}

fn seqIndexExists(allocator: std.mem.Allocator, sessions_root: []const u8) !bool {
    const path = try seqIndexPath(allocator, sessions_root);
    defer allocator.free(path);
    const file = std.Io.Dir.openFileAbsolute(defaultIo(), path, .{}) catch |err| switch (err) {
        error.FileNotFound => return false,
        else => return err,
    };
    file.close(defaultIo());
    return true;
}

fn cmdIndex(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const action = opts.index_action orelse "status";
    if (std.mem.eql(u8, action, "build") or std.mem.eql(u8, action, "refresh")) {
        try writeSeqIndex(allocator, sessions_root);
    } else if (std.mem.eql(u8, action, "vacuum")) {
        const path = try seqIndexPath(allocator, sessions_root);
        defer allocator.free(path);
        std.Io.Dir.deleteFileAbsolute(defaultIo(), path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        };
    } else if (!std.mem.eql(u8, action, "status")) {
        return error.InvalidModeArg;
    }

    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    const index_path = try seqIndexPath(allocator, sessions_root);
    defer allocator.free(index_path);
    try row.putStaticKey("root", .{ .string = sessions_root });
    try row.putStaticKey("index_path", .{ .string = index_path });
    try row.putStaticKey("exists", .{ .bool = try seqIndexExists(allocator, sessions_root) });
    try row.putStaticKey("action", .{ .string = action });
    try rows.append(allocator, row);
    const cols = [_][]const u8{ "root", "index_path", "exists", "action" };
    try output.writeOutput(allocator, opts.format, rows.items, cols[0..], opts.out_path);
}

fn writeSeqIndex(allocator: std.mem.Allocator, sessions_root: []const u8) !void {
    var paths = try collectJsonlPaths(allocator, sessions_root, null);
    defer freePathList(allocator, &paths);

    const index_path = try seqIndexPath(allocator, sessions_root);
    defer allocator.free(index_path);

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    for (paths.items) |path| {
        const file = std.Io.Dir.openFileAbsolute(defaultIo(), path, .{}) catch continue;
        defer file.close(defaultIo());
        const stat = try file.stat(defaultIo());
        try writer.writeByte('{');
        try output.writeJsonString(writer, "path");
        try writer.writeAll(":");
        try output.writeJsonString(writer, path);
        try writer.writeAll(",\"size_bytes\":");
        try writer.print("{d}", .{stat.size});
        try writer.writeAll(",\"mtime_ns\":");
        try writer.print("{d}", .{stat.mtime.nanoseconds});
        try writer.writeAll(",\"schema_version\":1,\"parser_version\":1}\n");
    }
    const data = try writer_alloc.toOwnedSlice();
    defer allocator.free(data);
    try std.Io.Dir.cwd().writeFile(defaultIo(), .{ .sub_path = index_path, .data = data });
}

fn writeQueryExplainJson(
    allocator: std.mem.Allocator,
    dataset_name: []const u8,
    query_spec: spec.QuerySpec,
    stats: stats_mod.SeqStats,
    rows: []const query.Row,
    columns_opt: ?[]const []const u8,
    out_path: ?[]const u8,
) !void {
    var infer_owned = false;
    const columns = blk: {
        if (columns_opt) |provided| break :blk provided;
        infer_owned = true;
        break :blk try output.inferColumns(allocator, rows);
    };
    defer if (infer_owned) output.freeColumns(allocator, columns);

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.writeAll("{\n  \"plan\": {\n");
    try writer.writeAll("    \"dataset\": ");
    try output.writeJsonString(writer, dataset_name);
    try writer.writeAll(",\n    \"scan\": ");
    try output.writeJsonString(writer, if (stats.used_bounded_day_dirs)
        "bounded_day_dirs"
    else if (stats.used_day_path_pushdown)
        "day_pushdown"
    else
        "walk");
    try writer.writeAll(",\n    \"query\": ");
    try output.writeJsonString(writer, if (stats.used_topk)
        "topk"
    else if (query_spec.group_by.len > 0)
        "grouped"
    else if (query_spec.sort.len > 0)
        "full_sort"
    else
        "scan");
    try writer.writeAll(",\n    \"projection\": ");
    try output.writeJsonString(writer, if (query_spec.select.len > 0) "selected" else "all");
    try writer.writeAll(",\n    \"index\": ");
    try output.writeJsonString(writer, if (stats.used_index) "used" else "none");
    try writer.writeAll("\n  },\n  \"stats\": ");
    try writeSeqStatsJson(writer, stats, true, "    ");
    try writer.writeAll(",\n  \"rows\": [");
    for (rows, 0..) |row, idx| {
        if (idx > 0) try writer.writeByte(',');
        try writer.writeByte('\n');
        try writer.writeAll("    ");
        try output.writeJsonObject(writer, row, columns, false, "");
    }
    if (rows.len > 0) try writer.writeByte('\n');
    try writer.writeAll("  ]\n}\n");

    const text = try writer_alloc.toOwnedSlice();
    defer allocator.free(text);
    try writeTextOutput(text, out_path);
}

const workflow_audit_summary_columns = [_][]const u8{ "source_kind", "signal_kind", "name", "outcome_kind", "mentions", "sessions" };
const workflow_audit_signal_columns = [_][]const u8{ "timestamp", "path", "source_kind", "signal_kind", "name", "outcome_kind", "snippet", "contamination_flags" };
const workflow_audit_outcome_columns = [_][]const u8{ "outcome_kind", "mentions", "sessions" };
const workflow_audit_session_columns = [_][]const u8{ "path", "signals", "first_seen", "last_seen" };
const workflow_audit_provenance_columns = [_][]const u8{ "session_id", "workflow_name", "evidence_class", "source", "timestamp", "ref", "reason", "path" };
const workflow_audit_term_summary_columns = [_][]const u8{ "term_group", "terms", "matched_rows", "unique_snippets", "sessions", "examples" };
const skill_block_term_count_columns = [_][]const u8{ "skill", "block_hash", "term_group", "terms", "matched", "term_occurrence_count", "block_occurrence_count", "first_seen_timestamp", "last_seen_timestamp" };
const skill_block_term_summary_columns = [_][]const u8{ "skill", "term_group", "terms", "blocks_scanned", "matching_blocks", "term_occurrence_count", "examples" };
const workflow_overlap_summary_columns = [_][]const u8{ "workflow_a", "workflow_b", "sessions_a", "sessions_b", "overlap_sessions", "a_only_sessions", "b_only_sessions", "pct_a_with_b", "pct_b_with_a" };
const workflow_overlap_session_columns = [_][]const u8{ "path", "overlap_class", "in_a", "in_b", "signals_a", "signals_b", "first_seen_a", "last_seen_a", "first_seen_b", "last_seen_b" };

const StringSet = struct {
    allocator: std.mem.Allocator,
    map: std.StringHashMap(void),

    fn init(allocator: std.mem.Allocator) StringSet {
        return .{
            .allocator = allocator,
            .map = std.StringHashMap(void).init(allocator),
        };
    }

    fn deinit(self: *StringSet) void {
        var it = self.map.keyIterator();
        while (it.next()) |key| self.allocator.free(key.*);
        self.map.deinit();
    }

    fn put(self: *StringSet, text: []const u8) !void {
        _ = try self.putNew(text);
    }

    fn putNew(self: *StringSet, text: []const u8) !bool {
        if (self.map.contains(text)) return false;
        const copy = try self.allocator.dupe(u8, text);
        errdefer self.allocator.free(copy);
        try self.map.put(copy, {});
        return true;
    }

    fn contains(self: *const StringSet, text: []const u8) bool {
        return self.map.contains(text);
    }

    fn count(self: *const StringSet) usize {
        return self.map.count();
    }
};

fn cmdWorkflowAudit(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const workflow = opts.workflow orelse return error.MissingWorkflowArg;
    const mode = opts.mode orelse "summary";
    const fmt = if (opts.format_set)
        opts.format
    else if (std.mem.eql(u8, mode, "report") or std.mem.eql(u8, mode, "cohort-report"))
        output.Format.markdown
    else
        output.Format.table;

    if (std.mem.eql(u8, mode, "term-summary")) {
        if (fmt == .markdown) return error.InvalidFormatForCommand;
        return cmdWorkflowTermSummaryRaw(allocator, sessions_root, opts, fmt);
    }

    if (std.mem.eql(u8, mode, "provenance")) {
        var rows = try collectWorkflowProvenanceRows(allocator, sessions_root, opts);
        defer deinitQueryRows(allocator, &rows);
        const query_spec = try workflowAuditQueryForMode(mode, opts.limit);
        var result = try query.execute(allocator, rows.items, query_spec);
        defer result.deinit(allocator);
        if (fmt == .markdown) {
            try writeWorkflowAuditModeMarkdown(allocator, workflow, mode, result.rows.items, workflowAuditColumnsForMode(mode) orelse return error.InvalidModeArg, opts.out_path);
            return;
        }
        try output.writeOutput(allocator, fmt, result.rows.items, workflowAuditColumnsForMode(mode), opts.out_path);
        return;
    }

    var rows = try collectWorkflowAuditRows(allocator, sessions_root, opts);
    defer deinitQueryRows(allocator, &rows);

    if (std.mem.eql(u8, mode, "cohort-report")) {
        try writeWorkflowCohortReport(allocator, workflow, rows.items, fmt, opts.limit, opts.out_path);
        return;
    }

    if (fmt == .markdown and std.mem.eql(u8, mode, "report")) {
        try writeWorkflowAuditMarkdown(allocator, workflow, rows.items, opts.out_path);
        return;
    }

    const query_spec = try workflowAuditQueryForMode(mode, opts.limit);
    var result = try query.execute(allocator, rows.items, query_spec);
    defer result.deinit(allocator);

    if (fmt == .markdown) {
        try writeWorkflowAuditModeMarkdown(allocator, workflow, mode, result.rows.items, workflowAuditColumnsForMode(mode) orelse return error.InvalidModeArg, opts.out_path);
        return;
    }

    try output.writeOutput(allocator, fmt, result.rows.items, workflowAuditColumnsForMode(mode), opts.out_path);
}

fn workflowAuditQueryForMode(mode: []const u8, limit: usize) !spec.QuerySpec {
    if (std.mem.eql(u8, mode, "summary")) {
        return .{
            .group_by = workflow_audit_summary_columns[0..4],
            .metrics = &.{
                .{ .op = .count, .alias = "mentions" },
                .{ .op = .count_distinct, .field = "path", .alias = "sessions" },
            },
            .sort = &.{.{ .field = "mentions", .descending = true }},
            .limit = if (limit > 0) limit else 50,
        };
    }

    if (std.mem.eql(u8, mode, "signals")) {
        return .{
            .select = workflow_audit_signal_columns[0..],
            .sort = &.{.{ .field = "timestamp", .descending = true }},
            .limit = if (limit > 0) limit else 100,
        };
    }

    if (std.mem.eql(u8, mode, "outcomes")) {
        return .{
            .where = &.{.{
                .field = "signal_kind",
                .op = .eq,
                .value = .{ .scalar = .{ .string = "outcome" } },
            }},
            .group_by = &.{"outcome_kind"},
            .metrics = &.{
                .{ .op = .count, .alias = "mentions" },
                .{ .op = .count_distinct, .field = "path", .alias = "sessions" },
            },
            .sort = &.{.{ .field = "mentions", .descending = true }},
            .limit = if (limit > 0) limit else 20,
        };
    }

    if (std.mem.eql(u8, mode, "sessions")) {
        return .{
            .group_by = &.{"path"},
            .metrics = &.{
                .{ .op = .count, .alias = "signals" },
                .{ .op = .min, .field = "timestamp", .alias = "first_seen" },
                .{ .op = .max, .field = "timestamp", .alias = "last_seen" },
            },
            .sort = &.{.{ .field = "signals", .descending = true }},
            .limit = if (limit > 0) limit else 50,
        };
    }

    if (std.mem.eql(u8, mode, "report")) {
        return .{
            .select = workflow_audit_signal_columns[0..],
            .sort = &.{.{ .field = "timestamp", .descending = true }},
            .limit = if (limit > 0) limit else 100,
        };
    }

    if (std.mem.eql(u8, mode, "provenance")) {
        return .{
            .select = workflow_audit_provenance_columns[0..],
            .sort = &.{.{ .field = "timestamp", .descending = true }},
            .limit = if (limit > 0) limit else 100,
        };
    }

    return error.InvalidModeArg;
}

fn workflowAuditColumnsForMode(mode: []const u8) ?[]const []const u8 {
    if (std.mem.eql(u8, mode, "summary")) return workflow_audit_summary_columns[0..];
    if (std.mem.eql(u8, mode, "signals")) return workflow_audit_signal_columns[0..];
    if (std.mem.eql(u8, mode, "outcomes")) return workflow_audit_outcome_columns[0..];
    if (std.mem.eql(u8, mode, "sessions")) return workflow_audit_session_columns[0..];
    if (std.mem.eql(u8, mode, "report")) return workflow_audit_signal_columns[0..];
    if (std.mem.eql(u8, mode, "cohort-report")) return workflow_audit_signal_columns[0..];
    if (std.mem.eql(u8, mode, "provenance")) return workflow_audit_provenance_columns[0..];
    if (std.mem.eql(u8, mode, "term-summary")) return workflow_audit_term_summary_columns[0..];
    return null;
}

fn collectWorkflowProvenanceRows(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    opts: Options,
) !std.ArrayList(query.Row) {
    const workflow = opts.workflow orelse return error.MissingWorkflowArg;

    var workdir_paths = StringSet.init(allocator);
    var has_workdir_filter = false;
    defer if (has_workdir_filter) workdir_paths.deinit();
    if (opts.workdir_text != null) {
        has_workdir_filter = true;
        try collectWorkdirSessionPaths(allocator, sessions_root, opts, &workdir_paths);
    }

    const day_filter = deriveSessionDayPathFilter("workflow_provenance", &.{});
    var paths = try collectJsonlPaths(allocator, sessions_root, day_filter);
    defer freePathList(allocator, &paths);
    const exclude_path = if (opts.exclude_current) try QueryLiftCommands.resolveCurrentSessionPathForExclusion(allocator, sessions_root) else null;
    defer if (exclude_path) |path| allocator.free(path);

    var out: std.ArrayList(query.Row) = .empty;
    errdefer deinitQueryRows(allocator, &out);
    for (paths.items) |path| {
        if (exclude_path) |excluded| {
            if (std.mem.eql(u8, path, excluded)) continue;
        }
        if (has_workdir_filter and !workdir_paths.contains(path)) continue;

        var parsed = canonical_trace.parseSessionTrace(allocator, path, traceParseOptions(opts)) catch continue;
        defer parsed.deinit(allocator);
        if (!resolveSessionOverlapsWindow(parsed.session.start_time, parsed.session.end_time, opts)) continue;

        const content = (try readFileAllocOrSkip(allocator, path)) orelse continue;
        defer allocator.free(content);
        const messages = datasets.messages.parseJsonl(allocator, path, content, .{
            .include_user = true,
            .include_assistant = true,
            .strip_echo_assistant = true,
            .skip_meta_user_messages = true,
            .dedupe_by_role_and_text = true,
            .strip_skill_blocks = true,
        }) catch continue;
        defer datasets.messages.freeRows(allocator, messages);

        for (messages) |message| {
            if (!timestampSatisfiesBounds(message.timestamp, opts)) continue;
            try appendMessageWorkflowProvenanceRows(allocator, &out, workflow, parsed.session.session_id, path, message);
        }
        for (parsed.tools.items) |tool| {
            if (!toolTimestampSatisfiesBounds(parsed, tool, opts)) continue;
            try appendToolWorkflowProvenanceRows(allocator, &out, workflow, parsed.session.session_id, path, parsed, tool);
        }
    }

    return out;
}

const TermGroup = struct {
    name: []const u8,
    terms: []const []const u8,
    terms_display: []const u8,

    fn deinit(self: TermGroup, allocator: std.mem.Allocator) void {
        allocator.free(self.terms);
        allocator.free(self.terms_display);
    }
};

const WorkflowTermState = struct {
    group: TermGroup,
    matched_rows: usize = 0,
    sessions: StringSet,
    uniques: StringSet,
    examples: std.ArrayList([]u8) = .empty,

    fn init(allocator: std.mem.Allocator, group: TermGroup) WorkflowTermState {
        return .{
            .group = group,
            .sessions = StringSet.init(allocator),
            .uniques = StringSet.init(allocator),
        };
    }

    fn deinit(self: *WorkflowTermState, allocator: std.mem.Allocator) void {
        self.group.deinit(allocator);
        self.sessions.deinit();
        self.uniques.deinit();
        for (self.examples.items) |example| allocator.free(example);
        self.examples.deinit(allocator);
    }
};

fn cmdWorkflowTermSummaryRaw(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    opts: Options,
    fmt: output.Format,
) !void {
    const workflow = opts.workflow orelse return error.MissingWorkflowArg;
    if (opts.term_group_count == 0) return error.MissingArgValue;
    const example_limit = @min(opts.examples, @as(usize, 10));
    const unique_by = opts.unique_by_text orelse "path-snippet";

    var states: std.ArrayList(WorkflowTermState) = .empty;
    defer {
        for (states.items) |*state| state.deinit(allocator);
        states.deinit(allocator);
    }

    var idx: usize = 0;
    while (idx < opts.term_group_count) : (idx += 1) {
        const raw = opts.term_group_texts[idx] orelse return error.InvalidModeArg;
        try states.append(allocator, WorkflowTermState.init(allocator, try parseTermGroup(allocator, raw)));
    }

    var workdir_paths = StringSet.init(allocator);
    var has_workdir_filter = false;
    defer if (has_workdir_filter) workdir_paths.deinit();
    if (opts.workdir_text != null) {
        has_workdir_filter = true;
        try collectWorkdirSessionPaths(allocator, sessions_root, opts, &workdir_paths);
    }

    const day_filter = deriveSessionDayPathFilterFromOptions(opts);
    var paths = try collectJsonlPaths(allocator, sessions_root, day_filter);
    defer freePathList(allocator, &paths);
    const exclude_path = if (opts.exclude_current) try QueryLiftCommands.resolveCurrentSessionPathForExclusion(allocator, sessions_root) else null;
    defer if (exclude_path) |path| allocator.free(path);

    for (paths.items) |path| {
        if (exclude_path) |excluded| {
            if (std.mem.eql(u8, path, excluded)) continue;
        }
        if (has_workdir_filter and !workdir_paths.contains(path)) continue;
        try recordWorkflowTermSummaryFromRawSignals(allocator, &states, path, workflow, opts, unique_by, example_limit);
    }

    var out_rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &out_rows);
    for (states.items) |*state| {
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        const examples = try joinExamples(allocator, state.examples.items);
        defer allocator.free(examples);
        try row.putOwnedKey("term_group", .{ .string = state.group.name });
        try row.putOwnedKey("terms", .{ .string = state.group.terms_display });
        try row.putOwnedKey("matched_rows", .{ .int = @intCast(state.matched_rows) });
        try row.putOwnedKey("unique_snippets", .{ .int = @intCast(state.uniques.count()) });
        try row.putOwnedKey("sessions", .{ .int = @intCast(state.sessions.count()) });
        try row.putOwnedKey("examples", .{ .string = examples });
        try out_rows.append(allocator, row);
    }

    try output.writeOutput(allocator, fmt, out_rows.items, workflow_audit_term_summary_columns[0..], opts.out_path);
}

fn recordWorkflowTermSummaryFromRawSignals(
    allocator: std.mem.Allocator,
    states: *std.ArrayList(WorkflowTermState),
    path: []const u8,
    workflow: []const u8,
    opts: Options,
    unique_by: []const u8,
    example_limit: usize,
) !void {
    const content = try readFileAllocOrSkip(allocator, path);
    if (content == null) return;
    defer allocator.free(content.?);

    var lines = std.mem.splitScalar(u8, content.?, '\n');
    while (lines.next()) |line| {
        if (!containsDollarWorkflowMention(line, workflow)) continue;
        if (!lineLooksLikeAssistantMessage(line)) continue;
        const timestamp = extractFlatJsonStringField(line, "timestamp");
        if (timestamp != null and !timestampSatisfiesBounds(timestamp, opts)) continue;
        const snippet = line[0..@min(line.len, 240)];
        for (states.items) |*state| {
            if (!termGroupMatches(snippet, state.group.terms)) continue;
            state.matched_rows += 1;
            try state.sessions.put(path);
            const unique_key = if (std.mem.eql(u8, unique_by, "snippet"))
                try allocator.dupe(u8, snippet)
            else
                try std.fmt.allocPrint(allocator, "{s}\x1f{s}", .{ path, snippet });
            defer allocator.free(unique_key);
            const was_new = try state.uniques.putNew(unique_key);
            if (was_new and state.examples.items.len < example_limit) {
                try state.examples.append(allocator, try allocator.dupe(u8, snippet));
            }
        }
    }
}

fn lineLooksLikeAssistantMessage(line: []const u8) bool {
    return std.mem.indexOf(u8, line, "\"role\":\"assistant\"") != null;
}

fn parseTermGroup(allocator: std.mem.Allocator, raw: []const u8) !TermGroup {
    const eq = std.mem.indexOfScalar(u8, raw, '=') orelse return error.InvalidModeArg;
    const name = std.mem.trim(u8, raw[0..eq], " \t\r\n");
    const terms_raw = std.mem.trim(u8, raw[eq + 1 ..], " \t\r\n");
    if (name.len == 0 or terms_raw.len == 0) return error.InvalidModeArg;

    var terms: std.ArrayList([]const u8) = .empty;
    defer terms.deinit(allocator);
    var split = std.mem.splitScalar(u8, terms_raw, ',');
    while (split.next()) |part_raw| {
        const part = std.mem.trim(u8, part_raw, " \t\r\n");
        if (part.len == 0) return error.InvalidModeArg;
        try terms.append(allocator, part);
    }
    if (terms.items.len == 0) return error.InvalidModeArg;

    return .{
        .name = name,
        .terms = try terms.toOwnedSlice(allocator),
        .terms_display = try allocator.dupe(u8, terms_raw),
    };
}

fn termGroupMatches(text: []const u8, terms: []const []const u8) bool {
    for (terms) |term| {
        if (containsIgnoreCaseAscii(text, term)) return true;
    }
    return false;
}

fn countIgnoreCaseAsciiOccurrences(haystack: []const u8, needle: []const u8) usize {
    if (needle.len == 0 or needle.len > haystack.len) return 0;
    var count: usize = 0;
    var start: usize = 0;
    while (start + needle.len <= haystack.len) {
        if (eqlIgnoreCaseAscii(haystack[start .. start + needle.len], needle)) {
            count += 1;
            start += needle.len;
        } else {
            start += 1;
        }
    }
    return count;
}

fn countTermGroupOccurrences(text: []const u8, terms: []const []const u8) usize {
    var total: usize = 0;
    for (terms) |term| {
        total += countIgnoreCaseAsciiOccurrences(text, term);
    }
    return total;
}

fn joinExamples(allocator: std.mem.Allocator, examples: []const []u8) ![]u8 {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    for (examples, 0..) |example, idx| {
        if (idx > 0) try writer.writeAll(" | ");
        try writer.writeAll(example);
    }
    return writer_alloc.toOwnedSlice();
}

const WorkflowPair = struct {
    a: []const u8,
    b: []const u8,
};

const WorkflowOverlapState = struct {
    path: []u8,
    signals_a: usize = 0,
    signals_b: usize = 0,
    first_seen_a: ?[]u8 = null,
    last_seen_a: ?[]u8 = null,
    first_seen_b: ?[]u8 = null,
    last_seen_b: ?[]u8 = null,

    fn deinit(self: *WorkflowOverlapState, allocator: std.mem.Allocator) void {
        allocator.free(self.path);
        if (self.first_seen_a) |value| allocator.free(value);
        if (self.last_seen_a) |value| allocator.free(value);
        if (self.first_seen_b) |value| allocator.free(value);
        if (self.last_seen_b) |value| allocator.free(value);
    }
};

fn cmdWorkflowOverlap(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const pair = try parseWorkflowPair(opts.workflow orelse return error.MissingWorkflowArg);
    const mode = opts.mode orelse "summary";

    var states = try collectWorkflowOverlapStates(allocator, sessions_root, opts, pair);
    defer deinitWorkflowOverlapStates(allocator, &states);

    var sessions_a: usize = 0;
    var sessions_b: usize = 0;
    var overlap_count: usize = 0;
    for (states.items) |state| {
        const has_a = state.signals_a > 0;
        const has_b = state.signals_b > 0;
        if (has_a) sessions_a += 1;
        if (has_b) sessions_b += 1;
        if (has_a and has_b) overlap_count += 1;
    }

    var out_rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &out_rows);

    if (std.mem.eql(u8, mode, "summary")) {
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        try row.putOwnedKey("workflow_a", .{ .string = pair.a });
        try row.putOwnedKey("workflow_b", .{ .string = pair.b });
        try row.putOwnedKey("sessions_a", .{ .int = @intCast(sessions_a) });
        try row.putOwnedKey("sessions_b", .{ .int = @intCast(sessions_b) });
        try row.putOwnedKey("overlap_sessions", .{ .int = @intCast(overlap_count) });
        try row.putOwnedKey("a_only_sessions", .{ .int = @intCast(sessions_a - overlap_count) });
        try row.putOwnedKey("b_only_sessions", .{ .int = @intCast(sessions_b - overlap_count) });
        try row.putOwnedKey("pct_a_with_b", .{ .float = percentage(overlap_count, sessions_a) });
        try row.putOwnedKey("pct_b_with_a", .{ .float = percentage(overlap_count, sessions_b) });
        try out_rows.append(allocator, row);
        return output.writeOutput(allocator, opts.format, out_rows.items, workflow_overlap_summary_columns[0..], opts.out_path);
    }

    if (!std.mem.eql(u8, mode, "sessions")) return error.InvalidModeArg;
    for (states.items) |state| {
        try appendWorkflowOverlapSessionStateRow(allocator, &out_rows, state);
    }

    const sort = [_]spec.SortSpec{
        .{ .field = "overlap_class", .descending = false },
        .{ .field = "path", .descending = false },
    };
    const limit = if (opts.limit > 0) opts.limit else out_rows.items.len;
    const query_spec = spec.QuerySpec{ .sort = sort[0..], .limit = limit };
    var result = try query.execute(allocator, out_rows.items, query_spec);
    defer result.deinit(allocator);
    try output.writeOutput(allocator, opts.format, result.rows.items, workflow_overlap_session_columns[0..], opts.out_path);
}

fn collectWorkflowOverlapStates(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    opts: Options,
    pair: WorkflowPair,
) !std.ArrayList(WorkflowOverlapState) {
    var where: std.ArrayList(spec.WhereClause) = .empty;
    defer where.deinit(allocator);
    try appendSessionTimeBounds(allocator, &where, opts);

    var workdir_paths = StringSet.init(allocator);
    var has_workdir_filter = false;
    defer if (has_workdir_filter) workdir_paths.deinit();
    if (opts.workdir_text != null) {
        has_workdir_filter = true;
        try collectWorkdirSessionPaths(allocator, sessions_root, opts, &workdir_paths);
    }

    const day_filter = deriveSessionDayPathFilter("workflow_signals", where.items);
    var paths = try collectJsonlPaths(allocator, sessions_root, day_filter);
    defer freePathList(allocator, &paths);

    var states: std.ArrayList(WorkflowOverlapState) = .empty;
    errdefer deinitWorkflowOverlapStates(allocator, &states);
    var index = std.StringHashMap(usize).init(allocator);
    defer index.deinit();

    for (paths.items) |path| {
        if (has_workdir_filter and !workdir_paths.contains(path)) continue;
        try appendWorkflowOverlapStateFromRawSignals(allocator, &states, &index, path, pair, opts);
    }

    return states;
}

fn appendWorkflowOverlapStateFromRawSignals(
    allocator: std.mem.Allocator,
    states: *std.ArrayList(WorkflowOverlapState),
    index: *std.StringHashMap(usize),
    path: []const u8,
    pair: WorkflowPair,
    opts: Options,
) !void {
    const content = try readFileAllocOrSkip(allocator, path);
    if (content == null) return;
    defer allocator.free(content.?);

    var lines = std.mem.splitScalar(u8, content.?, '\n');
    while (lines.next()) |line| {
        if (std.mem.indexOfScalar(u8, line, '$') == null) continue;
        const timestamp = extractFlatJsonStringField(line, "timestamp");
        if (timestamp != null and !timestampSatisfiesBounds(timestamp, opts)) continue;
        if (containsDollarWorkflowMention(line, pair.a)) {
            const idx = try getOrCreateWorkflowOverlapState(allocator, states, index, path);
            try recordWorkflowOverlapSignal(allocator, &states.items[idx], true, timestamp);
        }
        if (containsDollarWorkflowMention(line, pair.b)) {
            const idx = try getOrCreateWorkflowOverlapState(allocator, states, index, path);
            try recordWorkflowOverlapSignal(allocator, &states.items[idx], false, timestamp);
        }
    }
}

fn containsDollarWorkflowMention(text: []const u8, workflow: []const u8) bool {
    var pos: usize = 0;
    while (std.mem.indexOfScalarPos(u8, text, pos, '$')) |dollar| {
        const start = dollar + 1;
        if (start + workflow.len <= text.len and std.mem.eql(u8, text[start .. start + workflow.len], workflow)) {
            const end = start + workflow.len;
            if (end == text.len or !isSignalNameChar(text[end])) return true;
        }
        pos = start;
    }
    return false;
}

fn extractFlatJsonStringField(line: []const u8, field: []const u8) ?[]const u8 {
    var buf: [64]u8 = undefined;
    const pattern = std.fmt.bufPrint(&buf, "\"{s}\":\"", .{field}) catch return null;
    const start = (std.mem.indexOf(u8, line, pattern) orelse return null) + pattern.len;
    const rel_end = std.mem.indexOfScalarPos(u8, line, start, '"') orelse return null;
    return line[start..rel_end];
}

fn getOrCreateWorkflowOverlapState(
    allocator: std.mem.Allocator,
    states: *std.ArrayList(WorkflowOverlapState),
    index: *std.StringHashMap(usize),
    path: []const u8,
) !usize {
    if (index.get(path)) |idx| return idx;
    const owned_path = try allocator.dupe(u8, path);
    errdefer allocator.free(owned_path);
    try states.append(allocator, .{ .path = owned_path });
    errdefer {
        var popped = states.pop().?;
        popped.deinit(allocator);
    }
    const idx = states.items.len - 1;
    try index.put(states.items[idx].path, idx);
    return idx;
}

fn recordWorkflowOverlapSignal(
    allocator: std.mem.Allocator,
    state: *WorkflowOverlapState,
    is_a: bool,
    timestamp: ?[]const u8,
) !void {
    if (is_a) {
        state.signals_a += 1;
        try recordWorkflowOverlapTimestamp(allocator, &state.first_seen_a, &state.last_seen_a, timestamp);
    } else {
        state.signals_b += 1;
        try recordWorkflowOverlapTimestamp(allocator, &state.first_seen_b, &state.last_seen_b, timestamp);
    }
}

fn recordWorkflowOverlapTimestamp(
    allocator: std.mem.Allocator,
    first_seen: *?[]u8,
    last_seen: *?[]u8,
    timestamp: ?[]const u8,
) !void {
    const value = timestamp orelse return;
    if (first_seen.* == null or std.mem.order(u8, value, first_seen.*.?) == .lt) {
        if (first_seen.*) |old| allocator.free(old);
        first_seen.* = try allocator.dupe(u8, value);
    }
    if (last_seen.* == null or std.mem.order(u8, value, last_seen.*.?) == .gt) {
        if (last_seen.*) |old| allocator.free(old);
        last_seen.* = try allocator.dupe(u8, value);
    }
}

fn deinitWorkflowOverlapStates(allocator: std.mem.Allocator, states: *std.ArrayList(WorkflowOverlapState)) void {
    for (states.items) |*state| state.deinit(allocator);
    states.deinit(allocator);
}

fn parseWorkflowPair(raw: []const u8) !WorkflowPair {
    var split = std.mem.splitScalar(u8, raw, ',');
    const a = std.mem.trim(u8, split.next() orelse return error.InvalidModeArg, " \t\r\n");
    const b = std.mem.trim(u8, split.next() orelse return error.InvalidModeArg, " \t\r\n");
    if (split.next() != null or a.len == 0 or b.len == 0) return error.InvalidModeArg;
    return .{ .a = a, .b = b };
}

fn percentage(numerator: usize, denominator: usize) f64 {
    if (denominator == 0) return 0;
    return (@as(f64, @floatFromInt(numerator)) * 100.0) / @as(f64, @floatFromInt(denominator));
}

fn appendWorkflowOverlapSessionStateRow(
    allocator: std.mem.Allocator,
    out_rows: *std.ArrayList(query.Row),
    state: WorkflowOverlapState,
) !void {
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    const has_a = state.signals_a > 0;
    const has_b = state.signals_b > 0;
    try row.putOwnedKey("path", .{ .string = state.path });
    try row.putOwnedKey("overlap_class", .{ .string = if (has_a and has_b) "overlap" else if (has_a) "a_only" else "b_only" });
    try row.putOwnedKey("in_a", .{ .bool = has_a });
    try row.putOwnedKey("in_b", .{ .bool = has_b });
    try row.putOwnedKey("signals_a", if (has_a) .{ .int = @intCast(state.signals_a) } else .null);
    try row.putOwnedKey("signals_b", if (has_b) .{ .int = @intCast(state.signals_b) } else .null);
    try row.putOwnedKey("first_seen_a", if (state.first_seen_a) |value| .{ .string = value } else .null);
    try row.putOwnedKey("last_seen_a", if (state.last_seen_a) |value| .{ .string = value } else .null);
    try row.putOwnedKey("first_seen_b", if (state.first_seen_b) |value| .{ .string = value } else .null);
    try row.putOwnedKey("last_seen_b", if (state.last_seen_b) |value| .{ .string = value } else .null);
    try out_rows.append(allocator, row);
}

fn collectWorkflowAuditRows(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    opts: Options,
) !std.ArrayList(query.Row) {
    const workflow = opts.workflow orelse return error.MissingWorkflowArg;

    var where: std.ArrayList(spec.WhereClause) = .empty;
    defer where.deinit(allocator);
    const last_bounds = try QueryLiftCommands.appendLastWindowBoundsForField(allocator, &where, "timestamp", opts);
    defer last_bounds.deinit(allocator);
    try appendSessionTimeBounds(allocator, &where, opts);

    const signal_query = spec.QuerySpec{
        .where = where.items,
        .select = workflow_audit_signal_columns[0..],
    };
    var workdir_paths = StringSet.init(allocator);
    var has_workdir_filter = false;
    defer if (has_workdir_filter) workdir_paths.deinit();
    if (opts.workdir_text != null) {
        has_workdir_filter = true;
        try collectWorkdirSessionPaths(allocator, sessions_root, opts, &workdir_paths);
    }

    const day_filter = deriveSessionDayPathFilter("workflow_signals", where.items);
    var paths = try collectJsonlPaths(allocator, sessions_root, day_filter);
    defer freePathList(allocator, &paths);
    const exclude_path = if (opts.exclude_current) try QueryLiftCommands.resolveCurrentSessionPathForExclusion(allocator, sessions_root) else null;
    defer if (exclude_path) |path| allocator.free(path);

    var out: std.ArrayList(query.Row) = .empty;
    errdefer deinitQueryRows(allocator, &out);
    for (paths.items) |path| {
        if (exclude_path) |excluded| {
            if (std.mem.eql(u8, path, excluded)) continue;
        }
        if (has_workdir_filter and !workdir_paths.contains(path)) continue;
        try appendWorkflowAuditRowsForPath(allocator, sessions_root, path, signal_query, workflow, &out);
    }

    return out;
}

fn appendWorkflowAuditRowsForPath(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    path: []const u8,
    signal_query: spec.QuerySpec,
    workflow: []const u8,
    out_rows: *std.ArrayList(query.Row),
) !void {
    var text_rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &text_rows);
    try appendTextWorkflowSignalRowsForPath(allocator, path, &text_rows);

    var filtered_text = try query.execute(allocator, text_rows.items, signal_query);
    defer filtered_text.deinit(allocator);
    if (!hasWorkflowCohortSignal(filtered_text.rows.items, workflow)) return;

    try appendMovedRows(allocator, out_rows, &filtered_text.rows);

    var derived_rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &derived_rows);
    try appendToolWorkflowSignalRowsForPath(allocator, sessions_root, path, &derived_rows);
    try appendWorkflowGraphSignalsForPath(allocator, sessions_root, path, &derived_rows);

    var filtered_derived = try query.execute(allocator, derived_rows.items, signal_query);
    defer filtered_derived.deinit(allocator);
    try appendMovedRows(allocator, out_rows, &filtered_derived.rows);
}

fn appendMessageWorkflowProvenanceRows(
    allocator: std.mem.Allocator,
    out_rows: *std.ArrayList(query.Row),
    workflow: []const u8,
    session_id: ?[]const u8,
    path: []const u8,
    message: datasets.messages.MessageRow,
) !void {
    if (containsDollarWorkflowMention(message.text, workflow)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "explicit_workflow_declaration",
            .source = sourceKindForRole(message.role),
            .timestamp = message.timestamp,
            .ref = message.text,
            .reason = "dollar_workflow_declaration",
            .path = path,
        });
        return;
    }

    if (containsIgnoreCaseAscii(message.text, workflow) and containsArtifactRepairCue(message.text)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "artifact_under_repair",
            .source = sourceKindForRole(message.role),
            .timestamp = message.timestamp,
            .ref = message.text,
            .reason = "artifact_repair_text",
            .path = path,
        });
    } else if (containsIgnoreCaseAscii(message.text, workflow)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "filename_or_path_mention",
            .source = sourceKindForRole(message.role),
            .timestamp = message.timestamp,
            .ref = message.text,
            .reason = "workflow_name_text_mention",
            .path = path,
        });
    }
}

fn appendToolWorkflowProvenanceRows(
    allocator: std.mem.Allocator,
    out_rows: *std.ArrayList(query.Row),
    workflow: []const u8,
    session_id: ?[]const u8,
    path: []const u8,
    parsed: canonical_trace.CanonicalSessionTrace,
    tool: canonical_trace.ToolLifecycleRecord,
) !void {
    const tool_text = reviewCompilerToolText(tool);
    const timestamp = toolTimestamp(parsed, tool);
    if (std.mem.eql(u8, workflow, "review-compiler") and reviewCompilerToolIsCompletedC3Controller(tool)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "controller_invocation",
            .source = "tool_call",
            .timestamp = timestamp,
            .ref = tool.command_text orelse tool_text,
            .reason = "c3_controller_invocation",
            .path = path,
        });
    } else if (toolNameMatchesWorkflow(tool, workflow)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "controller_invocation",
            .source = "tool_call",
            .timestamp = timestamp,
            .ref = tool.command_text orelse tool_text,
            .reason = "tool_name_matches_workflow",
            .path = path,
        });
    } else if (containsIgnoreCaseAscii(tool_text, workflow) and containsArtifactRepairCue(tool_text)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "artifact_under_repair",
            .source = "tool_call",
            .timestamp = timestamp,
            .ref = tool_text,
            .reason = "artifact_repair_tool",
            .path = path,
        });
    } else if (containsIgnoreCaseAscii(tool_text, workflow)) {
        try appendWorkflowProvenanceRow(allocator, out_rows, .{
            .session_id = session_id,
            .workflow_name = workflow,
            .evidence_class = "filename_or_path_mention",
            .source = "tool_call",
            .timestamp = timestamp,
            .ref = tool_text,
            .reason = "workflow_name_tool_text_mention",
            .path = path,
        });
    }
}

const WorkflowProvenanceInput = struct {
    session_id: ?[]const u8,
    workflow_name: []const u8,
    evidence_class: []const u8,
    source: []const u8,
    timestamp: ?[]const u8,
    ref: []const u8,
    reason: []const u8,
    path: []const u8,
};

fn appendWorkflowProvenanceRow(
    allocator: std.mem.Allocator,
    out_rows: *std.ArrayList(query.Row),
    input: WorkflowProvenanceInput,
) !void {
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    try putOptionalString(&row, "session_id", input.session_id);
    try row.putStaticKey("workflow_name", .{ .string = input.workflow_name });
    try row.putStaticKey("evidence_class", .{ .string = input.evidence_class });
    try row.putStaticKey("source", .{ .string = input.source });
    try putOptionalString(&row, "timestamp", input.timestamp);
    try row.putStaticKey("ref", .{ .string = input.ref[0..@min(input.ref.len, 240)] });
    try row.putStaticKey("reason", .{ .string = input.reason });
    try row.putStaticKey("path", .{ .string = input.path });
    try out_rows.append(allocator, row);
}

fn containsArtifactRepairCue(text: []const u8) bool {
    return containsAnyIgnoreCaseAscii(text, &.{
        "artifact_under_repair",
        "artifact repair",
        "artifact maintenance",
        "delete_sidecar",
        "sidecar",
        "retiring",
        "retired",
        "duplicate sidecar",
    });
}

fn toolNameMatchesWorkflow(tool: canonical_trace.ToolLifecycleRecord, workflow: []const u8) bool {
    const tool_name = tool.tool_name orelse return false;
    return std.mem.eql(u8, tool_name, workflow) or
        std.mem.eql(u8, pathBasenameSlice(tool_name), workflow);
}

fn appendTextWorkflowSignalRowsForPath(
    allocator: std.mem.Allocator,
    path: []const u8,
    out_rows: *std.ArrayList(query.Row),
) !void {
    const content = try readFileAllocOrSkip(allocator, path);
    if (content == null) return;
    defer allocator.free(content.?);

    const messages = try datasets.messages.parseJsonl(allocator, path, content.?, .{
        .strip_skill_blocks = true,
        .dedupe_by_role_and_text = true,
    });
    defer datasets.messages.freeRows(allocator, messages);

    for (messages) |row| {
        try appendDollarWorkflowSignals(allocator, out_rows, row);
        try appendOutcomeSignals(allocator, out_rows, row);
    }

    const mentions = try datasets.skill_mentions.parseJsonl(allocator, path, content.?, .{
        .include_blocks = false,
        .include_dollars = true,
        .skip_dollar_in_skill_block = true,
        .dedupe_adjacent = true,
    });
    defer datasets.skill_mentions.freeRows(allocator, mentions);

    for (mentions) |row| {
        try appendWorkflowSignalRow(
            allocator,
            out_rows,
            row.path,
            null,
            row.timestamp,
            row.role,
            sourceKindForRole(row.role),
            "skill_mention",
            row.skill,
            null,
            row.snippet,
            "cleaned",
        );
    }
}

fn appendToolWorkflowSignalRowsForPath(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    path: []const u8,
    out_rows: *std.ArrayList(query.Row),
) !void {
    const params = [_]spec.ParamSpec{.{ .key = "path", .value = .{ .string = path } }};
    var tool_rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &tool_rows);
    try collectToolInvocationRows(allocator, sessions_root, null, params[0..], &tool_rows);

    for (tool_rows.items) |row| {
        const tool_name = scalarString(row.valueOrNull("tool_name")) orelse continue;
        try appendWorkflowSignalRow(
            allocator,
            out_rows,
            scalarString(row.valueOrNull("path")) orelse "",
            scalarString(row.valueOrNull("session_id")),
            scalarString(row.valueOrNull("timestamp")),
            null,
            "tool_trace",
            "tool_call",
            tool_name,
            null,
            scalarString(row.valueOrNull("command_text")) orelse tool_name,
            "none",
        );
    }
}

fn appendMovedRows(
    allocator: std.mem.Allocator,
    out_rows: *std.ArrayList(query.Row),
    rows: *std.ArrayList(query.Row),
) !void {
    for (rows.items) |*row| {
        const moved = row.*;
        try out_rows.append(allocator, moved);
        row.* = query.Row.init(allocator);
    }
}

fn hasWorkflowCohortSignal(rows: []const query.Row, workflow: []const u8) bool {
    for (rows) |row| {
        if (isWorkflowCohortSignal(row, workflow)) return true;
    }
    return false;
}

fn collectWorkdirSessionPaths(
    allocator: std.mem.Allocator,
    sessions_root: []const u8,
    opts: Options,
    out: *StringSet,
) !void {
    var where: std.ArrayList(spec.WhereClause) = .empty;
    defer where.deinit(allocator);

    if (opts.workdir_text) |value| try where.append(allocator, .{
        .field = "cwd",
        .op = .eq,
        .value = .{ .scalar = .{ .string = value } },
    });
    if (opts.since) |value| try where.append(allocator, .{
        .field = "start_time",
        .op = .gte,
        .value = .{ .scalar = .{ .string = value } },
    });
    if (opts.until) |value| try where.append(allocator, .{
        .field = "start_time",
        .op = .lte,
        .value = .{ .scalar = .{ .string = value } },
    });

    const session_query = spec.QuerySpec{ .where = where.items };
    var collected = try collectDatasetRowsForSpec(allocator, "sessions", sessions_root, session_query);
    defer deinitQueryRows(allocator, &collected);

    var filtered = try query.execute(allocator, collected.items, session_query);
    defer filtered.deinit(allocator);

    for (filtered.rows.items) |row| {
        const path = scalarString(row.valueOrNull("path")) orelse continue;
        try out.put(path);
    }
}

fn isWorkflowCohortSignal(row: query.Row, workflow: []const u8) bool {
    const name = scalarString(row.valueOrNull("name")) orelse return false;
    if (!std.mem.eql(u8, name, workflow)) return false;
    const signal_kind = scalarString(row.valueOrNull("signal_kind")) orelse return false;
    return std.mem.eql(u8, signal_kind, "workflow_mention") or
        std.mem.eql(u8, signal_kind, "skill_mention");
}

fn writeWorkflowAuditMarkdown(
    allocator: std.mem.Allocator,
    workflow: []const u8,
    rows: []const query.Row,
    out_path: ?[]const u8,
) !void {
    var sessions = StringSet.init(allocator);
    defer sessions.deinit();
    for (rows) |row| {
        if (scalarString(row.valueOrNull("path"))) |path| try sessions.put(path);
    }

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.print("# seq workflow-audit: {s}\n\n", .{workflow});
    try writer.print("- cohort_sessions: {d}\n", .{sessions.count()});
    try writer.print("- cohort_signals: {d}\n\n", .{rows.len});

    try writer.writeAll("## Signal Summary\n\n");
    try writeWorkflowAuditMarkdownSection(allocator, writer, rows, "summary");

    try writer.writeAll("\n## Outcomes\n\n");
    try writeWorkflowAuditMarkdownSection(allocator, writer, rows, "outcomes");

    try writer.writeAll("\n## Sessions\n\n");
    try writeWorkflowAuditMarkdownSection(allocator, writer, rows, "sessions");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, out_path);
}

const WorkflowCohortReport = struct {
    workflow: []const u8,
    rows: []const query.Row,
    cohort_paths: StringSet,
    direct_signals: usize = 0,

    fn init(allocator: std.mem.Allocator, workflow: []const u8, rows: []const query.Row) !WorkflowCohortReport {
        var report = WorkflowCohortReport{
            .workflow = workflow,
            .rows = rows,
            .cohort_paths = StringSet.init(allocator),
        };
        errdefer report.deinit();

        for (rows) |row| {
            if (!isWorkflowCohortSignal(row, workflow)) continue;
            const path = scalarString(row.valueOrNull("path")) orelse continue;
            try report.cohort_paths.put(path);
            report.direct_signals += 1;
        }

        return report;
    }

    fn deinit(self: *WorkflowCohortReport) void {
        self.cohort_paths.deinit();
    }
};

fn writeWorkflowCohortReport(
    allocator: std.mem.Allocator,
    workflow: []const u8,
    rows: []const query.Row,
    fmt: output.Format,
    limit: usize,
    out_path: ?[]const u8,
) !void {
    var report = try WorkflowCohortReport.init(allocator, workflow, rows);
    defer report.deinit();

    switch (fmt) {
        .markdown => try writeWorkflowCohortReportMarkdown(allocator, report, limit, out_path),
        .json => try writeWorkflowCohortReportJson(allocator, report, limit, out_path),
        else => return error.InvalidFormatForCommand,
    }
}

fn writeWorkflowCohortReportMarkdown(
    allocator: std.mem.Allocator,
    report: WorkflowCohortReport,
    limit: usize,
    out_path: ?[]const u8,
) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.print("# seq workflow-audit cohort-report: {s}\n\n", .{report.workflow});
    try writer.print("- cohort_sessions: {d}\n", .{report.cohort_paths.count()});
    try writer.print("- cohort_signals: {d}\n", .{report.rows.len});
    try writer.print("- direct_cohort_signals: {d}\n", .{report.direct_signals});
    try writer.writeAll("- cohort_authority: direct workflow_mention or skill_mention rows selected before derived rows\n\n");

    try writer.writeAll("## Signal Summary\n\n");
    try writeWorkflowAuditMarkdownSection(allocator, writer, report.rows, "summary");

    try writer.writeAll("\n## Outcomes\n\n");
    try writeWorkflowAuditMarkdownSection(allocator, writer, report.rows, "outcomes");

    try writer.writeAll("\n## Sessions\n\n");
    try writeWorkflowAuditMarkdownSection(allocator, writer, report.rows, "sessions");

    try writer.writeAll("\n## Evidence\n\n");
    const evidence_query = try workflowAuditQueryForMode("signals", if (limit > 0) limit else 25);
    var evidence = try query.execute(allocator, report.rows, evidence_query);
    defer evidence.deinit(allocator);
    try writeMarkdownTable(writer, evidence.rows.items, workflow_audit_signal_columns[0..]);

    try writer.writeAll("\n## Replaced Raw Queries\n\n");
    try writeWorkflowCohortReplacementTable(writer);

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, out_path);
}

fn writeWorkflowCohortReportJson(
    allocator: std.mem.Allocator,
    report: WorkflowCohortReport,
    limit: usize,
    out_path: ?[]const u8,
) !void {
    const summary_query = try workflowAuditQueryForMode("summary", 50);
    var summary = try query.execute(allocator, report.rows, summary_query);
    defer summary.deinit(allocator);

    const outcomes_query = try workflowAuditQueryForMode("outcomes", 20);
    var outcomes = try query.execute(allocator, report.rows, outcomes_query);
    defer outcomes.deinit(allocator);

    const sessions_query = try workflowAuditQueryForMode("sessions", if (limit > 0) limit else 50);
    var sessions = try query.execute(allocator, report.rows, sessions_query);
    defer sessions.deinit(allocator);

    const evidence_query = try workflowAuditQueryForMode("signals", if (limit > 0) limit else 25);
    var evidence = try query.execute(allocator, report.rows, evidence_query);
    defer evidence.deinit(allocator);

    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.writeAll("{\n  \"command\": \"workflow-audit\",\n  \"mode\": \"cohort-report\",\n  \"workflow\": ");
    try output.writeJsonString(writer, report.workflow);
    try writer.writeAll(",\n  \"cohort_selection\": {\n    \"authority\": \"direct workflow_mention or skill_mention rows selected before derived rows\",\n    \"paths\": ");
    try writeStringSetJsonArray(writer, report.cohort_paths);
    try writer.writeAll("\n  },\n  \"counts\": {\"cohort_sessions\": ");
    try writer.print("{d}", .{report.cohort_paths.count()});
    try writer.writeAll(", \"cohort_signals\": ");
    try writer.print("{d}", .{report.rows.len});
    try writer.writeAll(", \"direct_cohort_signals\": ");
    try writer.print("{d}", .{report.direct_signals});
    try writer.writeAll("},\n  \"performance_model\": {\"cohort_selection_passes\": 1, \"derived_rows_filtered_by_selected_paths\": true},\n  \"replaced_raw_queries\": ");
    try writeWorkflowCohortReplacementJson(writer);
    try writer.writeAll(",\n  \"summary\": ");
    try writeRowsJsonArray(writer, summary.rows.items, workflow_audit_summary_columns[0..], "    ");
    try writer.writeAll(",\n  \"outcomes\": ");
    try writeRowsJsonArray(writer, outcomes.rows.items, workflow_audit_outcome_columns[0..], "    ");
    try writer.writeAll(",\n  \"sessions\": ");
    try writeRowsJsonArray(writer, sessions.rows.items, workflow_audit_session_columns[0..], "    ");
    try writer.writeAll(",\n  \"evidence\": ");
    try writeRowsJsonArray(writer, evidence.rows.items, workflow_audit_signal_columns[0..], "    ");
    try writer.writeAll("\n}\n");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, out_path);
}

fn writeStringSetJsonArray(writer: anytype, set: StringSet) !void {
    try writer.writeAll("[");
    var it = set.map.keyIterator();
    var first = true;
    while (it.next()) |path| {
        if (!first) try writer.writeAll(", ");
        first = false;
        try output.writeJsonString(writer, path.*);
    }
    try writer.writeAll("]");
}

fn writeWorkflowCohortReplacementTable(writer: anytype) !void {
    try writer.writeAll("| legacy raw query family | cohort-report section |\n");
    try writer.writeAll("| --- | --- |\n");
    try writer.writeAll("| `workflow_signals` filtered by name/path | Signal Summary, Evidence |\n");
    try writer.writeAll("| `workflow_signals` grouped by path | Sessions |\n");
    try writer.writeAll("| outcome rows grouped by `outcome_kind` | Outcomes |\n");
    try writer.writeAll("| manual `seq query` plus follow-up table shaping | `--mode cohort-report --format markdown|json` |\n");
}

fn writeWorkflowCohortReplacementJson(writer: anytype) !void {
    try writer.writeAll("[\n");
    try writer.writeAll("    {\"legacy_query_family\": \"workflow_signals filtered by name/path\", \"cohort_report_section\": \"Signal Summary, Evidence\"},\n");
    try writer.writeAll("    {\"legacy_query_family\": \"workflow_signals grouped by path\", \"cohort_report_section\": \"Sessions\"},\n");
    try writer.writeAll("    {\"legacy_query_family\": \"outcome rows grouped by outcome_kind\", \"cohort_report_section\": \"Outcomes\"},\n");
    try writer.writeAll("    {\"legacy_query_family\": \"manual seq query plus follow-up table shaping\", \"cohort_report_section\": \"--mode cohort-report --format markdown|json\"}\n");
    try writer.writeAll("  ]");
}

fn writeWorkflowAuditMarkdownSection(
    allocator: std.mem.Allocator,
    writer: anytype,
    rows: []const query.Row,
    mode: []const u8,
) !void {
    const query_spec = try workflowAuditQueryForMode(mode, 10);
    var result = try query.execute(allocator, rows, query_spec);
    defer result.deinit(allocator);

    try writeMarkdownTable(writer, result.rows.items, workflowAuditColumnsForMode(mode) orelse &.{});
}

fn writeWorkflowAuditModeMarkdown(
    allocator: std.mem.Allocator,
    workflow: []const u8,
    mode: []const u8,
    rows: []const query.Row,
    columns: []const []const u8,
    out_path: ?[]const u8,
) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.print("# seq workflow-audit: {s} ({s})\n\n", .{ workflow, mode });
    try writeMarkdownTable(writer, rows, columns);

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    try writeTextOutput(rendered, out_path);
}

