    c3_apply_certified_seen: bool = false,
    c3_final_certified_seen: bool = false,
    c3_new_counterexample_seen: bool = false,
    c3_reset_seen: bool = false,
    c3_basis_after_reset_seen: bool = false,
    c3_recompiled_seen: bool = false,
    c3_raw_delivery_mutation_seen: bool = false,
    c3_commit_or_push_bypass_seen: bool = false,
    c3_candidate_worktree_context_seen: bool = false,
    mbk_begin_seen: bool = false,
    mbk_begin_at_ms: ?i64 = null,
    mbk_terminal_at_ms: ?i64 = null,
    mbk_tuple_closed_seen: bool = false,
    mbk_terminal_closed_seen: bool = false,
    mbk_kernel_accepted_seen: bool = false,
    mbk_clean_review_seen: bool = false,
    mbk_isolated_conformance_seen: bool = false,
    mbk_material_kernel_required_seen: bool = false,
    mbk_batches_total: usize = 0,
    mbk_potential_strict_progress: usize = 0,
    mbk_semantic_surface_before: usize = 0,
    mbk_semantic_surface_after: usize = 0,
    mbk_semantic_surface_delta: usize = 0,
    mbk_orphan_code_constructs: usize = 0,
    mbk_unmapped_proof_actions: usize = 0,
    mbk_wound_specific_tests: usize = 0,
    mbk_wound_specific_tests_class_mapped: bool = false,
    mbk_ac_rebased: bool = false,
    mbk_rac_total: usize = 0,
    mbk_rac_valid: usize = 0,
    mbk_rac_mutation_allowed: usize = 0,
    mbk_mutation_gate_status: []const u8 = "missing",
    mbk_closure_gate_status: []const u8 = "missing",
};

fn cmdResolveChurnAudit(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const repo_raw = opts.repo_text orelse return error.MissingArgValue;
    try validateWindowedAuditBounds(opts, "resolve-churn-audit");
    const repo_root = try resolveExplicitRepoRoot(allocator, repo_raw);
    defer allocator.free(repo_root);

    const current_thread_id = if (opts.exclude_current)
        getEnvVarOwned(allocator, "CODEX_THREAD_ID") catch |err| switch (err) {
            error.EnvironmentVariableNotFound => {
                printCliError("error: --exclude-current requires CODEX_THREAD_ID in the environment\n", .{});
                return error.CurrentSessionUnavailable;
            },
            else => return err,
        }
    else
        null;
    defer if (current_thread_id) |id| allocator.free(id);

    var audit = ResolveChurnAudit{};
    defer audit.deinit(allocator);

    var paths = try collectTraceRolloutPaths(allocator, sessions_root);
    defer freePathList(allocator, &paths);

    for (paths.items) |path| {
        var parsed = canonical_trace.parseSessionTrace(allocator, path, traceParseOptions(opts)) catch continue;
        defer parsed.deinit(allocator);

        if (current_thread_id) |thread_id| {
            if (resolveTraceMatchesThread(parsed, path, thread_id)) continue;
        }
        if (!resolveSessionOverlapsWindow(parsed.session.start_time, parsed.session.end_time, opts)) continue;
        if (!try resolveTraceMatchesRepo(allocator, repo_root, parsed)) continue;

        const content = (try readFileAllocOrSkip(allocator, path)) orelse continue;
        defer allocator.free(content);
        const messages = datasets.messages.parseJsonl(allocator, path, content, .{
            .include_user = true,
            .include_assistant = true,
            .strip_echo_assistant = true,
            .skip_meta_user_messages = true,
            .dedupe_by_role_and_text = false,
            .strip_skill_blocks = true,
        }) catch continue;
        defer datasets.messages.freeRows(allocator, messages);

        var signals = summarizeResolveSession(messages, parsed, opts);
        if (!signals.candidate) continue;
        audit.denominator.candidate_sessions += 1;
        if (!signals.true_resolve) {
            audit.denominator.exclusions += 1;
            continue;
        }

        audit.denominator.true_resolve_sessions += 1;
        try recordResolveMessages(allocator, &audit, messages, opts, &signals);
        try recordResolveTools(allocator, &audit, parsed, repo_root, opts, &signals);

        if (signals.mutation_session) {
            audit.permits.required += 1;
            if (!signals.permit_emitted) {
                audit.permits.missing += 1;
                audit.compliance.mutations_without_permit += 1;
            }
        }
        if (signals.fuse_tripped and signals.mutation_after_fuse and !signals.distillation_seen) {
            audit.compliance.mutations_after_fuse_without_distillation += 1;
        }
    }

    audit.compliance.normal_form_retries_after_falsification = audit.normal_forms.repeated_after_falsification;

    const fmt = if (opts.format_set) opts.format else output.Format.markdown;
    return switch (fmt) {
        .json => writeResolveChurnAuditJson(allocator, audit, opts.out_path),
        .markdown => writeResolveChurnAuditMarkdown(allocator, audit, opts.out_path),
        else => error.InvalidFormatForCommand,
    };
}

fn validateWindowedAuditBounds(opts: Options, command_name: []const u8) !void {
    const since = opts.since orelse return;
    const until = opts.until orelse return;
    const since_ms = time_utils.parseIsoTimestampMillis(since) orelse {
        printCliError("error: {s} --since must be an ISO-8601 timestamp with timezone\n", .{command_name});
        return error.InvalidTimestampArg;
    };
    const until_ms = time_utils.parseIsoTimestampMillis(until) orelse {
        printCliError("error: {s} --until must be an ISO-8601 timestamp with timezone\n", .{command_name});
        return error.InvalidTimestampArg;
    };
    if (since_ms > until_ms) {
        printCliError("error: {s} --since must be before or equal to --until\n", .{command_name});
        return error.InvalidTimestampArg;
    }
}

fn resolveSessionOverlapsWindow(start_opt: ?[]const u8, end_opt: ?[]const u8, opts: Options) bool {
    const start_ms = if (start_opt) |value| time_utils.parseIsoTimestampMillis(value) else null;
    const end_ms = if (end_opt) |value| time_utils.parseIsoTimestampMillis(value) else start_ms;
    const effective_start = start_ms orelse end_ms orelse return false;
    const effective_end = end_ms orelse effective_start;
    if (opts.since) |since| {
        const since_ms = time_utils.parseIsoTimestampMillis(since) orelse return false;
        if (effective_end < since_ms) return false;
    }
    if (opts.until) |until| {
        const until_ms = time_utils.parseIsoTimestampMillis(until) orelse return false;
        if (effective_start > until_ms) return false;
    }
    return true;
}

fn cmdReviewCompilerAudit(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
    const repo_raw = opts.repo_text orelse return error.MissingArgValue;
    try validateWindowedAuditBounds(opts, "review-compiler-audit");
    const repo_root = try resolveExplicitRepoRoot(allocator, repo_raw);
    defer allocator.free(repo_root);

    const current_thread_id = if (opts.exclude_current)
        getEnvVarOwned(allocator, "CODEX_THREAD_ID") catch |err| switch (err) {
            error.EnvironmentVariableNotFound => {
                printCliError("error: --exclude-current requires CODEX_THREAD_ID in the environment\n", .{});
                return error.CurrentSessionUnavailable;
            },
            else => return err,
        }
    else
        null;
    defer if (current_thread_id) |id| allocator.free(id);

    var audit = ReviewCompilerAudit{
        .requested_protocol = if (opts.protocol_text) |text| try parseReviewCompilerProtocol(text) else .auto,
    };
    defer audit.deinit(allocator);

    var paths = try collectTraceRolloutPaths(allocator, sessions_root);
    defer freePathList(allocator, &paths);

    for (paths.items) |path| {
        var parsed = canonical_trace.parseSessionTrace(allocator, path, traceParseOptions(opts)) catch continue;
        defer parsed.deinit(allocator);

        if (current_thread_id) |thread_id| {
            if (resolveTraceMatchesThread(parsed, path, thread_id)) continue;
        }
        if (!resolveSessionOverlapsWindow(parsed.session.start_time, parsed.session.end_time, opts)) continue;
        if (!try resolveTraceMatchesRepo(allocator, repo_root, parsed)) continue;

        const content = (try readFileAllocOrSkip(allocator, path)) orelse continue;
        defer allocator.free(content);
        const messages = datasets.messages.parseJsonl(allocator, path, content, .{
            .include_user = true,
            .include_assistant = true,
            .strip_echo_assistant = true,
            .skip_meta_user_messages = true,
            .dedupe_by_role_and_text = false,
            .strip_skill_blocks = true,
        }) catch continue;
        defer datasets.messages.freeRows(allocator, messages);

        var signals = summarizeReviewCompilerSession(messages, parsed, opts);
        if (!signals.candidate) continue;
        audit.denominator.candidate_sessions += 1;
        switch (signals.governance_state) {
            .authoritative => audit.denominator.authoritative_sessions += 1,
            .declared_uncontrolled => audit.denominator.declared_uncontrolled_sessions += 1,
            .incidental => audit.denominator.incidental_sessions += 1,
            .ambiguous => audit.denominator.ambiguous_sessions += 1,
            .absent => {},
        }
        audit.mbk.denominator.candidate_sessions += 1;
        var mbk_exclusion_recorded = false;
        if ((audit.requested_protocol == .auto or audit.requested_protocol == .mbk or audit.requested_protocol == .mbk_v1_legacy_open_horizon) and !signals.true_mbk) {
            try addReviewCompilerMBKExclusion(allocator, &audit, parsed.session.session_id, path, "candidate_without_mbk_evidence");
            mbk_exclusion_recorded = true;
        }
        const protocol_match = switch (audit.requested_protocol) {
            .auto => signals.true_resolve,
            .legacy_cleanroom => signals.true_legacy,
            .c3, .c3_mrpc => signals.true_c3,
            .mbk, .mbk_v1_legacy_open_horizon => signals.true_mbk,
            .intent_closed_cegis_v1 => signals.true_mbk and signals.true_c3,
            .mixed => signals.true_mbk and signals.true_c3,
            .none => false,
        };
        if (!protocol_match) {
            const reason: []const u8 = switch (audit.requested_protocol) {
                .auto => "candidate_without_protocol_evidence",
                .legacy_cleanroom => "candidate_without_assistant_cleanroom_evidence",
                .c3, .c3_mrpc => if (signals.governance_state == .incidental) signals.incidental_reason else "candidate_without_c3_evidence",
                .mbk, .mbk_v1_legacy_open_horizon => "candidate_without_mbk_evidence",
                .intent_closed_cegis_v1 => "candidate_without_intent_closed_artifact_evidence",
                .mixed => "candidate_without_mixed_protocol_evidence",
                .none => "protocol_none_never_included",
            };
            try addReviewCompilerExclusionWithGovernance(allocator, &audit, parsed.session.session_id, path, reason, signals.governance_state.label(), signals.delivery_closed_seen);
            if ((audit.requested_protocol == .mbk or audit.requested_protocol == .mbk_v1_legacy_open_horizon) and !mbk_exclusion_recorded) try addReviewCompilerMBKExclusion(allocator, &audit, parsed.session.session_id, path, reason);
            continue;
        }

        audit.denominator.true_resolve_sessions += 1;
        try recordReviewCompilerMessages(allocator, &audit, messages, opts, &signals, parsed.session.session_id);
        try recordReviewCompilerTools(allocator, &audit, parsed, repo_root, opts, &signals);
        finalizeReviewCompilerCompliance(&audit, signals);
        if (signals.true_mbk) try addReviewCompilerMaterialRun(allocator, &audit, signals, parsed.session.session_id, repo_root);
        if (signals.true_c3) try addReviewCompilerC3IncludedSession(allocator, &audit, signals, parsed.session.session_id, path);
    }

    const mode = if (opts.emit_count_evidence) "evidence" else opts.mode orelse "summary";
    const fmt = if (opts.format_set) opts.format else if (std.mem.eql(u8, mode, "summary") or std.mem.eql(u8, mode, "report")) output.Format.markdown else output.Format.table;
    if (opts.review_compiler_strict and hasStrictReviewCompilerFailure(audit)) std.process.exit(2);
    if (std.mem.eql(u8, mode, "runs")) return writeReviewCompilerRunsMode(allocator, audit, fmt, opts.out_path);
    if (std.mem.eql(u8, mode, "evidence")) return writeReviewCompilerEvidenceMode(allocator, audit, fmt, opts.out_path);
    if (std.mem.eql(u8, mode, "batches") or std.mem.eql(u8, mode, "counterexamples") or std.mem.eql(u8, mode, "potential") or std.mem.eql(u8, mode, "closure")) return writeReviewCompilerIntentRowsMode(allocator, audit, mode, fmt, opts.out_path);
    if (std.mem.eql(u8, mode, "report")) return writeReviewCompilerIntentReportMarkdown(allocator, audit, opts.artifact_root_text, opts.out_path);
    return switch (fmt) {
        .json => writeReviewCompilerAuditJson(allocator, audit, opts.out_path),
        .markdown => writeReviewCompilerAuditMarkdown(allocator, audit, opts.out_path),
        .table => writeReviewCompilerRunsMode(allocator, audit, fmt, opts.out_path),
        .jsonl => writeReviewCompilerRunsJsonl(allocator, audit, opts.out_path),
        else => error.InvalidFormatForCommand,
    };
}

fn addReviewCompilerExclusionWithGovernance(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    session_id: ?[]const u8,
    path: []const u8,
    reason: []const u8,
    governance: []const u8,
    delivery_closed: bool,
) !void {
    audit.denominator.excluded_sessions += 1;
    try audit.denominator.exclusions.append(allocator, .{
        .session_id = if (session_id) |id| try allocator.dupe(u8, id) else null,
        .path = try allocator.dupe(u8, path),
        .reason = try allocator.dupe(u8, reason),
        .governance = try allocator.dupe(u8, governance),
        .delivery_closed = delivery_closed,
    });
}

fn addReviewCompilerMaterialRun(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    signals: ReviewCompilerSessionSignals,
    session_id: ?[]const u8,
    repo_root: []const u8,
) !void {
    const run_id_source = session_id orelse "unknown-session";
    const semantic_delta = if (signals.mbk_semantic_surface_delta != 0)
        signals.mbk_semantic_surface_delta
    else if (signals.mbk_semantic_surface_after >= signals.mbk_semantic_surface_before)
        signals.mbk_semantic_surface_after - signals.mbk_semantic_surface_before
    else
        0;
    const closure_gate_status: []const u8 = signals.mbk_closure_gate_status;
    const mutation_gate_status: []const u8 = if (std.mem.eql(u8, signals.mbk_mutation_gate_status, "missing") and signals.mbk_rac_mutation_allowed > 0)
        "passed"
    else
        signals.mbk_mutation_gate_status;

    try audit.material_runs.append(allocator, .{
        .session_id = if (session_id) |id| try allocator.dupe(u8, id) else null,
        .run_id = try allocator.dupe(u8, run_id_source),
        .repo = try allocator.dupe(u8, repo_root),
        .protocol = try allocator.dupe(u8, "mbk"),
        .material = signals.mbk_material_kernel_required_seen,
        .c3_required = signals.mbk_material_kernel_required_seen,
        .c3_entered = signals.mbk_begin_seen,
        .c3_closed = signals.mbk_tuple_closed_seen,
        .delivery_closed = signals.mbk_tuple_closed_seen,
        .terminal_closed = signals.mbk_terminal_closed_seen,
        .compression_state = try allocator.dupe(u8, if (signals.mbk_tuple_closed_seen) "MBKC-v1" else "NONE"),
        .batches_total = signals.mbk_batches_total,
        .kernel_accepted = signals.mbk_kernel_accepted_seen,
        .potential_strict_progress = signals.mbk_potential_strict_progress,
        .semantic_surface_delta = semantic_delta,
        .ac_rebased = signals.mbk_ac_rebased,
        .rac_total = signals.mbk_rac_total,
        .rac_valid = signals.mbk_rac_valid,
        .rac_mutation_allowed = signals.mbk_rac_mutation_allowed,
        .mutation_gate_status = try allocator.dupe(u8, mutation_gate_status),
        .closure_gate_status = try allocator.dupe(u8, closure_gate_status),
        .orphan_code_constructs = signals.mbk_orphan_code_constructs,
        .unmapped_proof_actions = signals.mbk_unmapped_proof_actions,
        .wound_specific_tests = signals.mbk_wound_specific_tests,
        .wound_specific_tests_class_mapped = signals.mbk_wound_specific_tests_class_mapped,
    });
}

fn addReviewCompilerMBKExclusion(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    session_id: ?[]const u8,
    path: []const u8,
    reason: []const u8,
) !void {
    try audit.mbk.denominator.exclusions.append(allocator, .{
        .session_id = if (session_id) |id| try allocator.dupe(u8, id) else null,
        .path = try allocator.dupe(u8, path),
        .reason = try allocator.dupe(u8, reason),
        .governance = try allocator.dupe(u8, "absent"),
        .delivery_closed = false,
    });
}

fn writeReviewCompilerRunsMode(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, fmt: output.Format, out_path: ?[]const u8) !void {
    if (fmt == .markdown) return writeReviewCompilerAuditMarkdown(allocator, audit, out_path);
    if (fmt == .jsonl) return writeReviewCompilerRunsJsonl(allocator, audit, out_path);
    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    try appendReviewCompilerRunRows(allocator, &rows, audit);
    const cols = [_][]const u8{ "run_version", "session_id", "governance", "lifecycle", "delivery_closed", "c3_closed", "compression", "c3_required", "c3_entered", "protocol", "classification", "path" };
    try output.writeOutput(allocator, fmt, rows.items, cols[0..], out_path);
}

fn writeReviewCompilerIntentRowsMode(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, mode: []const u8, fmt: output.Format, out_path: ?[]const u8) !void {
    if (fmt == .markdown) return writeReviewCompilerIntentReportMarkdown(allocator, audit, null, out_path);
    if (fmt == .jsonl) return writeReviewCompilerIntentRowsJsonl(allocator, audit, mode, out_path);
    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    try appendReviewCompilerIntentRows(allocator, &rows, audit, mode);
    const cols = [_][]const u8{ "run_version", "mode", "session_id", "path", "protocol", "verdict", "evidence_refs", "limitations" };
    try output.writeOutput(allocator, fmt, rows.items, cols[0..], out_path);
}

fn writeReviewCompilerIntentRowsJsonl(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, mode: []const u8, out_path: ?[]const u8) !void {
    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    try appendReviewCompilerIntentRows(allocator, &rows, audit, mode);
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    const cols = [_][]const u8{ "run_version", "mode", "session_id", "path", "protocol", "verdict", "evidence_refs", "limitations" };
    for (rows.items) |row| {
        try output.writeJsonObject(writer, row, cols[0..], false, "");
        try writer.writeByte('\n');
    }
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn writeReviewCompilerEvidenceMode(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, fmt: output.Format, out_path: ?[]const u8) !void {
    if (fmt == .markdown) return writeReviewCompilerAuditMarkdown(allocator, audit, out_path);
    var rows: std.ArrayList(query.Row) = .empty;
    defer deinitQueryRows(allocator, &rows);
    for (audit.denominator.included_sessions.items) |row| {
        try appendReviewCompilerEvidenceRow(allocator, &rows, row, "true_c3", row.evidence.true_c3);
        try appendReviewCompilerEvidenceRow(allocator, &rows, row, "required", row.evidence.required);
        try appendReviewCompilerEvidenceRow(allocator, &rows, row, "entered", row.evidence.entered);
        try appendReviewCompilerEvidenceRow(allocator, &rows, row, "closed", row.evidence.closed);
    }
    const cols = [_][]const u8{ "session_id", "path", "signal", "present", "source", "timestamp", "reason", "snippet" };
    try output.writeOutput(allocator, fmt, rows.items, cols[0..], out_path);
}

fn writeReviewCompilerRunsJsonl(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, out_path: ?[]const u8) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    for (audit.denominator.included_sessions.items) |row| {
        try writeReviewCompilerIncludedSessionJson(writer, row);
        try writer.writeByte('\n');
    }
    for (audit.material_runs.items) |row| {
        try writeReviewCompilerMaterialRunJson(writer, row);
        try writer.writeByte('\n');
    }
    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn reviewCompilerVerdictForSession(row: ReviewCompilerAudit.IncludedSession) []const u8 {
    if (row.c3_closed and row.delivery_closed) return "clean_review_closed";
    if (row.c3_closed) return "intent_closed_terminal";
    if (row.delivery_closed) return "tuple_closed_holdout_pending";
    return "insufficient_evidence";
}

fn hasStrictReviewCompilerFailure(audit: ReviewCompilerAudit) bool {
    const protocol = audit.outputProtocol();
    if (protocol != .intent_closed_cegis_v1 and protocol != .mixed and protocol != .c3_mrpc and protocol != .c3) return false;
    return audit.c3.lab_vs_delivery.raw_delivery_mutations_while_frozen > 0 or
        audit.c3.delivery.raw_commits_while_active > 0 or
        audit.c3.delivery.raw_pushes_while_active > 0 or
        audit.c3.compliance.direct_review_to_delivery_mutation > 0 or
        audit.c3.compliance.commit_or_push_bypass > 0 or
        audit.c3.compliance.stale_mrpc > 0 or
        audit.c3.compliance.holdout_missing > 0;
}

fn appendReviewCompilerRunRows(allocator: std.mem.Allocator, rows: *std.ArrayList(query.Row), audit: ReviewCompilerAudit) !void {
    for (audit.denominator.included_sessions.items) |item| {
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        try row.putStaticKey("run_version", .{ .string = resolve_intent_closed.run_version });
        try putOptionalString(&row, "session_id", item.session_id);
        try row.putStaticKey("path", .{ .string = item.path });
        try row.putStaticKey("protocol", .{ .string = item.protocol });
        try row.putStaticKey("classification", .{ .string = item.classification });
        try row.putStaticKey("governance", .{ .string = item.governance });
        try row.putStaticKey("lifecycle", .{ .string = item.lifecycle });
        try row.putStaticKey("delivery_closed", .{ .bool = item.delivery_closed });
        try row.putStaticKey("c3_required", .{ .bool = item.c3_required });
        try row.putStaticKey("c3_entered", .{ .bool = item.c3_entered });
        try row.putStaticKey("c3_closed", .{ .bool = item.c3_closed });
        try row.putStaticKey("compression", .{ .string = item.compression });
        try rows.append(allocator, row);
    }
    for (audit.material_runs.items) |item| {
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        try row.putStaticKey("run_version", .{ .string = resolve_intent_closed.run_version });
        try putOptionalString(&row, "session_id", item.session_id);
        try row.putStaticKey("path", .{ .string = item.repo });
        try row.putStaticKey("protocol", .{ .string = item.protocol });
        try row.putStaticKey("classification", .{ .string = if (item.material) "material" else "candidate" });
        try row.putStaticKey("governance", .{ .string = "authoritative" });
        try row.putStaticKey("lifecycle", .{ .string = if (item.terminal_closed) "valid" else "open" });
        try row.putStaticKey("delivery_closed", .{ .bool = item.delivery_closed });
        try row.putStaticKey("c3_required", .{ .bool = item.c3_required });
        try row.putStaticKey("c3_entered", .{ .bool = item.c3_entered });
        try row.putStaticKey("c3_closed", .{ .bool = item.c3_closed });
        try row.putStaticKey("compression", .{ .string = item.compression_state });
        try rows.append(allocator, row);
    }
}

fn appendReviewCompilerIntentRows(allocator: std.mem.Allocator, rows: *std.ArrayList(query.Row), audit: ReviewCompilerAudit, mode: []const u8) !void {
    for (audit.denominator.included_sessions.items) |item| {
        var row = query.Row.init(allocator);
        errdefer row.deinit();
        try row.putStaticKey("run_version", .{ .string = resolve_intent_closed.run_version });
        try row.putStaticKey("mode", .{ .string = mode });
        try putOptionalString(&row, "session_id", item.session_id);
        try row.putStaticKey("path", .{ .string = item.path });
        try row.putStaticKey("protocol", .{ .string = audit.outputProtocol().label() });
        try row.putStaticKey("verdict", .{ .string = reviewCompilerVerdictForSession(item) });
        try row.putStaticKey("evidence_refs", .{ .string = "[]" });
        try row.putStaticKey("limitations", .{ .string = "[\"controller_artifact_projection_pending\"]" });
        try rows.append(allocator, row);
    }
}

fn appendReviewCompilerEvidenceRow(
    allocator: std.mem.Allocator,
    rows: *std.ArrayList(query.Row),
    included_run: ReviewCompilerAudit.IncludedSession,
    signal: []const u8,
    evidence: ReviewCompilerAudit.SignalEvidenceRef,
) !void {
    var row = query.Row.init(allocator);
    errdefer row.deinit();
    try putOptionalString(&row, "session_id", included_run.session_id);
    try row.putStaticKey("path", .{ .string = included_run.path });
    try row.putStaticKey("signal", .{ .string = signal });
    try row.putStaticKey("present", .{ .bool = evidence.present });
    try row.putStaticKey("source", .{ .string = evidence.source });
    try putOptionalString(&row, "timestamp", evidence.timestamp);
    try row.putStaticKey("reason", .{ .string = evidence.reason });
    try putOptionalString(&row, "snippet", evidence.snippet);
    try rows.append(allocator, row);
}

fn resolveTraceMatchesThread(parsed: canonical_trace.CanonicalSessionTrace, path: []const u8, thread_id: []const u8) bool {
    if (parsed.session.session_id) |id| {
        if (std.mem.eql(u8, id, thread_id) or std.mem.containsAtLeast(u8, id, 1, thread_id)) return true;
    }
    return std.mem.containsAtLeast(u8, path, 1, thread_id);
}

fn resolveTraceMatchesRepo(allocator: std.mem.Allocator, repo_root: []const u8, parsed: canonical_trace.CanonicalSessionTrace) !bool {
    if (parsed.session.cwd) |cwd| {
        if (try pathMatchesRepoScope(allocator, repo_root, cwd)) return true;
    }
    for (parsed.tools.items) |tool| {
        if (tool.cwd) |cwd| {
            if (try pathMatchesRepoScope(allocator, repo_root, cwd)) return true;
        }
    }
    return false;
}

fn summarizeResolveSession(
    messages: []const datasets.messages.MessageRow,
    parsed: canonical_trace.CanonicalSessionTrace,
    opts: Options,
) ResolveSessionSignals {
    var signals = ResolveSessionSignals{};
    for (messages) |message| {
        if (!timestampSatisfiesBounds(message.timestamp, opts)) continue;
        if (containsResolveCandidateCue(message.text)) signals.candidate = true;
        if (std.mem.eql(u8, message.role, "assistant") and containsTrueResolveAssistantEvidence(message.text)) {
            signals.candidate = true;
            signals.true_resolve = true;
        }
    }
    for (parsed.tools.items) |tool| {
        if (!toolTimestampSatisfiesBounds(parsed, tool, opts)) continue;
        if (toolHasCompletedResolveReviewEvidence(tool)) {
            signals.candidate = true;
            signals.true_resolve = true;
        }
    }
    return signals;
}

fn containsResolveCandidateCue(text: []const u8) bool {
    return containsDollarWorkflowMention(text, "resolve") or
        containsAnyIgnoreCaseAscii(text, &.{ "seq resolve-churn-audit", "resolve_churn_audit", "review governor", "review_governor" });
}

fn containsTrueResolveAssistantEvidence(text: []const u8) bool {
    return containsAnyIgnoreCaseAscii(text, &.{
        "using $resolve",
        "Review Governor",
        "review_governor_record",
        "RGR-V3-MUTATION-PERMIT",
        "RLR-v4",
        "resolve_learning_report",
        "review_charter",
        "finding_liability",
        "normal_form_register",
        "governor_fuse",
        "review_distillation_receipt",
    });
}

fn toolHasCompletedResolveReviewEvidence(tool: canonical_trace.ToolLifecycleRecord) bool {
    if (tool.lifecycle_status != .completed) return false;
    if (tool.kind == .exec_command and (tool.exit_code orelse -1) != 0) return false;
    const cmd = tool.command_text orelse tool.input_text orelse tool.arguments_json orelse "";
    return commandContainsReviewInvocation(cmd);
}

fn commandContainsReviewInvocation(cmd: []const u8) bool {
    var previous: ?[]const u8 = null;
    var tokens = std.mem.tokenizeAny(u8, cmd, " \t\r\n;&|()");
    while (tokens.next()) |raw| {
        const token = std.mem.trim(u8, raw, "\"'`.,{}[]");
        if (token.len == 0) continue;
        if (std.ascii.eqlIgnoreCase(token, "cas_review_session")) return true;
        if (previous) |prev| {
            if (std.ascii.eqlIgnoreCase(prev, "cas") and std.ascii.eqlIgnoreCase(token, "review_session")) return true;
            if (std.ascii.eqlIgnoreCase(prev, "codex") and std.ascii.eqlIgnoreCase(token, "review")) return true;
        }
        previous = token;
    }
    return false;
}

fn summarizeReviewCompilerSession(
    messages: []const datasets.messages.MessageRow,
    parsed: canonical_trace.CanonicalSessionTrace,
    opts: Options,
) ReviewCompilerSessionSignals {
    var signals = ReviewCompilerSessionSignals{};
    for (messages) |message| {
        if (!timestampSatisfiesBounds(message.timestamp, opts)) continue;
        const positive_evidence_contamination = isReviewCompilerPositiveEvidenceContamination(message.text);
        if (containsReviewCompilerCandidateCue(message.text)) signals.candidate = true;
        if (!positive_evidence_contamination and containsIncidentalC3ArtifactMention(message.text)) {
            signals.candidate = true;
            noteReviewCompilerIncidentalC3(&signals, "filename_or_path_mention");
        }
        if (!positive_evidence_contamination and containsGenericDeliveryClosure(message.text)) {
            signals.delivery_closed_seen = true;
            signals.closure_provenance = "generic_delivery_closure";
        }
        if (!std.mem.eql(u8, message.role, "assistant")) continue;
        if (positive_evidence_contamination) continue;
        if (containsTrueReviewCompilerAssistantEvidence(message.text)) {
            signals.candidate = true;
            signals.true_legacy = true;
            signals.true_resolve = true;
        }
        if (containsAuthoritativeC3EventText(message.text)) {
            signals.candidate = true;
            noteReviewCompilerAuthoritativeC3(&signals, "controller_event");
            signals.true_c3 = true;
            signals.true_resolve = true;
            recordReviewCompilerEvidenceRef(&signals.true_c3_evidence, "message", message.timestamp, message.text);
        } else if (containsDeclaredC3WorkflowEvidence(message.text)) {
            signals.candidate = true;
            noteReviewCompilerDeclaredC3(&signals);
            signals.true_c3 = true;
            signals.true_resolve = true;
            recordReviewCompilerEvidenceRef(&signals.true_c3_evidence, "message", message.timestamp, message.text);
        }
        if (containsTrueMBKEvidence(message.text)) {
            signals.candidate = true;
            signals.true_mbk = true;
            signals.true_resolve = true;
        }
    }
    for (parsed.tools.items) |tool| {
        if (!toolTimestampSatisfiesBounds(parsed, tool, opts)) continue;
        const tool_text = reviewCompilerToolText(tool);
        if (isReviewCompilerPositiveEvidenceContamination(tool_text)) continue;
        if (toolHasIncidentalC3Mention(tool)) {
            signals.candidate = true;
            noteReviewCompilerIncidentalC3(&signals, if (tool.kind == .patch_apply) "artifact_under_repair" else "filename_or_path_mention");
        }
        if (reviewCompilerToolIsCompletedC3Controller(tool)) {
            signals.candidate = true;
            noteReviewCompilerAuthoritativeC3(&signals, "controller_invocation");
            signals.true_c3 = true;
            signals.true_resolve = true;
            const controller_tool_text = tool.command_text orelse reviewCompilerToolText(tool);
            recordReviewCompilerEvidenceRef(&signals.true_c3_evidence, "tool_call", toolTimestamp(parsed, tool), controller_tool_text);
        }
        if (toolHasMBKEvidence(tool)) {
            signals.candidate = true;
            signals.true_mbk = true;
            signals.true_resolve = true;
        }
    }
    return signals;
}

fn noteReviewCompilerAuthoritativeC3(signals: *ReviewCompilerSessionSignals, provenance: []const u8) void {
    signals.authoritative_c3_seen = true;
    signals.governance_state = .authoritative;
    signals.governance_provenance = provenance;
}

fn noteReviewCompilerDeclaredC3(signals: *ReviewCompilerSessionSignals) void {
    signals.declared_c3_seen = true;
    if (signals.governance_state != .authoritative) {
        signals.governance_state = .declared_uncontrolled;
        signals.governance_provenance = "explicit_workflow_declaration";
    }
}

fn noteReviewCompilerIncidentalC3(signals: *ReviewCompilerSessionSignals, reason: []const u8) void {
    signals.incidental_c3_seen = true;
    if (std.mem.eql(u8, reason, "artifact_under_repair") or std.mem.eql(u8, signals.incidental_reason, "none")) {
        signals.incidental_reason = reason;
    }
    if (signals.governance_state == .absent) {
        signals.governance_state = .incidental;
        signals.governance_provenance = reason;
    } else if (signals.governance_state == .incidental and std.mem.eql(u8, reason, "artifact_under_repair")) {
        signals.governance_provenance = reason;
    }
}

fn toolHasIncidentalC3Mention(tool: canonical_trace.ToolLifecycleRecord) bool {
    if (reviewCompilerToolIsCompletedC3Controller(tool)) return false;
    return containsIncidentalC3ArtifactMention(tool.command_text orelse "") or
        containsIncidentalC3ArtifactMention(tool.input_text orelse "") or
        containsIncidentalC3ArtifactMention(tool.arguments_json orelse "") or
        containsIncidentalC3ArtifactMention(tool.output_text orelse "") or
        containsIncidentalC3ArtifactMention(tool.patch_changes_json orelse "");
}

