fn recordReviewCompilerEvidenceRef(slot: *?ReviewCompilerBorrowedEvidenceRef, source: []const u8, timestamp: ?[]const u8, text: []const u8) void {
    if (slot.* != null) return;
    slot.* = .{
        .source = source,
        .timestamp = timestamp,
        .snippet = firstNonEmptyLine(text),
    };
}

