    return containsAnyIgnoreCaseAscii(text, &.{ "non_branch_liabilities", "non-branch liability", "non_branch_liability" });
}

fn recordReviewCompilerMessages(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    messages: []const datasets.messages.MessageRow,
    opts: Options,
    signals: *ReviewCompilerSessionSignals,
    session_id: ?[]const u8,
) !void {
    for (messages) |message| {
        if (!timestampSatisfiesBounds(message.timestamp, opts)) continue;
        if (!std.mem.eql(u8, message.role, "assistant")) continue;
        const text = message.text;

        if (containsAnyIgnoreCaseAscii(text, &.{ "delivery_freeze", "DF-v1", "delivery freeze" })) {
            audit.legacy_cleanroom.cleanroom.delivery_freezes += 1;
            signals.delivery_freeze_seen = true;
        }
        if (containsAnyIgnoreCaseAscii(text, &.{ "counterexample_contract", "CEC-v1", "counterexample contract" })) {
            audit.legacy_cleanroom.cleanroom.counterexample_contracts += 1;
            signals.contract_seen = true;
        }
        if (containsAnyIgnoreCaseAscii(text, &.{ "delivery_patch_recipe", "DPR-v1", "delivery patch recipe" })) {
            audit.legacy_cleanroom.cleanroom.delivery_recipes += 1;
            signals.recipe_seen = true;
            recordReviewCompilerSignalTime(signals, .recipe, message.timestamp);
        }
        if (containsAnyIgnoreCaseAscii(text, &.{ "ablation_certificate", "ABL-CERT-v1", "ablation certificate" })) {
            audit.legacy_cleanroom.cleanroom.ablation_certificates += 1;
            signals.ablation_seen = true;
        }
        if (containsAnyIgnoreCaseAscii(text, &.{ "RGR-V4-COMPILED-DELIVERY-PERMIT", "compiled_delivery_permit" })) {
            audit.legacy_cleanroom.cleanroom.compiled_delivery_permits += 1;
            signals.permit_seen = true;
            recordReviewCompilerSignalTime(signals, .permit, message.timestamp);
        }

        const positive_evidence_contamination = isReviewCompilerPositiveEvidenceContamination(text);
        if (containsAnyIgnoreCaseAscii(text, &.{ "review_lab", "review lab", "disposable lab", "lab worktree", "scratch worktree" })) {
            signals.lab_context_seen = true;
        }

        if (containsReviewCompilerBranchLiabilityCue(text)) audit.legacy_cleanroom.liability.branch_liabilities += 1;
        if (containsReviewCompilerNonBranchLiabilityCue(text)) {
            audit.legacy_cleanroom.liability.non_branch_liabilities += 1;
            signals.non_branch_liability_seen = true;
        }
        if (containsAnyIgnoreCaseAscii(text, &.{ "liability_followups_captured", "liability followup captured", "liability follow-up captured" })) audit.legacy_cleanroom.liability.followups_captured += 1;

        if (containsAnyIgnoreCaseAscii(text, &.{ "falsified_routes_excluded", "falsified route excluded" })) audit.legacy_cleanroom.recipe.falsified_routes_excluded += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "surfaces_to_retire", "surface to retire" })) audit.legacy_cleanroom.recipe.surfaces_to_retire += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "permitted_new_surface", "permitted new surface" })) audit.legacy_cleanroom.recipe.permitted_new_surface += 1;

        if (containsAnyIgnoreCaseAscii(text, &.{ "surfaces_removed", "removed_from_recipe", "removed from recipe" })) audit.legacy_cleanroom.ablation.surfaces_removed += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "surfaces_survived", "survived_ablation", "survived ablation" })) audit.legacy_cleanroom.ablation.surfaces_survived += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "tests_merged_or_retired", "tests merged", "tests retired" })) audit.legacy_cleanroom.ablation.tests_merged_or_retired += 1;

        if (containsAnyIgnoreCaseAscii(text, &.{ "initial_broad", "initial broad", "broad review" })) audit.legacy_cleanroom.review_horizon.initial_broad_reviews += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "targeted_reviews", "targeted review", "targeted:", " targeted " })) audit.legacy_cleanroom.review_horizon.targeted_reviews += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "final_holdout", "final holdout", "holdout review" })) audit.legacy_cleanroom.review_horizon.final_holdout_reviews += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "holdout_findings_added_to_scope", "holdout findings added" })) audit.legacy_cleanroom.review_horizon.holdout_findings_added_to_scope += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "holdout_followups_captured", "holdout followups captured", "holdout follow-ups captured" })) audit.legacy_cleanroom.review_horizon.holdout_followups_captured += 1;

        if (!positive_evidence_contamination) {
            const c3_source: []const u8 = if (containsAuthoritativeC3EventText(text)) "controller_event" else "message";
            recordReviewCompilerC3Text(audit, text, message.timestamp, c3_source, signals);
            if (signals.true_mbk) try recordReviewCompilerMBKText(allocator, audit, text, message.timestamp, signals, session_id, "message");
        }
    }
}

const ReviewCompilerSignalTimeKind = enum { recipe, permit };

fn recordReviewCompilerC3Text(
    audit: *ReviewCompilerAudit,
    text: []const u8,
    timestamp: ?[]const u8,
    source: []const u8,
    signals: *ReviewCompilerSessionSignals,
) void {
    const controller_source = std.mem.eql(u8, source, "controller_tool") or std.mem.eql(u8, source, "controller_receipt") or std.mem.eql(u8, source, "controller_event");
    if (containsAnyIgnoreCaseAscii(text, &.{ "clean_review: true", "clean review", "clean_review_session" })) signals.clean_review_seen = true;
    if (containsAnyIgnoreCaseAscii(text, &.{ "isolated_waiver", "isolated waiver" })) signals.isolated_waiver_seen = true;
    if (containsAnyIgnoreCaseAscii(text, &.{ "candidate-worktree", "candidate worktree" })) signals.c3_candidate_worktree_context_seen = true;
    if (containsGenericDeliveryClosure(text)) {
        signals.delivery_closed_seen = true;
        signals.closure_provenance = "generic_delivery_closure";
    }

    if (controller_source and containsAnyIgnoreCaseAscii(text, &.{ "\"event\":\"begin\" controller=review-compiler", "event=begin", "review-compiler campaign begin", "\"event\":\"begin\"", "\"event\": \"begin\"", "\"event\":\"campaign-began\"", "\"event\": \"campaign-began\"", "event=campaign-began", "\nbegin\n" })) {
        audit.c3.controller.begin_events += 1;
        signals.c3_begin_seen = true;
        recordReviewCompilerEvidenceRef(&signals.c3_begin_evidence, source, timestamp, text);
        recordReviewCompilerC3Time(signals, .begin, timestamp);
    }
    if (containsIgnoreCaseAscii(text, ".ledger/c3/state.json")) audit.c3.controller.state_files += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "apply-certified", "apply_certified", "mrpc_apply_certified" })) {
        audit.c3.controller.mrpc_apply_certified += 1;
        signals.c3_apply_certified_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "final-certified", "final_certified", "mrpc_final_certified" })) {
        audit.c3.controller.mrpc_final_certified += 1;
        signals.c3_final_certified_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "MRPC-v1", "minimal_review_patch_certificate" })) signals.c3_mrpc_seen = true;
    if (controller_source and containsAnyIgnoreCaseAscii(text, &.{ "committed", "mrpc_committed" })) audit.c3.controller.mrpc_committed += 1;
    if (controller_source and containsAnyIgnoreCaseAscii(text, &.{ "pushed", "mrpc_pushed" })) audit.c3.controller.mrpc_pushed += 1;
    if (controller_source and containsAnyIgnoreCaseAscii(text, &.{ "review-compiler close", "\"event\":\"terminal-closed\"", "\"event\": \"terminal-closed\"", "event=terminal-closed", "\"event\":\"tuple-closed\"", "\"event\": \"tuple-closed\"", "event=tuple-closed", "mrpc_closed", "terminal-closed", "tuple-closed" })) {
        audit.c3.controller.mrpc_closed += 1;
        audit.c3.delivery.closed_runs += 1;
        signals.c3_closed_seen = true;
        signals.closure_provenance = "controller_close";
        recordReviewCompilerEvidenceRef(&signals.c3_closed_evidence, source, timestamp, text);
        recordReviewCompilerC3Time(signals, .closed, timestamp);
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "aborted", "\"event\":\"aborted\"", "\"event\": \"aborted\"" })) recordReviewCompilerC3Time(signals, .aborted, timestamp);

    if (containsAnyIgnoreCaseAscii(text, &.{ "raw_finding", "raw finding", "counterexample-added", "counterexample_added" })) audit.c3.counterexamples.raw_findings += 1;
    if (containsReviewCompilerBranchLiabilityCue(text)) audit.c3.counterexamples.branch_liabilities += 1;
    if (containsReviewCompilerNonBranchLiabilityCue(text)) audit.c3.counterexamples.non_branch_liabilities += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "independent_family", "independent families", "independent_families" })) audit.c3.counterexamples.independent_families += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "subsumed_finding", "subsumed finding", "subsumed_findings" })) audit.c3.counterexamples.subsumed_findings += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "basis-set", "basis_set", "basis:" })) {
        signals.c3_basis_seen = true;
        if (signals.c3_reset_seen) signals.c3_basis_after_reset_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "candidate-registered", "candidate_registered", "candidate_records" })) {
        audit.c3.tournament.candidate_records += 1;
        signals.c3_tournament_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "route_class", "route class" })) audit.c3.tournament.distinct_route_classes += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "invalid_candidate", "invalid candidate", "invalid_candidates" })) audit.c3.tournament.invalid_candidates += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "active_negative_routes_excluded", "active negative route excluded" })) audit.c3.tournament.active_negative_routes_excluded += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "candidate-selected", "candidate_selected", "selected_candidates" })) {
        audit.c3.tournament.selected_candidates += 1;
        signals.c3_tournament_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "tournament_waiver", "tournament waiver" })) {
        audit.c3.tournament.tournament_waivers += 1;
        signals.isolated_waiver_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "single_candidate_material_violation", "single-candidate material violation" })) audit.c3.tournament.single_candidate_material_violations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "global_optimality_overclaim", "global optimality overclaim" })) audit.c3.semantic_cost.global_optimality_overclaims += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "selected_semantic_cost:", "selected semantic cost:" })) audit.c3.semantic_cost.selected_semantic_cost += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "ablation-recorded", "ablation_recorded" })) signals.c3_ablation_seen = true;
    if (containsAnyIgnoreCaseAscii(text, &.{ "edit_atoms_tested", "edit atom tested", "edit_atoms:" })) {
        audit.c3.ablation.edit_atoms_tested += 1;
        signals.c3_ablation_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "removed_edit_atom", "removed edit atom", "removed:" })) audit.c3.ablation.removed += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "survived_edit_atom", "survived edit atom", "survived:" })) audit.c3.ablation.survived += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "orphan_edit_atom", "orphan edit atom", "orphan_edit_atoms" })) audit.c3.ablation.orphan_edit_atoms += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "one_minimal_pass", "one minimal pass" })) audit.c3.ablation.one_minimal_passes += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "one_minimal_failure", "one minimal failure" })) audit.c3.ablation.one_minimal_failures += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "candidate_surface_generated", "candidate surface generated" })) audit.c3.lab_vs_delivery.candidate_surface_generated += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "candidate_surface_discarded", "candidate surface discarded" })) audit.c3.lab_vs_delivery.candidate_surface_discarded += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "patch-applied", "patch_applied" })) audit.c3.lab_vs_delivery.delivery_apply_events += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "candidate_holdout", "candidate holdout" })) {
        audit.c3.holdout.candidate_holdouts += 1;
        signals.c3_holdout_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "delivery_holdout", "delivery holdout", "holdout-recorded", "holdout_recorded" })) {
        audit.c3.holdout.delivery_holdouts += 1;
        signals.c3_holdout_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "new_counterexample", "new counterexample" })) {
        audit.c3.holdout.new_counterexamples += 1;
        signals.c3_new_counterexample_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "invalidated", "invalidation", "invalidations" })) audit.c3.holdout.invalidations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "reset", "basis reset", "recompile", "recompilation" })) signals.c3_reset_seen = true;
    if (signals.c3_new_counterexample_seen and signals.c3_reset_seen and signals.c3_basis_after_reset_seen and !signals.c3_recompiled_seen) {
        audit.c3.holdout.recompilations += 1;
        signals.c3_recompiled_seen = true;
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "adjacent_followup", "adjacent follow-up", "adjacent followup" })) audit.c3.holdout.adjacent_followups += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "proof-recorded", "proof_recorded" })) signals.c3_proof_seen = true;
}

fn recordReviewCompilerMBKText(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    text: []const u8,
    timestamp: ?[]const u8,
    signals: *ReviewCompilerSessionSignals,
    session_id: ?[]const u8,
    source: []const u8,
) !void {
    recordReviewCompilerMBKRunProjectionSignals(signals, text);
    if (containsAnyIgnoreCaseAscii(text, &.{ "clean_review_session", "clean review session", "clean_review: true" })) signals.mbk_clean_review_seen = true;
    if (containsAnyIgnoreCaseAscii(text, &.{ "isolated_conformance_session", "isolated conformance session", "isolated_conformance" })) signals.mbk_isolated_conformance_seen = true;
    if (containsAnyIgnoreCaseAscii(text, &.{ "material_kernel_required", "material kernel required" })) signals.mbk_material_kernel_required_seen = true;

    if (containsAnyIgnoreCaseAscii(text, &.{ "campaign-began", "campaign_began", "review-compiler campaign begin" })) {
        audit.mbk.campaigns.campaign_ids += 1;
        signals.mbk_begin_seen = true;
        recordReviewCompilerMBKTime(signals, .begin, timestamp);
        try addReviewCompilerMBKEvidence(allocator, audit, session_id, "campaign-began", source, text);
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "fixed_base_pass", "fixed base pass" })) audit.mbk.campaigns.fixed_base_pass += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "base_reset_violation", "base reset violation", "campaign base reset" })) audit.mbk.campaigns.base_reset_violations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "review_ready_baseline", "review-ready baseline", "review ready baseline" })) audit.mbk.campaigns.review_ready_baselines += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "closure_attempt", "closure attempt" })) audit.mbk.campaigns.closure_attempts += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "prior_closure_head_used_as_new_base", "prior closure head used as new base" })) audit.mbk.campaigns.prior_closure_head_used_as_new_base += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "rebaseline_decision", "rebaseline decision" })) audit.mbk.campaigns.rebaseline_decisions += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "observation-added", "observation_added", "raw_finding", "raw finding" })) audit.mbk.observations.raw_findings += 1;
    if (containsReviewCompilerBranchLiabilityCue(text)) audit.mbk.observations.branch_liabilities += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "additional_witness", "additional witness" })) audit.mbk.observations.additional_witnesses += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "missing_distinction", "missing distinction" })) audit.mbk.observations.missing_distinctions += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "scope_expansion", "scope expansion" })) audit.mbk.observations.scope_expansions += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "adjacent_followup", "adjacent follow-up", "adjacent followup" })) audit.mbk.observations.adjacent_followups += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "preference_rejected", "preference rejected", "preferences_rejected" })) audit.mbk.observations.preferences_rejected += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "authority:", "authorities:", "kernel authority" })) audit.mbk.kernel.authorities += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "observable_state_class", "observable state class" })) audit.mbk.kernel.observable_state_classes += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "transition:", "transitions:", "kernel transition" })) audit.mbk.kernel.transitions += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "kernel_law", "kernel law", "law:" })) audit.mbk.kernel.laws += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "local_surface_family", "local-surface family", "local surface family" })) audit.mbk.kernel.local_surface_families += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "governing_law_family", "governing law family" })) audit.mbk.kernel.governing_law_families += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "findings_per_law", "findings per law" })) audit.mbk.kernel.findings_per_law += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "distinction_merged", "distinction merged", "distinctions_merged" })) audit.mbk.kernel.distinctions_merged += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "unwitnessed_distinction", "unwitnessed distinction", "unwitnessed_distinctions" })) audit.mbk.kernel.unwitnessed_distinctions += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "exact_quotient", "exact quotient", "exact_quotients" })) audit.mbk.kernel.exact_quotients += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "witnessed_quotient", "witnessed quotient", "witnessed_quotients" })) audit.mbk.kernel.witnessed_quotients += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "design-registered", "design_registered", "design registered" })) audit.mbk.realization.designs_considered += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "route_class", "route class" })) audit.mbk.realization.route_classes += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "design-selected", "design_selected", "design selected" })) audit.mbk.realization.selected_designs += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "realization_recompilation", "realization recompilation", "realization recompiled" })) audit.mbk.realization.realization_recompilations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "realization_from_campaign_base", "realization from campaign base" })) audit.mbk.realization.realizations_from_campaign_base += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "realization_from_prior_head", "realization from prior head" })) audit.mbk.realization.realizations_from_prior_head += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "surface_retired", "surface retired", "surfaces_retired" })) audit.mbk.realization.surfaces_retired += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "orphan_code_construct", "orphan code construct", "orphan_code_constructs" })) audit.mbk.realization.orphan_code_constructs += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "duplicate_realization", "duplicate realization", "duplicate_realizations" })) audit.mbk.realization.duplicate_realizations += 1;

    recordMBKSurfaceNumbers(&audit.mbk, text);

    if (containsAnyIgnoreCaseAscii(text, &.{ "hard_dimension_increase", "hard dimension increase" })) audit.mbk.semantic_surface.hard_dimension_increases += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "total_description_nonincrease_pass", "total description nonincrease pass" })) audit.mbk.semantic_surface.total_description_nonincrease_pass = true;
    if (containsAnyIgnoreCaseAscii(text, &.{ "approved_rebaseline", "approved rebaseline" })) audit.mbk.semantic_surface.approved_rebaselines += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "silent_scope_expansion", "silent scope expansion" })) audit.mbk.semantic_surface.silent_scope_expansions += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "kernel_laws", "kernel laws" })) audit.mbk.proof.kernel_laws += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "proof_family", "proof family", "proof_families" })) audit.mbk.proof.proof_families += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "wound_specific_test", "wound-specific test", "wound specific test" })) audit.mbk.proof.wound_specific_tests += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "tests_merged_or_retired", "tests merged or retired" })) audit.mbk.proof.tests_merged_or_retired += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "property_or_state_machine_family", "property family", "state machine family" })) audit.mbk.proof.property_or_state_machine_families += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "unmapped_proof_action", "unmapped proof action" })) audit.mbk.proof.unmapped_proof_actions += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "proof_run", "proof run", "proof_runs" })) audit.mbk.proof.proof_runs += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "stale_proof", "stale proof" })) audit.mbk.proof.stale_proof += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "delivery-applied", "delivery_applied", "physical_apply_event" })) audit.mbk.controller.physical_apply_events += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "state_only_apply", "state-only apply" })) audit.mbk.controller.state_only_apply_violations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "committed", "physical_commit" })) audit.mbk.controller.physical_commits += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "state_only_commit", "state-only commit" })) audit.mbk.controller.state_only_commit_violations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "pushed", "physical_push" })) audit.mbk.controller.physical_pushes += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "state_only_push", "state-only push" })) audit.mbk.controller.state_only_push_violations += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "backup_ref_created", "backup ref created" })) audit.mbk.controller.backup_refs_created += 1;

    if (containsAnyIgnoreCaseAscii(text, &.{ "kernel-accepted", "kernel_accepted", "kernel accepted" })) {
        audit.mbk.closure.kernel_accepted += 1;
        signals.mbk_kernel_accepted_seen = true;
        try addReviewCompilerMBKEvidence(allocator, audit, session_id, "kernel-accepted", source, text);
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "tuple-closed", "tuple_closed", "conformance_closed_for_tuple", "conformance closed for tuple" })) {
        audit.mbk.closure.conformance_closed_for_tuple += 1;
        signals.mbk_tuple_closed_seen = true;
        audit.mbk.campaigns.closure_attempts += 1;
        try addReviewCompilerMBKEvidence(allocator, audit, session_id, "tuple-closed", source, text);
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "terminal-closed", "terminal_closed", "terminal closed" })) {
        audit.mbk.closure.terminal_closed += 1;
        signals.mbk_terminal_closed_seen = true;
        audit.mbk.campaigns.closure_attempts += 1;
        recordReviewCompilerMBKTime(signals, .terminal, timestamp);
        try addReviewCompilerMBKEvidence(allocator, audit, session_id, "terminal-closed", source, text);
    }
    if (containsAnyIgnoreCaseAscii(text, &.{ "unqualified_complete_claim", "unqualified complete claim" })) audit.mbk.closure.unqualified_complete_claims += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "tuple_receipt_missing_horizon", "tuple receipt missing horizon" })) audit.mbk.closure.tuple_receipts_missing_horizon += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "post_push_reopen", "post-push reopen", "post push reopen" })) audit.mbk.closure.post_push_reopens += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "terminal_closure_with_new_evidence", "terminal closure with new evidence" })) audit.mbk.closure.terminal_closure_with_new_evidence += 1;
}

fn recordReviewCompilerMBKRunProjectionSignals(signals: *ReviewCompilerSessionSignals, text: []const u8) void {
    if (extractReviewCompilerNamedUsize(text, "batches_total")) |value| signals.mbk_batches_total += value;
    if (extractReviewCompilerNamedUsize(text, "potential.strict_progress")) |value| {
        signals.mbk_potential_strict_progress += value;
    } else if (extractReviewCompilerNamedUsize(text, "strict_progress")) |value| {
        signals.mbk_potential_strict_progress += value;
    } else if (containsAnyIgnoreCaseAscii(text, &.{ "\"strict_progress\":true", "\"strict_progress\": true", "strict_progress: true", "strict_progress=true" })) {
        signals.mbk_potential_strict_progress += 1;
    }

    if (extractReviewCompilerNamedUsize(text, "review_ready_baseline_semantic_surface")) |value| signals.mbk_semantic_surface_before += value;
    if (extractReviewCompilerNamedUsize(text, "terminal_semantic_surface")) |value| signals.mbk_semantic_surface_after += value;
    if (extractReviewCompilerNamedUsize(text, "semantic_surface_delta")) |value| {
        signals.mbk_semantic_surface_delta += value;
    } else if (extractReviewCompilerNamedUsize(text, "delta_semantic_surface")) |value| {
        signals.mbk_semantic_surface_delta += value;
    }

    if (extractReviewCompilerNamedUsize(text, "orphan_code_constructs")) |value| signals.mbk_orphan_code_constructs += value;
    if (extractReviewCompilerNamedUsize(text, "unmapped_proof_actions")) |value| signals.mbk_unmapped_proof_actions += value;
    if (extractReviewCompilerNamedUsize(text, "wound_specific_tests")) |value| signals.mbk_wound_specific_tests += value;
    if (containsAnyIgnoreCaseAscii(text, &.{ "wound_specific_test", "wound-specific test", "wound specific test" }) and signals.mbk_wound_specific_tests == 0) signals.mbk_wound_specific_tests += 1;
    if (extractReviewCompilerNamedBool(text, "wound_specific_tests_class_mapped")) |value| {
        signals.mbk_wound_specific_tests_class_mapped = value;
    } else if (containsAnyIgnoreCaseAscii(text, &.{ "wound-specific tests class mapped", "wound specific tests class mapped" })) {
        signals.mbk_wound_specific_tests_class_mapped = true;
    }
    if (extractReviewCompilerNamedBool(text, "ac_rebased")) |value| {
        signals.mbk_ac_rebased = value;
    } else if (extractReviewCompilerNamedBool(text, "explicit_ac_rebase")) |value| {
        signals.mbk_ac_rebased = value;
    } else if (containsAnyIgnoreCaseAscii(text, &.{"approved_rebaseline"})) {
        signals.mbk_ac_rebased = true;
    }

    if (containsAnyIgnoreCaseAscii(text, &.{ "RAC-v1", "resolve_authority_chain", "authority-chain" })) signals.mbk_rac_total += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "RAC-v1 valid", "\"complete_chain\":\"yes\"", "\"complete_chain\": \"yes\"", "complete_chain: yes" })) signals.mbk_rac_valid += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "\"mutation_allowed\":\"yes\"", "\"mutation_allowed\": \"yes\"", "mutation_allowed: yes", "gate_mutation_allowed" })) signals.mbk_rac_mutation_allowed += 1;
    if (containsAnyIgnoreCaseAscii(text, &.{ "mutation_gate.status=passed", "\"mutation_gate.status\":\"passed\"", "\"mutation_gate\":{\"status\":\"passed\"", "mutation_gate_passed" })) signals.mbk_mutation_gate_status = "passed";
    if (containsAnyIgnoreCaseAscii(text, &.{ "mutation_gate.status=failed", "\"mutation_gate.status\":\"failed\"", "\"mutation_gate\":{\"status\":\"failed\"", "mutation_gate_failed" })) signals.mbk_mutation_gate_status = "failed";
    if (containsAnyIgnoreCaseAscii(text, &.{ "closure_gate.status=passed", "\"closure_gate.status\":\"passed\"", "\"closure_gate\":{\"status\":\"passed\"", "closure_gate_passed" })) signals.mbk_closure_gate_status = "passed";
    if (containsAnyIgnoreCaseAscii(text, &.{ "closure_gate.status=failed", "\"closure_gate.status\":\"failed\"", "\"closure_gate\":{\"status\":\"failed\"", "closure_gate_failed" })) signals.mbk_closure_gate_status = "failed";
}

const ReviewCompilerC3TimeKind = enum { begin, closed, aborted };
const ReviewCompilerMBKTimeKind = enum { begin, terminal };

fn recordReviewCompilerC3Time(signals: *ReviewCompilerSessionSignals, kind: ReviewCompilerC3TimeKind, timestamp: ?[]const u8) void {
    const ms = time_utils.parseIsoTimestampMillis(timestamp orelse return) orelse return;
    switch (kind) {
        .begin => {
            if (signals.c3_begin_at_ms == null or ms < signals.c3_begin_at_ms.?) signals.c3_begin_at_ms = ms;
        },
        .closed => {
            if (signals.c3_closed_at_ms == null or ms < signals.c3_closed_at_ms.?) signals.c3_closed_at_ms = ms;
        },
        .aborted => {
            if (signals.c3_aborted_at_ms == null or ms < signals.c3_aborted_at_ms.?) signals.c3_aborted_at_ms = ms;
        },
    }
}

fn recordReviewCompilerMBKTime(signals: *ReviewCompilerSessionSignals, kind: ReviewCompilerMBKTimeKind, timestamp: ?[]const u8) void {
    const ms = time_utils.parseIsoTimestampMillis(timestamp orelse return) orelse return;
    switch (kind) {
        .begin => {
            if (signals.mbk_begin_at_ms == null or ms < signals.mbk_begin_at_ms.?) signals.mbk_begin_at_ms = ms;
        },
        .terminal => {
            if (signals.mbk_terminal_at_ms == null or ms < signals.mbk_terminal_at_ms.?) signals.mbk_terminal_at_ms = ms;
        },
    }
}

fn addReviewCompilerMBKEvidence(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    session_id: ?[]const u8,
    event: []const u8,
    source: []const u8,
    text: []const u8,
) !void {
    try audit.mbk.evidence_ledger.append(allocator, .{
        .session_id = if (session_id) |id| try allocator.dupe(u8, id) else null,
        .event = try allocator.dupe(u8, event),
        .source = try allocator.dupe(u8, source),
        .snippet = try allocator.dupe(u8, firstNonEmptyLine(text)),
    });
}

fn recordMBKSurfaceNumbers(mbk: *ReviewCompilerAudit.MBK, text: []const u8) void {
    if (extractReviewCompilerNamedUsize(text, "review_ready_baseline_semantic_surface")) |value| mbk.semantic_surface.review_ready_baseline.semantic_surface += value;
    if (extractReviewCompilerNamedUsize(text, "review_ready_baseline_governing_laws")) |value| mbk.semantic_surface.review_ready_baseline.governing_laws += value;
    if (extractReviewCompilerNamedUsize(text, "review_ready_baseline_realization_surface")) |value| mbk.semantic_surface.review_ready_baseline.realization_surface += value;
    if (extractReviewCompilerNamedUsize(text, "review_ready_baseline_proof_families")) |value| mbk.semantic_surface.review_ready_baseline.proof_families += value;

    if (extractReviewCompilerNamedUsize(text, "terminal_semantic_surface")) |value| mbk.semantic_surface.terminal.semantic_surface += value;
    if (extractReviewCompilerNamedUsize(text, "terminal_governing_laws")) |value| mbk.semantic_surface.terminal.governing_laws += value;
    if (extractReviewCompilerNamedUsize(text, "terminal_realization_surface")) |value| mbk.semantic_surface.terminal.realization_surface += value;
    if (extractReviewCompilerNamedUsize(text, "terminal_proof_families")) |value| mbk.semantic_surface.terminal.proof_families += value;

    if (extractReviewCompilerNamedUsize(text, "delta_semantic_surface")) |value| mbk.semantic_surface.delta.semantic_surface += value;
    if (extractReviewCompilerNamedUsize(text, "delta_governing_laws")) |value| mbk.semantic_surface.delta.governing_laws += value;
    if (extractReviewCompilerNamedUsize(text, "delta_realization_surface")) |value| mbk.semantic_surface.delta.realization_surface += value;
    if (extractReviewCompilerNamedUsize(text, "delta_proof_families")) |value| mbk.semantic_surface.delta.proof_families += value;

    if (extractReviewCompilerNamedUsize(text, "git_files_changed")) |value| mbk.git_tree_metrics.files_changed += value;
    if (extractReviewCompilerNamedUsize(text, "git_insertions")) |value| mbk.git_tree_metrics.insertions += value;
    if (extractReviewCompilerNamedUsize(text, "git_deletions")) |value| mbk.git_tree_metrics.deletions += value;
    mbk.git_tree_metrics.net_lines = @as(i64, @intCast(mbk.git_tree_metrics.insertions)) - @as(i64, @intCast(mbk.git_tree_metrics.deletions));
}

fn extractReviewCompilerNamedUsize(text: []const u8, key: []const u8) ?usize {
    var search_start: usize = 0;
    while (std.mem.indexOfPos(u8, text, search_start, key)) |idx| {
        var cursor = reviewCompilerNamedValueCursor(text, idx + key.len);
        while (cursor < text.len and (std.ascii.isWhitespace(text[cursor]) or text[cursor] == ':' or text[cursor] == '=')) : (cursor += 1) {}
        const start = cursor;
        while (cursor < text.len and std.ascii.isDigit(text[cursor])) : (cursor += 1) {}
        if (cursor > start) return std.fmt.parseInt(usize, text[start..cursor], 10) catch null;
        search_start = idx + key.len;
    }
    return null;
}

fn extractReviewCompilerNamedBool(text: []const u8, key: []const u8) ?bool {
    var search_start: usize = 0;
    while (std.mem.indexOfPos(u8, text, search_start, key)) |idx| {
        var cursor = reviewCompilerNamedValueCursor(text, idx + key.len);
        while (cursor < text.len and (std.ascii.isWhitespace(text[cursor]) or text[cursor] == ':' or text[cursor] == '=')) : (cursor += 1) {}
        if (cursor < text.len and text[cursor] == '"') cursor += 1;
        if (cursor + 4 <= text.len and std.ascii.eqlIgnoreCase(text[cursor .. cursor + 4], "true")) return true;
        if (cursor + 5 <= text.len and std.ascii.eqlIgnoreCase(text[cursor .. cursor + 5], "false")) return false;
        if (cursor + 3 <= text.len and std.ascii.eqlIgnoreCase(text[cursor .. cursor + 3], "yes")) return true;
        if (cursor + 2 <= text.len and std.ascii.eqlIgnoreCase(text[cursor .. cursor + 2], "no")) return false;
        search_start = idx + key.len;
    }
    return null;
}

fn reviewCompilerNamedValueCursor(text: []const u8, start: usize) usize {
    var cursor = start;
    while (cursor < text.len and (std.ascii.isWhitespace(text[cursor]) or text[cursor] == '"')) : (cursor += 1) {}
    return cursor;
}

fn recordReviewCompilerSignalTime(signals: *ReviewCompilerSessionSignals, kind: ReviewCompilerSignalTimeKind, timestamp: ?[]const u8) void {
    const ms = time_utils.parseIsoTimestampMillis(timestamp orelse return) orelse return;
    switch (kind) {
        .recipe => {
            if (signals.recipe_seen_at_ms == null or ms < signals.recipe_seen_at_ms.?) signals.recipe_seen_at_ms = ms;
        },
        .permit => {
            if (signals.permit_seen_at_ms == null or ms < signals.permit_seen_at_ms.?) signals.permit_seen_at_ms = ms;
        },
    }
}

fn recordReviewCompilerTools(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    parsed: canonical_trace.CanonicalSessionTrace,
    repo_root: []const u8,
    opts: Options,
    signals: *ReviewCompilerSessionSignals,
) !void {
    for (parsed.tools.items) |tool| {
        if (!toolTimestampSatisfiesBounds(parsed, tool, opts)) continue;
        if (!toolIsInRepoScope(allocator, repo_root, parsed.session.cwd, tool)) continue;
        const is_lab = toolLooksReviewLab(tool, signals.*);
        const tool_text = reviewCompilerToolText(tool);
        if (reviewCompilerToolIsCompletedC3Controller(tool)) {
            recordReviewCompilerC3Text(audit, tool.command_text orelse tool_text, toolTimestamp(parsed, tool), "controller_tool", signals);
            if (tool.output_text) |out| {
                if (containsAuthoritativeC3EventText(out) or containsAnyIgnoreCaseAscii(out, &.{ "terminal-closed", "tuple-closed", "mrpc_closed" })) {
                    recordReviewCompilerC3Text(audit, out, toolTimestamp(parsed, tool), "controller_receipt", signals);
                }
            }
        } else if (toolHasIncidentalC3Mention(tool)) {
            noteReviewCompilerIncidentalC3(signals, if (tool.kind == .patch_apply) "artifact_under_repair" else "filename_or_path_mention");
        }
        if (signals.true_mbk and containsReviewCompilerMBKToolAccountingCue(tool_text)) {
            if (!isReviewCompilerPositiveEvidenceContamination(tool_text)) {
                try recordReviewCompilerMBKText(allocator, audit, tool_text, toolTimestamp(parsed, tool), signals, parsed.session.session_id, "tool");
            }
        }

        if (tool.kind == .patch_apply and tool.lifecycle_status == .completed and tool.patch_success != false) {
            const patch_text = tool.input_text orelse tool.arguments_json orelse tool.patch_changes_json orelse "";
            const counts = countResolvePatchLines(patch_text);
            const surface = reviewCompilerSurfaceCount(counts);
            if (is_lab) {
                audit.legacy_cleanroom.lab_vs_delivery.lab_apply_patch_calls += 1;
                audit.legacy_cleanroom.lab_vs_delivery.lab_surface_added += surface;
                audit.legacy_cleanroom.lab_vs_delivery.lab_surface_discarded += surface;
                audit.c3.lab_vs_delivery.lab_apply_patch_calls += 1;
                audit.c3.lab_vs_delivery.candidate_surface_generated += surface;
                audit.c3.lab_vs_delivery.candidate_surface_discarded += surface;
            } else {
                audit.legacy_cleanroom.lab_vs_delivery.delivery_apply_patch_calls += 1;
                audit.legacy_cleanroom.lab_vs_delivery.delivery_surface_shipped += surface;
                signals.delivery_mutation_seen = true;
                if (reviewCompilerToolBeforeSignal(parsed, tool, signals.recipe_seen_at_ms)) signals.delivery_before_recipe_seen = true;
                if (reviewCompilerToolBeforeSignal(parsed, tool, signals.permit_seen_at_ms)) audit.legacy_cleanroom.compliance.review_derived_delivery_patches += 1;
                if (reviewCompilerToolMutatesNonBranchLiability(tool)) audit.legacy_cleanroom.liability.non_branch_liabilities_mutated += 1;
                audit.c3.lab_vs_delivery.delivery_surface_shipped += surface;
                if (reviewCompilerC3ToolWhileActive(parsed, tool, signals.*)) {
                    audit.c3.lab_vs_delivery.raw_delivery_mutations_while_frozen += 1;
                    signals.c3_raw_delivery_mutation_seen = true;
                    audit.c3.compliance.direct_review_to_delivery_mutation += 1;
                }
                if (reviewCompilerMBKToolWhileActive(parsed, tool, signals.*)) {
                    audit.mbk.controller.raw_delivery_mutations_while_active += 1;
                }
            }
            continue;
        }

        if (tool.kind == .exec_command and tool.lifecycle_status == .completed and (tool.exit_code orelse -1) == 0) {
            const cmd = tool.command_text orelse "";
            if (commandContainsReviewCompileController(cmd, "apply")) {
                audit.c3.lab_vs_delivery.delivery_apply_events += 1;
                if (signals.true_mbk) audit.mbk.controller.physical_apply_events += 1;
            }
            if (commandContainsReviewCompileController(cmd, "commit")) {
                audit.c3.delivery.controller_commits += 1;
                audit.c3.controller.mrpc_committed += 1;
                if (signals.true_mbk) audit.mbk.controller.physical_commits += 1;
            }
            if (commandContainsReviewCompileController(cmd, "push")) {
                audit.c3.delivery.controller_pushes += 1;
                audit.c3.controller.mrpc_pushed += 1;
                if (signals.true_mbk) audit.mbk.controller.physical_pushes += 1;
            }
            if (commandContainsReviewCompileController(cmd, "close") or commandContainsReviewCompileController(cmd, "closed")) {
                audit.c3.delivery.closed_runs += 1;
                audit.c3.controller.mrpc_closed += 1;
                signals.c3_closed_seen = true;
                recordReviewCompilerEvidenceRef(&signals.c3_closed_evidence, "tool", toolTimestamp(parsed, tool), cmd);
                recordReviewCompilerC3Time(signals, .closed, toolTimestamp(parsed, tool));
            }
            if (containsGitCommitCommand(cmd)) {
                if (is_lab) {
                    audit.legacy_cleanroom.lab_vs_delivery.lab_commits += 1;
                    audit.c3.lab_vs_delivery.lab_commits += 1;
                } else {
                    audit.legacy_cleanroom.lab_vs_delivery.delivery_commits += 1;
                    signals.delivery_mutation_seen = true;
                    if (reviewCompilerToolBeforeSignal(parsed, tool, signals.recipe_seen_at_ms)) signals.delivery_before_recipe_seen = true;
                    if (reviewCompilerToolBeforeSignal(parsed, tool, signals.permit_seen_at_ms)) audit.legacy_cleanroom.compliance.review_derived_delivery_patches += 1;
                    if (reviewCompilerToolMutatesNonBranchLiability(tool)) audit.legacy_cleanroom.liability.non_branch_liabilities_mutated += 1;
                    if (reviewCompilerC3ToolWhileActive(parsed, tool, signals.*) and !commandContainsReviewCompileController(cmd, "commit")) {
                        audit.c3.delivery.raw_commits_while_active += 1;
                        audit.c3.compliance.commit_or_push_bypass += 1;
                        signals.c3_commit_or_push_bypass_seen = true;
                    }
                    if (signals.true_mbk and !commandContainsReviewCompileController(cmd, "commit")) {
                        audit.mbk.controller.physical_commits += 1;
                        if (reviewCompilerMBKToolWhileActive(parsed, tool, signals.*)) audit.mbk.controller.raw_delivery_mutations_while_active += 1;
                    }
                }
            }
            if (containsGitPushCommand(cmd) and reviewCompilerC3ToolWhileActive(parsed, tool, signals.*) and !commandContainsReviewCompileController(cmd, "push")) {
                audit.c3.delivery.raw_pushes_while_active += 1;
                audit.c3.compliance.commit_or_push_bypass += 1;
                signals.c3_commit_or_push_bypass_seen = true;
            }
            if (signals.true_mbk and containsGitPushCommand(cmd) and !commandContainsReviewCompileController(cmd, "push")) {
                audit.mbk.controller.physical_pushes += 1;
                if (reviewCompilerMBKToolWhileActive(parsed, tool, signals.*)) audit.mbk.controller.raw_delivery_mutations_while_active += 1;
            }
        }
    }
}

fn reviewCompilerToolBeforeSignal(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord, signal_ms_opt: ?i64) bool {
    const signal_ms = signal_ms_opt orelse return true;
    const tool_ms = toolTimestampMillis(parsed, tool) orelse return false;
    return tool_ms < signal_ms;
}

fn reviewCompilerToolMutatesNonBranchLiability(tool: canonical_trace.ToolLifecycleRecord) bool {
    return reviewCompilerToolContainsAny(tool, &.{ "non_branch_liability", "non_branch_liabilities", "non-branch liability" });
}

fn toolLooksReviewLab(tool: canonical_trace.ToolLifecycleRecord, signals: ReviewCompilerSessionSignals) bool {
    const cwd = tool.cwd orelse "";
    const lab_terms = &.{ "review-lab", "review_lab", "resolve-lab", "scratch worktree", "candidate-worktree", "candidate worktree" };
    return containsAnyIgnoreCaseAscii(cwd, &.{ "review-lab", "review_lab", "resolve-lab", "scratch" }) or
        reviewCompilerToolContainsAny(tool, lab_terms) or
        (signals.c3_candidate_worktree_context_seen and tool.kind == .patch_apply) or
        (signals.lab_context_seen and reviewCompilerToolContainsAny(tool, &.{ "lab patch", "lab commit", "review lab" }));
}

fn reviewCompilerToolText(tool: canonical_trace.ToolLifecycleRecord) []const u8 {
    return tool.output_text orelse tool.command_text orelse tool.input_text orelse tool.arguments_json orelse tool.patch_changes_json orelse "";
}

fn reviewCompilerToolIsCompletedC3Controller(tool: canonical_trace.ToolLifecycleRecord) bool {
    if (tool.kind != .exec_command) return false;
    if (tool.lifecycle_status != .completed) return false;
    if ((tool.exit_code orelse -1) != 0) return false;
    return commandInvokesReviewCompilerController(tool.command_text orelse "");
}

fn commandInvokesReviewCompilerController(cmd: []const u8) bool {
    var split = std.mem.tokenizeAny(u8, cmd, " \t\r\n'\"");
    var index: usize = 0;
    while (split.next()) |token_raw| : (index += 1) {
        const token = trimCommandPunctuation(token_raw);
        if (token.len == 0) continue;
        const base = pathBasenameSlice(token);
        if (std.mem.eql(u8, base, "review-compiler")) return true;
        if ((std.mem.eql(u8, base, "seq") or std.mem.eql(u8, base, "skills-zig") or std.mem.eql(u8, base, "zig-out/bin/seq")) and index <= 2) {
            while (split.next()) |next_raw| {
                const next = trimCommandPunctuation(next_raw);
                if (next.len == 0 or std.mem.startsWith(u8, next, "-")) continue;
                if (std.mem.eql(u8, pathBasenameSlice(next), "review-compiler")) return true;
                break;
            }
            return false;
        }
    }
    return false;
}

fn trimCommandPunctuation(text: []const u8) []const u8 {
    return std.mem.trim(u8, text, " \t\r\n;|&(){}[]'\",");
}

fn pathBasenameSlice(text: []const u8) []const u8 {
    if (std.mem.lastIndexOfScalar(u8, text, '/')) |idx| return text[idx + 1 ..];
    return text;
}

fn reviewCompilerToolContainsAny(tool: canonical_trace.ToolLifecycleRecord, needles: []const []const u8) bool {
    return containsAnyIgnoreCaseAscii(tool.command_text orelse "", needles) or
        containsAnyIgnoreCaseAscii(tool.input_text orelse "", needles) or
        containsAnyIgnoreCaseAscii(tool.arguments_json orelse "", needles) or
        containsAnyIgnoreCaseAscii(tool.output_text orelse "", needles) or
        containsAnyIgnoreCaseAscii(tool.patch_changes_json orelse "", needles);
}

fn commandContainsReviewCompileController(cmd: []const u8, subcommand: []const u8) bool {
    if (!commandInvokesReviewCompilerController(cmd)) return false;
    return containsIgnoreCaseAscii(cmd, subcommand);
}

fn reviewCompilerC3ToolWhileActive(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord, signals: ReviewCompilerSessionSignals) bool {
    const begin_ms = signals.c3_begin_at_ms orelse return false;
    const tool_ms = toolTimestampMillis(parsed, tool) orelse return false;
    if (tool_ms < begin_ms) return false;
    if (signals.c3_closed_at_ms) |closed_ms| {
        if (tool_ms >= closed_ms) return false;
    }
    if (signals.c3_aborted_at_ms) |aborted_ms| {
        if (tool_ms >= aborted_ms) return false;
    }
    return true;
}

fn reviewCompilerMBKToolWhileActive(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord, signals: ReviewCompilerSessionSignals) bool {
    const begin_ms = signals.mbk_begin_at_ms orelse return false;
    const tool_ms = toolTimestampMillis(parsed, tool) orelse return false;
    if (tool_ms < begin_ms) return false;
    if (signals.mbk_terminal_at_ms) |terminal_ms| {
        if (tool_ms >= terminal_ms) return false;
    }
    return true;
}

fn reviewCompilerSurfaceCount(counts: ResolvePatchCounts) usize {
    return counts.production_insertions + counts.production_deletions + counts.test_insertions + counts.test_deletions;
}

fn finalizeReviewCompilerCompliance(audit: *ReviewCompilerAudit, signals: ReviewCompilerSessionSignals) void {
    if (signals.clean_review_seen) audit.denominator.clean_review_sessions += 1;
    if (signals.isolated_waiver_seen) audit.denominator.isolated_waiver_sessions += 1;
    if (signals.true_c3 and !signals.clean_review_seen and !signals.isolated_waiver_seen) audit.denominator.c3_required_sessions += 1;
    if (signals.c3_begin_seen) audit.denominator.c3_entered_sessions += 1;
    if (signals.c3_closed_seen) audit.denominator.c3_closed_sessions += 1;

    if (signals.delivery_mutation_seen) {
        if (signals.delivery_before_recipe_seen) audit.legacy_cleanroom.compliance.delivery_mutations_before_recipe += 1;
        if (!signals.contract_seen) audit.legacy_cleanroom.compliance.missing_contract += 1;
        if (!signals.recipe_seen) audit.legacy_cleanroom.compliance.missing_recipe += 1;
        if (!signals.ablation_seen) audit.legacy_cleanroom.compliance.missing_ablation += 1;
    }

    if (signals.true_c3) {
        if (!signals.clean_review_seen and !signals.isolated_waiver_seen) {
            if (!signals.c3_basis_seen) audit.c3.compliance.basis_missing += 1;
            if (!signals.c3_tournament_seen) audit.c3.compliance.tournament_missing += 1;
            if (!signals.c3_ablation_seen) audit.c3.compliance.ablation_missing += 1;
            if (!signals.c3_proof_seen) audit.c3.compliance.proof_missing += 1;
            if (!signals.c3_holdout_seen) audit.c3.compliance.holdout_missing += 1;
        }
        if (signals.c3_mrpc_seen and signals.c3_raw_delivery_mutation_seen) {
            audit.c3.compliance.stale_mrpc += 1;
        }
        finalizeReviewCompilerC3ClosureCompression(audit, signals);
    }

    if (!signals.true_mbk) return;
    audit.mbk.denominator.true_resolve_sessions += 1;
    if (signals.mbk_clean_review_seen) audit.mbk.denominator.clean_review_sessions += 1;
    if (signals.mbk_isolated_conformance_seen) audit.mbk.denominator.isolated_conformance_sessions += 1;
    if (signals.mbk_material_kernel_required_seen and !signals.mbk_clean_review_seen and !signals.mbk_isolated_conformance_seen) audit.mbk.denominator.material_kernel_required_sessions += 1;
    if (signals.mbk_begin_seen) audit.mbk.denominator.kernel_campaign_entered_sessions += 1;
    if (signals.mbk_kernel_accepted_seen) audit.mbk.denominator.kernel_accepted_sessions += 1;
    if (signals.mbk_tuple_closed_seen) audit.mbk.denominator.tuple_closed_sessions += 1;
    if (signals.mbk_terminal_closed_seen) audit.mbk.denominator.terminal_closed_sessions += 1;

    if (audit.mbk.semantic_surface.delta.semantic_surface == 0 and audit.mbk.semantic_surface.terminal.semantic_surface >= audit.mbk.semantic_surface.review_ready_baseline.semantic_surface) {
        audit.mbk.semantic_surface.delta.semantic_surface = audit.mbk.semantic_surface.terminal.semantic_surface - audit.mbk.semantic_surface.review_ready_baseline.semantic_surface;
    }
    if (audit.mbk.semantic_surface.delta.governing_laws == 0 and audit.mbk.semantic_surface.terminal.governing_laws >= audit.mbk.semantic_surface.review_ready_baseline.governing_laws) {
        audit.mbk.semantic_surface.delta.governing_laws = audit.mbk.semantic_surface.terminal.governing_laws - audit.mbk.semantic_surface.review_ready_baseline.governing_laws;
    }
    if (audit.mbk.semantic_surface.delta.realization_surface == 0 and audit.mbk.semantic_surface.terminal.realization_surface >= audit.mbk.semantic_surface.review_ready_baseline.realization_surface) {
        audit.mbk.semantic_surface.delta.realization_surface = audit.mbk.semantic_surface.terminal.realization_surface - audit.mbk.semantic_surface.review_ready_baseline.realization_surface;
    }
    if (audit.mbk.semantic_surface.delta.proof_families == 0 and audit.mbk.semantic_surface.terminal.proof_families >= audit.mbk.semantic_surface.review_ready_baseline.proof_families) {
        audit.mbk.semantic_surface.delta.proof_families = audit.mbk.semantic_surface.terminal.proof_families - audit.mbk.semantic_surface.review_ready_baseline.proof_families;
    }
}

fn recordResolveMessages(
    allocator: std.mem.Allocator,
    audit: *ResolveChurnAudit,
    messages: []const datasets.messages.MessageRow,
    opts: Options,
    signals: *ResolveSessionSignals,
) !void {
    _ = allocator;
    for (messages) |message| {
        if (!timestampSatisfiesBounds(message.timestamp, opts)) continue;
        if (!std.mem.eql(u8, message.role, "assistant")) continue;
        const text = message.text;

        if (containsAnyIgnoreCaseAscii(text, &.{ "initial_broad", "initial broad", "broad sensing" })) audit.review_horizon.initial_broad += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "targeted", "charter-clean", "clean current-head" })) audit.review_horizon.targeted += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "final_holdout", "final holdout", "broad holdout" })) audit.review_horizon.final_holdout += 1;

        if (containsAnyIgnoreCaseAscii(text, &.{ "introduced_by_current_diff", "introduced_by_diff" })) audit.finding_liability.introduced_by_diff += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "exposed_and_required_by_current_acceptance", "acceptance_required" })) audit.finding_liability.acceptance_required += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "preexisting_but_blocks_current_invariant", "preexisting_blocker" })) audit.finding_liability.preexisting_blocker += 1;
        if (containsIgnoreCaseAscii(text, "adjacent_preexisting")) audit.finding_liability.adjacent_preexisting += 1;
        if (containsIgnoreCaseAscii(text, "reviewer_preference")) audit.finding_liability.reviewer_preference += 1;
        if (containsIgnoreCaseAscii(text, "finding_liability: unknown") or containsIgnoreCaseAscii(text, "liability: unknown")) audit.finding_liability.unknown += 1;

        if (containsAnyIgnoreCaseAscii(text, &.{ "normal_form_status: proposed", "normal form status: proposed", "status: proposed" })) audit.normal_forms.proposed += 1;
        if (containsIgnoreCaseAscii(text, "falsified")) audit.normal_forms.falsified += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "repeated_after_falsification", "same_family_after_normal_form: yes", "family_recurred_after: yes" })) audit.normal_forms.repeated_after_falsification += 1;

        if (containsAnyIgnoreCaseAscii(text, &.{ "distillation_required: yes", "same_family_after_normal_form: yes", "normal_form_falsified: yes", "governor_fuse" })) audit.fuse.required += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "fuse_state: tripped", "delivery_mutation_frozen: yes" })) {
            audit.fuse.tripped += 1;
            signals.fuse_tripped = true;
            if (message.timestamp) |ts| {
                if (time_utils.parseIsoTimestampMillis(ts)) |ms| {
                    if (signals.fuse_tripped_at_ms == null or ms < signals.fuse_tripped_at_ms.?) signals.fuse_tripped_at_ms = ms;
                }
            }
        }
        if (containsIgnoreCaseAscii(text, "review_distillation_receipt")) signals.distillation_seen = true;

        if (containsIgnoreCaseAscii(text, "RGR-V3-MUTATION-PERMIT")) {
            audit.permits.emitted += 1;
            signals.permit_emitted = true;
        }

        if (containsAnyIgnoreCaseAscii(text, &.{ "ledger map", "ledger gate", "negative_route_gate" })) audit.negative_ledger.maps_or_gates += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "ledger capture", "capture_created: yes" })) audit.negative_ledger.captures += 1;
        if (containsIgnoreCaseAscii(text, "route_changed_at_leverage_level: yes")) audit.negative_ledger.route_changes += 1;
        if (containsAnyIgnoreCaseAscii(text, &.{ "reviewThreads", "gh pr view", "PR sweep", "pr_sweeps" })) audit.review.pr_sweeps += 1;
    }
}

fn recordResolveTools(
    allocator: std.mem.Allocator,
    audit: *ResolveChurnAudit,
    parsed: canonical_trace.CanonicalSessionTrace,
    repo_root: []const u8,
    opts: Options,
    signals: *ResolveSessionSignals,
) !void {
    for (parsed.tools.items) |tool| {
        if (!toolTimestampSatisfiesBounds(parsed, tool, opts)) continue;
        if (!toolIsInRepoScope(allocator, repo_root, parsed.session.cwd, tool)) continue;
        if (toolHasCompletedResolveReviewEvidence(tool)) {
            const head = extractReviewHeadFromTool(tool) orelse "unknown";
            try recordReviewHead(allocator, &audit.review.cas_reviews_by_head, head);
        }

        if (tool.kind == .patch_apply and tool.lifecycle_status == .completed and tool.patch_success != false) {
            audit.mutation.apply_patch_calls += 1;
            signals.mutation_session = true;
            const patch_text = tool.input_text orelse tool.arguments_json orelse tool.patch_changes_json orelse "";
            const counts = countResolvePatchLines(patch_text);
            addResolvePatchCounts(&audit.mutation, counts);
            if (toolOccursAfterFuse(parsed, tool, signals)) {
                audit.fuse.mutations_after_trip += 1;
                signals.mutation_after_fuse = true;
                audit.fuse.production_net_after_trip += counts.productionNet();
            }
            continue;
        }

        if (tool.kind == .exec_command and tool.lifecycle_status == .completed and (tool.exit_code orelse -1) == 0) {
            const cmd = tool.command_text orelse "";
            if (containsGitCommitCommand(cmd)) {
                audit.mutation.commits += 1;
                signals.mutation_session = true;
                if (toolOccursAfterFuse(parsed, tool, signals)) {
                    audit.fuse.mutations_after_trip += 1;
                    signals.mutation_after_fuse = true;
                }
            }
        }
    }
    audit.mutation.refreshNet();
}

fn toolTimestampSatisfiesBounds(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord, opts: Options) bool {
    const timestamp = toolTimestamp(parsed, tool) orelse return false;
    return timestampSatisfiesBounds(timestamp, opts);
}

fn toolTimestampMillis(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord) ?i64 {
    const timestamp = toolTimestamp(parsed, tool) orelse return null;
    return time_utils.parseIsoTimestampMillis(timestamp);
}

fn toolTimestamp(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord) ?[]const u8 {
    if (tool.completed_at) |value| return value;
    if (tool.started_at) |value| return value;
    if (tool.turn_index) |tool_turn_index| {
        for (parsed.turns.items) |turn| {
            if (turn.turn_index != tool_turn_index) continue;
            if (turn.completed_at) |value| return value;
            if (turn.started_at) |value| return value;
            break;
        }
    }
    return null;
}

fn toolOccursAfterFuse(parsed: canonical_trace.CanonicalSessionTrace, tool: canonical_trace.ToolLifecycleRecord, signals: *const ResolveSessionSignals) bool {
    const fuse_ms = signals.fuse_tripped_at_ms orelse return false;
    const tool_ms = toolTimestampMillis(parsed, tool) orelse return false;
    return tool_ms > fuse_ms;
}

fn toolIsInRepoScope(allocator: std.mem.Allocator, repo_root: []const u8, session_cwd: ?[]const u8, tool: canonical_trace.ToolLifecycleRecord) bool {
    const cwd = tool.cwd orelse session_cwd orelse return false;
    return pathMatchesRepoScope(allocator, repo_root, cwd) catch false;
}

fn recordReviewHead(allocator: std.mem.Allocator, heads: *std.ArrayList(ResolveChurnAudit.ReviewHeadCount), head: []const u8) !void {
    for (heads.items) |*item| {
        if (std.mem.eql(u8, item.head, head)) {
            item.count += 1;
            return;
        }
    }
    try heads.append(allocator, .{ .head = try allocator.dupe(u8, head), .count = 1 });
}

fn extractReviewHeadFromTool(tool: canonical_trace.ToolLifecycleRecord) ?[]const u8 {
    if (tool.output_text) |text| {
        if (extractFlatJsonStringField(text, "headSha")) |head| return head;
        if (extractFlatJsonStringField(text, "head_sha")) |head| return head;
        if (extractReviewHead(text)) |head| return head;
    }
    if (tool.command_text) |text| {
        if (extractReviewHead(text)) |head| return head;
    }
    if (tool.input_text) |text| {
        if (extractReviewHead(text)) |head| return head;
    }
    if (tool.arguments_json) |text| {
        if (extractReviewHead(text)) |head| return head;
    }
    return null;
}

fn extractReviewHead(text: []const u8) ?[]const u8 {
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |line_raw| {
        const line = std.mem.trim(u8, line_raw, " \t\r\n,");
        if (line.len == 0) continue;
        if (std.mem.indexOf(u8, line, "headSha")) |idx| return tokenAfterMarker(line[idx..], ':');
        if (std.mem.indexOf(u8, line, "head_sha")) |idx| return tokenAfterMarker(line[idx..], ':');
        if (std.mem.indexOf(u8, line, "--head")) |idx| return tokenAfterMarker(line[idx + "--head".len ..], ' ');
    }
    return null;
}

fn tokenAfterMarker(text: []const u8, marker: u8) ?[]const u8 {
    const start_raw = if (std.mem.indexOfScalar(u8, text, marker)) |idx| idx + 1 else 0;
    var start = start_raw;
    while (start < text.len and (std.ascii.isWhitespace(text[start]) or text[start] == '"' or text[start] == '\'')) : (start += 1) {}
    var end = start;
    while (end < text.len and !std.ascii.isWhitespace(text[end]) and text[end] != ',' and text[end] != '}' and text[end] != '"') : (end += 1) {}
    if (end <= start) return null;
    return text[start..end];
}

fn containsGitCommitCommand(text: []const u8) bool {
    return containsIgnoreCaseAscii(text, "git commit");
}

fn containsGitPushCommand(text: []const u8) bool {
    return containsIgnoreCaseAscii(text, "git push");
}

fn addResolvePatchCounts(mutation: *ResolveChurnAudit.Mutation, counts: ResolvePatchCounts) void {
    mutation.production_insertions += counts.production_insertions;
    mutation.production_deletions += counts.production_deletions;
    mutation.test_insertions += counts.test_insertions;
    mutation.test_deletions += counts.test_deletions;
}

fn countResolvePatchLines(patch_text: []const u8) ResolvePatchCounts {
    var counts = ResolvePatchCounts{};
    var current_kind: ResolvePathKind = .other;
    var lines = std.mem.splitScalar(u8, patch_text, '\n');
    while (lines.next()) |line| {
        if (std.mem.startsWith(u8, line, "*** Add File: ")) {
            current_kind = classifyResolvePath(line["*** Add File: ".len..]);
            continue;
        }
        if (std.mem.startsWith(u8, line, "*** Update File: ")) {
            current_kind = classifyResolvePath(line["*** Update File: ".len..]);
            continue;
        }
        if (std.mem.startsWith(u8, line, "*** Delete File: ")) {
            current_kind = classifyResolvePath(line["*** Delete File: ".len..]);
            continue;
        }
        if (std.mem.startsWith(u8, line, "+++ ") or std.mem.startsWith(u8, line, "--- ") or std.mem.startsWith(u8, line, "***")) continue;
        if (line.len == 0) continue;

        if (line[0] == '+') {
            switch (current_kind) {
                .production => counts.production_insertions += 1,
                .tests => counts.test_insertions += 1,
                .other => {},
            }
        } else if (line[0] == '-') {
            switch (current_kind) {
                .production => counts.production_deletions += 1,
                .tests => counts.test_deletions += 1,
                .other => {},
            }
        }
    }
    return counts;
}

fn classifyResolvePath(path_raw: []const u8) ResolvePathKind {
    const path = std.mem.trim(u8, path_raw, " \t\r\n\"");
    if (containsAnyIgnoreCaseAscii(path, &.{ "/test", "tests/", "test/", "testdata", "fixtures", "__tests__", "__fixtures__", "spec/" })) return .tests;
    if (std.mem.startsWith(u8, path, "apps/seq/src/tests")) return .tests;
    if (std.mem.endsWith(u8, path, "_test.zig")) return .tests;
    if (std.mem.endsWith(u8, path, ".test.ts") or
        std.mem.endsWith(u8, path, ".test.tsx") or
        std.mem.endsWith(u8, path, ".test.js") or
        std.mem.endsWith(u8, path, ".test.jsx") or
        std.mem.endsWith(u8, path, ".spec.ts") or
        std.mem.endsWith(u8, path, ".spec.tsx") or
        std.mem.endsWith(u8, path, ".spec.js") or
        std.mem.endsWith(u8, path, ".spec.jsx"))
        return .tests;
    if (containsAnyIgnoreCaseAscii(path, &.{ "src/", "cmd/", "lib/", "libs/", "app/", "apps/", "pkg/", "internal/", "crates/", "packages/", "tools/", "bin/" })) return .production;
    if (isCodeLikeProductionPath(path)) return .production;
    if (std.mem.eql(u8, path, "build.zig") or std.mem.endsWith(u8, path, "/build.zig")) return .production;
    return .other;
}

fn isCodeLikeProductionPath(path: []const u8) bool {
    return std.mem.endsWith(u8, path, ".zig") or
        std.mem.endsWith(u8, path, ".zon") or
        std.mem.endsWith(u8, path, ".c") or
        std.mem.endsWith(u8, path, ".h") or
        std.mem.endsWith(u8, path, ".cpp") or
        std.mem.endsWith(u8, path, ".hpp") or
        std.mem.endsWith(u8, path, ".rs") or
        std.mem.endsWith(u8, path, ".go") or
        std.mem.endsWith(u8, path, ".py") or
        std.mem.endsWith(u8, path, ".js") or
        std.mem.endsWith(u8, path, ".jsx") or
        std.mem.endsWith(u8, path, ".ts") or
        std.mem.endsWith(u8, path, ".tsx") or
        std.mem.endsWith(u8, path, ".java") or
        std.mem.endsWith(u8, path, ".kt") or
        std.mem.endsWith(u8, path, ".swift") or
        std.mem.endsWith(u8, path, ".rb") or
        std.mem.endsWith(u8, path, ".sh") or
        std.mem.endsWith(u8, path, ".sql") or
        std.mem.endsWith(u8, path, ".lua");
}

fn writeResolveChurnAuditMarkdown(allocator: std.mem.Allocator, audit: ResolveChurnAudit, out_path: ?[]const u8) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.writeAll("# seq resolve-churn-audit\n\n```yaml\nresolve_churn_audit:\n");
    try writeResolveChurnAuditYamlBody(writer, audit, "  ");
    try writer.writeAll("```\n");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn writeResolveChurnAuditYamlBody(writer: anytype, audit: ResolveChurnAudit, indent: []const u8) !void {
    try writer.print("{s}denominator:\n", .{indent});
    try writer.print("{s}  candidate_sessions: {d}\n{s}  true_resolve_sessions: {d}\n{s}  exclusions: {d}\n", .{ indent, audit.denominator.candidate_sessions, indent, audit.denominator.true_resolve_sessions, indent, audit.denominator.exclusions });
    try writer.print("{s}review_horizon:\n{s}  initial_broad: {d}\n{s}  targeted: {d}\n{s}  final_holdout: {d}\n", .{ indent, indent, audit.review_horizon.initial_broad, indent, audit.review_horizon.targeted, indent, audit.review_horizon.final_holdout });
    try writer.print("{s}finding_liability:\n{s}  introduced_by_diff: {d}\n{s}  acceptance_required: {d}\n{s}  preexisting_blocker: {d}\n{s}  adjacent_preexisting: {d}\n{s}  reviewer_preference: {d}\n{s}  unknown: {d}\n", .{ indent, indent, audit.finding_liability.introduced_by_diff, indent, audit.finding_liability.acceptance_required, indent, audit.finding_liability.preexisting_blocker, indent, audit.finding_liability.adjacent_preexisting, indent, audit.finding_liability.reviewer_preference, indent, audit.finding_liability.unknown });
    try writer.print("{s}normal_forms:\n{s}  proposed: {d}\n{s}  falsified: {d}\n{s}  repeated_after_falsification: {d}\n", .{ indent, indent, audit.normal_forms.proposed, indent, audit.normal_forms.falsified, indent, audit.normal_forms.repeated_after_falsification });
    try writer.print("{s}fuse:\n{s}  required: {d}\n{s}  tripped: {d}\n{s}  mutations_after_trip: {d}\n{s}  production_net_after_trip: {d}\n", .{ indent, indent, audit.fuse.required, indent, audit.fuse.tripped, indent, audit.fuse.mutations_after_trip, indent, audit.fuse.production_net_after_trip });
    try writer.print("{s}owner_pressure:\n{s}  by_owner: []\n", .{ indent, indent });
    try writer.print("{s}mutation:\n{s}  apply_patch_calls: {d}\n{s}  commits: {d}\n{s}  production_insertions: {d}\n{s}  production_deletions: {d}\n{s}  production_net: {d}\n{s}  test_insertions: {d}\n{s}  test_deletions: {d}\n{s}  test_net: {d}\n", .{ indent, indent, audit.mutation.apply_patch_calls, indent, audit.mutation.commits, indent, audit.mutation.production_insertions, indent, audit.mutation.production_deletions, indent, audit.mutation.production_net, indent, audit.mutation.test_insertions, indent, audit.mutation.test_deletions, indent, audit.mutation.test_net });
    try writer.print("{s}permits:\n{s}  required: {d}\n{s}  emitted: {d}\n{s}  missing: {d}\n", .{ indent, indent, audit.permits.required, indent, audit.permits.emitted, indent, audit.permits.missing });
    try writer.print("{s}negative_ledger:\n{s}  maps_or_gates: {d}\n{s}  captures: {d}\n{s}  route_changes: {d}\n", .{ indent, indent, audit.negative_ledger.maps_or_gates, indent, audit.negative_ledger.captures, indent, audit.negative_ledger.route_changes });
    try writer.print("{s}review:\n{s}  cas_reviews_by_head:", .{ indent, indent });
    if (audit.review.cas_reviews_by_head.items.len == 0) {
        try writer.writeAll(" []\n");
    } else {
        try writer.writeByte('\n');
        for (audit.review.cas_reviews_by_head.items) |item| {
            try writer.print("{s}    - head: {s}\n{s}      count: {d}\n", .{ indent, item.head, indent, item.count });
        }
    }
    try writer.print("{s}  pr_sweeps: {d}\n", .{ indent, audit.review.pr_sweeps });
    try writer.print("{s}compliance:\n{s}  mutations_without_permit: {d}\n{s}  normal_form_retries_after_falsification: {d}\n{s}  mutations_after_fuse_without_distillation: {d}\n", .{ indent, indent, audit.compliance.mutations_without_permit, indent, audit.compliance.normal_form_retries_after_falsification, indent, audit.compliance.mutations_after_fuse_without_distillation });
}

fn writeResolveChurnAuditJson(allocator: std.mem.Allocator, audit: ResolveChurnAudit, out_path: ?[]const u8) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.writeAll("{\n  \"resolve_churn_audit\": {\n");
    try writer.print("    \"denominator\": {{ \"candidate_sessions\": {d}, \"true_resolve_sessions\": {d}, \"exclusions\": {d} }},\n", .{ audit.denominator.candidate_sessions, audit.denominator.true_resolve_sessions, audit.denominator.exclusions });
    try writer.print("    \"review_horizon\": {{ \"initial_broad\": {d}, \"targeted\": {d}, \"final_holdout\": {d} }},\n", .{ audit.review_horizon.initial_broad, audit.review_horizon.targeted, audit.review_horizon.final_holdout });
    try writer.print("    \"finding_liability\": {{ \"introduced_by_diff\": {d}, \"acceptance_required\": {d}, \"preexisting_blocker\": {d}, \"adjacent_preexisting\": {d}, \"reviewer_preference\": {d}, \"unknown\": {d} }},\n", .{ audit.finding_liability.introduced_by_diff, audit.finding_liability.acceptance_required, audit.finding_liability.preexisting_blocker, audit.finding_liability.adjacent_preexisting, audit.finding_liability.reviewer_preference, audit.finding_liability.unknown });
    try writer.print("    \"normal_forms\": {{ \"proposed\": {d}, \"falsified\": {d}, \"repeated_after_falsification\": {d} }},\n", .{ audit.normal_forms.proposed, audit.normal_forms.falsified, audit.normal_forms.repeated_after_falsification });
    try writer.print("    \"fuse\": {{ \"required\": {d}, \"tripped\": {d}, \"mutations_after_trip\": {d}, \"production_net_after_trip\": {d} }},\n", .{ audit.fuse.required, audit.fuse.tripped, audit.fuse.mutations_after_trip, audit.fuse.production_net_after_trip });
    try writer.writeAll("    \"owner_pressure\": { \"by_owner\": [] },\n");
    try writer.print("    \"mutation\": {{ \"apply_patch_calls\": {d}, \"commits\": {d}, \"production_insertions\": {d}, \"production_deletions\": {d}, \"production_net\": {d}, \"test_insertions\": {d}, \"test_deletions\": {d}, \"test_net\": {d} }},\n", .{ audit.mutation.apply_patch_calls, audit.mutation.commits, audit.mutation.production_insertions, audit.mutation.production_deletions, audit.mutation.production_net, audit.mutation.test_insertions, audit.mutation.test_deletions, audit.mutation.test_net });
    try writer.print("    \"permits\": {{ \"required\": {d}, \"emitted\": {d}, \"missing\": {d} }},\n", .{ audit.permits.required, audit.permits.emitted, audit.permits.missing });
    try writer.print("    \"negative_ledger\": {{ \"maps_or_gates\": {d}, \"captures\": {d}, \"route_changes\": {d} }},\n", .{ audit.negative_ledger.maps_or_gates, audit.negative_ledger.captures, audit.negative_ledger.route_changes });
    try writer.writeAll("    \"review\": { \"cas_reviews_by_head\": [");
    for (audit.review.cas_reviews_by_head.items, 0..) |item, idx| {
        if (idx > 0) try writer.writeAll(", ");
        try writer.writeAll("{ \"head\": ");
        try output.writeJsonString(writer, item.head);
        try writer.print(", \"count\": {d} }}", .{item.count});
    }
    try writer.print("], \"pr_sweeps\": {d} }},\n", .{audit.review.pr_sweeps});
    try writer.print("    \"compliance\": {{ \"mutations_without_permit\": {d}, \"normal_form_retries_after_falsification\": {d}, \"mutations_after_fuse_without_distillation\": {d} }}\n", .{ audit.compliance.mutations_without_permit, audit.compliance.normal_form_retries_after_falsification, audit.compliance.mutations_after_fuse_without_distillation });
    try writer.writeAll("  }\n}\n");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn finalizeReviewCompilerC3ClosureCompression(audit: *ReviewCompilerAudit, signals: ReviewCompilerSessionSignals) void {
    const material_c3 = signals.true_c3 and !signals.clean_review_seen and !signals.isolated_waiver_seen;
    const closed = signals.c3_closed_seen;
    if (!closed) return;

    audit.c3.closure_compression.closed_total += 1;
    if (!material_c3) {
        audit.c3.closure_compression.closed_compressed += 1;
        audit.c3.closure_compression.compression_not_required += 1;
        return;
    }

    const permit_ok = signals.c3_apply_certified_seen or signals.c3_final_certified_seen;
    const stale_mrpc = signals.c3_mrpc_seen and signals.c3_raw_delivery_mutation_seen;
    const compression_ok = signals.c3_basis_seen and
        signals.c3_tournament_seen and
        signals.c3_ablation_seen and
        signals.c3_proof_seen and
        signals.c3_holdout_seen and
        permit_ok and
        !stale_mrpc and
        !signals.c3_raw_delivery_mutation_seen and
        !signals.c3_commit_or_push_bypass_seen;

    if (compression_ok) {
        audit.c3.closure_compression.closed_compressed += 1;
        return;
    }

    audit.c3.closure_compression.closed_uncompressed += 1;
    const missing = &audit.c3.closure_compression.missing_compression_evidence;
    if (!signals.c3_basis_seen) missing.basis += 1;
    if (!signals.c3_tournament_seen) missing.tournament += 1;
    if (!signals.c3_ablation_seen) missing.ablation += 1;
    if (!signals.c3_proof_seen) missing.proof += 1;
    if (!signals.c3_holdout_seen) missing.holdout += 1;
    if (!permit_ok) missing.permit += 1;
    if (stale_mrpc) missing.stale_mrpc += 1;
    if (signals.c3_raw_delivery_mutation_seen) missing.direct_review_to_delivery_mutation += 1;
    if (signals.c3_commit_or_push_bypass_seen) missing.commit_or_push_bypass += 1;
}

fn addReviewCompilerC3IncludedSession(
    allocator: std.mem.Allocator,
    audit: *ReviewCompilerAudit,
    signals: ReviewCompilerSessionSignals,
    session_id: ?[]const u8,
    path: []const u8,
) !void {
    const required = reviewCompilerC3Material(signals);
    const classification: []const u8 = if (signals.clean_review_seen)
        "clean_review"
    else if (signals.isolated_waiver_seen)
        "isolated_waiver"
    else
        "material_c3";
    const protocol: []const u8 = if (signals.c3_mrpc_seen) "c3-mrpc" else "c3";
    const lifecycle = reviewCompilerLifecycleState(signals);
    const compression = (try reviewCompilerC3ClosureEvidence(allocator, signals));
    errdefer compression.deinit(allocator);

    try audit.denominator.included_sessions.append(allocator, .{
        .session_id = if (session_id) |id| try allocator.dupe(u8, id) else null,
        .path = try allocator.dupe(u8, path),
        .protocol = try allocator.dupe(u8, protocol),
        .classification = try allocator.dupe(u8, classification),
        .c3_required = required,
        .c3_entered = signals.c3_begin_seen,
        .c3_closed = signals.c3_closed_seen,
        .governance = try allocator.dupe(u8, signals.governance_state.label()),
        .lifecycle = try allocator.dupe(u8, lifecycle.label()),
        .delivery_closed = signals.delivery_closed_seen,
        .compression = try allocator.dupe(u8, compression.summary_state.label()),
        .evidence = .{
            .true_c3 = try reviewCompilerOwnedEvidenceFromSignal(allocator, signals.true_c3_evidence, "true_c3_signal_present", "missing_true_c3_signal"),
            .required = try reviewCompilerOwnedDerivedEvidence(allocator, required, if (required) "true_c3 && !clean_review_seen && !isolated_waiver_seen" else if (signals.clean_review_seen) "clean_review_session" else if (signals.isolated_waiver_seen) "isolated_waiver_session" else "no_true_c3_signal"),
            .entered = try reviewCompilerOwnedEvidenceFromSignal(allocator, signals.c3_begin_evidence, "c3_begin_signal_present", "no_c3_begin_signal"),
            .closed = try reviewCompilerOwnedEvidenceFromSignal(allocator, signals.c3_closed_evidence, "c3_closed_signal_present", "no_c3_closed_signal"),
            .closure_compression = compression,
        },
    });
}

fn reviewCompilerLifecycleState(signals: ReviewCompilerSessionSignals) ReviewCompilerLifecycleState {
    if (signals.governance_state == .incidental) return .incidental;
    if (signals.governance_state == .declared_uncontrolled and !signals.c3_begin_seen and !signals.c3_closed_seen) return .declared_uncontrolled;
    if (signals.c3_closed_seen and !signals.c3_begin_seen and signals.imported_c3_state_seen) return .imported_state;
    if (signals.c3_closed_seen and !signals.c3_begin_seen) return .orphan_close;
    if (signals.c3_begin_seen and signals.c3_closed_seen) return .valid;
    if (signals.c3_begin_seen) return .open;
    return switch (signals.governance_state) {
        .authoritative => .open,
        .declared_uncontrolled => .declared_uncontrolled,
        .ambiguous => .contradictory,
        else => .incidental,
    };
}

fn reviewCompilerC3Material(signals: ReviewCompilerSessionSignals) bool {
    return signals.true_c3 and !signals.clean_review_seen and !signals.isolated_waiver_seen;
}

fn reviewCompilerC3PermitOk(signals: ReviewCompilerSessionSignals) bool {
    return signals.c3_apply_certified_seen or signals.c3_final_certified_seen;
}

fn reviewCompilerC3StaleMRPC(signals: ReviewCompilerSessionSignals) bool {
    return signals.c3_mrpc_seen and signals.c3_raw_delivery_mutation_seen;
}

fn reviewCompilerC3CompressionOk(signals: ReviewCompilerSessionSignals) bool {
    return signals.c3_basis_seen and
        signals.c3_tournament_seen and
        signals.c3_ablation_seen and
        signals.c3_proof_seen and
        signals.c3_holdout_seen and
        reviewCompilerC3PermitOk(signals) and
        !reviewCompilerC3StaleMRPC(signals) and
        !signals.c3_raw_delivery_mutation_seen and
        !signals.c3_commit_or_push_bypass_seen;
}

fn reviewCompilerOwnedEvidenceFromSignal(
    allocator: std.mem.Allocator,
    evidence: ?ReviewCompilerBorrowedEvidenceRef,
    present_reason: []const u8,
    absent_reason: []const u8,
) !ReviewCompilerAudit.SignalEvidenceRef {
    if (evidence) |ref| {
        return .{
            .present = true,
            .source = try allocator.dupe(u8, ref.source),
            .timestamp = if (ref.timestamp) |timestamp| try allocator.dupe(u8, timestamp) else null,
            .snippet = try allocator.dupe(u8, ref.snippet),
            .reason = try allocator.dupe(u8, present_reason),
        };
    }
    return .{
        .present = false,
        .source = try allocator.dupe(u8, "absent"),
        .timestamp = null,
        .snippet = null,
        .reason = try allocator.dupe(u8, absent_reason),
    };
}

fn reviewCompilerOwnedDerivedEvidence(
    allocator: std.mem.Allocator,
    present: bool,
    reason: []const u8,
) !ReviewCompilerAudit.SignalEvidenceRef {
    return .{
        .present = present,
        .source = try allocator.dupe(u8, "derived"),
        .timestamp = null,
        .snippet = null,
        .reason = try allocator.dupe(u8, reason),
    };
}

fn reviewCompilerC3ClosureEvidence(
    allocator: std.mem.Allocator,
    signals: ReviewCompilerSessionSignals,
) !ReviewCompilerAudit.ClosureCompressionEvidence {
    const material_c3 = reviewCompilerC3Material(signals);
    const closed = signals.c3_closed_seen;
    if (!closed) {
        return .{
            .summary_state = .none,
            .reason = try allocator.dupe(u8, if (material_c3) "c3_not_closed" else "not_closed_and_compression_not_required"),
        };
    }
    if (!material_c3) {
        return .{
            .summary_state = .closed,
            .reason = try allocator.dupe(u8, "closed_compression_not_required"),
        };
    }
    if (reviewCompilerC3CompressionOk(signals)) {
        return .{
            .summary_state = .closed,
            .reason = try allocator.dupe(u8, "closed_with_required_compression_evidence"),
        };
    }
    return .{
        .summary_state = .closed_uncompressed,
        .reason = try allocator.dupe(u8, "closed_material_c3_missing_compression_evidence"),
        .missing_compression_evidence = reviewCompilerC3MissingCompressionEvidence(signals),
    };
}

fn reviewCompilerC3MissingCompressionEvidence(signals: ReviewCompilerSessionSignals) ReviewCompilerAudit.MissingCompressionEvidence {
    var missing: ReviewCompilerAudit.MissingCompressionEvidence = .{};
    if (!signals.c3_basis_seen) missing.basis += 1;
    if (!signals.c3_tournament_seen) missing.tournament += 1;
    if (!signals.c3_ablation_seen) missing.ablation += 1;
    if (!signals.c3_proof_seen) missing.proof += 1;
    if (!signals.c3_holdout_seen) missing.holdout += 1;
    if (!reviewCompilerC3PermitOk(signals)) missing.permit += 1;
    if (reviewCompilerC3StaleMRPC(signals)) missing.stale_mrpc += 1;
    if (signals.c3_raw_delivery_mutation_seen) missing.direct_review_to_delivery_mutation += 1;
    if (signals.c3_commit_or_push_bypass_seen) missing.commit_or_push_bypass += 1;
    return missing;
}

fn writeReviewCompilerIntentReportMarkdown(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, artifact_root: ?[]const u8, out_path: ?[]const u8) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;
    const protocol = audit.outputProtocol();

    try writer.writeAll("# seq review-compiler-audit intent-closed report\n\n");
    try writer.writeAll("## Corpus and capability proof\n\n");
    try writer.print("- seq_version: {s}\n- scanner_version: {s}\n- run_version: {s}\n- protocol: {s}\n- candidate_sessions: {d}\n- included_sessions: {d}\n- artifact_root: ", .{ app_meta.version, resolve_intent_closed.scanner_version, resolve_intent_closed.run_version, protocol.label(), audit.denominator.candidate_sessions, audit.denominator.included_sessions.items.len });
    if (artifact_root) |root| try output.writeJsonString(writer, root) else try writer.writeAll("null");
    try writer.writeAll("\n\n");

    try writer.writeAll("## Protocol-separated denominator\n\n");
    try writer.print("- true_resolve_sessions: {d}\n- excluded_sessions: {d}\n- authoritative_sessions: {d}\n- declared_uncontrolled_sessions: {d}\n- incidental_sessions: {d}\n- ambiguous_sessions: {d}\n\n", .{ audit.denominator.true_resolve_sessions, audit.denominator.excluded_sessions, audit.denominator.authoritative_sessions, audit.denominator.declared_uncontrolled_sessions, audit.denominator.incidental_sessions, audit.denominator.ambiguous_sessions });

    try writer.writeAll("## AC/horizon integrity\n\n");
    try writer.writeAll("- AC-v2 controller artifact projection: pending in resolve-intent-closed dataset slice.\n- Absence reason: no accepted AC rows are emitted from transcript prose.\n\n");

    try writer.writeAll("## Review batch/mode discipline\n\n");
    try writer.print("- c3_required_sessions: {d}\n- c3_entered_sessions: {d}\n- c3_closed_sessions: {d}\n- direct_review_to_delivery_mutation: {d}\n\n", .{ audit.denominator.c3_required_sessions, audit.denominator.c3_entered_sessions, audit.denominator.c3_closed_sessions, audit.c3.compliance.direct_review_to_delivery_mutation });

    try writer.writeAll("## Counterexample novelty/compression\n\n");
    try writer.print("- raw_findings: {d}\n- branch_liabilities: {d}\n- independent_families: {d}\n- subsumed_findings: {d}\n\n", .{ audit.c3.counterexamples.raw_findings + audit.mbk.observations.raw_findings, audit.c3.counterexamples.branch_liabilities + audit.mbk.observations.branch_liabilities, audit.c3.counterexamples.independent_families, audit.c3.counterexamples.subsumed_findings });

    try writer.writeAll("## Kernel/realization lineage\n\n");
    try writer.print("- kernel_laws: {d}\n- selected_designs: {d}\n- realization_recompilations: {d}\n- duplicate_realizations: {d}\n\n", .{ audit.mbk.kernel.laws, audit.mbk.realization.selected_designs, audit.mbk.realization.realization_recompilations, audit.mbk.realization.duplicate_realizations });

    try writer.writeAll("## PHI progress\n\n");
    try writer.writeAll("- PHI-v1 strict progress recomputation: available in shared parser; cohort projection pending in dataset slice.\n\n");

    try writer.writeAll("## Mapping/proof compression\n\n");
    try writer.print("- proof_runs: {d}\n- proof_families: {d}\n- wound_specific_tests: {d}\n- unmapped_proof_actions: {d}\n\n", .{ audit.mbk.proof.proof_runs, audit.mbk.proof.proof_families, audit.mbk.proof.wound_specific_tests, audit.mbk.proof.unmapped_proof_actions });

    try writer.writeAll("## Holdout/delivery/closure\n\n");
    try writer.print("- delivery_holdouts: {d}\n- new_counterexamples: {d}\n- closed_runs: {d}\n- terminal_closed_sessions: {d}\n- raw_commits_while_active: {d}\n- raw_pushes_while_active: {d}\n\n", .{ audit.c3.holdout.delivery_holdouts, audit.c3.holdout.new_counterexamples, audit.c3.delivery.closed_runs, audit.mbk.denominator.terminal_closed_sessions, audit.c3.delivery.raw_commits_while_active, audit.c3.delivery.raw_pushes_while_active });

    try writer.writeAll("## Decision effects\n\n");
    try writer.writeAll("- Controller-derived historical decision projection: pending in decision normalization slice.\n\n");

    try writer.writeAll("## Violations and exact evidence\n\n");
    const strict_failure = hasStrictReviewCompilerFailure(audit);
    try writer.print("- strict_failure: {any}\n- stale_mrpc: {d}\n- holdout_missing: {d}\n- commit_or_push_bypass: {d}\n\n", .{ strict_failure, audit.c3.compliance.stale_mrpc, audit.c3.compliance.holdout_missing, audit.c3.compliance.commit_or_push_bypass });

    try writer.writeAll("## Remaining source gaps\n\n");
    try writer.writeAll("- Structured AC/RB/RAP/CEX/CEB/PHI rows are parsed by the shared scanner but not yet registered as query datasets in this slice.\n\n");
    try writer.writeAll("SINGLE MOST IMPORTANT REMAINING BLIND SPOT:\ncontroller artifact roots are accepted in the command surface, but full AC/RB/RAP/CEX/CEB/PHI lineage projection is completed in the dataset/decision slices, not this review-compiler slice.\n");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn writeReviewCompilerAuditMarkdown(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, out_path: ?[]const u8) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.writeAll("# seq review-compiler-audit\n\n```yaml\nreview_compiler_audit:\n");
    try writeReviewCompilerAuditYamlBody(writer, audit, "  ");
    try writer.writeAll("```\n");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn writeReviewCompilerAuditYamlBody(writer: anytype, audit: ReviewCompilerAudit, indent: []const u8) !void {
    const protocol = audit.outputProtocol();
    try writer.print("{s}protocol: {s}\n", .{ indent, protocol.label() });
    if (reviewCompilerProtocolIsMBK(protocol)) {
        try writeReviewCompilerMBKYamlBody(writer, audit.mbk, indent);
        return;
    }
    try writer.print("{s}denominator:\n", .{indent});
    try writer.print("{s}  candidate_sessions: {d}\n{s}  true_resolve_sessions: {d}\n{s}  clean_review_sessions: {d}\n{s}  isolated_waiver_sessions: {d}\n{s}  c3_required_sessions: {d}\n{s}  c3_entered_sessions: {d}\n{s}  c3_closed_sessions: {d}\n", .{ indent, audit.denominator.candidate_sessions, indent, audit.denominator.true_resolve_sessions, indent, audit.denominator.clean_review_sessions, indent, audit.denominator.isolated_waiver_sessions, indent, audit.denominator.c3_required_sessions, indent, audit.denominator.c3_entered_sessions, indent, audit.denominator.c3_closed_sessions });
    try writer.print("{s}  exclusions:", .{indent});
    if (audit.denominator.exclusions.items.len == 0) {
        try writer.writeAll(" []\n");
    } else {
        try writer.writeByte('\n');
        for (audit.denominator.exclusions.items) |item| {
            try writer.print("{s}    - session_id: ", .{indent});
            if (item.session_id) |id| try writeYamlInlineString(writer, id) else try writer.writeAll("null");
            try writer.writeByte('\n');
            try writer.print("{s}      path: ", .{indent});
            try writeYamlInlineString(writer, item.path);
            try writer.writeByte('\n');
            try writer.print("{s}      reason: ", .{indent});
            try writeYamlInlineString(writer, item.reason);
            try writer.writeByte('\n');
        }
    }
    if (reviewCompilerProtocolIncludesC3(protocol)) try writeReviewCompilerIncludedSessionsYaml(writer, audit.denominator.included_sessions.items, indent);
    if (reviewCompilerProtocolIncludesC3(protocol)) try writeReviewCompilerC3YamlBody(writer, audit, indent);
    try writeReviewCompilerLegacyYamlBody(writer, audit.legacy_cleanroom, indent);
}

fn writeReviewCompilerMBKYamlBody(writer: anytype, mbk: ReviewCompilerAudit.MBK, indent: []const u8) !void {
    try writer.print("{s}denominator:\n", .{indent});
    try writer.print("{s}  candidate_sessions: {d}\n{s}  true_resolve_sessions: {d}\n{s}  clean_review_sessions: {d}\n{s}  isolated_conformance_sessions: {d}\n{s}  material_kernel_required_sessions: {d}\n{s}  kernel_campaign_entered_sessions: {d}\n{s}  kernel_accepted_sessions: {d}\n{s}  tuple_closed_sessions: {d}\n{s}  terminal_closed_sessions: {d}\n", .{ indent, mbk.denominator.candidate_sessions, indent, mbk.denominator.true_resolve_sessions, indent, mbk.denominator.clean_review_sessions, indent, mbk.denominator.isolated_conformance_sessions, indent, mbk.denominator.material_kernel_required_sessions, indent, mbk.denominator.kernel_campaign_entered_sessions, indent, mbk.denominator.kernel_accepted_sessions, indent, mbk.denominator.tuple_closed_sessions, indent, mbk.denominator.terminal_closed_sessions });
    try writer.print("{s}  exclusions:", .{indent});
    if (mbk.denominator.exclusions.items.len == 0) {
        try writer.writeAll(" []\n");
    } else {
        try writer.writeByte('\n');
        for (mbk.denominator.exclusions.items) |item| {
            try writer.print("{s}    - session_id: ", .{indent});
            if (item.session_id) |id| try writeYamlInlineString(writer, id) else try writer.writeAll("null");
            try writer.writeByte('\n');
            try writer.print("{s}      path: ", .{indent});
            try writeYamlInlineString(writer, item.path);
            try writer.writeByte('\n');
            try writer.print("{s}      reason: ", .{indent});
            try writeYamlInlineString(writer, item.reason);
            try writer.writeByte('\n');
        }
    }

    try writer.print("{s}campaigns:\n{s}  campaign_ids: {d}\n{s}  fixed_base_pass: {d}\n{s}  base_reset_violations: {d}\n{s}  review_ready_baselines: {d}\n{s}  closure_attempts: {d}\n{s}  prior_closure_head_used_as_new_base: {d}\n{s}  rebaseline_decisions: {d}\n", .{ indent, indent, mbk.campaigns.campaign_ids, indent, mbk.campaigns.fixed_base_pass, indent, mbk.campaigns.base_reset_violations, indent, mbk.campaigns.review_ready_baselines, indent, mbk.campaigns.closure_attempts, indent, mbk.campaigns.prior_closure_head_used_as_new_base, indent, mbk.campaigns.rebaseline_decisions });
    try writer.print("{s}observations:\n{s}  raw_findings: {d}\n{s}  branch_liabilities: {d}\n{s}  additional_witnesses: {d}\n{s}  missing_distinctions: {d}\n{s}  scope_expansions: {d}\n{s}  adjacent_followups: {d}\n{s}  preferences_rejected: {d}\n", .{ indent, indent, mbk.observations.raw_findings, indent, mbk.observations.branch_liabilities, indent, mbk.observations.additional_witnesses, indent, mbk.observations.missing_distinctions, indent, mbk.observations.scope_expansions, indent, mbk.observations.adjacent_followups, indent, mbk.observations.preferences_rejected });
    try writer.print("{s}kernel:\n{s}  authorities: {d}\n{s}  observable_state_classes: {d}\n{s}  transitions: {d}\n{s}  laws: {d}\n{s}  local_surface_families: {d}\n{s}  governing_law_families: {d}\n{s}  findings_per_law: {d}\n{s}  distinctions_merged: {d}\n{s}  unwitnessed_distinctions: {d}\n{s}  exact_quotients: {d}\n{s}  witnessed_quotients: {d}\n", .{ indent, indent, mbk.kernel.authorities, indent, mbk.kernel.observable_state_classes, indent, mbk.kernel.transitions, indent, mbk.kernel.laws, indent, mbk.kernel.local_surface_families, indent, mbk.kernel.governing_law_families, indent, mbk.kernel.findings_per_law, indent, mbk.kernel.distinctions_merged, indent, mbk.kernel.unwitnessed_distinctions, indent, mbk.kernel.exact_quotients, indent, mbk.kernel.witnessed_quotients });
    try writer.print("{s}realization:\n{s}  designs_considered: {d}\n{s}  route_classes: {d}\n{s}  selected_designs: {d}\n{s}  realization_recompilations: {d}\n{s}  realizations_from_campaign_base: {d}\n{s}  realizations_from_prior_head: {d}\n{s}  surfaces_retired: {d}\n{s}  orphan_code_constructs: {d}\n{s}  duplicate_realizations: {d}\n", .{ indent, indent, mbk.realization.designs_considered, indent, mbk.realization.route_classes, indent, mbk.realization.selected_designs, indent, mbk.realization.realization_recompilations, indent, mbk.realization.realizations_from_campaign_base, indent, mbk.realization.realizations_from_prior_head, indent, mbk.realization.surfaces_retired, indent, mbk.realization.orphan_code_constructs, indent, mbk.realization.duplicate_realizations });

    try writer.print("{s}semantic_surface:\n{s}  review_ready_baseline:\n", .{ indent, indent });
    try writeMBKSurfaceSnapshotYaml(writer, mbk.semantic_surface.review_ready_baseline, indent, "    ");
    try writer.print("{s}  terminal:\n", .{indent});
    try writeMBKSurfaceSnapshotYaml(writer, mbk.semantic_surface.terminal, indent, "    ");
    try writer.print("{s}  delta:\n", .{indent});
    try writeMBKSurfaceSnapshotYaml(writer, mbk.semantic_surface.delta, indent, "    ");
    try writer.print("{s}  hard_dimension_increases: []\n{s}  hard_dimension_increase_events: {d}\n{s}  total_description_nonincrease_pass: {any}\n{s}  approved_rebaselines: {d}\n{s}  silent_scope_expansions: {d}\n", .{ indent, indent, mbk.semantic_surface.hard_dimension_increases, indent, mbk.semantic_surface.total_description_nonincrease_pass, indent, mbk.semantic_surface.approved_rebaselines, indent, mbk.semantic_surface.silent_scope_expansions });
    try writer.print("{s}git_tree_metrics:\n{s}  files_changed: {d}\n{s}  insertions: {d}\n{s}  deletions: {d}\n{s}  net_lines: {d}\n", .{ indent, indent, mbk.git_tree_metrics.files_changed, indent, mbk.git_tree_metrics.insertions, indent, mbk.git_tree_metrics.deletions, indent, mbk.git_tree_metrics.net_lines });

    try writer.print("{s}proof:\n{s}  kernel_laws: {d}\n{s}  proof_families: {d}\n{s}  wound_specific_tests: {d}\n{s}  tests_merged_or_retired: {d}\n{s}  property_or_state_machine_families: {d}\n{s}  unmapped_proof_actions: {d}\n{s}  proof_runs: {d}\n{s}  stale_proof: {d}\n", .{ indent, indent, mbk.proof.kernel_laws, indent, mbk.proof.proof_families, indent, mbk.proof.wound_specific_tests, indent, mbk.proof.tests_merged_or_retired, indent, mbk.proof.property_or_state_machine_families, indent, mbk.proof.unmapped_proof_actions, indent, mbk.proof.proof_runs, indent, mbk.proof.stale_proof });
    try writer.print("{s}controller:\n{s}  physical_apply_events: {d}\n{s}  state_only_apply_violations: {d}\n{s}  physical_commits: {d}\n{s}  state_only_commit_violations: {d}\n{s}  physical_pushes: {d}\n{s}  state_only_push_violations: {d}\n{s}  raw_delivery_mutations_while_active: {d}\n{s}  backup_refs_created: {d}\n", .{ indent, indent, mbk.controller.physical_apply_events, indent, mbk.controller.state_only_apply_violations, indent, mbk.controller.physical_commits, indent, mbk.controller.state_only_commit_violations, indent, mbk.controller.physical_pushes, indent, mbk.controller.state_only_push_violations, indent, mbk.controller.raw_delivery_mutations_while_active, indent, mbk.controller.backup_refs_created });
    try writer.print("{s}closure:\n{s}  kernel_accepted: {d}\n{s}  conformance_closed_for_tuple: {d}\n{s}  terminal_closed: {d}\n{s}  unqualified_complete_claims: {d}\n{s}  tuple_receipts_missing_horizon: {d}\n{s}  post_push_reopens: {d}\n{s}  terminal_closure_with_new_evidence: {d}\n", .{ indent, indent, mbk.closure.kernel_accepted, indent, mbk.closure.conformance_closed_for_tuple, indent, mbk.closure.terminal_closed, indent, mbk.closure.unqualified_complete_claims, indent, mbk.closure.tuple_receipts_missing_horizon, indent, mbk.closure.post_push_reopens, indent, mbk.closure.terminal_closure_with_new_evidence });

    try writer.print("{s}key_metrics:\n", .{indent});
    try writeYamlRatio(writer, indent, "  finding_compression", mbk.observations.branch_liabilities, mbk.kernel.governing_law_families, "governing_law_families_zero");
    try writeYamlRatio(writer, indent, "  semantic_realization_density", mbk.kernel.governing_law_families, mbk.semantic_surface.terminal.realization_surface, "terminal_realization_surface_zero");
    try writeYamlRatio(writer, indent, "  proof_compression", mbk.observations.raw_findings, mbk.proof.proof_families, "proof_families_zero");
    try writer.print("{s}  review_growth: {d}\n", .{ indent, @as(i64, @intCast(mbk.semantic_surface.terminal.semantic_surface)) - @as(i64, @intCast(mbk.semantic_surface.review_ready_baseline.semantic_surface)) });
    try writeYamlRatio(writer, indent, "  base_discipline", mbk.campaigns.fixed_base_pass, mbk.denominator.material_kernel_required_sessions, "material_kernel_required_sessions_zero");

    try writer.print("{s}evidence_ledger:", .{indent});
    if (mbk.evidence_ledger.items.len == 0) {
        try writer.writeAll(" []\n");
    } else {
        try writer.writeByte('\n');
        for (mbk.evidence_ledger.items) |item| {
            try writer.print("{s}  - session_id: ", .{indent});
            if (item.session_id) |id| try writeYamlInlineString(writer, id) else try writer.writeAll("null");
            try writer.writeByte('\n');
            try writer.print("{s}    event: ", .{indent});
            try writeYamlInlineString(writer, item.event);
            try writer.writeByte('\n');
            try writer.print("{s}    source: ", .{indent});
            try writeYamlInlineString(writer, item.source);
            try writer.writeByte('\n');
            try writer.print("{s}    snippet: ", .{indent});
            try writeYamlInlineString(writer, item.snippet);
            try writer.writeByte('\n');
        }
    }
}

fn writeMBKSurfaceSnapshotYaml(writer: anytype, snapshot: ReviewCompilerAudit.SurfaceSnapshot, indent: []const u8, extra: []const u8) !void {
    try writer.print("{s}{s}semantic_surface: {d}\n{s}{s}governing_laws: {d}\n{s}{s}realization_surface: {d}\n{s}{s}proof_families: {d}\n", .{ indent, extra, snapshot.semantic_surface, indent, extra, snapshot.governing_laws, indent, extra, snapshot.realization_surface, indent, extra, snapshot.proof_families });
}

fn writeReviewCompilerC3YamlBody(writer: anytype, audit: ReviewCompilerAudit, indent: []const u8) !void {
    try writer.print("{s}controller:\n{s}  begin_events: {d}\n{s}  state_files: {d}\n{s}  mrpc_apply_certified: {d}\n{s}  mrpc_final_certified: {d}\n{s}  mrpc_committed: {d}\n{s}  mrpc_pushed: {d}\n{s}  mrpc_closed: {d}\n", .{ indent, indent, audit.c3.controller.begin_events, indent, audit.c3.controller.state_files, indent, audit.c3.controller.mrpc_apply_certified, indent, audit.c3.controller.mrpc_final_certified, indent, audit.c3.controller.mrpc_committed, indent, audit.c3.controller.mrpc_pushed, indent, audit.c3.controller.mrpc_closed });
    try writer.print("{s}counterexamples:\n{s}  raw_findings: {d}\n{s}  branch_liabilities: {d}\n{s}  non_branch_liabilities: {d}\n{s}  independent_families: {d}\n{s}  subsumed_findings: {d}\n", .{ indent, indent, audit.c3.counterexamples.raw_findings, indent, audit.c3.counterexamples.branch_liabilities, indent, audit.c3.counterexamples.non_branch_liabilities, indent, audit.c3.counterexamples.independent_families, indent, audit.c3.counterexamples.subsumed_findings });
    try writeYamlRatio(writer, indent, "  compression_ratio", audit.c3.counterexamples.branch_liabilities, audit.c3.counterexamples.independent_families, "independent_families_zero");
    try writer.print("{s}tournament:\n{s}  candidate_records: {d}\n{s}  distinct_route_classes: {d}\n{s}  invalid_candidates: {d}\n{s}  active_negative_routes_excluded: {d}\n{s}  selected_candidates: {d}\n{s}  tournament_waivers: {d}\n{s}  single_candidate_material_violations: {d}\n", .{ indent, indent, audit.c3.tournament.candidate_records, indent, audit.c3.tournament.distinct_route_classes, indent, audit.c3.tournament.invalid_candidates, indent, audit.c3.tournament.active_negative_routes_excluded, indent, audit.c3.tournament.selected_candidates, indent, audit.c3.tournament.tournament_waivers, indent, audit.c3.tournament.single_candidate_material_violations });
    try writeYamlRatio(writer, indent, "  candidate_discard_ratio", audit.c3.tournament.candidate_records -| audit.c3.tournament.selected_candidates, audit.c3.tournament.candidate_records, "candidate_records_zero");
    try writer.print("{s}semantic_cost:\n{s}  selected_cost_vectors: []\n{s}  selected_route_classes: {{}}\n{s}  global_optimality_overclaims: {d}\n", .{ indent, indent, indent, indent, audit.c3.semantic_cost.global_optimality_overclaims });
    try writeYamlRatio(writer, indent, "  semantic_delivery_efficiency", audit.c3.counterexamples.independent_families, audit.c3.semantic_cost.selected_semantic_cost, "selected_semantic_cost_zero");
    try writer.print("{s}ablation:\n{s}  edit_atoms_tested: {d}\n{s}  removed: {d}\n{s}  survived: {d}\n{s}  orphan_edit_atoms: {d}\n{s}  one_minimal_passes: {d}\n{s}  one_minimal_failures: {d}\n", .{ indent, indent, audit.c3.ablation.edit_atoms_tested, indent, audit.c3.ablation.removed, indent, audit.c3.ablation.survived, indent, audit.c3.ablation.orphan_edit_atoms, indent, audit.c3.ablation.one_minimal_passes, indent, audit.c3.ablation.one_minimal_failures });
    try writeYamlRatio(writer, indent, "  ablation_removal_ratio", audit.c3.ablation.removed, audit.c3.ablation.edit_atoms_tested, "edit_atoms_tested_zero");
    try writer.print("{s}lab_vs_delivery:\n{s}  lab_apply_patch_calls: {d}\n{s}  lab_commits: {d}\n{s}  candidate_surface_generated: {d}\n{s}  candidate_surface_discarded: {d}\n{s}  delivery_apply_events: {d}\n{s}  delivery_surface_shipped: {d}\n{s}  raw_delivery_mutations_while_frozen: {d}\n", .{ indent, indent, audit.c3.lab_vs_delivery.lab_apply_patch_calls, indent, audit.c3.lab_vs_delivery.lab_commits, indent, audit.c3.lab_vs_delivery.candidate_surface_generated, indent, audit.c3.lab_vs_delivery.candidate_surface_discarded, indent, audit.c3.lab_vs_delivery.delivery_apply_events, indent, audit.c3.lab_vs_delivery.delivery_surface_shipped, indent, audit.c3.lab_vs_delivery.raw_delivery_mutations_while_frozen });
    try writer.print("{s}holdout:\n{s}  candidate_holdouts: {d}\n{s}  delivery_holdouts: {d}\n{s}  new_counterexamples: {d}\n{s}  invalidations: {d}\n{s}  recompilations: {d}\n{s}  adjacent_followups: {d}\n", .{ indent, indent, audit.c3.holdout.candidate_holdouts, indent, audit.c3.holdout.delivery_holdouts, indent, audit.c3.holdout.new_counterexamples, indent, audit.c3.holdout.invalidations, indent, audit.c3.holdout.recompilations, indent, audit.c3.holdout.adjacent_followups });
    try writer.print("{s}delivery:\n{s}  controller_commits: {d}\n{s}  raw_commits_while_active: {d}\n{s}  controller_pushes: {d}\n{s}  raw_pushes_while_active: {d}\n{s}  closed_runs: {d}\n", .{ indent, indent, audit.c3.delivery.controller_commits, indent, audit.c3.delivery.raw_commits_while_active, indent, audit.c3.delivery.controller_pushes, indent, audit.c3.delivery.raw_pushes_while_active, indent, audit.c3.delivery.closed_runs });
    try writeYamlRatio(writer, indent, "  controller_adoption", audit.denominator.c3_entered_sessions, audit.denominator.c3_required_sessions, "c3_required_sessions_zero");
    try writeReviewCompilerClosureCompressionYaml(writer, audit.c3.closure_compression, indent);
    try writer.print("{s}compliance:\n{s}  basis_missing: {d}\n{s}  tournament_missing: {d}\n{s}  ablation_missing: {d}\n{s}  proof_missing: {d}\n{s}  holdout_missing: {d}\n{s}  stale_mrpc: {d}\n{s}  direct_review_to_delivery_mutation: {d}\n{s}  commit_or_push_bypass: {d}\n", .{ indent, indent, audit.c3.compliance.basis_missing, indent, audit.c3.compliance.tournament_missing, indent, audit.c3.compliance.ablation_missing, indent, audit.c3.compliance.proof_missing, indent, audit.c3.compliance.holdout_missing, indent, audit.c3.compliance.stale_mrpc, indent, audit.c3.compliance.direct_review_to_delivery_mutation, indent, audit.c3.compliance.commit_or_push_bypass });
}

fn writeReviewCompilerClosureCompressionYaml(writer: anytype, closure: ReviewCompilerAudit.ClosureCompression, indent: []const u8) !void {
    const missing = closure.missing_compression_evidence;
    try writer.print("{s}closure_compression:\n{s}  summary_state: {s}\n{s}  closed_total: {d}\n{s}  closed_compressed: {d}\n{s}  closed_uncompressed: {d}\n{s}  blocked: {d}\n{s}  compression_not_required: {d}\n", .{ indent, indent, closure.summaryState().label(), indent, closure.closed_total, indent, closure.closed_compressed, indent, closure.closed_uncompressed, indent, closure.blocked, indent, closure.compression_not_required });
    try writer.print("{s}  missing_compression_evidence:\n{s}    basis: {d}\n{s}    tournament: {d}\n{s}    ablation: {d}\n{s}    proof: {d}\n{s}    holdout: {d}\n{s}    permit: {d}\n{s}    stale_mrpc: {d}\n{s}    direct_review_to_delivery_mutation: {d}\n{s}    commit_or_push_bypass: {d}\n", .{ indent, indent, missing.basis, indent, missing.tournament, indent, missing.ablation, indent, missing.proof, indent, missing.holdout, indent, missing.permit, indent, missing.stale_mrpc, indent, missing.direct_review_to_delivery_mutation, indent, missing.commit_or_push_bypass });
}

fn writeReviewCompilerIncludedSessionsYaml(writer: anytype, rows: []const ReviewCompilerAudit.IncludedSession, indent: []const u8) !void {
    try writer.print("{s}  included_sessions:", .{indent});
    if (rows.len == 0) {
        try writer.writeAll(" []\n");
        return;
    }
    try writer.writeByte('\n');
    for (rows) |row| {
        try writer.print("{s}    - session_id: ", .{indent});
        if (row.session_id) |id| try writeYamlInlineString(writer, id) else try writer.writeAll("null");
        try writer.writeByte('\n');
        try writer.print("{s}      path: ", .{indent});
        try writeYamlInlineString(writer, row.path);
        try writer.writeByte('\n');
        try writer.print("{s}      protocol: ", .{indent});
        try writeYamlInlineString(writer, row.protocol);
        try writer.writeByte('\n');
        try writer.print("{s}      classification: ", .{indent});
        try writeYamlInlineString(writer, row.classification);
        try writer.writeByte('\n');
        try writer.print("{s}      c3_required: {any}\n{s}      c3_entered: {any}\n{s}      c3_closed: {any}\n{s}      evidence:\n", .{ indent, row.c3_required, indent, row.c3_entered, indent, row.c3_closed, indent });
        try writeReviewCompilerSignalEvidenceYaml(writer, "true_c3", row.evidence.true_c3, indent, "        ");
        try writeReviewCompilerSignalEvidenceYaml(writer, "required", row.evidence.required, indent, "        ");
        try writeReviewCompilerSignalEvidenceYaml(writer, "entered", row.evidence.entered, indent, "        ");
        try writeReviewCompilerSignalEvidenceYaml(writer, "closed", row.evidence.closed, indent, "        ");
        try writeReviewCompilerClosureEvidenceYaml(writer, row.evidence.closure_compression, indent, "        ");
    }
}

fn writeReviewCompilerSignalEvidenceYaml(writer: anytype, name: []const u8, evidence: ReviewCompilerAudit.SignalEvidenceRef, indent: []const u8, extra: []const u8) !void {
    try writer.print("{s}{s}{s}:\n{s}{s}  present: {any}\n{s}{s}  source: ", .{ indent, extra, name, indent, extra, evidence.present, indent, extra });
    try writeYamlInlineString(writer, evidence.source);
    try writer.writeByte('\n');
    try writer.print("{s}{s}  timestamp: ", .{ indent, extra });
    if (evidence.timestamp) |timestamp| try writeYamlInlineString(writer, timestamp) else try writer.writeAll("null");
    try writer.writeByte('\n');
    try writer.print("{s}{s}  snippet: ", .{ indent, extra });
    if (evidence.snippet) |snippet| try writeYamlInlineString(writer, snippet) else try writer.writeAll("null");
    try writer.writeByte('\n');
    try writer.print("{s}{s}  reason: ", .{ indent, extra });
    try writeYamlInlineString(writer, evidence.reason);
    try writer.writeByte('\n');
}

fn writeReviewCompilerClosureEvidenceYaml(writer: anytype, evidence: ReviewCompilerAudit.ClosureCompressionEvidence, indent: []const u8, extra: []const u8) !void {
    const missing = evidence.missing_compression_evidence;
    try writer.print("{s}{s}closure_compression:\n{s}{s}  summary_state: {s}\n{s}{s}  reason: ", .{ indent, extra, indent, extra, evidence.summary_state.label(), indent, extra });
    try writeYamlInlineString(writer, evidence.reason);
    try writer.writeByte('\n');
    try writer.print("{s}{s}  missing_compression_evidence:\n{s}{s}    basis: {d}\n{s}{s}    tournament: {d}\n{s}{s}    ablation: {d}\n{s}{s}    proof: {d}\n{s}{s}    holdout: {d}\n{s}{s}    permit: {d}\n{s}{s}    stale_mrpc: {d}\n{s}{s}    direct_review_to_delivery_mutation: {d}\n{s}{s}    commit_or_push_bypass: {d}\n", .{ indent, extra, indent, extra, missing.basis, indent, extra, missing.tournament, indent, extra, missing.ablation, indent, extra, missing.proof, indent, extra, missing.holdout, indent, extra, missing.permit, indent, extra, missing.stale_mrpc, indent, extra, missing.direct_review_to_delivery_mutation, indent, extra, missing.commit_or_push_bypass });
}

fn writeReviewCompilerLegacyYamlBody(writer: anytype, legacy: ReviewCompilerAudit.LegacyCleanroom, indent: []const u8) !void {
    try writer.print("{s}legacy_cleanroom:\n", .{indent});
    try writer.print("{s}  cleanroom:\n{s}    delivery_freezes: {d}\n{s}    counterexample_contracts: {d}\n{s}    delivery_recipes: {d}\n{s}    ablation_certificates: {d}\n{s}    compiled_delivery_permits: {d}\n", .{ indent, indent, legacy.cleanroom.delivery_freezes, indent, legacy.cleanroom.counterexample_contracts, indent, legacy.cleanroom.delivery_recipes, indent, legacy.cleanroom.ablation_certificates, indent, legacy.cleanroom.compiled_delivery_permits });
    try writer.print("{s}  lab_vs_delivery:\n{s}    lab_apply_patch_calls: {d}\n{s}    lab_commits: {d}\n{s}    delivery_apply_patch_calls: {d}\n{s}    delivery_commits: {d}\n{s}    lab_surface_added: {d}\n{s}    lab_surface_discarded: {d}\n{s}    delivery_surface_shipped: {d}\n", .{ indent, indent, legacy.lab_vs_delivery.lab_apply_patch_calls, indent, legacy.lab_vs_delivery.lab_commits, indent, legacy.lab_vs_delivery.delivery_apply_patch_calls, indent, legacy.lab_vs_delivery.delivery_commits, indent, legacy.lab_vs_delivery.lab_surface_added, indent, legacy.lab_vs_delivery.lab_surface_discarded, indent, legacy.lab_vs_delivery.delivery_surface_shipped });
    try writer.print("{s}  liability:\n{s}    branch_liabilities: {d}\n{s}    non_branch_liabilities: {d}\n{s}    followups_captured: {d}\n{s}    non_branch_liabilities_mutated: {d}\n", .{ indent, indent, legacy.liability.branch_liabilities, indent, legacy.liability.non_branch_liabilities, indent, legacy.liability.followups_captured, indent, legacy.liability.non_branch_liabilities_mutated });
    try writer.print("{s}  recipe:\n{s}    falsified_routes_excluded: {d}\n{s}    surfaces_to_retire: {d}\n{s}    permitted_new_surface: {d}\n", .{ indent, indent, legacy.recipe.falsified_routes_excluded, indent, legacy.recipe.surfaces_to_retire, indent, legacy.recipe.permitted_new_surface });
    try writer.print("{s}  ablation:\n{s}    surfaces_removed: {d}\n{s}    surfaces_survived: {d}\n{s}    tests_merged_or_retired: {d}\n", .{ indent, indent, legacy.ablation.surfaces_removed, indent, legacy.ablation.surfaces_survived, indent, legacy.ablation.tests_merged_or_retired });
    try writer.print("{s}  review_horizon:\n{s}    initial_broad_reviews: {d}\n{s}    targeted_reviews: {d}\n{s}    final_holdout_reviews: {d}\n{s}    holdout_findings_added_to_scope: {d}\n{s}    holdout_followups_captured: {d}\n", .{ indent, indent, legacy.review_horizon.initial_broad_reviews, indent, legacy.review_horizon.targeted_reviews, indent, legacy.review_horizon.final_holdout_reviews, indent, legacy.review_horizon.holdout_findings_added_to_scope, indent, legacy.review_horizon.holdout_followups_captured });
    try writer.print("{s}  compliance:\n{s}    delivery_mutations_before_recipe: {d}\n{s}    review_derived_delivery_patches: {d}\n{s}    missing_contract: {d}\n{s}    missing_recipe: {d}\n{s}    missing_ablation: {d}\n", .{ indent, indent, legacy.compliance.delivery_mutations_before_recipe, indent, legacy.compliance.review_derived_delivery_patches, indent, legacy.compliance.missing_contract, indent, legacy.compliance.missing_recipe, indent, legacy.compliance.missing_ablation });
}

fn writeYamlRatio(writer: anytype, indent: []const u8, name: []const u8, numerator: usize, denominator: usize, zero_reason: []const u8) !void {
    if (denominator == 0) {
        try writer.print("{s}{s}: null\n{s}{s}_reason: ", .{ indent, name, indent, name });
        try writeYamlInlineString(writer, zero_reason);
        try writer.writeByte('\n');
        return;
    }
    const value = @as(f64, @floatFromInt(numerator)) / @as(f64, @floatFromInt(denominator));
    try writer.print("{s}{s}: {d:.6}\n", .{ indent, name, value });
}

fn writeYamlInlineString(writer: anytype, value: []const u8) !void {
    try writer.writeByte('"');
    for (value) |c| {
        switch (c) {
            '\\' => try writer.writeAll("\\\\"),
            '"' => try writer.writeAll("\\\""),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            else => try writer.writeByte(c),
        }
    }
    try writer.writeByte('"');
}

fn writeReviewCompilerAuditJson(allocator: std.mem.Allocator, audit: ReviewCompilerAudit, out_path: ?[]const u8) !void {
    var writer_alloc = std.Io.Writer.Allocating.init(allocator);
    defer writer_alloc.deinit();
    const writer = &writer_alloc.writer;

    try writer.writeAll("{\n  \"review_compiler_audit\": {\n");
    try writer.print("    \"protocol\": \"{s}\",\n", .{audit.outputProtocol().label()});
    try writeReviewCompilerAuthoritySummaryJsonFields(writer, audit);
    if (reviewCompilerProtocolIsMBK(audit.outputProtocol())) {
        try writeReviewCompilerMBKJsonFields(writer, audit.mbk);
        try writer.writeAll("  }\n}\n");

        const rendered = try writer_alloc.toOwnedSlice();
        defer allocator.free(rendered);
        if (out_path) |path| try ensureParentDir(path);
        try writeTextOutput(rendered, out_path);
        return;
    }
    try writer.print("    \"denominator\": {{ \"candidate_sessions\": {d}, \"true_resolve_sessions\": {d}, \"authoritative_sessions\": {d}, \"declared_uncontrolled_sessions\": {d}, \"incidental_sessions\": {d}, \"ambiguous_sessions\": {d}, \"excluded_sessions\": {d}, \"clean_review_sessions\": {d}, \"isolated_waiver_sessions\": {d}, \"c3_required_sessions\": {d}, \"c3_entered_sessions\": {d}, \"c3_closed_sessions\": {d}, \"exclusions\": [", .{ audit.denominator.candidate_sessions, audit.denominator.true_resolve_sessions, audit.denominator.authoritative_sessions, audit.denominator.declared_uncontrolled_sessions, audit.denominator.incidental_sessions, audit.denominator.ambiguous_sessions, audit.denominator.excluded_sessions, audit.denominator.clean_review_sessions, audit.denominator.isolated_waiver_sessions, audit.denominator.c3_required_sessions, audit.denominator.c3_entered_sessions, audit.denominator.c3_closed_sessions });
    for (audit.denominator.exclusions.items, 0..) |item, idx| {
        if (idx > 0) try writer.writeAll(", ");
        try writer.writeAll("{ \"session_id\": ");
        if (item.session_id) |id| try output.writeJsonString(writer, id) else try writer.writeAll("null");
        try writer.writeAll(", \"path\": ");
        try output.writeJsonString(writer, item.path);
        try writer.writeAll(", \"reason\": ");
        try output.writeJsonString(writer, item.reason);
        try writer.writeAll(", \"governance\": ");
        try output.writeJsonString(writer, item.governance);
        try writer.print(", \"delivery_closed\": {any}", .{item.delivery_closed});
        try writer.writeAll(" }");
    }
    try writer.writeAll("], \"included_sessions\": [");
    for (audit.denominator.included_sessions.items, 0..) |item, idx| {
        if (idx > 0) try writer.writeAll(", ");
        try writeReviewCompilerIncludedSessionJson(writer, item);
    }
    try writer.writeAll("] },\n");
    const protocol = audit.outputProtocol();
    if (reviewCompilerProtocolIncludesC3(protocol)) {
        try writer.print("    \"controller\": {{ \"begin_events\": {d}, \"state_files\": {d}, \"mrpc_apply_certified\": {d}, \"mrpc_final_certified\": {d}, \"mrpc_committed\": {d}, \"mrpc_pushed\": {d}, \"mrpc_closed\": {d} }},\n", .{ audit.c3.controller.begin_events, audit.c3.controller.state_files, audit.c3.controller.mrpc_apply_certified, audit.c3.controller.mrpc_final_certified, audit.c3.controller.mrpc_committed, audit.c3.controller.mrpc_pushed, audit.c3.controller.mrpc_closed });
        try writer.print("    \"counterexamples\": {{ \"raw_findings\": {d}, \"branch_liabilities\": {d}, \"non_branch_liabilities\": {d}, \"independent_families\": {d}, \"subsumed_findings\": {d}, ", .{ audit.c3.counterexamples.raw_findings, audit.c3.counterexamples.branch_liabilities, audit.c3.counterexamples.non_branch_liabilities, audit.c3.counterexamples.independent_families, audit.c3.counterexamples.subsumed_findings });
        try writeJsonRatioFields(writer, "compression_ratio", audit.c3.counterexamples.branch_liabilities, audit.c3.counterexamples.independent_families, "independent_families_zero");
        try writer.writeAll(" },\n");
        try writer.print("    \"tournament\": {{ \"candidate_records\": {d}, \"distinct_route_classes\": {d}, \"invalid_candidates\": {d}, \"active_negative_routes_excluded\": {d}, \"selected_candidates\": {d}, \"tournament_waivers\": {d}, \"single_candidate_material_violations\": {d}, ", .{ audit.c3.tournament.candidate_records, audit.c3.tournament.distinct_route_classes, audit.c3.tournament.invalid_candidates, audit.c3.tournament.active_negative_routes_excluded, audit.c3.tournament.selected_candidates, audit.c3.tournament.tournament_waivers, audit.c3.tournament.single_candidate_material_violations });
        try writeJsonRatioFields(writer, "candidate_discard_ratio", audit.c3.tournament.candidate_records -| audit.c3.tournament.selected_candidates, audit.c3.tournament.candidate_records, "candidate_records_zero");
        try writer.writeAll(" },\n");
        try writer.print("    \"semantic_cost\": {{ \"selected_cost_vectors\": [], \"selected_route_classes\": {{}}, \"global_optimality_overclaims\": {d}, ", .{audit.c3.semantic_cost.global_optimality_overclaims});
        try writeJsonRatioFields(writer, "semantic_delivery_efficiency", audit.c3.counterexamples.independent_families, audit.c3.semantic_cost.selected_semantic_cost, "selected_semantic_cost_zero");
        try writer.writeAll(" },\n");
        try writer.print("    \"ablation\": {{ \"edit_atoms_tested\": {d}, \"removed\": {d}, \"survived\": {d}, \"orphan_edit_atoms\": {d}, \"one_minimal_passes\": {d}, \"one_minimal_failures\": {d}, ", .{ audit.c3.ablation.edit_atoms_tested, audit.c3.ablation.removed, audit.c3.ablation.survived, audit.c3.ablation.orphan_edit_atoms, audit.c3.ablation.one_minimal_passes, audit.c3.ablation.one_minimal_failures });
        try writeJsonRatioFields(writer, "ablation_removal_ratio", audit.c3.ablation.removed, audit.c3.ablation.edit_atoms_tested, "edit_atoms_tested_zero");
        try writer.writeAll(" },\n");
        try writer.print("    \"lab_vs_delivery\": {{ \"lab_apply_patch_calls\": {d}, \"lab_commits\": {d}, \"candidate_surface_generated\": {d}, \"candidate_surface_discarded\": {d}, \"delivery_apply_events\": {d}, \"delivery_surface_shipped\": {d}, \"raw_delivery_mutations_while_frozen\": {d} }},\n", .{ audit.c3.lab_vs_delivery.lab_apply_patch_calls, audit.c3.lab_vs_delivery.lab_commits, audit.c3.lab_vs_delivery.candidate_surface_generated, audit.c3.lab_vs_delivery.candidate_surface_discarded, audit.c3.lab_vs_delivery.delivery_apply_events, audit.c3.lab_vs_delivery.delivery_surface_shipped, audit.c3.lab_vs_delivery.raw_delivery_mutations_while_frozen });
        try writer.print("    \"holdout\": {{ \"candidate_holdouts\": {d}, \"delivery_holdouts\": {d}, \"new_counterexamples\": {d}, \"invalidations\": {d}, \"recompilations\": {d}, \"adjacent_followups\": {d} }},\n", .{ audit.c3.holdout.candidate_holdouts, audit.c3.holdout.delivery_holdouts, audit.c3.holdout.new_counterexamples, audit.c3.holdout.invalidations, audit.c3.holdout.recompilations, audit.c3.holdout.adjacent_followups });
        try writer.print("    \"delivery\": {{ \"controller_commits\": {d}, \"raw_commits_while_active\": {d}, \"controller_pushes\": {d}, \"raw_pushes_while_active\": {d}, \"closed_runs\": {d}, ", .{ audit.c3.delivery.controller_commits, audit.c3.delivery.raw_commits_while_active, audit.c3.delivery.controller_pushes, audit.c3.delivery.raw_pushes_while_active, audit.c3.delivery.closed_runs });
        try writeJsonRatioFields(writer, "controller_adoption", audit.denominator.c3_entered_sessions, audit.denominator.c3_required_sessions, "c3_required_sessions_zero");
        try writer.writeAll(" },\n");
        try writeReviewCompilerClosureCompressionJson(writer, audit.c3.closure_compression);
        try writer.writeAll(",\n");
        try writer.print("    \"compliance\": {{ \"basis_missing\": {d}, \"tournament_missing\": {d}, \"ablation_missing\": {d}, \"proof_missing\": {d}, \"holdout_missing\": {d}, \"stale_mrpc\": {d}, \"direct_review_to_delivery_mutation\": {d}, \"commit_or_push_bypass\": {d} }},\n", .{ audit.c3.compliance.basis_missing, audit.c3.compliance.tournament_missing, audit.c3.compliance.ablation_missing, audit.c3.compliance.proof_missing, audit.c3.compliance.holdout_missing, audit.c3.compliance.stale_mrpc, audit.c3.compliance.direct_review_to_delivery_mutation, audit.c3.compliance.commit_or_push_bypass });
    }
    const legacy = audit.legacy_cleanroom;
    try writer.print("    \"legacy_cleanroom\": {{ \"cleanroom\": {{ \"delivery_freezes\": {d}, \"counterexample_contracts\": {d}, \"delivery_recipes\": {d}, \"ablation_certificates\": {d}, \"compiled_delivery_permits\": {d} }}, ", .{ legacy.cleanroom.delivery_freezes, legacy.cleanroom.counterexample_contracts, legacy.cleanroom.delivery_recipes, legacy.cleanroom.ablation_certificates, legacy.cleanroom.compiled_delivery_permits });
    try writer.print("\"lab_vs_delivery\": {{ \"lab_apply_patch_calls\": {d}, \"lab_commits\": {d}, \"delivery_apply_patch_calls\": {d}, \"delivery_commits\": {d}, \"lab_surface_added\": {d}, \"lab_surface_discarded\": {d}, \"delivery_surface_shipped\": {d} }}, ", .{ legacy.lab_vs_delivery.lab_apply_patch_calls, legacy.lab_vs_delivery.lab_commits, legacy.lab_vs_delivery.delivery_apply_patch_calls, legacy.lab_vs_delivery.delivery_commits, legacy.lab_vs_delivery.lab_surface_added, legacy.lab_vs_delivery.lab_surface_discarded, legacy.lab_vs_delivery.delivery_surface_shipped });
    try writer.print("\"liability\": {{ \"branch_liabilities\": {d}, \"non_branch_liabilities\": {d}, \"followups_captured\": {d}, \"non_branch_liabilities_mutated\": {d} }}, ", .{ legacy.liability.branch_liabilities, legacy.liability.non_branch_liabilities, legacy.liability.followups_captured, legacy.liability.non_branch_liabilities_mutated });
    try writer.print("\"recipe\": {{ \"falsified_routes_excluded\": {d}, \"surfaces_to_retire\": {d}, \"permitted_new_surface\": {d} }}, ", .{ legacy.recipe.falsified_routes_excluded, legacy.recipe.surfaces_to_retire, legacy.recipe.permitted_new_surface });
    try writer.print("\"ablation\": {{ \"surfaces_removed\": {d}, \"surfaces_survived\": {d}, \"tests_merged_or_retired\": {d} }}, ", .{ legacy.ablation.surfaces_removed, legacy.ablation.surfaces_survived, legacy.ablation.tests_merged_or_retired });
    try writer.print("\"review_horizon\": {{ \"initial_broad_reviews\": {d}, \"targeted_reviews\": {d}, \"final_holdout_reviews\": {d}, \"holdout_findings_added_to_scope\": {d}, \"holdout_followups_captured\": {d} }}, ", .{ legacy.review_horizon.initial_broad_reviews, legacy.review_horizon.targeted_reviews, legacy.review_horizon.final_holdout_reviews, legacy.review_horizon.holdout_findings_added_to_scope, legacy.review_horizon.holdout_followups_captured });
    try writer.print("\"compliance\": {{ \"delivery_mutations_before_recipe\": {d}, \"review_derived_delivery_patches\": {d}, \"missing_contract\": {d}, \"missing_recipe\": {d}, \"missing_ablation\": {d} }} }}\n", .{ legacy.compliance.delivery_mutations_before_recipe, legacy.compliance.review_derived_delivery_patches, legacy.compliance.missing_contract, legacy.compliance.missing_recipe, legacy.compliance.missing_ablation });
    try writer.writeAll("  }\n}\n");

    const rendered = try writer_alloc.toOwnedSlice();
    defer allocator.free(rendered);
    if (out_path) |path| try ensureParentDir(path);
    try writeTextOutput(rendered, out_path);
}

fn writeReviewCompilerAuthoritySummaryJsonFields(writer: anytype, audit: ReviewCompilerAudit) !void {
    const protocol = audit.outputProtocol();
    const mbk_protocol = reviewCompilerProtocolIsMBK(protocol);
    const candidate_sessions = if (mbk_protocol) audit.mbk.denominator.candidate_sessions else audit.denominator.candidate_sessions;
    const true_resolve_sessions = if (mbk_protocol) audit.mbk.denominator.true_resolve_sessions else audit.denominator.true_resolve_sessions;
    const tuple_closed_sessions = if (mbk_protocol) audit.mbk.denominator.tuple_closed_sessions else audit.denominator.c3_closed_sessions;
    const terminal_closed_sessions = if (mbk_protocol) audit.mbk.denominator.terminal_closed_sessions else audit.c3.delivery.closed_runs;
    var material_runs_total: usize = 0;
    var material_runs_with_rac: usize = 0;
    var material_runs_with_mutation_gate: usize = 0;
    var material_runs_with_closure_gate: usize = 0;
    for (audit.material_runs.items) |row| {
        if (!row.material) continue;
        material_runs_total += 1;
        if (row.rac_total > 0) material_runs_with_rac += 1;
        if (!std.mem.eql(u8, row.mutation_gate_status, "missing")) material_runs_with_mutation_gate += 1;
        if (!std.mem.eql(u8, row.closure_gate_status, "missing")) material_runs_with_closure_gate += 1;
    }
    if (!mbk_protocol and material_runs_total == 0) {
        material_runs_total = audit.denominator.c3_required_sessions;
    }

    const mechanically_closed = reviewCompilerHasMechanicallyClosedMaterialRun(audit);
    try writer.print("    \"candidate_sessions\": {d},\n", .{candidate_sessions});
    try writer.print("    \"true_resolve_sessions\": {d},\n", .{true_resolve_sessions});
    try writer.print("    \"tuple_closed_sessions\": {d},\n", .{tuple_closed_sessions});
    try writer.print("    \"terminal_closed_sessions\": {d},\n", .{terminal_closed_sessions});
    try writer.print("    \"material_runs_total\": {d},\n", .{material_runs_total});
    try writer.print("    \"material_runs_with_rac\": {d},\n", .{material_runs_with_rac});
    try writer.print("    \"material_runs_with_mutation_gate\": {d},\n", .{material_runs_with_mutation_gate});
    try writer.print("    \"material_runs_with_closure_gate\": {d},\n", .{material_runs_with_closure_gate});
    try writer.print("    \"uncompiled_review_text_mutations\": {d},\n", .{audit.c3.compliance.direct_review_to_delivery_mutation});
    try writer.print("    \"raw_delivery_mutations_while_active\": {d},\n", .{audit.mbk.controller.raw_delivery_mutations_while_active + audit.c3.lab_vs_delivery.raw_delivery_mutations_while_frozen});
    try writer.print("    \"state_only_apply_violations\": {d},\n", .{audit.mbk.controller.state_only_apply_violations});
    try writer.print("    \"state_only_commit_violations\": {d},\n", .{audit.mbk.controller.state_only_commit_violations});
    try writer.print("    \"state_only_push_violations\": {d},\n", .{audit.mbk.controller.state_only_push_violations});
    try writer.print("    \"semantic_surface_before\": {d},\n", .{audit.mbk.semantic_surface.review_ready_baseline.semantic_surface});
    try writer.print("    \"semantic_surface_after\": {d},\n", .{audit.mbk.semantic_surface.terminal.semantic_surface});
    try writer.print("    \"semantic_surface_delta\": {d},\n", .{audit.mbk.semantic_surface.delta.semantic_surface});
    try writer.print("    \"orphan_code_constructs\": {d},\n", .{audit.mbk.realization.orphan_code_constructs});
    try writer.print("    \"unmapped_proof_actions\": {d},\n", .{audit.mbk.proof.unmapped_proof_actions});
    try writer.print("    \"wound_specific_tests\": {d},\n", .{audit.mbk.proof.wound_specific_tests});
    try writer.writeAll("    \"mechanical_closure_falsifier\": { \"status\": ");
    try output.writeJsonString(writer, if (mechanically_closed) "passed" else "not_found");
    try writer.writeAll(", \"message\": ");
    try output.writeJsonString(writer, if (mechanically_closed) "mechanically closed material resolve run found" else "no mechanically closed material resolve run found");
    try writer.writeAll(" },\n");
}

fn writeReviewCompilerClosureCompressionJson(writer: anytype, closure: ReviewCompilerAudit.ClosureCompression) !void {
    const missing = closure.missing_compression_evidence;
    try writer.print("    \"closure_compression\": {{ \"summary_state\": ", .{});
    try output.writeJsonString(writer, closure.summaryState().label());
    try writer.print(", \"closed_total\": {d}, \"closed_compressed\": {d}, \"closed_uncompressed\": {d}, \"blocked\": {d}, \"compression_not_required\": {d}, \"missing_compression_evidence\": {{ \"basis\": {d}, \"tournament\": {d}, \"ablation\": {d}, \"proof\": {d}, \"holdout\": {d}, \"permit\": {d}, \"stale_mrpc\": {d}, \"direct_review_to_delivery_mutation\": {d}, \"commit_or_push_bypass\": {d} }} }}", .{ closure.closed_total, closure.closed_compressed, closure.closed_uncompressed, closure.blocked, closure.compression_not_required, missing.basis, missing.tournament, missing.ablation, missing.proof, missing.holdout, missing.permit, missing.stale_mrpc, missing.direct_review_to_delivery_mutation, missing.commit_or_push_bypass });
}

fn reviewCompilerHasMechanicallyClosedMaterialRun(audit: ReviewCompilerAudit) bool {
    for (audit.material_runs.items) |row| {
        if (row.material and
            row.c3_required and
            row.c3_entered and
            row.c3_closed and
            !std.mem.eql(u8, row.compression_state, "NONE") and
            row.batches_total > 0 and
            row.kernel_accepted and
            row.potential_strict_progress > 0 and
            row.delivery_closed and
            row.terminal_closed and
            row.rac_valid > 0 and
            row.rac_mutation_allowed > 0 and
            std.mem.eql(u8, row.mutation_gate_status, "passed") and
            std.mem.eql(u8, row.closure_gate_status, "passed"))
        {
            return true;
        }
    }
    return false;
}

