    try writer.print("    \"observations\": {{ \"raw_findings\": {d}, \"branch_liabilities\": {d}, \"additional_witnesses\": {d}, \"missing_distinctions\": {d}, \"scope_expansions\": {d}, \"adjacent_followups\": {d}, \"preferences_rejected\": {d} }},\n", .{ mbk.observations.raw_findings, mbk.observations.branch_liabilities, mbk.observations.additional_witnesses, mbk.observations.missing_distinctions, mbk.observations.scope_expansions, mbk.observations.adjacent_followups, mbk.observations.preferences_rejected });
    try writer.print("    \"kernel\": {{ \"authorities\": {d}, \"observable_state_classes\": {d}, \"transitions\": {d}, \"laws\": {d}, \"local_surface_families\": {d}, \"governing_law_families\": {d}, \"findings_per_law\": {d}, \"distinctions_merged\": {d}, \"unwitnessed_distinctions\": {d}, \"exact_quotients\": {d}, \"witnessed_quotients\": {d} }},\n", .{ mbk.kernel.authorities, mbk.kernel.observable_state_classes, mbk.kernel.transitions, mbk.kernel.laws, mbk.kernel.local_surface_families, mbk.kernel.governing_law_families, mbk.kernel.findings_per_law, mbk.kernel.distinctions_merged, mbk.kernel.unwitnessed_distinctions, mbk.kernel.exact_quotients, mbk.kernel.witnessed_quotients });
    try writer.print("    \"realization\": {{ \"designs_considered\": {d}, \"route_classes\": {d}, \"selected_designs\": {d}, \"realization_recompilations\": {d}, \"realizations_from_campaign_base\": {d}, \"realizations_from_prior_head\": {d}, \"surfaces_retired\": {d}, \"orphan_code_constructs\": {d}, \"duplicate_realizations\": {d} }},\n", .{ mbk.realization.designs_considered, mbk.realization.route_classes, mbk.realization.selected_designs, mbk.realization.realization_recompilations, mbk.realization.realizations_from_campaign_base, mbk.realization.realizations_from_prior_head, mbk.realization.surfaces_retired, mbk.realization.orphan_code_constructs, mbk.realization.duplicate_realizations });

    try writer.writeAll("    \"semantic_surface\": { \"review_ready_baseline\": ");
    try writeMBKSurfaceSnapshotJson(writer, mbk.semantic_surface.review_ready_baseline);
    try writer.writeAll(", \"terminal\": ");
    try writeMBKSurfaceSnapshotJson(writer, mbk.semantic_surface.terminal);
    try writer.writeAll(", \"delta\": ");
    try writeMBKSurfaceSnapshotJson(writer, mbk.semantic_surface.delta);
    try writer.print(", \"hard_dimension_increases\": [], \"hard_dimension_increase_events\": {d}, \"total_description_nonincrease_pass\": {any}, \"approved_rebaselines\": {d}, \"silent_scope_expansions\": {d} }},\n", .{ mbk.semantic_surface.hard_dimension_increases, mbk.semantic_surface.total_description_nonincrease_pass, mbk.semantic_surface.approved_rebaselines, mbk.semantic_surface.silent_scope_expansions });
    try writer.print("    \"git_tree_metrics\": {{ \"files_changed\": {d}, \"insertions\": {d}, \"deletions\": {d}, \"net_lines\": {d} }},\n", .{ mbk.git_tree_metrics.files_changed, mbk.git_tree_metrics.insertions, mbk.git_tree_metrics.deletions, mbk.git_tree_metrics.net_lines });
    try writer.print("    \"proof\": {{ \"kernel_laws\": {d}, \"proof_families\": {d}, \"wound_specific_tests\": {d}, \"tests_merged_or_retired\": {d}, \"property_or_state_machine_families\": {d}, \"unmapped_proof_actions\": {d}, \"proof_runs\": {d}, \"stale_proof\": {d} }},\n", .{ mbk.proof.kernel_laws, mbk.proof.proof_families, mbk.proof.wound_specific_tests, mbk.proof.tests_merged_or_retired, mbk.proof.property_or_state_machine_families, mbk.proof.unmapped_proof_actions, mbk.proof.proof_runs, mbk.proof.stale_proof });
    try writer.print("    \"controller\": {{ \"physical_apply_events\": {d}, \"state_only_apply_violations\": {d}, \"physical_commits\": {d}, \"state_only_commit_violations\": {d}, \"physical_pushes\": {d}, \"state_only_push_violations\": {d}, \"raw_delivery_mutations_while_active\": {d}, \"backup_refs_created\": {d} }},\n", .{ mbk.controller.physical_apply_events, mbk.controller.state_only_apply_violations, mbk.controller.physical_commits, mbk.controller.state_only_commit_violations, mbk.controller.physical_pushes, mbk.controller.state_only_push_violations, mbk.controller.raw_delivery_mutations_while_active, mbk.controller.backup_refs_created });
    try writer.print("    \"closure\": {{ \"kernel_accepted\": {d}, \"conformance_closed_for_tuple\": {d}, \"terminal_closed\": {d}, \"unqualified_complete_claims\": {d}, \"tuple_receipts_missing_horizon\": {d}, \"post_push_reopens\": {d}, \"terminal_closure_with_new_evidence\": {d} }},\n", .{ mbk.closure.kernel_accepted, mbk.closure.conformance_closed_for_tuple, mbk.closure.terminal_closed, mbk.closure.unqualified_complete_claims, mbk.closure.tuple_receipts_missing_horizon, mbk.closure.post_push_reopens, mbk.closure.terminal_closure_with_new_evidence });

    try writer.writeAll("    \"key_metrics\": { ");
    try writeJsonRatioFields(writer, "finding_compression", mbk.observations.branch_liabilities, mbk.kernel.governing_law_families, "governing_law_families_zero");
    try writer.writeAll(", ");
    try writeJsonRatioFields(writer, "semantic_realization_density", mbk.kernel.governing_law_families, mbk.semantic_surface.terminal.realization_surface, "terminal_realization_surface_zero");
    try writer.writeAll(", ");
    try writeJsonRatioFields(writer, "proof_compression", mbk.observations.raw_findings, mbk.proof.proof_families, "proof_families_zero");
    try writer.print(", \"review_growth\": {d}, ", .{@as(i64, @intCast(mbk.semantic_surface.terminal.semantic_surface)) - @as(i64, @intCast(mbk.semantic_surface.review_ready_baseline.semantic_surface))});
    try writeJsonRatioFields(writer, "base_discipline", mbk.campaigns.fixed_base_pass, mbk.denominator.material_kernel_required_sessions, "material_kernel_required_sessions_zero");
    try writer.writeAll(" },\n");

    try writer.writeAll("    \"evidence_ledger\": [");
    for (mbk.evidence_ledger.items, 0..) |item, idx| {
        if (idx > 0) try writer.writeAll(", ");
        try writer.writeAll("{ \"session_id\": ");
        if (item.session_id) |id| try output.writeJsonString(writer, id) else try writer.writeAll("null");
        try writer.writeAll(", \"event\": ");
        try output.writeJsonString(writer, item.event);
        try writer.writeAll(", \"source\": ");
        try output.writeJsonString(writer, item.source);
        try writer.writeAll(", \"snippet\": ");
        try output.writeJsonString(writer, item.snippet);
        try writer.writeAll(" }");
    }
    try writer.writeAll("]\n");
}

fn writeMBKSurfaceSnapshotJson(writer: anytype, snapshot: ReviewCompilerAudit.SurfaceSnapshot) !void {
    try writer.print("{{ \"semantic_surface\": {d}, \"governing_laws\": {d}, \"realization_surface\": {d}, \"proof_families\": {d} }}", .{ snapshot.semantic_surface, snapshot.governing_laws, snapshot.realization_surface, snapshot.proof_families });
}

fn writeJsonRatioFields(writer: anytype, name: []const u8, numerator: usize, denominator: usize, zero_reason: []const u8) !void {
    try writer.print("\"{s}\": ", .{name});
    if (denominator == 0) {
        try writer.print("null, \"{s}_reason\": ", .{name});
        try output.writeJsonString(writer, zero_reason);
        return;
    }
    const value = @as(f64, @floatFromInt(numerator)) / @as(f64, @floatFromInt(denominator));
    try writer.print("{d:.6}, \"{s}_reason\": null", .{ value, name });
}

fn ensureParentDir(path: []const u8) !void {
    if (std.fs.path.dirname(path)) |dir| {
        if (dir.len > 0) try std.Io.Dir.cwd().createDirPath(std.Io.Threaded.global_single_threaded.io(), dir);
    }
}

fn writeMarkdownTable(writer: anytype, rows: []const query.Row, columns: []const []const u8) !void {
    if (columns.len == 0) {
        try writer.writeAll("(no columns)\n");
        return;
    }
    if (rows.len == 0) {
        try writer.writeAll("(no results)\n");
        return;
    }

    try writer.writeAll("|");
    for (columns) |column| {
        try writer.writeByte(' ');
        try writeEscapedMarkdownCell(writer, column);
        try writer.writeAll(" |");
    }
    try writer.writeByte('\n');

    try writer.writeAll("|");
    for (columns) |_| try writer.writeAll(" --- |");
    try writer.writeByte('\n');

    for (rows) |row| {
        try writer.writeAll("|");
        for (columns) |column| {
            try writer.writeByte(' ');
            try writeMarkdownScalar(writer, row.valueOrNull(column));
            try writer.writeAll(" |");
        }
        try writer.writeByte('\n');
    }
}

fn writeMarkdownScalar(writer: anytype, value: spec.Scalar) !void {
    switch (value) {
        .null => {},
        .bool => |flag| try writer.print("{}", .{flag}),
        .int => |number| try writer.print("{d}", .{number}),
        .float => |number| try writer.print("{d}", .{number}),
        .string => |text| try writeEscapedMarkdownCell(writer, text),
    }
}

fn writeEscapedMarkdownCell(writer: anytype, text: []const u8) !void {
    for (text) |ch| {
        switch (ch) {
            '|', '\\' => {
                try writer.writeByte('\\');
                try writer.writeByte(ch);
            },
            '\n', '\r' => try writer.writeByte(' '),
            else => try writer.writeByte(ch),
        }
    }
}

const QueryLiftCommands = struct {
    const skill_audit_summary_columns = [_][]const u8{ "skill", "mentions", "sessions", "first_seen", "last_seen" };
    const skill_audit_mentions_columns = [_][]const u8{ "timestamp", "role", "skill", "types", "snippet", "path" };
    const skill_audit_trend_columns = [_][]const u8{ "day", "mentions", "sessions" };
    const skill_audit_activation_columns = [_][]const u8{ "skill", "evidence_kind", "rows", "sessions", "first_seen", "last_seen", "example", "activation_verdict" };

    const SkillActivationKind = enum {
        explicit_user_call,
        implicit_assistant_call,
        injected_skill_block,
        skill_file_read,
        other_reference,
    };

    const SkillActivationState = struct {
        kind: SkillActivationKind,
        rows: usize = 0,
        sessions: StringSet,
        first_seen: ?[]u8 = null,
        last_seen: ?[]u8 = null,
        example: ?[]u8 = null,

        fn init(allocator: std.mem.Allocator, kind: SkillActivationKind) SkillActivationState {
            return .{
                .kind = kind,
                .sessions = StringSet.init(allocator),
            };
        }

        fn deinit(self: *SkillActivationState, allocator: std.mem.Allocator) void {
            self.sessions.deinit();
            if (self.first_seen) |value| allocator.free(value);
            if (self.last_seen) |value| allocator.free(value);
            if (self.example) |value| allocator.free(value);
        }

        fn record(
            self: *SkillActivationState,
            allocator: std.mem.Allocator,
            path: []const u8,
            timestamp: ?[]const u8,
            snippet: []const u8,
        ) !void {
            self.rows += 1;
            try self.sessions.put(path);
            if (timestamp) |ts| {
                if (self.first_seen == null or compareNormalizedTimestamp(ts, self.first_seen.?) == .lt) {
                    if (self.first_seen) |value| allocator.free(value);
                    self.first_seen = try allocator.dupe(u8, ts);
                }
                if (self.last_seen == null or compareNormalizedTimestamp(ts, self.last_seen.?) == .gt) {
                    if (self.last_seen) |value| allocator.free(value);
                    self.last_seen = try allocator.dupe(u8, ts);
                }
            }
            if (self.example == null) {
                self.example = try activationSnippet(allocator, snippet, 160);
            }
        }
    };

    const SkillActivationWindow = struct {
        since_ms: ?i64 = null,
        until_ms: ?i64 = null,
    };

    fn activationKindName(kind: SkillActivationKind) []const u8 {
        return switch (kind) {
            .explicit_user_call => "explicit_user_call",
            .implicit_assistant_call => "implicit_assistant_call",
            .injected_skill_block => "injected_skill_block",
            .skill_file_read => "skill_file_read",
            .other_reference => "other_reference",
        };
    }

    fn activationVerdict(kind: SkillActivationKind) []const u8 {
        return switch (kind) {
            .explicit_user_call, .implicit_assistant_call => "activation",
            .injected_skill_block, .skill_file_read => "not_activation",
            .other_reference => "reference",
        };
    }

    fn activationStateIndex(kind: SkillActivationKind) usize {
        return switch (kind) {
            .explicit_user_call => 0,
            .implicit_assistant_call => 1,
            .injected_skill_block => 2,
            .skill_file_read => 3,
            .other_reference => 4,
        };
    }

    fn resolveSkillActivationWindow(opts: Options) !SkillActivationWindow {
        const until_ms = try parseSkillActivationBoundMillis(opts.until, "--until");
        if (opts.last_text) |raw| {
            const duration_ms = try parseLastWindowMillis(raw);
            const anchor_ms = until_ms orelse currentUnixMillis();
            return .{ .since_ms = anchor_ms - duration_ms, .until_ms = anchor_ms };
        }
        return .{
            .since_ms = try parseSkillActivationBoundMillis(opts.since, "--since"),
            .until_ms = until_ms,
        };
    }

    fn parseSkillActivationBoundMillis(raw_opt: ?[]const u8, flag_name: []const u8) !?i64 {
        const raw = raw_opt orelse return null;
        return time_utils.parseIsoTimestampMillis(raw) orelse blk: {
            printCliError("error: skill-audit activation {s} must be an ISO-8601 timestamp with timezone\n", .{flag_name});
            break :blk error.InvalidTimestampArg;
        };
    }

    fn timestampSatisfiesActivationWindow(ts_opt: ?[]const u8, window: SkillActivationWindow) bool {
        const ts = ts_opt orelse return false;
        const ts_ms = time_utils.parseIsoTimestampMillis(ts) orelse return false;
        if (window.since_ms) |since| {
            if (ts_ms < since) return false;
        }
        if (window.until_ms) |until| {
            if (ts_ms > until) return false;
        }
        return true;
    }

    fn activationSnippet(allocator: std.mem.Allocator, text: []const u8, limit: usize) ![]u8 {
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(allocator);

        var i: usize = 0;
        while (i < text.len and out.items.len < limit) : (i += 1) {
            const c = text[i];
            try out.append(allocator, if (c == '\n' or c == '\r') ' ' else c);
        }
        return out.toOwnedSlice(allocator);
    }

    fn containsDollarSkill(text: []const u8, skill: []const u8) bool {
        var pos: usize = 0;
        while (std.mem.indexOfPos(u8, text, pos, "$")) |dollar_pos| {
            const start = dollar_pos + 1;
            const end = start + skill.len;
            if (end <= text.len and eqlIgnoreCaseAscii(text[start..end], skill)) {
                if (end == text.len or !isSkillSignalNameChar(text[end])) return true;
            }
            pos = dollar_pos + 1;
        }
        return false;
    }

    fn containsBareSkillReference(text: []const u8, skill: []const u8) bool {
        if (skill.len == 0 or skill.len > text.len) return false;
        var pos: usize = 0;
        while (pos + skill.len <= text.len) : (pos += 1) {
            const end = pos + skill.len;
            if (!eqlIgnoreCaseAscii(text[pos..end], skill)) continue;
            if (pos > 0 and isSkillSignalNameChar(text[pos - 1])) continue;
            if (end < text.len and isSkillSignalNameChar(text[end])) continue;
            return true;
        }
        return false;
    }

    fn containsSkillPathSegment(text: []const u8, skill: []const u8) bool {
        if (skill.len == 0 or skill.len > text.len) return false;
        var pos: usize = 0;
        while (pos + skill.len <= text.len) : (pos += 1) {
            const end = pos + skill.len;
            if (!eqlIgnoreCaseAscii(text[pos..end], skill)) continue;
            if (pos == 0 or !isPathSep(text[pos - 1])) continue;
            if (end >= text.len or !isPathSep(text[end])) continue;
            return true;
        }
        return false;
    }

    fn containsSkillFileRead(text_opt: ?[]const u8, skill: []const u8) bool {
        const text = text_opt orelse return false;
        return containsIgnoreCaseAscii(text, "SKILL.md") and containsSkillPathSegment(text, skill);
    }

    fn isSkillSignalNameChar(ch: u8) bool {
        return std.ascii.isAlphanumeric(ch) or ch == '-' or ch == '_';
    }
    const tool_audit_summary_columns = [_][]const u8{ "tool_name", "calls", "sessions", "avg_wall_ms", "max_wall_ms" };
    const tool_audit_row_columns = [_][]const u8{ "timestamp", "tool_name", "primary_executable", "workdir", "exit_code", "wall_time_ms", "command_text", "path" };
    const tool_audit_arg_columns = [_][]const u8{ "tool_name", "arg_path", "count" };
    const memory_inventory_category_columns = [_][]const u8{ "category", "extension", "files", "bytes", "latest_modified" };
    const memory_inventory_file_columns = [_][]const u8{ "relative_path", "category", "extension", "size_bytes", "modified_at", "preview" };
    const memory_inventory_block_columns = [_][]const u8{ "doc_kind", "title", "updated_at", "thread_id", "relative_path", "preview" };
    const memory_inventory_stage1_columns = [_][]const u8{ "generated_at", "last_usage", "cwd", "title", "thread_id", "rollout_path" };
    const memory_inventory_extension_columns = [_][]const u8{ "extension_name", "has_instructions", "modified_at", "size_bytes", "instructions_path" };
    const message_search_columns = [_][]const u8{ "timestamp", "role", "text", "path" };
    const message_audit_summary_columns = [_][]const u8{ "role", "messages", "sessions", "chars", "first_seen", "last_seen" };
    const message_audit_row_columns = [_][]const u8{ "timestamp", "role", "text_len", "text", "path" };
    const message_audit_session_columns = [_][]const u8{ "path", "messages", "chars", "first_seen", "last_seen" };
    const skill_cohort_summary_columns = [_][]const u8{ "skill", "mentions", "sessions", "first_seen", "last_seen" };
    const skill_cohort_mention_columns = [_][]const u8{ "timestamp", "role", "skill", "types", "snippet", "path" };
    const skill_cohort_columns = [_][]const u8{ "cohort_skill", "skill", "mentions", "sessions", "cohort_sessions", "first_seen", "last_seen" };
    const tool_search_row_columns = [_][]const u8{ "timestamp", "session_id", "tool_name", "primary_executable", "workdir", "exit_code", "wall_time_ms", "command_text", "arguments_text", "input_text", "path" };
    const tool_search_summary_columns = [_][]const u8{ "primary_executable", "calls", "sessions", "avg_wall_ms", "max_wall_ms" };
    const tool_search_arg_columns = [_][]const u8{ "tool_name", "arg_path", "value_kind", "value_text", "count" };
    const memory_extension_summary_columns = [_][]const u8{ "row_kind", "extensions", "with_instructions", "without_instructions", "total_bytes", "provenance_status", "causality_claimed" };
    const memory_extension_row_columns = [_][]const u8{ "extension_name", "has_instructions", "modified_at", "size_bytes", "instructions_path", "provenance_status", "causality_claimed" };
    const token_window_summary_columns = [_][]const u8{ "window_hours", "window_start", "window_end", "observed_end", "total_tokens", "rows", "path_count", "source_dataset", "sorted_by", "since", "until" };
    const token_window_row_columns = [_][]const u8{ "timestamp", "delta_total_tokens", "path", "thread_id", "root_session_id", "parent_thread_id", "model", "service_tier", "accounting_method", "segment", "model_context_window" };
    const workdir_report_summary_columns = [_][]const u8{ "cwd", "sessions", "turns", "total_tokens", "first_seen", "last_seen" };
    const workdir_report_session_columns = [_][]const u8{ "start_time", "end_time", "cwd", "model", "total_tokens", "path" };
    const goal_audit_row_columns = [_][]const u8{
        "timestamp",
        "objective_kind",
        "status",
        "time_used_seconds",
        "tokens_used",
        "review_invocation_count",
        "objective",
        "thread_id",
        "session_id",
        "path",
        "missing_duration",
        "contamination_flags",
    };
    const goal_audit_summary_columns = [_][]const u8{ "objective_kind", "runs", "sessions", "review_invocations", "max_time_used_seconds" };

    fn appendTimeBoundsForField(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        opts: Options,
    ) !void {
        if (opts.since) |value| try where_out.append(allocator, .{
            .field = field,
            .op = .gte,
            .value = .{ .scalar = .{ .string = value } },
        });
        if (opts.until) |value| try where_out.append(allocator, .{
            .field = field,
            .op = .lte,
            .value = .{ .scalar = .{ .string = value } },
        });
    }

    const OwnedTimeBounds = struct {
        since: ?[]u8 = null,
        until: ?[]u8 = null,

        fn deinit(self: OwnedTimeBounds, allocator: std.mem.Allocator) void {
            if (self.since) |value| allocator.free(value);
            if (self.until) |value| allocator.free(value);
        }
    };

    const OwnedScalarLists = struct {
        lists: std.ArrayList([]spec.Scalar) = .empty,
        time_bounds: std.ArrayList(OwnedTimeBounds) = .empty,

        fn keep(self: *OwnedScalarLists, allocator: std.mem.Allocator, list_opt: ?[]spec.Scalar) !void {
            const list = list_opt orelse return;
            try self.lists.append(allocator, list);
        }

        fn keepTime(self: *OwnedScalarLists, allocator: std.mem.Allocator, bounds: OwnedTimeBounds) !void {
            try self.time_bounds.append(allocator, bounds);
        }

        fn deinit(self: *OwnedScalarLists, allocator: std.mem.Allocator) void {
            for (self.lists.items) |list| allocator.free(list);
            self.lists.deinit(allocator);
            for (self.time_bounds.items) |bounds| bounds.deinit(allocator);
            self.time_bounds.deinit(allocator);
        }
    };

    fn appendLastWindowBoundsForField(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        opts: Options,
    ) !OwnedTimeBounds {
        const raw = opts.last_text orelse return .{};
        const duration_ms = try parseLastWindowMillis(raw);
        const anchor_ms = if (opts.until) |until| blk: {
            break :blk time_utils.parseIsoTimestampMillis(until) orelse {
                printCliError("error: --until must be an ISO-8601 timestamp with timezone when combined with --last\n", .{});
                return error.InvalidTimestampArg;
            };
        } else currentUnixMillis();
        const since_ms = anchor_ms - duration_ms;
        const since = try formatUnixMillisIsoUtcAlloc(allocator, since_ms);
        errdefer allocator.free(since);
        try where_out.append(allocator, .{
            .field = field,
            .op = .gte,
            .value = .{ .scalar = .{ .string = since } },
        });

        var owned = OwnedTimeBounds{ .since = since };
        if (opts.until == null) {
            const until = try formatUnixMillisIsoUtcAlloc(allocator, anchor_ms);
            errdefer allocator.free(until);
            try where_out.append(allocator, .{
                .field = field,
                .op = .lte,
                .value = .{ .scalar = .{ .string = until } },
            });
            owned.until = until;
        }
        return owned;
    }

    fn formatUnixMillisIsoUtcAlloc(allocator: std.mem.Allocator, ts_ms: i64) ![]u8 {
        const date = time_utils.dateFromTimestampMillis(ts_ms, .utc) orelse return error.InvalidTimestampArg;
        const day_ms = time_utils.daysFromCivil(date.year, date.month, date.day) * 86_400_000;
        const ms_of_day = ts_ms - day_ms;
        const total_seconds = @divFloor(ms_of_day, 1000);
        const millis = @mod(ms_of_day, 1000);
        const hour = @divFloor(total_seconds, 3600);
        const minute = @divFloor(@mod(total_seconds, 3600), 60);
        const second = @mod(total_seconds, 60);
        return std.fmt.allocPrint(allocator, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}.{d:0>3}Z", .{
            @as(u16, @intCast(date.year)),
            @as(u8, @intCast(date.month)),
            @as(u8, @intCast(date.day)),
            @as(u8, @intCast(hour)),
            @as(u8, @intCast(minute)),
            @as(u8, @intCast(second)),
            @as(u16, @intCast(millis)),
        });
    }

    fn appendOptionalStringEq(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        value_opt: ?[]const u8,
    ) !void {
        if (value_opt) |value| try where_out.append(allocator, .{
            .field = field,
            .op = .eq,
            .value = .{ .scalar = .{ .string = value } },
        });
    }

    fn appendOptionalContains(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        value_opt: ?[]const u8,
    ) !void {
        if (value_opt) |value| try where_out.append(allocator, .{
            .field = field,
            .op = .contains,
            .value = .{ .scalar = .{ .string = value } },
            .case_insensitive = true,
        });
    }

    fn appendOptionalRegex(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        value_opt: ?[]const u8,
    ) !void {
        if (value_opt) |value| try where_out.append(allocator, .{
            .field = field,
            .op = .regex,
            .value = .{ .scalar = .{ .string = value } },
            .case_insensitive = true,
        });
    }

    fn appendCsvContainsAny(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        raw_opt: ?[]const u8,
    ) !?[]spec.Scalar {
        const raw = raw_opt orelse return null;
        var values: std.ArrayList(spec.Scalar) = .empty;
        defer values.deinit(allocator);

        var split = std.mem.splitScalar(u8, raw, ',');
        while (split.next()) |part_raw| {
            const part = std.mem.trim(u8, part_raw, " \t\r\n");
            if (part.len == 0) continue;
            try values.append(allocator, .{ .string = part });
        }
        if (values.items.len == 0) return error.InvalidModeArg;
        const owned = try values.toOwnedSlice(allocator);
        try where_out.append(allocator, .{
            .field = field,
            .op = .contains_any,
            .value = .{ .list = owned },
            .case_insensitive = true,
        });
        return owned;
    }

    fn appendCsvContainsAll(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        field: []const u8,
        raw_opt: ?[]const u8,
    ) !void {
        const raw = raw_opt orelse return;
        var added = false;
        var split = std.mem.splitScalar(u8, raw, ',');
        while (split.next()) |part_raw| {
            const part = std.mem.trim(u8, part_raw, " \t\r\n");
            if (part.len == 0) continue;
            added = true;
            try where_out.append(allocator, .{
                .field = field,
                .op = .contains,
                .value = .{ .scalar = .{ .string = part } },
                .case_insensitive = true,
            });
        }
        if (!added) return error.InvalidModeArg;
    }

    fn appendRolesWhere(
        allocator: std.mem.Allocator,
        where_out: *std.ArrayList(spec.WhereClause),
        raw_opt: ?[]const u8,
    ) !?[]spec.Scalar {
        const raw = raw_opt orelse return null;
        var values: std.ArrayList(spec.Scalar) = .empty;
        defer values.deinit(allocator);

        var split = std.mem.splitScalar(u8, raw, ',');
        while (split.next()) |part_raw| {
            const part = std.mem.trim(u8, part_raw, " \t\r\n");
            if (part.len == 0) continue;
            if (!std.mem.eql(u8, part, "user") and !std.mem.eql(u8, part, "assistant")) {
                printCliError("error: invalid --roles value {s}\n", .{part});
                return error.InvalidModeArg;
            }
            try values.append(allocator, .{ .string = part });
        }
        if (values.items.len == 0) return error.InvalidModeArg;
        const owned = try values.toOwnedSlice(allocator);
        try where_out.append(allocator, .{
            .field = "role",
            .op = .in,
            .value = .{ .list = owned },
        });
        return owned;
    }

    fn queryLimit(opts: Options, default_limit: usize) usize {
        return if (opts.limit == 0) default_limit else opts.limit;
    }

    fn runQueryLiftDataset(
        allocator: std.mem.Allocator,
        dataset_name: []const u8,
        sessions_root: []const u8,
        query_spec: spec.QuerySpec,
        opts: Options,
        columns: []const []const u8,
    ) !void {
        if (opts.show_query) return writeGeneratedQuerySpec(allocator, dataset_name, query_spec, opts.out_path);
        return runDatasetQuery(allocator, dataset_name, sessions_root, query_spec, opts.format, opts.out_path, columns);
    }

    fn appendCurrentSessionExclusion(
        allocator: std.mem.Allocator,
        sessions_root: []const u8,
        where_out: *std.ArrayList(spec.WhereClause),
        opts: Options,
    ) !?[]u8 {
        if (!opts.exclude_current) return null;
        const path = try resolveCurrentSessionPathForExclusion(allocator, sessions_root);
        errdefer allocator.free(path);
        try where_out.append(allocator, .{
            .field = "path",
            .op = .neq,
            .value = .{ .scalar = .{ .string = path } },
        });
        return path;
    }

    fn resolveCurrentSessionPathForExclusion(allocator: std.mem.Allocator, sessions_root: []const u8) ![]u8 {
        const thread_id = getEnvVarOwned(allocator, "CODEX_THREAD_ID") catch {
            printCliError("error: --exclude-current requires CODEX_THREAD_ID in the environment\n", .{});
            return error.CurrentSessionUnavailable;
        };
        defer allocator.free(thread_id);

        var paths = try collectTraceRolloutPaths(allocator, sessions_root);
        defer freePathList(allocator, &paths);

        for (paths.items) |path| {
            var parsed = canonical_trace.parseSessionTrace(allocator, path, .{}) catch continue;
            defer parsed.deinit(allocator);
            if (parsed.session.session_id) |id| {
                if (std.mem.eql(u8, id, thread_id) or std.mem.containsAtLeast(u8, id, 1, thread_id)) {
                    return allocator.dupe(u8, path);
                }
            }
            if (std.mem.containsAtLeast(u8, path, 1, thread_id)) {
                return allocator.dupe(u8, path);
            }
        }

        printCliError("error: --exclude-current could not resolve CODEX_THREAD_ID {s} under sessions root {s}\n", .{ thread_id, sessions_root });
        return error.CurrentSessionUnavailable;
    }

    fn writeGeneratedQuerySpec(
        allocator: std.mem.Allocator,
        dataset_name: []const u8,
        query_spec: spec.QuerySpec,
        out_path: ?[]const u8,
    ) !void {
        var writer_alloc = std.Io.Writer.Allocating.init(allocator);
        defer writer_alloc.deinit();
        const writer = &writer_alloc.writer;

        try writer.writeAll("{\n  \"dataset\": ");
        try output.writeJsonString(writer, dataset_name);
        try writer.writeAll(",\n  \"where\": ");
        try writeWhereJson(writer, query_spec.where);
        try writer.writeAll(",\n  \"group_by\": ");
        try writeStringArrayJson(writer, query_spec.group_by);
        try writer.writeAll(",\n  \"metrics\": ");
        try writeMetricsJson(writer, query_spec.metrics);
        try writer.writeAll(",\n  \"select\": ");
        try writeStringArrayJson(writer, query_spec.select);
        try writer.writeAll(",\n  \"sort\": ");
        try writeSortJson(writer, query_spec.sort);
        try writer.writeAll(",\n  \"params\": ");
        try writeParamsJson(writer, query_spec.params);
        try writer.print(",\n  \"limit\": {d}\n}}\n", .{query_spec.limit});

        const rendered = try writer_alloc.toOwnedSlice();
        defer allocator.free(rendered);
        if (out_path) |path| {
            if (std.fs.path.dirname(path)) |dir| {
                if (dir.len > 0) try std.Io.Dir.cwd().createDirPath(defaultIo(), dir);
            }
            try std.Io.Dir.cwd().writeFile(defaultIo(), .{ .sub_path = path, .data = rendered });
            return;
        }

        var stdout = std.Io.File.stdout().writer(defaultIo(), &.{});
        try stdout.interface.writeAll(rendered);
    }

    fn writeWhereJson(writer: anytype, clauses: []const spec.WhereClause) !void {
        try writer.writeByte('[');
        for (clauses, 0..) |clause, i| {
            if (i > 0) try writer.writeAll(", ");
            try writer.writeAll("{\"field\":");
            try output.writeJsonString(writer, clause.field);
            try writer.writeAll(",\"op\":");
            try output.writeJsonString(writer, @tagName(clause.op));
            if (clause.value) |value| {
                try writer.writeAll(",\"value\":");
                try writeWhereValueJson(writer, value);
            }
            if (clause.case_insensitive) try writer.writeAll(",\"case_insensitive\":true");
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
    }

    fn writeWhereValueJson(writer: anytype, value: spec.WhereValue) !void {
        switch (value) {
            .scalar => |scalar| try output.writeScalarJson(writer, scalar),
            .list => |items| try writeScalarArrayJson(writer, items),
        }
    }

    fn writeScalarArrayJson(writer: anytype, items: []const spec.Scalar) !void {
        try writer.writeByte('[');
        for (items, 0..) |item, i| {
            if (i > 0) try writer.writeAll(", ");
            try output.writeScalarJson(writer, item);
        }
        try writer.writeByte(']');
    }

    fn writeStringArrayJson(writer: anytype, items: []const []const u8) !void {
        try writer.writeByte('[');
        for (items, 0..) |item, i| {
            if (i > 0) try writer.writeAll(", ");
            try output.writeJsonString(writer, item);
        }
        try writer.writeByte(']');
    }

    fn writeMetricsJson(writer: anytype, metrics: []const spec.MetricSpec) !void {
        try writer.writeByte('[');
        for (metrics, 0..) |metric, i| {
            if (i > 0) try writer.writeAll(", ");
            try writer.writeAll("{\"op\":");
            try output.writeJsonString(writer, @tagName(metric.op));
            if (metric.field) |field| {
                try writer.writeAll(",\"field\":");
                try output.writeJsonString(writer, field);
            }
            if (metric.alias) |alias| {
                try writer.writeAll(",\"as\":");
                try output.writeJsonString(writer, alias);
            }
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
    }

    fn writeSortJson(writer: anytype, sort_items: []const spec.SortSpec) !void {
        try writer.writeByte('[');
        for (sort_items, 0..) |sort_item, i| {
            if (i > 0) try writer.writeAll(", ");
            if (sort_item.descending) {
                try writer.writeByte('"');
                try writer.writeByte('-');
                for (sort_item.field) |c| {
                    if (c == '"' or c == '\\') try writer.writeByte('\\');
                    try writer.writeByte(c);
                }
                try writer.writeByte('"');
            } else {
                try output.writeJsonString(writer, sort_item.field);
            }
        }
        try writer.writeByte(']');
    }

    fn writeParamsJson(writer: anytype, params: []const spec.ParamSpec) !void {
        try writer.writeByte('{');
        for (params, 0..) |param, i| {
            if (i > 0) try writer.writeAll(", ");
            try output.writeJsonString(writer, param.key);
            try writer.writeByte(':');
            try output.writeScalarJson(writer, param.value);
        }
        try writer.writeByte('}');
    }

    fn cmdSkillAudit(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
        const mode = opts.mode orelse "summary";
        if (std.mem.eql(u8, mode, "activation")) {
            return cmdSkillAuditActivation(allocator, sessions_root, opts);
        }

        var where: std.ArrayList(spec.WhereClause) = .empty;
        defer where.deinit(allocator);
        try appendOptionalStringEq(allocator, &where, "skill", opts.skill);
        const last_bounds = try appendLastWindowBoundsForField(allocator, &where, "timestamp", opts);
        defer last_bounds.deinit(allocator);
        try appendSessionTimeBounds(allocator, &where, opts);
        const exclude_path = try appendCurrentSessionExclusion(allocator, sessions_root, &where, opts);
        defer if (exclude_path) |path| allocator.free(path);
        const role_values = try appendRolesWhere(allocator, &where, opts.roles_csv);
        defer if (role_values) |values| allocator.free(values);

        if (std.mem.eql(u8, mode, "summary")) {
            const query_spec = spec.QuerySpec{
                .where = where.items,
                .group_by = &.{"skill"},
                .metrics = &.{
                    .{ .op = .count, .alias = "mentions" },
                    .{ .op = .count_distinct, .field = "path", .alias = "sessions" },
                    .{ .op = .min, .field = "timestamp", .alias = "first_seen" },
                    .{ .op = .max, .field = "timestamp", .alias = "last_seen" },
                },
                .sort = &.{.{ .field = "mentions", .descending = true }},
                .limit = queryLimit(opts, 20),
            };
            return runQueryLiftDataset(allocator, "skill_mentions", sessions_root, query_spec, opts, skill_audit_summary_columns[0..]);
        }

        if (std.mem.eql(u8, mode, "mentions")) {
            const query_spec = spec.QuerySpec{
                .where = where.items,
                .select = skill_audit_mentions_columns[0..],
                .sort = &.{.{ .field = "timestamp", .descending = true }},
                .limit = queryLimit(opts, 50),
            };
            return runQueryLiftDataset(allocator, "skill_mentions", sessions_root, query_spec, opts, skill_audit_mentions_columns[0..]);
        }

        if (std.mem.eql(u8, mode, "trend")) {
            if (opts.skill == null) return error.MissingSkillArg;
            const query_spec = spec.QuerySpec{
                .where = where.items,
                .group_by = &.{"day"},
                .metrics = &.{
                    .{ .op = .count, .alias = "mentions" },
                    .{ .op = .count_distinct, .field = "path", .alias = "sessions" },
                },
                .sort = &.{.{ .field = "day", .descending = false }},
                .limit = opts.limit,
            };
            return runQueryLiftDataset(allocator, "skill_mentions", sessions_root, query_spec, opts, skill_audit_trend_columns[0..]);
        }

        return error.InvalidModeArg;
    }

    fn cmdSkillAuditActivation(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
        const skill = opts.skill orelse return error.MissingSkillArg;
        try validateRolesCsv(opts.roles_csv);
        const window = try resolveSkillActivationWindow(opts);
        const day_filter = deriveSessionDayPathFilterFromWindow(.{
            .since_ms = window.since_ms,
            .until_ms = window.until_ms,
        });
        var paths = try collectJsonlPaths(allocator, sessions_root, day_filter);
        defer freePathList(allocator, &paths);
        const exclude_path = if (opts.exclude_current) try resolveCurrentSessionPathForExclusion(allocator, sessions_root) else null;
        defer if (exclude_path) |path| allocator.free(path);

        var states = [_]SkillActivationState{
            SkillActivationState.init(allocator, .explicit_user_call),
            SkillActivationState.init(allocator, .implicit_assistant_call),
            SkillActivationState.init(allocator, .injected_skill_block),
            SkillActivationState.init(allocator, .skill_file_read),
            SkillActivationState.init(allocator, .other_reference),
        };
        defer for (&states) |*state| state.deinit(allocator);

        for (paths.items) |path| {
            if (exclude_path) |excluded| {
                if (std.mem.eql(u8, path, excluded)) continue;
            }
            const content = try readFileAllocOrSkip(allocator, path);
            if (content == null) continue;
            defer allocator.free(content.?);

            try recordSkillActivationMentions(allocator, &states, skill, path, content.?, window, opts);
            try recordSkillActivationReferences(allocator, &states, skill, path, content.?, window, opts);
            try recordSkillActivationToolReads(allocator, &states, skill, path, window);
        }

        var out_rows: std.ArrayList(query.Row) = .empty;
        defer deinitQueryRows(allocator, &out_rows);
        for (&states) |*state| {
            var row = query.Row.init(allocator);
            errdefer row.deinit();
            try row.putOwnedKey("skill", .{ .string = skill });
            try row.putOwnedKey("evidence_kind", .{ .string = activationKindName(state.kind) });
            try row.putOwnedKey("rows", .{ .int = @intCast(state.rows) });
            try row.putOwnedKey("sessions", .{ .int = @intCast(state.sessions.count()) });
            try putOptionalString(&row, "first_seen", state.first_seen);
            try putOptionalString(&row, "last_seen", state.last_seen);
            try row.putOwnedKey("example", .{ .string = state.example orelse "" });
            try row.putOwnedKey("activation_verdict", .{ .string = activationVerdict(state.kind) });
            try out_rows.append(allocator, row);
        }

        try output.writeOutput(allocator, opts.format, out_rows.items, skill_audit_activation_columns[0..], opts.out_path);
    }

    fn recordSkillActivationMentions(
        allocator: std.mem.Allocator,
        states: *[5]SkillActivationState,
        skill: []const u8,
        path: []const u8,
        content: []const u8,
        window: SkillActivationWindow,
        opts: Options,
    ) !void {
        const mentions = try datasets.skill_mentions.parseJsonl(allocator, path, content, .{});
        defer datasets.skill_mentions.freeRows(allocator, mentions);

        for (mentions) |row| {
            if (!eqlIgnoreCaseAscii(row.skill, skill)) continue;
            if (!timestampSatisfiesActivationWindow(row.timestamp, window)) continue;
            if (opts.roles_csv) |roles| {
                if (!csvContainsToken(roles, row.role)) continue;
            }

            const kind = activationKindFromDecisionSignal(skill_decision_signals.classifySkillMention(row.role, row.types));
            try states[activationStateIndex(kind)].record(allocator, row.path, row.timestamp, row.snippet);
        }
    }

    fn activationKindFromDecisionSignal(kind: skill_decision_signals.SignalKind) SkillActivationKind {
        return switch (kind) {
            .explicit_user_activation => .explicit_user_call,
            .assistant_declared_activation => .implicit_assistant_call,
            .injected_skill_block => .injected_skill_block,
            else => .other_reference,
        };
    }

    fn recordSkillActivationReferences(
        allocator: std.mem.Allocator,
        states: *[5]SkillActivationState,
        skill: []const u8,
        path: []const u8,
        content: []const u8,
        window: SkillActivationWindow,
        opts: Options,
    ) !void {
        const messages = try datasets.messages.parseJsonl(allocator, path, content, .{
            .strip_skill_blocks = true,
            .dedupe_by_role_and_text = true,
        });
        defer datasets.messages.freeRows(allocator, messages);

        for (messages) |row| {
            if (!timestampSatisfiesActivationWindow(row.timestamp, window)) continue;
            if (opts.roles_csv) |roles| {
                if (!csvContainsToken(roles, row.role)) continue;
            }
            if (!containsBareSkillReference(row.text, skill)) continue;
            if (containsDollarSkill(row.text, skill)) continue;
            try states[activationStateIndex(.other_reference)].record(allocator, row.path, row.timestamp, row.text);
        }
    }

    fn recordSkillActivationToolReads(
        allocator: std.mem.Allocator,
        states: *[5]SkillActivationState,
        skill: []const u8,
        path: []const u8,
        window: SkillActivationWindow,
    ) !void {
        var records: std.ArrayList(InvocationRecord) = .empty;
        defer deinitInvocationRecords(allocator, &records);
        try collectInvocationRecordsFromSession(allocator, path, &records);

        for (records.items) |record| {
            if (!timestampSatisfiesActivationWindow(record.start_ts, window)) continue;
            if (!containsSkillFileRead(record.command_text, skill) and
                !containsSkillFileRead(record.arguments_text, skill) and
                !containsSkillFileRead(record.input_text, skill))
            {
                continue;
            }
            const snippet = record.command_text orelse record.arguments_text orelse record.input_text orelse "";
            try states[activationStateIndex(.skill_file_read)].record(allocator, record.path, record.start_ts, snippet);
        }
    }

    const SkillEvidenceKind = enum {
        injected_skill_block,
        assistant_declared_skill_use,
        manual_skill_file_read,
        target_skill_lens_use,
        successful_activation_outcome,
        raw_mention,
    };

    const SkillEvidenceCursor = struct {
        version: i64 = 1,
        session_id: []const u8 = "",
        skill: []const u8 = "",
        path_fingerprint: []const u8 = "",
        last_line_number: usize = 0,
        last_timestamp: ?[]const u8 = null,
        last_file_size: usize = 0,
        evidence_hash: []const u8 = "",

        fn deinit(self: *SkillEvidenceCursor, allocator: std.mem.Allocator) void {
            if (self.session_id.len > 0) allocator.free(self.session_id);
            if (self.skill.len > 0) allocator.free(self.skill);
            if (self.path_fingerprint.len > 0) allocator.free(self.path_fingerprint);
            if (self.last_timestamp) |value| allocator.free(value);
            if (self.evidence_hash.len > 0) allocator.free(self.evidence_hash);
        }
    };

    const SkillEvidenceRecord = struct {
        kind: SkillEvidenceKind,
        timestamp: ?[]u8 = null,
        role: []u8,
        source: []u8,
        snippet: []u8,
        raw: ?[]u8 = null,
        ordinal: usize = 0,

        fn deinit(self: *SkillEvidenceRecord, allocator: std.mem.Allocator) void {
            if (self.timestamp) |value| allocator.free(value);
            allocator.free(self.role);
            allocator.free(self.source);
            allocator.free(self.snippet);
            if (self.raw) |value| allocator.free(value);
        }
    };

    fn cmdSkillEvidence(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
        const skill = opts.skill orelse return error.MissingSkillArg;
        if (opts.path == null and opts.session_id == null) return error.MissingSessionArg;

        var paths = try resolveTraceTargetPaths(allocator, sessions_root, opts, true);
        defer freePathList(allocator, &paths);
        const path = paths.items[0];

        var parsed = canonical_trace.parseSessionTrace(allocator, path, traceParseOptions(opts)) catch null;
        defer if (parsed) |*trace| trace.deinit(allocator);
        const session_id = if (parsed) |trace| trace.session.session_id orelse inferSessionIdFromPath(path) else inferSessionIdFromPath(path);

        const content = (try readFileAllocOrSkip(allocator, path)) orelse return error.SessionNotFound;
        defer allocator.free(content);

        const window = try resolveSkillActivationWindow(opts);
        var evidence: std.ArrayList(SkillEvidenceRecord) = .empty;
        defer {
            for (evidence.items) |*item| item.deinit(allocator);
            evidence.deinit(allocator);
        }

        try collectSkillEvidenceMentions(allocator, &evidence, skill, path, content, window, opts);
        try collectSkillEvidenceMessages(allocator, &evidence, skill, path, content, window, opts);
        try collectSkillEvidenceToolReads(allocator, &evidence, skill, path, window, opts);
        if (hasActivationEvidence(evidence.items)) {
            try collectSkillEvidenceOutcomes(allocator, &evidence, path, content, window, opts);
        }

        std.mem.sort(SkillEvidenceRecord, evidence.items, {}, skillEvidenceLessThan);
        for (evidence.items, 0..) |*item, idx| item.ordinal = idx + 1;

        const path_fingerprint = try skillEvidenceHexHashAlloc(allocator, path);
        defer allocator.free(path_fingerprint);
        const evidence_hash = try skillEvidenceHashAlloc(allocator, evidence.items);
        defer allocator.free(evidence_hash);

        var cursor_start: ?SkillEvidenceCursor = null;
        if (opts.since_cursor_text) |raw_cursor| {
            cursor_start = try parseSkillEvidenceCursor(allocator, raw_cursor);
        }
        defer if (cursor_start) |*cursor| cursor.deinit(allocator);

        var warnings: std.ArrayList([]const u8) = .empty;
        defer warnings.deinit(allocator);
        const cursor_valid = if (cursor_start) |cursor|
            std.mem.eql(u8, cursor.session_id, session_id) and
                eqlIgnoreCaseAscii(cursor.skill, skill) and
                std.mem.eql(u8, cursor.path_fingerprint, path_fingerprint)
        else
            true;
        if (!cursor_valid) try warnings.append(allocator, "since_cursor_target_mismatch_ignored");

        const cursor_line = if (cursor_start != null and cursor_valid) cursor_start.?.last_line_number else 0;
        const changed = if (cursor_start) |cursor|
            !(cursor_valid and cursor.last_file_size == content.len and std.mem.eql(u8, cursor.evidence_hash, evidence_hash))
        else
            evidence.items.len > 0;

        const visible_start = firstEvidenceAfterCursor(evidence.items, cursor_line);
        const visible = if (changed) evidence.items[visible_start..] else evidence.items[0..0];
        const cursor_end_json = try renderSkillEvidenceCursorJson(allocator, .{
            .version = 1,
            .session_id = session_id,
            .skill = skill,
            .path_fingerprint = path_fingerprint,
            .last_line_number = evidence.items.len,
            .last_timestamp = if (evidence.items.len > 0) evidence.items[evidence.items.len - 1].timestamp else null,
            .last_file_size = content.len,
            .evidence_hash = evidence_hash,
        });
        defer allocator.free(cursor_end_json);
        const cursor_end_token = try base64UrlEncodeAlloc(allocator, cursor_end_json);
        defer allocator.free(cursor_end_token);

        var writer_alloc = std.Io.Writer.Allocating.init(allocator);
        defer writer_alloc.deinit();
        const writer = &writer_alloc.writer;
        try writeSkillEvidenceJson(writer, .{
            .session_id = session_id,
            .path = path,
            .skill = skill,
            .cursor_start = if (cursor_start) |cursor| cursor else null,
            .cursor_end_json = cursor_end_json,
            .cursor_end_token = cursor_end_token,
            .changed = changed,
            .cursor_line = cursor_line,
            .total_current = evidence.items.len,
            .visible = visible,
            .include_raw = opts.include_raw,
            .warnings = warnings.items,
        });
        const rendered = try writer_alloc.toOwnedSlice();
        defer allocator.free(rendered);
        try writeTextOutput(rendered, opts.out_path);
    }

    fn collectSkillEvidenceMentions(
        allocator: std.mem.Allocator,
        out: *std.ArrayList(SkillEvidenceRecord),
        skill: []const u8,
        path: []const u8,
        content: []const u8,
        window: SkillActivationWindow,
        opts: Options,
    ) !void {
        const mentions = try datasets.skill_mentions.parseJsonl(allocator, path, content, .{});
        defer datasets.skill_mentions.freeRows(allocator, mentions);
        for (mentions) |row| {
            if (!eqlIgnoreCaseAscii(row.skill, skill)) continue;
            if (!timestampSatisfiesActivationWindow(row.timestamp, window)) continue;
            if (opts.roles_csv) |roles| if (!csvContainsToken(roles, row.role)) continue;
            const kind = evidenceKindFromDecisionSignal(skill_decision_signals.classifySkillMention(row.role, row.types));
            try appendSkillEvidenceRecord(allocator, out, kind, row.timestamp, row.role, "skill_mentions", row.snippet, opts.include_raw);
        }
    }

    fn evidenceKindFromDecisionSignal(kind: skill_decision_signals.SignalKind) SkillEvidenceKind {
        return switch (kind) {
            .assistant_declared_activation => .assistant_declared_skill_use,
            .injected_skill_block => .injected_skill_block,
            else => .raw_mention,
        };
    }

    fn collectSkillEvidenceMessages(
        allocator: std.mem.Allocator,
        out: *std.ArrayList(SkillEvidenceRecord),
        skill: []const u8,
        path: []const u8,
        content: []const u8,
        window: SkillActivationWindow,
        opts: Options,
    ) !void {
        const messages = try datasets.messages.parseJsonl(allocator, path, content, .{
            .strip_skill_blocks = true,
            .dedupe_by_role_and_text = true,
        });
        defer datasets.messages.freeRows(allocator, messages);
        for (messages) |row| {
            if (!timestampSatisfiesActivationWindow(row.timestamp, window)) continue;
            if (opts.roles_csv) |roles| if (!csvContainsToken(roles, row.role)) continue;
            const assistant_declared = std.mem.eql(u8, row.role, "assistant") and
                !containsDollarSkill(row.text, skill) and
                containsAssistantDeclaredSkillUse(row.text, skill);
            const target_lens = containsTargetSkillLensUse(row.text, skill);
            if (assistant_declared) {
                try appendSkillEvidenceRecord(allocator, out, .assistant_declared_skill_use, row.timestamp, row.role, "messages", row.text, opts.include_raw);
            }
            if (target_lens) {
                try appendSkillEvidenceRecord(allocator, out, .target_skill_lens_use, row.timestamp, row.role, "messages", row.text, opts.include_raw);
            }
            if (containsBareSkillReference(row.text, skill) and
                !containsDollarSkill(row.text, skill) and
                !assistant_declared and
                !target_lens and
                skillSuccessOutcomeForText(row.text).positive_bits == 0)
            {
                try appendSkillEvidenceRecord(allocator, out, .raw_mention, row.timestamp, row.role, "messages", row.text, opts.include_raw);
            }
        }
    }

    fn collectSkillEvidenceToolReads(
        allocator: std.mem.Allocator,
        out: *std.ArrayList(SkillEvidenceRecord),
        skill: []const u8,
        path: []const u8,
        window: SkillActivationWindow,
        opts: Options,
    ) !void {
        var records: std.ArrayList(InvocationRecord) = .empty;
        defer deinitInvocationRecords(allocator, &records);
        try collectInvocationRecordsFromSession(allocator, path, &records);
        for (records.items) |record| {
            if (!timestampSatisfiesActivationWindow(record.start_ts, window)) continue;
            if (!containsSkillFileRead(record.command_text, skill) and
                !containsSkillFileRead(record.arguments_text, skill) and
                !containsSkillFileRead(record.input_text, skill))
            {
                continue;
            }
            const snippet = record.command_text orelse record.arguments_text orelse record.input_text orelse "";
            try appendSkillEvidenceRecord(allocator, out, .manual_skill_file_read, record.start_ts, "tool", "tool_invocations", snippet, opts.include_raw);
        }
    }

    fn collectSkillEvidenceOutcomes(
        allocator: std.mem.Allocator,
        out: *std.ArrayList(SkillEvidenceRecord),
        path: []const u8,
        content: []const u8,
        window: SkillActivationWindow,
        opts: Options,
    ) !void {
        const messages = try datasets.messages.parseJsonl(allocator, path, content, .{
            .strip_skill_blocks = true,
            .dedupe_by_role_and_text = true,
        });
        defer datasets.messages.freeRows(allocator, messages);
        for (messages) |row| {
            if (!timestampSatisfiesActivationWindow(row.timestamp, window)) continue;
            if (opts.roles_csv) |roles| if (!csvContainsToken(roles, row.role)) continue;
            const outcome = skillSuccessOutcomeForText(row.text);
            if (outcome.positive_bits == 0) continue;
            try appendSkillEvidenceRecord(allocator, out, .successful_activation_outcome, row.timestamp, row.role, "messages", row.text, opts.include_raw);
        }
    }

    fn appendSkillEvidenceRecord(
        allocator: std.mem.Allocator,
        out: *std.ArrayList(SkillEvidenceRecord),
        kind: SkillEvidenceKind,
        timestamp: ?[]const u8,
        role: []const u8,
        source: []const u8,
        text: []const u8,
        include_raw: bool,
    ) !void {
        const snippet = try activationSnippet(allocator, text, 180);
        errdefer allocator.free(snippet);
        const raw = if (include_raw) try allocator.dupe(u8, text) else null;
        errdefer if (raw) |value| allocator.free(value);
        try out.append(allocator, .{
            .kind = kind,
            .timestamp = if (timestamp) |value| try allocator.dupe(u8, value) else null,
            .role = try allocator.dupe(u8, role),
            .source = try allocator.dupe(u8, source),
            .snippet = snippet,
            .raw = raw,
        });
    }

    fn hasActivationEvidence(items: []const SkillEvidenceRecord) bool {
        for (items) |item| switch (item.kind) {
            .injected_skill_block,
            .assistant_declared_skill_use,
            .manual_skill_file_read,
            .target_skill_lens_use,
            => return true,
            .successful_activation_outcome,
            .raw_mention,
            => {},
        };
        return false;
    }

    fn containsAssistantDeclaredSkillUse(text: []const u8, skill: []const u8) bool {
        if (!containsBareSkillReference(text, skill)) return false;
        return containsAnyIgnoreCaseAscii(text, &.{
            "using ",
            "use ",
            "loaded ",
            "activating ",
            "activation",
            "skill",
        });
    }

    fn containsTargetSkillLensUse(text: []const u8, skill: []const u8) bool {
        if (!containsBareSkillReference(text, skill) and !containsDollarSkill(text, skill)) return false;
        return containsAnyIgnoreCaseAscii(text, &.{
            "target_skill",
            "target skill",
            "lens",
            "skill lens",
            "root-equivalent",
            "root equivalent",
        });
    }

    fn skillEvidenceLessThan(_: void, lhs: SkillEvidenceRecord, rhs: SkillEvidenceRecord) bool {
        const lhs_ts = lhs.timestamp orelse "";
        const rhs_ts = rhs.timestamp orelse "";
        const order = std.mem.order(u8, lhs_ts, rhs_ts);
        if (order != .eq) return order == .lt;
        const kind_order = std.mem.order(u8, skillEvidenceKindName(lhs.kind), skillEvidenceKindName(rhs.kind));
        if (kind_order != .eq) return kind_order == .lt;
        return std.mem.order(u8, lhs.snippet, rhs.snippet) == .lt;
    }

    fn firstEvidenceAfterCursor(items: []const SkillEvidenceRecord, cursor_line: usize) usize {
        for (items, 0..) |item, idx| {
            if (item.ordinal > cursor_line) return idx;
        }
        return items.len;
    }

    fn skillEvidenceKindName(kind: SkillEvidenceKind) []const u8 {
        return switch (kind) {
            .injected_skill_block => "injected_skill_block",
            .assistant_declared_skill_use => "assistant_declared_skill_use",
            .manual_skill_file_read => "manual_skill_file_read",
            .target_skill_lens_use => "target_skill_lens_use",
            .successful_activation_outcome => "successful_activation_outcome",
            .raw_mention => "raw_mention",
        };
    }

    fn skillEvidenceKindIndex(kind: SkillEvidenceKind) usize {
        return switch (kind) {
            .injected_skill_block => 0,
            .assistant_declared_skill_use => 1,
            .manual_skill_file_read => 2,
            .target_skill_lens_use => 3,
            .successful_activation_outcome => 4,
            .raw_mention => 5,
        };
    }

    fn skillEvidenceHexHashAlloc(allocator: std.mem.Allocator, text: []const u8) ![]u8 {
        return std.fmt.allocPrint(allocator, "{x:0>16}", .{std.hash.Wyhash.hash(0, text)});
    }

    fn skillEvidenceHashAlloc(allocator: std.mem.Allocator, items: []const SkillEvidenceRecord) ![]u8 {
        var hasher = std.hash.Wyhash.init(0);
        for (items) |item| {
            hasher.update(skillEvidenceKindName(item.kind));
            hasher.update("\x00");
            if (item.timestamp) |timestamp| hasher.update(timestamp);
            hasher.update("\x00");
            hasher.update(item.role);
            hasher.update("\x00");
            hasher.update(item.snippet);
            hasher.update("\x00");
        }
        return std.fmt.allocPrint(allocator, "{x:0>16}", .{hasher.final()});
    }

    fn renderSkillEvidenceCursorJson(allocator: std.mem.Allocator, cursor: SkillEvidenceCursor) ![]u8 {
        var writer_alloc = std.Io.Writer.Allocating.init(allocator);
        defer writer_alloc.deinit();
        const writer = &writer_alloc.writer;
        try writeSkillEvidenceCursorObject(writer, cursor, false);
        return writer_alloc.toOwnedSlice();
    }

    fn base64UrlEncodeAlloc(allocator: std.mem.Allocator, raw: []const u8) ![]u8 {
        const size = std.base64.url_safe_no_pad.Encoder.calcSize(raw.len);
        const out = try allocator.alloc(u8, size);
        _ = std.base64.url_safe_no_pad.Encoder.encode(out, raw);
        return out;
    }

    fn base64UrlDecodeAlloc(allocator: std.mem.Allocator, raw: []const u8) ![]u8 {
        const size = try std.base64.url_safe_no_pad.Decoder.calcSizeForSlice(raw);
        const out = try allocator.alloc(u8, size);
        errdefer allocator.free(out);
        try std.base64.url_safe_no_pad.Decoder.decode(out, raw);
        return out;
    }

    fn parseSkillEvidenceCursor(allocator: std.mem.Allocator, raw: []const u8) !SkillEvidenceCursor {
        const json_text = if (std.mem.startsWith(u8, std.mem.trim(u8, raw, " \t\r\n"), "{"))
            try allocator.dupe(u8, raw)
        else
            base64UrlDecodeAlloc(allocator, raw) catch return error.InvalidModeArg;
        defer allocator.free(json_text);

        var parsed = std.json.parseFromSlice(std.json.Value, allocator, json_text, .{}) catch return error.InvalidModeArg;
        defer parsed.deinit();
        const obj = switch (parsed.value) {
            .object => |object| object,
            else => return error.InvalidModeArg,
        };

        return .{
            .version = stdJsonIntField(obj, "version") orelse 1,
            .session_id = try dupeNonEmptyCursorString(allocator, stdJsonStringField(obj, "session_id") orelse ""),
            .skill = try dupeNonEmptyCursorString(allocator, stdJsonStringField(obj, "skill") orelse ""),
            .path_fingerprint = try dupeNonEmptyCursorString(allocator, stdJsonStringField(obj, "path_fingerprint") orelse ""),
            .last_line_number = @intCast(stdJsonIntField(obj, "last_line_number") orelse 0),
            .last_timestamp = if (stdJsonStringField(obj, "last_timestamp")) |value| try allocator.dupe(u8, value) else null,
            .last_file_size = @intCast(stdJsonIntField(obj, "last_file_size") orelse 0),
            .evidence_hash = try dupeNonEmptyCursorString(allocator, stdJsonStringField(obj, "evidence_hash") orelse ""),
        };
    }

    fn dupeNonEmptyCursorString(allocator: std.mem.Allocator, text: []const u8) ![]const u8 {
        if (text.len == 0) return "";
        return allocator.dupe(u8, text);
    }

    const SkillEvidenceJsonInput = struct {
        session_id: []const u8,
        path: []const u8,
        skill: []const u8,
        cursor_start: ?SkillEvidenceCursor,
        cursor_end_json: []const u8,
        cursor_end_token: []const u8,
        changed: bool,
        cursor_line: usize,
        total_current: usize,
        visible: []const SkillEvidenceRecord,
        include_raw: bool,
        warnings: []const []const u8,
    };

    fn writeSkillEvidenceJson(writer: anytype, input: SkillEvidenceJsonInput) !void {
        try writeSkillEvidenceJsonInner(writer, input);
    }

    fn writeSkillEvidenceJsonInner(writer: anytype, input: SkillEvidenceJsonInput) !void {
        try writer.writeAll("{\n  \"command\": \"skill-evidence\",\n  \"session\": {\"session_id\": ");
        try output.writeJsonString(writer, input.session_id);
        try writer.writeAll(", \"path\": ");
        try output.writeJsonString(writer, input.path);
        try writer.writeAll("},\n  \"skill\": ");
        try output.writeJsonString(writer, input.skill);
        try writer.writeAll(",\n  \"cursor_start\": ");
        if (input.cursor_start) |cursor| {
            try writeSkillEvidenceCursorObject(writer, cursor, true);
        } else {
            try writer.writeAll("null");
        }
        try writer.writeAll(",\n  \"cursor_end\": {\"token\": ");
        try output.writeJsonString(writer, input.cursor_end_token);
        try writer.writeAll(", \"json\": ");
        try writer.writeAll(input.cursor_end_json);
        try writer.writeAll("},\n  \"evidence_delta\": {\"changed\": ");
        try writer.writeAll(if (input.changed) "true" else "false");
        try writer.print(", \"cursor_line\": {d}, \"current_total\": {d}, \"delta_total\": {d}}},\n", .{
            input.cursor_line,
            input.total_current,
            input.visible.len,
        });
        try writeSkillEvidenceSummaryJson(writer, input.visible, input.include_raw);
        try writer.writeAll(",\n  \"privacy\": {\"raw_transcript_included\": ");
        try writer.writeAll(if (input.include_raw) "true" else "false");
        try writer.writeAll(", \"default_sanitized\": ");
        try writer.writeAll(if (input.include_raw) "false" else "true");
        try writer.writeAll("},\n  \"warnings\": [");
        for (input.warnings, 0..) |warning, idx| {
            if (idx > 0) try writer.writeAll(", ");
            try output.writeJsonString(writer, warning);
        }
        try writer.writeAll("]\n}\n");
    }

    fn writeSkillEvidenceSummaryJson(writer: anytype, items: []const SkillEvidenceRecord, include_raw: bool) !void {
        var counts = [_]usize{0} ** 6;
        var first_seen = [_]?[]const u8{null} ** 6;
        var last_seen = [_]?[]const u8{null} ** 6;
        var examples = [_]?[]const u8{null} ** 6;
        for (items) |item| {
            const idx = skillEvidenceKindIndex(item.kind);
            counts[idx] += 1;
            if (examples[idx] == null) examples[idx] = item.snippet;
            if (item.timestamp) |timestamp| {
                if (first_seen[idx] == null or compareNormalizedTimestamp(timestamp, first_seen[idx].?) == .lt) {
                    first_seen[idx] = timestamp;
                }
                if (last_seen[idx] == null or compareNormalizedTimestamp(timestamp, last_seen[idx].?) == .gt) {
                    last_seen[idx] = timestamp;
                }
            }
        }

        const kinds = [_]SkillEvidenceKind{
            .injected_skill_block,
            .assistant_declared_skill_use,
            .manual_skill_file_read,
            .target_skill_lens_use,
            .successful_activation_outcome,
            .raw_mention,
        };
        try writer.writeAll("  \"summary\": {");
        for (kinds, 0..) |kind, idx| {
            if (idx > 0) try writer.writeAll(", ");
            try output.writeJsonString(writer, skillEvidenceKindName(kind));
            try writer.print(": {d}", .{counts[idx]});
        }
        try writer.writeAll("},\n  \"evidence\": [");
        var emitted: usize = 0;
        for (kinds, 0..) |kind, idx| {
            if (counts[idx] == 0) continue;
            if (emitted > 0) try writer.writeByte(',');
            emitted += 1;
            try writer.writeAll("\n    {\"kind\": ");
            try output.writeJsonString(writer, skillEvidenceKindName(kind));
            try writer.print(", \"count\": {d}, \"first_seen\": ", .{counts[idx]});
            try writeNullableJsonString(writer, first_seen[idx]);
            try writer.writeAll(", \"last_seen\": ");
            try writeNullableJsonString(writer, last_seen[idx]);
            try writer.writeAll(", \"example\": ");
            try writeNullableJsonString(writer, examples[idx]);
            if (include_raw) {
                try writer.writeAll(", \"raw_examples\": [");
                var raw_count: usize = 0;
                for (items) |item| {
                    if (item.kind != kind) continue;
                    const raw = item.raw orelse item.snippet;
                    if (raw_count > 0) try writer.writeAll(", ");
                    try output.writeJsonString(writer, raw);
                    raw_count += 1;
                    if (raw_count >= 3) break;
                }
                try writer.writeByte(']');
            }
            try writer.writeByte('}');
        }
        if (emitted > 0) try writer.writeByte('\n');
        try writer.writeAll("  ]");
    }

    fn writeNullableJsonString(writer: anytype, value: ?[]const u8) !void {
        if (value) |text| {
            try output.writeJsonString(writer, text);
        } else {
            try writer.writeAll("null");
        }
    }

    fn writeSkillEvidenceCursorObject(writer: anytype, cursor: SkillEvidenceCursor, pretty: bool) !void {
        _ = pretty;
        try writer.writeAll("{\"version\": ");
        try writer.print("{d}", .{cursor.version});
        try writer.writeAll(", \"session_id\": ");
        try output.writeJsonString(writer, cursor.session_id);
        try writer.writeAll(", \"skill\": ");
        try output.writeJsonString(writer, cursor.skill);
        try writer.writeAll(", \"path_fingerprint\": ");
        try output.writeJsonString(writer, cursor.path_fingerprint);
        try writer.print(", \"last_line_number\": {d}, \"last_timestamp\": ", .{cursor.last_line_number});
        try writeNullableJsonString(writer, cursor.last_timestamp);
        try writer.print(", \"last_file_size\": {d}, \"evidence_hash\": ", .{cursor.last_file_size});
        try output.writeJsonString(writer, cursor.evidence_hash);
        try writer.writeByte('}');
    }

    fn validateRolesCsv(raw_opt: ?[]const u8) !void {
        const raw = raw_opt orelse return;
        var any = false;
        var split = std.mem.splitScalar(u8, raw, ',');
        while (split.next()) |part_raw| {
            const part = std.mem.trim(u8, part_raw, " \t\r\n");
            if (part.len == 0) continue;
            any = true;
            if (!std.mem.eql(u8, part, "user") and !std.mem.eql(u8, part, "assistant")) {
                printCliError("error: invalid --roles value {s}\n", .{part});
                return error.InvalidModeArg;
            }
        }
        if (!any) return error.InvalidModeArg;
    }

    fn csvContainsToken(raw: []const u8, expected: []const u8) bool {
        var split = std.mem.splitScalar(u8, raw, ',');
        while (split.next()) |part_raw| {
            const part = std.mem.trim(u8, part_raw, " \t\r\n");
            if (std.mem.eql(u8, part, expected)) return true;
        }
        return false;
    }

    fn toolAuditGroupField(raw_opt: ?[]const u8) ![]const u8 {
        const raw = raw_opt orelse "tool";
        if (std.mem.eql(u8, raw, "tool")) return "tool_name";
        if (std.mem.eql(u8, raw, "executable")) return "primary_executable";
        if (std.mem.eql(u8, raw, "session")) return "session_id";
        if (std.mem.eql(u8, raw, "workdir")) return "workdir";
        if (std.mem.eql(u8, raw, "command")) return "command_text";
        return error.InvalidModeArg;
    }

    fn cmdToolAudit(allocator: std.mem.Allocator, sessions_root: []const u8, opts: Options) !void {
        const mode = opts.mode orelse "summary";
        var where: std.ArrayList(spec.WhereClause) = .empty;
        defer where.deinit(allocator);
        const last_bounds = try appendLastWindowBoundsForField(allocator, &where, "timestamp", opts);
        defer last_bounds.deinit(allocator);
        try appendTimeBoundsForField(allocator, &where, "timestamp", opts);
        try appendOptionalStringEq(allocator, &where, "tool_name", opts.tool);
        try appendOptionalStringEq(allocator, &where, "primary_executable", opts.executable_text);
        try appendOptionalStringEq(allocator, &where, "workdir", opts.workdir_text);
        try appendOptionalContains(allocator, &where, "command_text", opts.contains);

        if (std.mem.eql(u8, mode, "summary")) {
            const group_field = try toolAuditGroupField(opts.group_by_text);
            const group_by = [_][]const u8{group_field};
            var columns = [_][]const u8{ group_field, "calls", "sessions", "avg_wall_ms", "max_wall_ms" };
            const query_spec = spec.QuerySpec{
                .where = where.items,
                .group_by = group_by[0..],
                .metrics = &.{
                    .{ .op = .count, .alias = "calls" },
                    .{ .op = .count_distinct, .field = "session_id", .alias = "sessions" },
                    .{ .op = .avg, .field = "wall_time_ms", .alias = "avg_wall_ms" },
                    .{ .op = .max, .field = "wall_time_ms", .alias = "max_wall_ms" },
                },
                .sort = &.{.{ .field = "calls", .descending = true }},
                .limit = queryLimit(opts, 20),
            };
            return runQueryLiftDataset(allocator, "tool_invocations", sessions_root, query_spec, opts, columns[0..]);
        }

        if (std.mem.eql(u8, mode, "rows") or std.mem.eql(u8, mode, "unresolved")) {
            if (std.mem.eql(u8, mode, "unresolved")) {
                try where.append(allocator, .{ .field = "unresolved", .op = .eq, .value = .{ .scalar = .{ .bool = true } } });
            }
            const query_spec = spec.QuerySpec{
                .where = where.items,
                .select = tool_audit_row_columns[0..],
                .sort = &.{.{ .field = "timestamp", .descending = true }},
                .limit = queryLimit(opts, 50),
            };
            return runQueryLiftDataset(allocator, "tool_invocations", sessions_root, query_spec, opts, tool_audit_row_columns[0..]);
        }

        if (std.mem.eql(u8, mode, "args")) {
            var arg_where: std.ArrayList(spec.WhereClause) = .empty;
            defer arg_where.deinit(allocator);
            const arg_last_bounds = try appendLastWindowBoundsForField(allocator, &arg_where, "timestamp", opts);
            defer arg_last_bounds.deinit(allocator);
            try appendTimeBoundsForField(allocator, &arg_where, "timestamp", opts);
            try appendOptionalStringEq(allocator, &arg_where, "tool_name", opts.tool);
            try appendOptionalContains(allocator, &arg_where, "value_text", opts.contains);
            const query_spec = spec.QuerySpec{
                .where = arg_where.items,
                .group_by = &.{ "tool_name", "arg_path" },
                .metrics = &.{.{ .op = .count, .alias = "count" }},
                .sort = &.{.{ .field = "count", .descending = true }},
                .limit = queryLimit(opts, 50),
            };
            return runQueryLiftDataset(allocator, "tool_call_args", sessions_root, query_spec, opts, tool_audit_arg_columns[0..]);
        }

        return error.InvalidModeArg;
    }

