            const n = try std.fmt.parseInt(i64, args[i], 10);
            if (n < 0) return error.InvalidLimit;
            opts.limit = @intCast(n);
        } else {
            printCliError("error: unknown option {s}\n", .{arg});
            return error.UnknownArgument;
        }
    }
    return opts;
}

fn parseDurationSeconds(raw: []const u8) !i64 {
    const trimmed = std.mem.trim(u8, raw, " \t\r\n");
    if (trimmed.len == 0) return error.InvalidLimit;
    const unit = trimmed[trimmed.len - 1];
    const has_unit = unit == 's' or unit == 'm' or unit == 'h';
    const number_text = if (has_unit) trimmed[0 .. trimmed.len - 1] else trimmed;
    if (number_text.len == 0) return error.InvalidLimit;
    const value = try std.fmt.parseInt(i64, number_text, 10);
    if (value < 1) return error.InvalidLimit;
    return switch (unit) {
        'h' => std.math.mul(i64, value, 3600) catch return error.InvalidLimit,
        'm' => std.math.mul(i64, value, 60) catch return error.InvalidLimit,
        else => value,
    };
}

test "actuation-audit validates bounded selector modes and formats" {
    const path_opts = try parseOptionsForCommand(.actuation_audit, &.{
        "--root",
        "/tmp/sessions",
        "--path",
        "/tmp/session.jsonl",
        "--mode",
        "summary",
        "--format",
        "json",
        "--include-workers",
        "--include-excerpts",
        "--strict",
    });
    try std.testing.expect(path_opts.actuation_strict);
    try validateFormatForCommand(.actuation_audit, path_opts);
    try validateCommandOptions(.actuation_audit, path_opts);

    const artifact_root_opts = try parseOptionsForCommand(.actuation_audit, &.{ "--path", "/tmp/session.jsonl", "--artifact-root", "/tmp/artifacts" });
    try std.testing.expectError(error.UnsupportedOption, validateCommandOptions(.actuation_audit, artifact_root_opts));

    const session_opts = try parseOptionsForCommand(.actuation_audit, &.{ "--session-id", "abc", "--mode", "runs" });
    try validateCommandOptions(.actuation_audit, session_opts);

    const repo_window_opts = try parseOptionsForCommand(.actuation_audit, &.{ "--repo", "/tmp/repo", "--last", "2h" });
    try validateCommandOptions(.actuation_audit, repo_window_opts);

    const unbounded_opts = try parseOptionsForCommand(.actuation_audit, &.{ "--root", "/tmp/sessions" });
    try std.testing.expectError(error.MissingArgValue, validateCommandOptions(.actuation_audit, unbounded_opts));

    const repo_without_window_opts = try parseOptionsForCommand(.actuation_audit, &.{ "--repo", "/tmp/repo" });
