        "{\"timestamp\":\"2026-05-12T13:37:00Z\",\"type\":\"response_item\",\"payload\":{\"type\":\"function_call\",\"name\":\"exec_command\",\"call_id\":\"help-1\",\"arguments\":\"{\\\"cmd\\\":\\\"codex review --help\\\",\\\"workdir\\\":\\\"/repo\\\"}\"}}\n" ++
